var PATH_BOOK_BIO = {"subject": "生物", "book": "必修1《分子与细胞》", "version": "人教版", "chapters": [{"no": "第一章", "title": "走近细胞", "units": ["u_bio_1", "u_bio_2"]}, {"no": "第二章", "title": "组成细胞的分子", "units": ["u_bio_3", "u_bio_4", "u_bio_5", "u_bio_6", "u_bio_7"]}, {"no": "第三章", "title": "细胞的基本结构", "units": ["u_bio_8", "u_bio_9", "u_bio_10"]}, {"no": "第四章", "title": "细胞的物质输入和输出", "units": ["u_bio_11", "u_bio_12"]}, {"no": "第五章", "title": "细胞的能量供应和利用", "units": ["u_bio_13", "u_bio_14", "u_bio_15", "u_bio_16", "u_bio_17", "u_bio_18"]}, {"no": "第六章", "title": "细胞的生命历程", "units": ["u_bio_19", "u_bio_20", "u_bio_21"]}], "order": ["u_bio_1", "u_bio_2", "u_bio_3", "u_bio_4", "u_bio_5", "u_bio_6", "u_bio_7", "u_bio_8", "u_bio_9", "u_bio_10", "u_bio_11", "u_bio_12", "u_bio_13", "u_bio_14", "u_bio_15", "u_bio_16", "u_bio_17", "u_bio_18", "u_bio_19", "u_bio_20", "u_bio_21"], "nodes": {"bio_b001": {"name": "细胞学说及其意义", "sec": 1, "secTitle": "细胞是生命活动的基本单位", "page": 2, "desc": "细胞学说的建立者与三要点；魏尔肖的补充；细胞学说揭示动植物统一性。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": [], "next": ["bio_b002"], "content": {"advance": {"a": "该说法错误。细胞学说的讨论对象是一切动植物，并未声称病毒等无细胞生物也由细胞构成，因此病毒的现象并不与学说矛盾。恰恰相反，病毒没有细胞结构，必须寄生在活细胞内才能繁殖，离开细胞就不能独立完成代谢和繁殖，这从反面说明细胞是生命活动的基本单位，生命活动离不开细胞。细胞学说揭示的是动植物结构与功能的统一性，其适用范围有限，但在其范围内是正确的。", "kind": "self", "q": "有人说：“既然细胞学说认为细胞是生命活动的基本单位，那么病毒离开细胞就不能表现出生命现象，说明细胞学说是错的。”请用本节知识评析这一说法。"}, "apply": [{"ans": 3, "opts": ["观察了多种植物细胞，都有细胞壁，得出植物细胞都有细胞壁", "观察了所收集的全部天鹅都是白的，得出天鹅都是白的", "观察了多种动物细胞，都有细胞膜，得出动物细胞都有细胞膜", "在多地区观察到植物细胞都有叶绿体，得出所有植物细胞都有叶绿体"], "q": "科学家用归纳法从大量动植物观察中得出“动植物都由细胞构成”的结论。下列同样运用归纳法得出的结论，可靠性相对最低的是（ ）", "why": "D可靠性最低且结论本身错误：根尖等不见光的植物细胞没有叶绿体，以偏概全。归纳法得出的结论不一定完全正确，样本越不全面越不可靠。A、B、C样本虽也有限，但结论与事实基本相符或属于教材说明归纳法局限的典型例子；本题比较之下D的错误最明显——并非所有植物细胞都有叶绿体。"}, {"ans": 1, "opts": ["胡克在软木中观察到蜂窝状的小室", "洋葱根尖分生区细胞中观察到处于不同时期的分裂象", "列文虎克在池水中观察到游动的单细胞生物", "施旺观察到动物腓肠肌由纤维细胞构成"], "q": "下列事实或观察结果支持“新细胞由老细胞分裂产生”这一观点的是（ ）", "why": "B正确：根尖细胞出现不同分裂时期的图像，直接表明新细胞是老细胞分裂的产物，支持魏尔肖的观点。A是细胞的发现与命名，C是活细胞的观察，D是动物由细胞构成的证据，均不能证明细胞分裂产生新细胞。"}], "basics": [{"ans": 1, "opts": ["细胞学说认为一切生物都由细胞和细胞产物构成", "施莱登和施旺提出新细胞可以从老细胞中以结晶方式产生，后被魏尔肖修正", "魏尔肖提出细胞通过分裂产生新细胞，并独立建立了细胞学说", "细胞学说揭示了生物界的多样性和细胞的多样性"], "q": "下列关于细胞学说及其建立过程的叙述，正确的是（ ）", "why": "B正确：施莱登、施旺早期认为新细胞以结晶方式产生，魏尔肖提出新细胞由老细胞分裂产生，予以修正。A错，学说对象是动植物，不是包括病毒在内的一切生物。C错，建立者是施莱登和施旺，魏尔肖是补充者。D错，学说揭示的是统一性，不是多样性。"}, {"ans": 3, "opts": ["揭示了动物和植物的统一性", "为生物进化论的确立奠定了基础", "标志着生物学研究进入细胞水平", "阐明了原核细胞与真核细胞的区别"], "q": "细胞学说的重要意义不包括（ ）", "why": "D不属于学说意义。细胞学说未涉及原核生物，更未区分原核与真核细胞。A、B、C均为教材明确表述的意义：统一性、为进化论奠基、研究进入细胞水平。"}], "case": {"a": "（1）胡克看到的是已经死亡的植物细胞的细胞壁，他观察到的蜂窝状小室是细胞壁围成的空腔，并非活细胞。（2）细胞学说前两条——动植物由细胞发育而来、细胞是相对独立的生命单位——魏尔肖并未否定，他只针对第三条，把错误的“结晶方式产生新细胞”修正为“新细胞由老细胞通过分裂产生”，因此是补充和修正，不是推翻重建。（3）启示：科学结论来自大量观察后的归纳，样本和技术有限时结论可能不完善；新技术和新证据出现后要敢于修正，科学学说是在不断修正中发展的。", "hints": ["胡克的材料是软木，是死细胞", "看魏尔肖保留了哪两条、只改了哪一条"], "q": "材料：1665年胡克观察软木薄片，看到许多小室并命名为细胞；1838年施莱登提出植物体由细胞构成，1839年施旺提出动物体也由细胞构成，但二人认为新细胞是老细胞核外以结晶方式长出来的；1858年魏尔肖通过对病理组织和细胞分裂的观察提出一切细胞来自活细胞。请回答：（1）胡克看到的“细胞”实际上是什么结构？（2）为什么说魏尔肖的观点是对细胞学说的修正而不是推翻？（3）这段历史对科学方法的启示是什么？", "steps": ["先定性胡克观察对象：软木细胞已死亡，只剩细胞壁", "对比三要点：魏尔肖保留了‘动植物由细胞构成’和‘细胞是相对独立单位’，只修正第三条新细胞来源", "从方法看：学说靠观察+归纳形成，新证据出现后修正补充，体现科学的渐进性和可修正性"], "talk": ["记人物对号入座：胡克命名、列文虎克看活、施莱登施旺建学说、魏尔肖补分裂"], "title": "案例：从虎克到魏尔肖——学说是如何一步步完善的"}, "intro": "19世纪以前，人们看生物还停留在器官、组织层面，总觉得动植物是两套完全不同的东西。直到显微镜越做越好，科学家才发现，不管是植物的叶片还是动物的肌肉，拆到最后都是由**细胞**组成的。\n\n1838—1839年，德国植物学家**施莱登**和动物学家**施旺**在大量观察的基础上提出了**细胞学说**。==细胞学说揭示了动物和植物的统一性，从而阐明了生物界的统一性==。这句话是本节最爱考的一句，务必记牢。\n\n细胞学说不是施莱登、施旺两个人一夜之间想出来的，它是许多科学家观察、归纳的结果；后来德国的**魏尔肖**又作了关键补充。==新细胞是由老细胞分裂产生的==。记住：学说建立靠的是**归纳法**，不是演绎推理。", "learn": [{"h": "细胞学说的三要点，一个字都不能错", "p": "第一，**细胞是一个有机体，一切动植物都由细胞发育而来，并由细胞和细胞产物所构成**。注意是“动植物”，不是“一切生物”——病毒、原核生物不在这个表述里，考试最爱在这里挖坑。第二，**细胞是一个相对独立的单位，既有它自己的生命，又对与其他细胞共同组成的整体的生命起作用**。第三，**新细胞是由老细胞分裂产生的**。第三点最初施莱登、施旺的说法并不准确，是魏尔肖后来修正补充的。"}, {"h": "建立过程：谁做了什么", "p": "英国科学家**罗伯特·胡克**用自制显微镜观察软木，看到了死细胞的细胞壁，并命名了**cell（细胞）**，他看的其实是死细胞。荷兰的**列文虎克**第一次观察到活细胞。施莱登研究植物后提出植物体都是由细胞构成的；施旺受其启发研究动物，得出同样的结论，两人共同建立细胞学说。1858年，**魏尔肖**提出“细胞通过分裂产生新细胞”，他的名言是“所有的细胞都来源于先前存在的细胞”，==这句话修正了施莱登和施旺关于新细胞形成的错误观点==。"}, {"h": "细胞学说的意义，为什么重要", "p": "第一，揭示了**细胞的统一性**和**生物体结构的统一性**，使人们认识到各种生物在结构上有着共同的基础。第二，为后来**生物进化论**的确立埋下了伏笔——既然动植物都有共同的结构基础，就暗示它们可能有共同的祖先。第三，它标志着生物学研究进入了**细胞水平**，为后来进入分子水平打下基础。要注意，细胞学说只涉及动植物的统一性，==它没有揭示生物的多样性，也没有阐明真核细胞和原核细胞的区别==。"}, {"h": "学说的局限与适用范围", "p": "细胞学说主要阐述的是**动植物**，不涉及**原核生物**和**病毒**。所以判断题里出现“细胞学说认为一切生物都由细胞构成”就是错的，因为病毒没有细胞结构。同样，“细胞学说证明了细菌也是由细胞构成的”也不对，学说建立时还没有深入到原核生物这一层。考试判断学说内容时，先看对象是不是动植物，再看说法是不是三要点原文。"}], "pitfalls": ["把三要点第一条说成“一切生物都由细胞构成”——错。原文是“一切动植物”，病毒无细胞结构，原核生物也不在学说讨论范围内。", "认为魏尔肖建立了细胞学说——错。建立者是施莱登和施旺，魏尔肖只是提出“细胞通过分裂产生新细胞”作了修正和补充。", "认为胡克发现了活细胞或提出了细胞学说——错。胡克只是命名了细胞，看到的是软木死细胞的细胞壁；列文虎克才首先观察到活细胞。"]}, "video": {"bvid": "BV1p54y177e6", "p": 1, "t": "细胞是生命活动的基本单位", "dur": "55:24", "from": "锦城大同教育·杨波生物", "vtop": ["细胞学说把动植物统一到细胞层面：一切动植物都由细胞发育而来，但它不涉及原核细胞和病毒。", "病毒没有细胞结构，却必须寄生在活细胞里才能繁殖，这恰恰反证了细胞是生命活动的基本单位。", "生命系统九个层次从细胞起步、到生物圈封顶：最基本的是细胞，种群的判断要同时满足同种、同区域、全部个体。"], "vsum": "本课回答一个根问题：为什么说**细胞是生命活动的基本单位**。先看**细胞学说**：施莱登、施旺提出一切动植物都由细胞发育而来，魏尔肖补充「新细胞由老细胞分裂产生」；学说揭示了细胞的统一性和生物体结构的统一性。再看证据链：单细胞生物一个细胞完成全部生命活动，多细胞生物靠分化细胞协作，**病毒**无细胞结构、必须寄生在活细胞中繁殖。==判断生命活动是否离不开细胞，就抓一条：有没有细胞结构、能不能独立完成生命活动；病毒是反例式特例，离不开活细胞恰恰说明细胞是基本单位。==最后是**生命系统的结构层次**：细胞→组织→器官→系统→个体→种群→群落→生态系统→生物圈。易错提醒：魏尔肖是学说的补充者不是建立者；「一个池塘的全部鱼」不是种群，因为鱼不止一个物种。", "vtech": [["学说内容落笔三句", "看到细胞学说简答题 → 按三句写：一切动植物由细胞发育而来、并由细胞和细胞产物构成；细胞是相对独立的单位；新细胞由老细胞分裂产生。"], ["病毒题先抓结构", "看到病毒相关选项 → 先核三条：无细胞结构、只有核酸加蛋白质外壳、必须寄生在活细胞内，错一条即排除。"], ["层次排序钉两头", "看到结构层次排序题 → 先定最小是细胞、最大是生物圈，再查中间：植物没有系统这一层，单细胞生物一个细胞就是个体。"], ["种群判断三条件", "看到「某区域的全部某种生物」→ 逐项核对同种、同区域、全部个体，缺任何一个都不是种群。"]], "vgaokao": []}}, "bio_b002": {"name": "生命活动离不开细胞与生命系统的结构层次", "sec": 2, "secTitle": "细胞是生命活动的基本单位", "page": 6, "desc": "病毒必须寄生活细胞；单细胞与多细胞生物的生命活动；生命系统九层次与种群、群落、生态系统的区别。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b001"], "next": ["bio_b003"], "content": {"advance": {"a": "一棵松树属于个体层次（植物无系统层次，由器官直接构成个体）；一只松鼠属于个体层次；一条蚯蚓属于个体层次。森林中全部的松树是同种生物的全部个体，属于种群层次；全部的生物（所有动物、植物、微生物的种群集合）属于群落层次；整片森林包括群落及其阳光、土壤、水等无机环境，属于生态系统层次。判断依据是概念的组成范围：种群强调同种全部个体，群落强调全部生物，生态系统强调生物加无机环境。", "kind": "self", "q": "一片森林中，一棵松树、一只松鼠、一条土壤中的蚯蚓分别属于生命系统的哪些层次？这片森林中全部的松树、全部的生物、整片森林又分别属于哪些层次？请说明判断依据。"}, "apply": [{"ans": 3, "opts": ["新冠病毒的增殖过程离不开活细胞提供的物质和能量", "新冠病毒不属于生命系统的结构层次", "新冠病毒与上皮细胞一样，都含有蛋白质和核酸", "新冠病毒是单细胞生物，能在培养基上独立繁殖"], "q": "新冠病毒由蛋白质外壳和单链RNA组成，侵入人体呼吸道上皮细胞后，利用宿主细胞的核糖体合成自身蛋白质，并复制RNA组装成子代病毒。下列叙述错误的是（ ）", "why": "D错误：病毒无细胞结构，不是单细胞生物，也不能在普通培养基上独立繁殖，必须用活细胞培养。A正确，材料已说明它借用宿主核糖体和物质。B正确，病毒连细胞层次都不属于。C正确，两者都含蛋白质和核酸，病毒的遗传物质是RNA。"}, {"ans": 0, "opts": ["①②③", "②③④", "③②①", "①③②"], "q": "下列各项中，依次属于种群、群落、生态系统层次的是（ ） ①一片草原上全部的绵羊 ②一片草原上全部的生物 ③一片草原上全部生物及无机环境 ④一个培养皿中的大肠杆菌菌落", "why": "A正确：①同种全部个体是种群；②全部生物是群落；③生物加无机环境是生态系统。④菌落是同种细菌的集合，属于种群，可作干扰项排除。注意题干要求依次对应种群、群落、生态系统，只有①②③符合顺序。"}], "basics": [{"ans": 1, "opts": ["病毒不具有细胞结构，所以它的生命活动与细胞无关", "单细胞生物的一个细胞能完成各项生命活动", "多细胞生物的每一个细胞都能独立完成全部生命活动", "人体的生命活动与细胞无关，只与器官系统有关"], "q": "下列关于生命活动与细胞关系的叙述，正确的是（ ）", "why": "B正确：草履虫等单细胞生物靠单个细胞完成摄食、运动、繁殖等全部活动。A错，病毒必须寄生在活细胞内增殖，生命活动离不开细胞。C错，多细胞生物细胞已分化，单个细胞功能有限，需协作。D错，人体生命活动以细胞为基础，受精卵就是起点。"}, {"ans": 1, "opts": ["该湿地中全部的鲤鱼", "该湿地中芦苇、鲤鱼、青蛙和微生物等全部生物", "该湿地中全部生物及其生存的无机环境", "该湿地中全部的芦苇和鲤鱼"], "q": "某湿地中生活着芦苇、鲤鱼、青蛙、微生物等多种生物，还有水、阳光、土壤等。下列组合中属于群落的是（ ）", "why": "B正确：群落是同一区域内各种生物种群的集合，即全部生物。A是同种全部个体，属于种群。C是生物加环境，属于生态系统。D只有两个物种，既非种群也非群落。"}], "case": {"a": "（1）HIV没有细胞结构，没有核糖体、线粒体等完成代谢和增殖所需的结构与场所，自身不能合成蛋白质、不能复制核酸，也不能产生能量，必须寄生在活细胞内，利用宿主的核糖体、酶、原料和能量才能增殖，所以离开活细胞便不能繁殖并很快失活。（2）HIV主要侵染辅助性T细胞。该细胞在免疫调节中起关键作用，其大量破裂减少会使患者细胞免疫和体液免疫都严重受损，无法清除病原体，因而容易发生多种机会性感染和肿瘤。（3）辅助性T细胞属于细胞层次，是最基本的生命系统；它单独不能完成完整的免疫应答，必须与B细胞、细胞毒性T细胞、抗原呈递细胞等分化细胞协作，这也说明多细胞生物的生命活动依赖分化细胞的合作。", "hints": ["病毒缺什么结构，就不能独立完成什么过程", "辅助性T细胞是免疫系统的关键协作细胞"], "q": "材料：HIV主要侵染人体辅助性T细胞，病毒的遗传物质RNA进入细胞后逆转录成DNA并整合到宿主DNA上，随细胞分裂而潜伏；病毒大量增殖后导致辅助性T细胞破裂减少，患者免疫功能逐渐丧失。游离在血液中的HIV在体外很快失活。请回答：（1）HIV离开活细胞为什么不能增殖？（2）HIV主要攻击哪类细胞，这与患者易患多种感染有何关系？（3）用生命系统层次说明，辅助性T细胞属于哪个层次？", "steps": ["先看病毒结构：只有蛋白质和核酸，没有核糖体等结构，不能独立合成蛋白质和复制核酸", "再看宿主作用：增殖所需的酶、原料、能量、场所都由活细胞提供，所以离体很快失活", "最后联系层次：单个T细胞属于细胞层次，它参与的免疫功能需要多种细胞协作才能完成"], "talk": ["病毒题先抓三点：无细胞结构、只有蛋白质加核酸、必须寄生活细胞"], "title": "案例：HIV为什么难治——从病毒寄生看生命离不开细胞"}, "intro": "为什么说离开细胞就没有生命？一颗草履虫自己就能吃、能动、能繁殖；人身上一个细胞单独拿出来却活不下去；病毒更极端，自己连一套完整的“做饭工具”都没有。把这三种情况摆在一起看，道理就清楚了。\n\n**单细胞生物**靠**单个细胞**就能完成全部生命活动，**多细胞生物**则靠**分化的细胞**密切合作。==细胞是生物体结构和功能的基本单位，生命活动离不开细胞==。\n\n从一个细胞往外数，生物和环境一层层组成更大的系统。==细胞是最基本的生命系统==。层次名称不多，但**种群**、**群落**、**生态系统**这三个概念年年考、年年有人混。", "learn": [{"h": "生命活动为什么离不开细胞", "p": "第一类，**单细胞生物**如草履虫、衣藻、酵母菌、变形虫，一个细胞就是一个个体，摄食、运动、繁殖全部由这一个细胞完成。第二类，**多细胞生物**如人，生命开始于**受精卵**，经过细胞分裂和**细胞分化**形成各种组织器官，单个细胞只能完成一种或几种功能，必须依赖分工合作才能完成繁殖、反射等复杂活动，比如完成缩手反射至少需要感受器、传入神经元、神经中枢、传出神经元、效应器等多种细胞参与。第三类，**病毒**没有细胞结构，只有**蛋白质外壳**和内部的**核酸**，不能独立代谢，必须**寄生在活细胞内**，借助宿主细胞的物质和能量才能增殖。常见例子要记牢：**新型冠状病毒**、**HIV（艾滋病病毒）**、**噬菌体（寄生细菌的病毒）**、烟草花叶病毒。"}, {"h": "生命系统的结构层次，按顺序背", "p": "顺序是：**细胞→组织→器官→系统→个体→种群→群落→生态系统→生物圈**。细胞是起点，**生物圈**是最大的生命系统。植物没有**系统**这一层次，植物是细胞→组织→器官→个体；单细胞生物一个细胞既是细胞层次又是**个体**层次，它没有组织、器官、系统层次。冷知识也是考点：并非所有生物都有全部层次，判断时先看是单细胞、多细胞植物还是多细胞动物。"}, {"h": "种群、群落、生态系统，一字之差分清", "p": "**种群**：在一定的空间范围内，**同种生物**的所有个体形成的集合，如一个池塘里全部的鲤鱼。关键词是“同种+全部个体”。**群落**：同一时间内聚集在一定区域中**各种生物种群**的集合，如一个池塘里全部的鱼、藻、微生物。关键词是“所有生物”。**生态系统**：由**群落**与它生存的**无机环境**相互作用而形成的统一整体，如整个池塘。关键词是“生物+环境”。==判断口诀：同种是个种群，全部生物是群落，再加环境是生态系统==。地球上所有生物+环境就是生物圈。"}, {"h": "为什么说细胞是最基本的生命系统", "p": "比细胞更小的层次，如分子、原子，不属于生命系统，因为单个蛋白质或核酸不能独立表现出生命现象。细胞是能完整表现生命活动的最小单位：它有完整的膜系统、代谢场所和遗传物质，能独立或与其他细胞配合完成生命活动。所以层次判断题里，问“最基本”选细胞，问“最大”选生物圈，问“病毒属于哪个层次”——病毒不属于任何生命系统层次，它连细胞层次都够不上。"}], "pitfalls": ["把“一块骨骼肌”“一颗心脏”判错层次：骨骼肌主要是肌肉组织属于组织层次，心脏属于器官层次，血液属于组织（结缔组织），不要按日常感觉乱判。", "认为病毒是单细胞生物或属于个体层次——错。病毒无细胞结构，不属于生命系统的任何层次，必须寄生活细胞才能增殖。", "把“一个池塘中所有的鱼”当成种群或群落——错。所有的鱼包含多个物种，既不是同种（非种群），也不包括藻类、微生物等全部生物（非群落），什么都不是。"]}, "video": {"bvid": "BV1p54y177e6", "p": 1, "t": "细胞是生命活动的基本单位", "dur": "55:24", "from": "锦城大同教育·杨波生物", "vtop": ["细胞学说把动植物统一到细胞层面：一切动植物都由细胞发育而来，但它不涉及原核细胞和病毒。", "病毒没有细胞结构，却必须寄生在活细胞里才能繁殖，这恰恰反证了细胞是生命活动的基本单位。", "生命系统九个层次从细胞起步、到生物圈封顶：最基本的是细胞，种群的判断要同时满足同种、同区域、全部个体。"], "vsum": "本课回答一个根问题：为什么说**细胞是生命活动的基本单位**。先看**细胞学说**：施莱登、施旺提出一切动植物都由细胞发育而来，魏尔肖补充「新细胞由老细胞分裂产生」；学说揭示了细胞的统一性和生物体结构的统一性。再看证据链：单细胞生物一个细胞完成全部生命活动，多细胞生物靠分化细胞协作，**病毒**无细胞结构、必须寄生在活细胞中繁殖。==判断生命活动是否离不开细胞，就抓一条：有没有细胞结构、能不能独立完成生命活动；病毒是反例式特例，离不开活细胞恰恰说明细胞是基本单位。==最后是**生命系统的结构层次**：细胞→组织→器官→系统→个体→种群→群落→生态系统→生物圈。易错提醒：魏尔肖是学说的补充者不是建立者；「一个池塘的全部鱼」不是种群，因为鱼不止一个物种。", "vtech": [["学说内容落笔三句", "看到细胞学说简答题 → 按三句写：一切动植物由细胞发育而来、并由细胞和细胞产物构成；细胞是相对独立的单位；新细胞由老细胞分裂产生。"], ["病毒题先抓结构", "看到病毒相关选项 → 先核三条：无细胞结构、只有核酸加蛋白质外壳、必须寄生在活细胞内，错一条即排除。"], ["层次排序钉两头", "看到结构层次排序题 → 先定最小是细胞、最大是生物圈，再查中间：植物没有系统这一层，单细胞生物一个细胞就是个体。"], ["种群判断三条件", "看到「某区域的全部某种生物」→ 逐项核对同种、同区域、全部个体，缺任何一个都不是种群。"]], "vgaokao": []}}, "bio_b003": {"name": "使用高倍显微镜观察几种细胞", "sec": 3, "secTitle": "细胞的多样性和统一性", "page": 9, "desc": "高倍镜操作四步；放大倍数与视野变化；物像移动规律与污点判断。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b002"], "next": ["bio_b004"], "content": {"advance": {"a": "从视野范围看，低倍镜视野大、看到的范围广，容易快速定位标本；高倍镜视野小，一开始就用高倍如同大海捞针，目标不在小视野内就找不到。从亮度看，低倍镜进光多、视野亮，便于对光和初步观察；高倍镜视野暗，不利于搜寻。从操作安全看，低倍物镜短、工作距离长，不易压片；高倍物镜长、离装片很近，若直接用高倍并转粗准焦螺旋极易压碎装片和损坏镜头。因此规范流程是低倍找像、移至中央、再换高倍细调。", "kind": "self", "q": "为什么观察时要先用低倍镜再换高倍镜，而不能一开始就用高倍镜找标本？请从视野范围、亮度和操作安全三个角度说明。"}, "apply": [{"ans": 0, "opts": ["换高倍前没有把目标细胞移到视野中央，且未调大光圈", "对光时选用了平面反光镜", "低倍观察时转动了细准焦螺旋", "装片放置时标本未正对通光孔"], "q": "小明在低倍镜下观察洋葱表皮，视野左下方有一个清晰气泡干扰，他想把中央的正常细胞移至视野正中并换高倍观察，却发现换高倍后看不到细胞且视野很暗。最可能的操作失误是（ ）", "why": "A正确：未移到中央，换高倍后视野范围缩小，目标移出视野；高倍下进光少视野暗，需调大光圈或换凹面镜，他未调节故很暗，两点都对上。B平面镜在光线强时可用，不是主要失误。C低倍下用细准焦螺旋调清是允许的。D若未对准通光孔，低倍下根本看不到清晰细胞，与题干矛盾。"}, {"ans": 2, "opts": ["装片上", "物镜上", "目镜上", "反光镜上"], "q": "在显微镜视野中发现一污点，移动装片污点不动，转动目镜污点随之转动。则该污点位于（ ）", "why": "C正确：移动装片不动排除装片，转动目镜污点动说明污点在目镜上。判断口诀：动目镜动在目镜，动装片动在装片，都不动在物镜。反光镜不在成像光路的焦面上，不会形成视野污点。"}], "basics": [{"ans": 0, "opts": ["④②③①", "②④③①", "④③②①", "②③①④"], "q": "使用高倍显微镜观察细胞的正确操作顺序是（ ） ①转动细准焦螺旋调焦 ②低倍镜下将目标移到视野中央 ③转动转换器换上高倍物镜 ④低倍镜下找到目标", "why": "A正确：必须先低倍找到目标④，再移到中央②，然后换高倍物镜③，最后转细准焦螺旋调焦①。C错在未移到中央就换高倍，目标可能移出视野。B、D顺序混乱，低倍找像必须在最前面。"}, {"ans": 0, "opts": ["2个", "8个", "16个", "32个"], "q": "某同学用目镜10×、物镜10×观察到视野中一排有8个细胞。若换用物镜40×（目镜不变），这一排可观察到的细胞数约为（ ）", "why": "A正确：放大倍数由100倍变为400倍，变为原来的4倍。放大的是长度，一排细胞数与放大倍数成反比，8÷4＝2个。B未考虑倍数变化；C、D把关系算反了，倍数越大看到的细胞越少。"}], "case": {"a": "（1）三个错误：①未将要观察的细胞从视野右上方移到视野中央就直接换高倍镜，导致目标移出缩小的视野；②换高倍镜后视野变暗时未调节光圈和反光镜；③在高倍镜下大幅转动粗准焦螺旋调焦，违反高倍镜操作规范。（2）视野变暗时应转动遮光器换用较大的光圈，并将平面反光镜换为凹面反光镜聚光，必要时提高光源亮度。（3）碎裂声最可能是载玻片（装片）被高倍物镜压碎，盖玻片和标本也会受损。防压操作：低倍下镜筒下降时眼睛注视物镜与装片的距离；换高倍镜后绝不使用粗准焦螺旋，只用细准焦螺旋缓慢微调。", "hints": ["换高倍前要先做一步关键动作", "高倍下只能用哪种准焦螺旋"], "q": "材料：某同学制作人口腔上皮细胞临时装片，在低倍镜下右上方找到几个细胞，直接转动转换器换高倍镜后，发现视野一片暗、找不到细胞，于是大幅转动粗准焦螺旋，听到轻微碎裂声。请回答：（1）该同学至少犯了哪三个操作错误？（2）换高倍镜后视野变暗应如何调节？（3）碎裂声最可能是什么被压碎？正确防压的操作是什么？", "steps": ["找错误一：目标在右上方未移到中央就换高倍，视野缩小后目标移出", "找错误二：高倍下视野暗未调光，应换大光圈和凹面镜", "找错误三：高倍下转粗准焦螺旋且幅度大，物镜压到装片", "对应正确做法逐条写出规范操作"], "talk": ["实验题答法：先移中央、再换高倍、只调细准、暗了调光"], "title": "案例：观察口腔上皮细胞时视野总偏暗又找不到细胞"}, "intro": "显微镜是生物考试里唯一一个“动手题”，但高考和学考大多是纸上考操作：给个情景问你下一步怎么做、看到的现象说明什么。只要把顺序和原理搞清，这类题就是送分题。\n\n核心顺序只有一条主线：先**低倍镜**找，再**高倍镜**看。==换高倍镜后只能转动细准焦螺旋，不能动粗准焦螺旋==。这句话几乎年年考。\n\n还要记住，显微镜成的像是**倒像**。==物像移动方向与装片实际移动方向相反，物像偏哪就把装片往哪移==。这就是常说的“偏哪移哪”。", "learn": [{"h": "标准操作顺序，一步都不能颠倒", "p": "第一步，**取镜和安放**，再**对光**：转动转换器使低倍物镜对准通光孔，转动遮光器选较大光圈，用反光镜对光，看到明亮的圆形视野为止。第二步，放装片，标本正对通光孔中心，先用**低倍镜**观察：转动粗准焦螺旋使镜筒下降时，眼睛要看着**物镜**防止压碎装片；找到物像后把要放大的部分**移到视野中央**。第三步，换**高倍镜**：直接转动转换器换高倍物镜，不要提升镜筒。第四步，调焦和调光：高倍下视野变暗，可换大光圈或凹面反光镜；只能转动**细准焦螺旋**使物像清晰。==高倍镜下千万不能转动粗准焦螺旋，否则容易压片且找不到像==。"}, {"h": "放大倍数到底放大了什么", "p": "**放大倍数＝目镜放大倍数×物镜放大倍数**。放大的不是面积也不是体积，而是物体的**长度或宽度**。若长度放大了100倍，面积实际放大了10000倍（平方关系），考试爱用面积设陷阱。还有一条实用规律：一行细胞数目的计算——若视野中一排有16个细胞，放大倍数变为原来的4倍，这一行只能看到4个，因为放大的是长度，数目与放大倍数成反比。若是充满整个视野的细胞数，则与放大倍数的平方成反比。"}, {"h": "换高倍镜后，视野发生了什么变化", "p": "三变要背熟：**细胞体积变大、细胞数目变少、视野变暗、视野范围变小**。原因是高倍镜下看到的只是低倍视野中央的一小块。视野变暗是因为进光量减少，处理方法是调大**光圈**或改用**凹面镜**。镜头长短也有规律：**物镜越长，放大倍数越大**，且物镜越长离装片越近；**目镜越长，放大倍数越小**。给图判断倍数高低就靠这条。"}, {"h": "倒像移动与污点判断", "p": "显微镜成上下颠倒、左右相反的**倒像**。玻片上写“b”，视野里看到的是“q”。物像偏在左上方，想把它移到中央，要把装片向**左上方**移动，即偏哪移哪（因为成倒像，移动方向与物像移动方向相反）。视野中有污点时判断位置：**转动目镜**，污点动说明在目镜上；**移动装片**，污点动说明在装片上；两者都不动，说明在**物镜**上。==污点只可能在目镜、物镜、装片三处，逐一排查即可==。"}], "pitfalls": ["高倍镜下还去转粗准焦螺旋找像——错。换高倍镜前低倍下已调清且移到中央，换后只需转细准焦螺旋微调，转粗准焦螺旋易压碎装片且像会跑掉。", "认为放大倍数放大的是面积——错。放大倍数指的是长度或宽度的倍数，面积放大倍数是它的平方，这个点在计算题里最容易丢分。", "物像偏右下方却把装片往左上方移——错。记住偏哪移哪：偏右下就往右下移装片，物像才会向中央（左上）移动。"]}, "video": {"bvid": "BV1p54y177e6", "p": 3, "t": "细胞的多样性和统一性", "dur": "91:22", "from": "锦城大同教育·杨波生物", "vtop": ["原核与真核的分界只有一条：有没有以核膜为界限的细胞核；原核细胞只有拟核，细胞器只有核糖体一种。", "高倍镜口诀：低倍找、高倍看，换镜后只动细准焦；放大倍数等于目镜乘物镜，放大的是长度不是面积。", "显微镜成的是倒像：物像偏向哪边，玻片就往哪边移（同向移动），与直觉相反。"], "vsum": "本课两大块：先学**高倍显微镜的使用**，再按有没有真正的细胞核给细胞分类。显微镜抓三件事：结构（目镜、物镜、转换器、粗/细准焦螺旋）、步骤（对光→低倍观察→把像移到中央→转高倍→调细准焦）、成像规律（**倒像**、放大倍数＝目镜×物镜）。==换上高倍镜后视野变暗，只能用细准焦螺旋和反光镜、光圈调，绝不能再动粗准焦——会压碎玻片、丢失物像。==分类部分：**真核细胞**有以核膜为界限的细胞核，**原核细胞**只有**拟核**、只有**核糖体**一种细胞器；原核生物包括细菌、蓝细菌、支原体等。多样性背后是**统一性**：都具细胞膜、细胞质、核糖体，都以 DNA 为遗传物质。易错提醒：蓝细菌能进行光合作用但没有叶绿体；支原体没有细胞壁；病毒没有细胞结构，不属于原核生物。", "vtech": [["高倍镜四步", "看到显微镜操作题 → 按序写：对光、低倍镜下找到物像、把物像移到视野中央、转动转换器换高倍镜后只调细准焦螺旋。"], ["倒像同向移", "看到物像偏在视野左上方 → 玻片也向左上方移动，因为显微镜成倒像，像的移动方向与玻片相反。"], ["分类先看核", "看到细胞分类题 → 先看有无核膜包被的细胞核定真核原核，再验证：细胞器只剩核糖体的是原核细胞。"], ["蓝细菌陷阱", "看到「蓝藻有叶绿体」→ 判错：蓝细菌是原核生物，没有叶绿体，靠含藻蓝素和叶绿素的光合片层进行光合作用。"]], "vgaokao": []}}, "bio_b004": {"name": "原核细胞和真核细胞", "sec": 4, "secTitle": "细胞的多样性和统一性", "page": 11, "desc": "有无核膜是分类依据；原核细胞的拟核与唯一细胞器核糖体；蓝细菌、支原体特例与「菌」字辨析。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b003"], "next": [], "content": {"advance": {"a": "乳酸菌是原核生物（细菌），酵母菌是真核生物（真菌），二者结构差别很大。细胞核：乳酸菌无核膜、无真正的细胞核，只有拟核，遗传物质为裸露环状DNA，无染色体；酵母菌有核膜包被的细胞核，DNA与蛋白质组成染色体。细胞器：乳酸菌只有核糖体一种细胞器；酵母菌有线粒体、内质网等多种细胞器。细胞壁：乳酸菌细胞壁主要成分是肽聚糖；酵母菌细胞壁主要成分是几丁质等。相同点：都有细胞膜、细胞质、核糖体，都以DNA为遗传物质。应用：乳酸菌常用于制作酸奶、泡菜（无氧呼吸产生乳酸）；酵母菌常用于酿酒和制作馒头、面包（呼吸产生二氧化碳使面团膨松）。", "kind": "self", "q": "有人根据“乳酸菌、酵母菌都带菌字”推断二者结构相同。请比较乳酸菌与酵母菌在细胞核、细胞器、细胞壁成分上的异同，并说明乳酸菌与酵母菌分别常用于什么食品制作。"}, "apply": [{"ans": 1, "opts": ["发菜细胞有叶绿体，能进行光合作用，属于植物", "发菜细胞的遗传物质位于拟核区，是裸露的环状DNA", "发菜细胞有染色体，DNA与蛋白质紧密结合", "发菜细胞只有线粒体和核糖体两种细胞器"], "q": "发菜是一种蓝细菌，因过度采挖会破坏草原生态。下列关于发菜细胞的叙述，正确的是（ ）", "why": "B正确：发菜是原核生物，遗传物质是拟核区裸露的环状DNA。A错，它没有叶绿体，靠叶绿素和藻蓝素光合，也不属于植物。C错，原核细胞没有染色体。D错，原核细胞只有核糖体一种细胞器，没有线粒体。"}, {"ans": 1, "opts": ["肺炎支原体是病毒，必须寄生在活细胞内", "肺炎支原体没有细胞壁，这可能是它形态多变的原因之一", "肺炎支原体有核膜包被的细胞核，属于真核生物", "作用于细菌细胞壁肽聚糖的某些抗生素对支原体同样高效"], "q": "支原体肺炎曾在人群中流行，病原体肺炎支原体能独立生活但形体微小、可通过除菌滤器。下列推断合理的是（ ）", "why": "B合理：支原体是原核生物且无细胞壁，没有壁的束缚形态易变，也能通过滤器。A错，支原体是单细胞原核生物，能独立生活，不是病毒。C错，它没有核膜和真正的细胞核。D不合理，支原体无细胞壁也就没有肽聚糖壁，针对细胞壁的抗生素对其效果差，这正是临床用药要避开的点。"}], "basics": [{"ans": 1, "opts": ["酵母菌", "蓝细菌", "蘑菇", "青霉"], "q": "下列生物中，属于原核生物的是（ ）", "why": "B正确：蓝细菌无核膜包被的细胞核，属于原核生物。A酵母菌、C蘑菇（食用菌）、D青霉（霉菌）都属于真菌，具有真正的细胞核，是真核生物。带菌不一定是细菌，真菌全是真核。"}, {"ans": 2, "opts": ["有无细胞膜", "有无核糖体", "有无以核膜为界限的细胞核", "有无细胞壁"], "q": "原核细胞与真核细胞最主要的区别是（ ）", "why": "C正确：分类依据就是有无以核膜为界限的细胞核。A、B两类细胞都有细胞膜和核糖体，不能作区别。D不是主要区别，支原体无细胞壁、动物细胞也无细胞壁，用有无细胞壁无法划分两类细胞。"}], "case": {"a": "（1）蓝细菌属于原核生物。判断依据是它没有以核膜为界限的细胞核，遗传物质是拟核区裸露的环状DNA，没有染色体，这一条是划分原核与真核的根本标准。（2）光合作用的必要条件是光合色素和有关的酶，不一定需要叶绿体这一结构。蓝细菌细胞内含有叶绿素和藻蓝素及光合所需的酶，分布在光合膜上，能进行光合作用制造有机物，故能借助富营养化的氮、磷大量繁殖；其大量死亡后，尸体被需氧微生物分解时消耗大量氧气，加之浮沫遮光使水生植物光合减弱，水中溶氧急剧下降，鱼类窒息死亡。（3）共同结构有细胞膜、细胞质、核糖体和遗传物质DNA，体现了原核细胞与真核细胞的统一性。", "hints": ["判断原核真核只看一条标准：核膜", "光合作用需要的是色素和酶，不一定非要叶绿体"], "q": "材料：夏季某淡水湖气温高、含氮磷的污水排入增多，蓝细菌在短期内大量繁殖形成水华，湖面出现蓝绿色浮沫，水中溶氧下降，鱼类死亡。检测发现蓝细菌细胞中无叶绿体，但含有叶绿素和藻蓝素。请回答：（1）蓝细菌属于原核还是真核生物？判断依据是什么？（2）没有叶绿体，蓝细菌为什么还能进行光合作用并导致水中生物缺氧死亡？（3）从细胞结构统一性角度，蓝细菌与鱼的体细胞有哪些共同结构？", "steps": ["先用核膜标准定类：蓝细菌无核膜、无染色体，是原核生物", "再解释光合：含叶绿素和藻蓝素及光合酶，在光合膜上完成光合，是自养生物", "联系水华危害：大量繁殖遮光、死亡后被分解者分解耗氧，导致溶氧下降", "最后找共同结构：细胞膜、细胞质、核糖体、DNA"], "talk": ["原核真核判断只认核膜，色素认藻蓝加叶绿，统一性认膜质糖体DNA"], "title": "案例：水华暴发——蓝细菌到底是敌是友"}, "intro": "细菌和草履虫看起来都只有一个细胞，但内部差别极大：一个连真正的细胞核都没有，一个结构齐全。生物学家就抓住这一条，把细胞分成两大类。\n\n分类的唯一依据是看有没有**核膜**。==根据细胞内有无以核膜为界限的细胞核，把细胞分为真核细胞和原核细胞==。这一句就是本节的总纲。\n\n原核生物里最容易考错的是**蓝细菌**和**支原体**，一个“能光合作用却不是植物”，一个“没有细胞壁却是原核”。==蓝细菌没有叶绿体却能进行光合作用，靠的是藻蓝素和叶绿素==。", "learn": [{"h": "两类细胞的划分与代表生物", "p": "**原核细胞**：没有以核膜为界限的细胞核。代表类群要成串背：**细菌**（大肠杆菌、乳酸菌等）、**蓝细菌**（旧称蓝藻，如发菜、念珠藻、颤藻）、**支原体**、**衣原体**、**放线菌**。一句话记忆：细菌、蓝细菌、支原体、衣原体、放线菌都是原核。**真核细胞**：有以核膜为界限的细胞核。包括动物、植物和**真菌**，真菌里有**酵母菌**（单细胞）、**霉菌**（青霉、曲霉）和大型**食用菌**（蘑菇、木耳）。动植物是真核这点不会错，失分全在真菌和蓝细菌上。"}, {"h": "原核细胞的结构特点", "p": "原核细胞体积一般较小。没有核膜，遗传物质是一个裸露的**环状DNA分子**，集中在称为**拟核**的区域，没有**染色体**（染色体是DNA加蛋白质，原核的DNA不与蛋白质结合成染色体）。细胞质中只有**核糖体**一种细胞器，没有线粒体、叶绿体等其他细胞器。大多数原核细胞有**细胞壁**，细菌细胞壁的主要成分是**肽聚糖**（注意：植物细胞壁是纤维素和果胶，真菌是几丁质，三者成分不要混）。部分细菌还有荚膜、鞭毛等特殊结构，但那不是所有细菌都有。"}, {"h": "蓝细菌和支原体，两个特殊分子", "p": "**蓝细菌**：细胞内含有**藻蓝素**和**叶绿素**，能进行**光合作用**，是自养生物；但它没有**叶绿体**，光合作用在细胞质和光合膜上进行。它属于原核生物，不是植物，水华的形成就与蓝细菌等大量繁殖有关。**支原体**：是目前发现的**最小、最简单的单细胞生物**，最大的特点是**没有细胞壁**，因此形态多变，也能通过某些滤膜。考试问“原核生物一定有细胞壁吗”答案是否定的，反例就是支原体。肺炎支原体引起的支原体肺炎就来自它。"}, {"h": "“菌”字辨析与真核细胞的特点", "p": "名字带“菌”不一定是细菌。规律是：名称里带**杆、球、弧、螺旋**字样的多是细菌，如大肠杆菌、肺炎链球菌（旧称肺炎双球菌）、霍乱弧菌、幽门螺杆菌；**乳酸菌**全名乳酸杆菌，也是细菌。带“菌”却是真核的有**酵母菌、霉菌、食用菌**，它们都是真菌。**真核细胞**的特点：有核膜包被的细胞核，DNA与蛋白质结合形成**染色体（染色质）**，细胞质中有多种细胞器，体积一般较大。原核与真核的统一性也要知道：都有**细胞膜**、**细胞质**、**核糖体**和**DNA**，这说明细胞具有统一性。"}], "pitfalls": ["把蓝细菌当成植物或真核生物——错。蓝细菌是原核生物，没有叶绿体，靠藻蓝素和叶绿素进行光合作用，能光合作用不等于就是植物。", "认为所有原核生物都有细胞壁、所有细菌都有细胞壁——错。支原体是原核生物但没有细胞壁，这是最常考的例外。", "把酵母菌、霉菌当成细菌（原核）——错。酵母菌和霉菌属于真菌，是真核生物，有真正的细胞核和染色体。"]}, "video": {"bvid": "BV1p54y177e6", "p": 3, "t": "细胞的多样性和统一性", "dur": "91:22", "from": "锦城大同教育·杨波生物", "vtop": ["原核与真核的分界只有一条：有没有以核膜为界限的细胞核；原核细胞只有拟核，细胞器只有核糖体一种。", "高倍镜口诀：低倍找、高倍看，换镜后只动细准焦；放大倍数等于目镜乘物镜，放大的是长度不是面积。", "显微镜成的是倒像：物像偏向哪边，玻片就往哪边移（同向移动），与直觉相反。"], "vsum": "本课两大块：先学**高倍显微镜的使用**，再按有没有真正的细胞核给细胞分类。显微镜抓三件事：结构（目镜、物镜、转换器、粗/细准焦螺旋）、步骤（对光→低倍观察→把像移到中央→转高倍→调细准焦）、成像规律（**倒像**、放大倍数＝目镜×物镜）。==换上高倍镜后视野变暗，只能用细准焦螺旋和反光镜、光圈调，绝不能再动粗准焦——会压碎玻片、丢失物像。==分类部分：**真核细胞**有以核膜为界限的细胞核，**原核细胞**只有**拟核**、只有**核糖体**一种细胞器；原核生物包括细菌、蓝细菌、支原体等。多样性背后是**统一性**：都具细胞膜、细胞质、核糖体，都以 DNA 为遗传物质。易错提醒：蓝细菌能进行光合作用但没有叶绿体；支原体没有细胞壁；病毒没有细胞结构，不属于原核生物。", "vtech": [["高倍镜四步", "看到显微镜操作题 → 按序写：对光、低倍镜下找到物像、把物像移到视野中央、转动转换器换高倍镜后只调细准焦螺旋。"], ["倒像同向移", "看到物像偏在视野左上方 → 玻片也向左上方移动，因为显微镜成倒像，像的移动方向与玻片相反。"], ["分类先看核", "看到细胞分类题 → 先看有无核膜包被的细胞核定真核原核，再验证：细胞器只剩核糖体的是原核细胞。"], ["蓝细菌陷阱", "看到「蓝藻有叶绿体」→ 判错：蓝细菌是原核生物，没有叶绿体，靠含藻蓝素和叶绿素的光合片层进行光合作用。"]], "vgaokao": []}}, "bio_b005": {"name": "细胞中的元素和化合物", "sec": 5, "secTitle": "细胞中的元素和化合物", "page": 16, "desc": "大量与微量元素；最基本元素 C；鲜重与干重的含量之最。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": [], "next": ["bio_b006", "bio_b007"], "content": {"advance": {"a": "含量高低与是否基本不是一回事。O 在鲜重中最高是因为水多。C 的特殊性在于：糖类、脂质、蛋白质、核酸等所有有机大分子都以碳原子形成的碳链为基本骨架，没有碳链就无法构建这些大分子，生命的物质基础也就不存在，所以 C 是最基本元素。", "kind": "self", "q": "为什么说 C 是组成细胞的最基本元素，而不是含量最高的 O？"}, "apply": [{"ans": 1, "opts": ["都是自由水", "晒干减自由水，烘烤减结合水", "都是结合水", "晒干减无机盐，烘烤减蛋白质"], "q": "将一粒小麦种子晒干后称重，再烘烤至恒重后称重，两次减少的重量主要是（ ）", "why": "晒干主要失去可流动的自由水，烘烤温度高会破坏细胞结构，失去与蛋白质等结合的结合水，种子也会失去活性。"}, {"ans": 2, "opts": ["糖类", "脂肪", "蛋白质", "水"], "q": "某生物组织样液检测显示含氮量较高，且干重占比最大，该化合物最可能是（ ）", "why": "蛋白质含 N，且是干重含量最高的化合物；糖类和脂肪主要含 C、H、O，不含 N，水不含 N。"}], "basics": [{"ans": 0, "opts": ["C、H、O、N、P、S、K、Ca、Mg", "Fe、Mn、Zn、Cu、B、Mo", "C、H、O、N、Fe、Zn", "O、K、Zn、Mo"], "q": "组成细胞的大量元素是（ ）", "why": "大量元素为 C、H、O、N、P、S、K、Ca、Mg 共9种；Fe、Mn、Zn、Cu、B、Mo 是微量元素。"}, {"ans": 1, "opts": ["水、糖类", "水、蛋白质", "蛋白质、水", "核酸、蛋白质"], "q": "细胞鲜重中含量最高的化合物和干重中含量最高的化合物分别是（ ）", "why": "鲜重时水占绝大部分，含量最高；除去水后的干重中，蛋白质含量最高。"}], "case": {"a": "不矛盾。前者是鲜重数据，水含量最高，水中氧元素占比高，故 O 含量最高；后者是干重数据，水被去除，蛋白质、糖类等有机物成为主体，有机物均以碳链为骨架，故 C 含量最高且占比大幅升高。这也说明 C 是最基本元素。", "hints": ["想想鲜重时什么化合物最多，它的组成元素是什么", "烘干去掉的主要是什么"], "q": "材料：某同学测得玉米细胞中 O 占65%、C 占18%，另一同学烘干后测得 C 占55%、O 占10%，两人争论谁对。问题：两人结果矛盾吗？为什么细胞干重中 C 比例大幅升高？", "steps": ["第一步：前者测的是鲜重，后者测的是干重，条件不同", "第二步：鲜重时水含量最高，水的组成元素中 O 占比例大，所以 O 最高", "第三步：烘干去掉水后，有机物比例上升，有机物以碳链为骨架，所以 C 比例大幅升高"], "talk": ["鲜重想水氧最高，干重想碳蛋白质最高"], "title": "案例：鲜重与干重的含量之争"}, "intro": "细胞里到底有哪些东西？先记一句话：**细胞**是生命活动的基本单位，不管是人、玉米还是细菌，组成它们的**元素**和**化合物**大同小异。==组成细胞的元素中，鲜重含量最高的是 O，干重含量最高的是 C；鲜重含量最高的化合物是水，干重含量最高的是蛋白质。==考试最爱在这里挖坑：把鲜重和干重、元素和化合物混着问，看清题干再下笔。", "learn": [{"h": "大量元素和微量元素怎么分", "p": "**大量元素**是指含量占生物体总重量万分之一以上的元素，有 **C、H、O、N、P、S、K、Ca、Mg** 共9种，背口诀：碳氢氧氮磷硫，钾钙镁。**微量元素**含量很少，但缺了不行，有 **Fe、Mn、Zn、Cu、B、Mo** 等，口诀：铁猛碰新木桶（Fe、Mn、B、Zn、Mo、Cu）。==大量和微量是按含量分的，不按重要性分，微量元素同样不可缺少。==比如缺 **Fe** 会影响血红蛋白合成，缺 **Zn** 会影响生长发育。"}, {"h": "C 为什么最特殊", "p": "在所有元素里，**C** 是**最基本元素**，因为糖类、脂质、蛋白质、核酸这些大分子都以碳链为骨架，没有碳就没有这些有机大分子。**基本元素**是 **C、H、O、N** 四种，它们在干重中占比最高，其中干重最高的就是 **C**。而细胞**鲜重**时水最多，水里氧多，所以鲜重最高的是 **O**。这两个最高一定要分开记：问鲜重想水，问干重想蛋白质和碳。"}, {"h": "化合物分两大类", "p": "组成细胞的**化合物**分两类：**无机物**包括 **水** 和 **无机盐**；**有机物**包括 **糖类、脂质、蛋白质、核酸**。==鲜重时水占85%左右所以最高，烘干把水去掉后，剩下的干重里蛋白质最多，约占7%-10%（鲜重计）但在干重中比例最高。==注意：元素是元素，化合物是化合物，题目问元素答 O 或 C，问化合物答水或蛋白质，千万别答串。"}], "pitfalls": ["鲜重最高元素是 O、干重最高元素是 C；鲜重最高化合物是水、干重最高化合物是蛋白质，四句话不能混。", "微量元素不是不重要，只是含量少；大量元素也不是都比微量元素重要，划分标准只有含量。", "C 是最基本元素，C、H、O、N 是基本元素，两个概念范围不同，不要写反。"]}, "video": {"bvid": "BV1p54y177e6", "p": 7, "t": "细胞中的元素和化合物", "dur": "72:32", "from": "锦城大同教育·杨波生物", "vtop": ["元素排序分干重鲜重：含量最高的元素都是 O，最基本元素是 C，基本元素是 C、H、O、N 四个。", "三组鉴定记牢：还原糖配斐林试剂（水浴、砖红色），脂肪配苏丹III（橘黄色），蛋白质配双缩脲试剂（先 A 后 B、紫色）。", "斐林与双缩脲成分相同用法不同：斐林等量混合现配现用，双缩脲先加 NaOH 再加 CuSO4 且不加热。"], "vsum": "本课两段：先认**元素与化合物**的家底，再练**三大有机物的鉴定**实验。元素部分抓排序与分类：**大量元素**（C、H、O、N、P、S、K、Ca、Mg）与**微量元素**（Fe、Mn、Zn、Cu、B、Mo 等）都不可或缺，区别只在含量多少；生物界与非生物界的**统一性**看元素种类、**差异性**看元素含量。==化合物里水含量最高、蛋白质是最多的有机物；三大鉴定实验是本课的得分点：还原糖加斐林试剂水浴出砖红色沉淀，脂肪被苏丹III 染成橘黄色，蛋白质遇双缩脲试剂变紫色。==补讲的金晶生物一集专攻鉴定实验的材料与步骤细节，正好和主讲互补。易错提醒：蔗糖和淀粉不是还原糖、斐林试剂测不出来；双缩脲试剂不加热、不用等量混合出题最爱在这两处设套。", "vtech": [["排序先问干鲜", "看到元素含量排序题 → 先确认是干重还是鲜重再下笔，两个条件下 H、N 的相对位置不同，最容易混。"], ["鉴定先对试剂", "看到鉴定材料题 → 先定检什么：还原糖斐林（水浴）、脂肪苏丹III、蛋白质双缩脲、淀粉碘液，试剂对不上直接排除。"], ["铜试剂辨析三处", "看到斐林与双缩脲比较题 → 抓三处不同：混合方式（等量混合/先 A 后 B）、要不要加热（水浴/不加热）、CuSO4 浓度与滴数。"], ["材料避开颜色", "看到选鉴定材料题 → 还原糖用苹果、梨等近白色材料避开颜色干扰，脂肪用花生种子，蛋白质用豆浆或稀释蛋清。"]], "vgaokao": []}}, "bio_b006": {"name": "检测生物组织中的糖类、脂肪和蛋白质", "sec": 6, "secTitle": "细胞中的元素和化合物", "page": 18, "desc": "斐林、双缩脲、苏丹Ⅲ、碘液四种鉴定：试剂、条件、颜色与选材规范。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b005"], "next": [], "content": {"advance": {"a": "两者浓度不同：斐林乙液 CuSO4 浓度为0.05 g/mL，双缩脲B液为0.01 g/mL。斐林试剂是甲乙混合后，Cu(OH)2与还原糖在加热条件下发生氧化还原反应生成砖红色 Cu2O，所以要等量混合、现配、水浴加热。双缩脲试剂是先用A液营造碱性环境，再滴加少量B液，Cu2+与蛋白质中的肽键络合呈紫色，不需加热，也不能混合后使用。原理不同决定了用法不同。", "kind": "self", "q": "斐林试剂和双缩脲试剂成分相似，都含 NaOH 和 CuSO4，为什么用法和现象不同？"}, "apply": [{"ans": 2, "opts": ["是还原糖", "是蛋白质", "不是还原糖，也不是蛋白质", "是淀粉"], "q": "某同学用斐林试剂鉴定蔗糖溶液，水浴加热后无砖红色，又用双缩脲试剂检测也无紫色，说明蔗糖（ ）", "why": "蔗糖不是还原糖，所以斐林试剂无砖红色；它也不是蛋白质，所以双缩脲无紫色。结论符合蔗糖的性质。"}, {"ans": 1, "opts": ["颜色更明显", "试管受热不均易炸裂且温度不易控制", "不会出现任何反应", "会变成紫色"], "q": "糖尿病患者尿液中含葡萄糖，可用斐林试剂检测。检测时若直接加热试管底部而不水浴，最可能的问题是（ ）", "why": "水浴加热是为了受热均匀、温度可控在50-65℃，直接加热易使试管炸裂、液体冲出，也不符合规范操作要求。"}], "basics": [{"ans": 1, "opts": ["先加甲液后加乙液，不需加热", "甲乙液等量混合后加入，水浴加热", "只加乙液，水浴加热", "甲乙液提前配好长期保存使用"], "q": "鉴定还原糖时使用的斐林试剂，正确的用法是（ ）", "why": "斐林试剂甲、乙液等量混合、现配现用，加入样液后需50-65℃水浴加热，出现砖红色沉淀。"}, {"ans": 2, "opts": ["蓝色、紫色", "砖红色、橘黄色", "橘黄色、紫色", "橘黄色、砖红色"], "q": "花生子叶脂肪鉴定和豆浆蛋白质鉴定的颜色分别是（ ）", "why": "脂肪+苏丹Ⅲ染液呈橘黄色，蛋白质+双缩脲试剂呈紫色。"}], "case": {"a": "甲出现砖红色沉淀，说明样液含还原糖，乳糖正是还原糖，支持含乳糖的说法；乙呈紫色，说明含蛋白质，支持富含蛋白质的说法；丙不变蓝说明不含淀粉，证明商家没有用廉价淀粉掺假。所以三项结果共同支持商家说法且排除淀粉掺假。", "hints": ["乳糖属于哪类糖？砖红色说明有什么", "碘液是验什么的，不变蓝排除了什么掺假"], "q": "材料：商家宣称某奶粉富含蛋白质且含乳糖。质检员取样液分三份：甲加斐林试剂水浴加热，乙加双缩脲试剂，丙加碘液。结果甲砖红色、乙紫色、丙不变蓝。问题：结果能支持商家的哪些说法？为什么丙不变蓝也很重要？", "steps": ["第一步：甲砖红色说明含还原糖，乳糖是还原糖，与含乳糖的说法相符", "第二步：乙紫色说明含蛋白质（或多肽），支持富含蛋白质的说法", "第三步：丙加碘液不变蓝说明不含淀粉，排除了用淀粉冒充或掺假增稠的可能"], "talk": ["斐林砖红验还原糖，双缩脲紫验蛋白，碘液蓝验淀粉"], "title": "案例：奶粉成分真假鉴定"}, "intro": "这是必修1第一个重点**鉴定实验**，高考最爱考操作细节。==还原糖用斐林试剂水浴加热出现砖红色沉淀，脂肪用苏丹Ⅲ染液呈橘黄色，蛋白质用双缩脲试剂呈紫色，淀粉用碘液呈蓝色。==四组试剂、颜色、条件必须一一对牢，尤其 **斐林试剂** 和 **双缩脲试剂** 用法完全不同，是头号陷阱。", "learn": [{"h": "还原糖鉴定：斐林试剂 + 水浴加热", "p": "**还原糖**包括 **葡萄糖、果糖、麦芽糖、乳糖**；**蔗糖、淀粉不是还原糖**，这是高频判断点。鉴定试剂是 **斐林试剂**，由甲液（质量浓度0.1 g/mL的 **NaOH**）和乙液（0.05 g/mL的 **CuSO4**）组成。==斐林试剂必须甲、乙液等量混合，现配现用，并需在50-65℃水浴加热，才会出现砖红色沉淀。==选材要用梨匀浆、苹果匀浆等含糖高且颜色浅的材料，避免材料本身颜色干扰观察。"}, {"h": "脂肪和蛋白质鉴定：一个不用加热，一个先A后B", "p": "鉴定 **脂肪** 用 **苏丹Ⅲ染液**，结果呈 **橘黄色**；也可用苏丹Ⅳ染液呈红色。做花生子叶切片时，要用体积分数 **50%的酒精洗去浮色**，再在显微镜下观察。鉴定 **蛋白质** 用 **双缩脲试剂**：==先加A液（0.1 g/mL的 NaOH）摇匀，再加B液（0.01 g/mL的 CuSO4），结果呈紫色，全程不需要加热。==豆浆、鸡蛋清稀释液是常用材料。顺序反了、把双缩脲当斐林等量混合，都是错。"}, {"h": "淀粉鉴定与选材通则", "p": "鉴定 **淀粉** 用 **碘液**，结果呈 **蓝色**，马铃薯匀浆是典型材料。==所有鉴定实验的选材通则：材料要富含待测物质，且颜色浅、无色或白色，避免遮盖反应颜色。==比如鉴定还原糖不能用西红柿、红甘蔗（颜色深），鉴定蛋白质的鸡蛋清要先稀释防止黏附试管不好清洗。对照意识也要有：最好留一部分样液作对照，证明颜色变化是试剂与待测物反应产生的。"}], "pitfalls": ["蔗糖、淀粉不是还原糖；乳糖是还原糖，常被误判为非还原糖。", "斐林试剂是等量混合现配现用+水浴加热，双缩脲试剂是先A后B不加热，两者成分浓度也不同，不能混用。", "脂肪鉴定用50%酒精是洗浮色，不是脱色或消毒；蛋白质鉴定呈紫色不是因为加热，加热反而可能干扰。"]}, "video": {"bvid": "BV1p54y177e6", "p": 7, "t": "细胞中的元素和化合物", "dur": "72:32", "from": "锦城大同教育·杨波生物", "vtop": ["元素排序分干重鲜重：含量最高的元素都是 O，最基本元素是 C，基本元素是 C、H、O、N 四个。", "三组鉴定记牢：还原糖配斐林试剂（水浴、砖红色），脂肪配苏丹III（橘黄色），蛋白质配双缩脲试剂（先 A 后 B、紫色）。", "斐林与双缩脲成分相同用法不同：斐林等量混合现配现用，双缩脲先加 NaOH 再加 CuSO4 且不加热。"], "vsum": "本课两段：先认**元素与化合物**的家底，再练**三大有机物的鉴定**实验。元素部分抓排序与分类：**大量元素**（C、H、O、N、P、S、K、Ca、Mg）与**微量元素**（Fe、Mn、Zn、Cu、B、Mo 等）都不可或缺，区别只在含量多少；生物界与非生物界的**统一性**看元素种类、**差异性**看元素含量。==化合物里水含量最高、蛋白质是最多的有机物；三大鉴定实验是本课的得分点：还原糖加斐林试剂水浴出砖红色沉淀，脂肪被苏丹III 染成橘黄色，蛋白质遇双缩脲试剂变紫色。==补讲的金晶生物一集专攻鉴定实验的材料与步骤细节，正好和主讲互补。易错提醒：蔗糖和淀粉不是还原糖、斐林试剂测不出来；双缩脲试剂不加热、不用等量混合出题最爱在这两处设套。", "vtech": [["排序先问干鲜", "看到元素含量排序题 → 先确认是干重还是鲜重再下笔，两个条件下 H、N 的相对位置不同，最容易混。"], ["鉴定先对试剂", "看到鉴定材料题 → 先定检什么：还原糖斐林（水浴）、脂肪苏丹III、蛋白质双缩脲、淀粉碘液，试剂对不上直接排除。"], ["铜试剂辨析三处", "看到斐林与双缩脲比较题 → 抓三处不同：混合方式（等量混合/先 A 后 B）、要不要加热（水浴/不加热）、CuSO4 浓度与滴数。"], ["材料避开颜色", "看到选鉴定材料题 → 还原糖用苹果、梨等近白色材料避开颜色干扰，脂肪用花生种子，蛋白质用豆浆或稀释蛋清。"]], "vgaokao": []}}, "bio_b007": {"name": "细胞中的水和无机盐", "sec": 7, "secTitle": "细胞中的无机物", "page": 20, "desc": "自由水与结合水的功能和比例；无机盐的三种功能与缺素实例。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b005"], "next": ["bio_b008"], "content": {"advance": {"a": "无机盐含量虽只占1%-1.5%，但功能关键且不可替代：一是作为某些化合物的组成成分，如Fe2+是血红蛋白的成分，缺铁会导致贫血、运输氧能力下降；Mg2+是叶绿素成分，缺镁植物不能合成叶绿素、光合受阻、老叶发黄。二是维持渗透压、酸碱平衡和神经肌肉兴奋性，如Ca2+过低抽搐、过高肌无力，Na+、K+维持细胞渗透压。含量少不等于不重要。", "kind": "self", "q": "为什么无机盐在细胞中含量很少，却说它对生命活动不可缺少？请举两例说明。"}, "apply": [{"ans": 1, "opts": ["自由水增多，代谢增强", "自由水转化为结合水，抗寒性增强", "结合水全部失去", "无机盐全部排出"], "q": "北方植物越冬时，细胞内发生的变化最合理的是（ ）", "why": "越冬时自由水减少、结合水比例升高，代谢减慢，抗寒、抗逆性增强，防止结冰破坏细胞。"}, {"ans": 1, "opts": ["提供大量能量", "维持渗透压和酸碱平衡等生命活动", "合成蛋白质", "代替水的作用"], "q": "运动员大量出汗后最好补充淡盐水，主要原因是无机盐能（ ）", "why": "汗液带走水和Na+等无机盐，补充淡盐水可维持细胞外液渗透压和正常生命活动；无机盐不供能。"}], "basics": [{"ans": 2, "opts": ["作为良好溶剂", "运输营养物质", "是细胞结构的重要组成成分", "参与光合作用供能"], "q": "结合水的主要作用是（ ）", "why": "结合水与蛋白质等结合，是细胞结构成分；溶剂、运输、参与反应主要是自由水的功能。"}, {"ans": 1, "opts": ["肌无力、新叶发黄", "抽搐、老叶发黄", "抽搐、新叶发黄", "肌无力、老叶发黄"], "q": "人体血钙过低和植物缺镁的典型症状分别是（ ）", "why": "Ca2+过低引起抽搐，过高肌无力；Mg是叶绿素成分且可再利用，缺Mg时老叶中的Mg转运至新叶，故老叶先发黄。"}], "case": {"a": "晒干主要失去自由水，自由水与结合水比值降低，种子呼吸作用等代谢活动显著减弱，有机物消耗少，同时抗逆性增强，所以能长期储存并保持萌发能力。烘烤过度则失去结合水，结合水是细胞结构成分，其丧失会破坏细胞结构和蛋白质空间结构，种子死亡，故种不活。低温干燥环境也是通过降低代谢来延长储存期。", "hints": ["晒干去掉哪种水，对代谢有什么影响", "烘烤过度去掉哪种水，为什么会死"], "q": "材料：粮仓储存小麦种子要求含水量降到安全标准以下，且要放在低温干燥处。农民说晒干的种子放一年还能种，烘烤得太干的种子反而种不活。问题：用自由水和结合水的知识解释这两个现象。", "steps": ["第一步：晒干主要减少自由水，自由水/结合水比值下降", "第二步：比值下降使呼吸等代谢大幅减弱，消耗有机物少，利于长期储存且仍保留活性", "第三步：烘烤过度会进一步夺走结合水，破坏蛋白质等结构，细胞死亡，所以不能萌发"], "talk": ["晒干去自由水保命，烘烤丢结合水要命"], "title": "案例：种子储存为什么要晒干"}, "intro": "水是细胞里最多的化合物，但水和水不一样。==自由水与结合水的比值越高，代谢越旺盛，抗逆性越差；比值越低，代谢越弱，抗逆性越强。==再加上 **无机盐** 虽然量少，缺了却会抽搐、发黄、贫血，这一节就是考比例关系和具体离子功能。", "learn": [{"h": "自由水与结合水：一个能跑，一个被绑住", "p": "**自由水** 是以游离形式存在、可以自由流动的水，占细胞内水分绝大部分。它的作用多：**良好溶剂、运输营养和废物、参与生化反应、为反应提供液体场所**。**结合水** 是与 **蛋白质** 等物质结合、不能自由流动的水，是 **细胞结构的重要组成成分**。==晒干种子主要失去自由水，代谢降到很低便于储存；烘烤种子失去结合水，细胞结构被破坏，种子会死亡、不能萌发。==休眠种子、越冬植物都会主动降低自由水比例来抗寒抗旱。"}, {"h": "比例决定代谢与抗逆性", "p": "判断题最爱这么问：**自由水/结合水** 比值高，细胞代谢旺盛，但抗逆性差，比如正在萌发的种子、生长旺盛的幼叶；比值低，代谢缓慢，抗逆性强，比如休眠种子、干旱下的植物。温度降低时，部分自由水会转化为结合水来抗冻。这不是死记，要理解：自由水是干活的水，多了反应就快；结合水是稳结构的水，多了就更耐折腾。"}, {"h": "无机盐：多以离子存在，功能分三类", "p": "细胞中的 **无机盐** 大多数以 **离子** 形式存在，如 **Na+、K+、Ca2+、Fe2+** 等。功能三类：第一，**组成细胞内某些化合物**：**Fe** 是血红蛋白成分，**Mg** 是叶绿素成分，**I** 是甲状腺激素成分；第二，**维持渗透压和酸碱平衡**：如 Na+、K+ 维持渗透压，**HCO3-、HPO4^2-** 维持酸碱平衡；第三，**维持正常生命活动**：==血钙（Ca2+）过低会抽搐，过高会肌无力；植物缺 Mg 叶绿素不能合成，老叶先发黄。==缺什么、补什么、症状是什么，要成串记。"}], "pitfalls": ["晒干损失自由水、烘烤损失结合水，不能说晒干也失去结合水；失去结合水种子会死亡。", "缺 Mg 时是老叶先发黄（Mg 可被重复利用，先转运到新叶），不是新叶先黄，不要记反。", "Ca2+ 缺乏是抽搐、过多是肌无力，两个症状方向相反，是选择题最爱对调的坑。"]}, "video": {"bvid": "BV1p54y177e6", "p": 9, "t": "细胞中的无机物", "dur": "45:56", "from": "锦城大同教育·杨波生物", "vtop": ["水是细胞中含量最多的化合物：自由水能流动，结合水被束缚；两者的比值决定代谢强弱，比值高则代谢旺、抗逆差。", "无机盐大多以离子形式存在，三大功能：构成复杂化合物、维持渗透压、维持酸碱平衡。", "晒干种子失去自由水（代谢最低、利于保存，还能萌发），烘烤失去结合水（结构破坏、不能再萌发）。"], "vsum": "本课讲细胞里的两类无机物：**水**和**无机盐**。水按状态分**自由水**（可自由流动，是良好溶剂，参与物质运输和代谢反应）和**结合水**（与其他物质结合，是细胞结构的重要组成成分）。**自由水与结合水的比值**是核心考点：比值升高时代谢旺盛、抗逆性下降；比值降低则相反，种子晒干储存、植物越冬靠的都是比值降低。==判断抗逆性看结合水占比（越高越抗旱抗寒），判断代谢强弱看自由水占比，两个方向正好相反，别记反。==**无机盐**只占 1% 到 1.5%，大多以**离子**形式存在，功能有三：组成复杂化合物（Fe²⁺ 之于血红蛋白、Mg²⁺ 之于叶绿素、I 之于甲状腺激素）、维持**渗透压**、维持**酸碱平衡**。易错提醒：无机盐含量少不等于不重要，缺铁性贫血、地方性甲状腺肿都是缺乏症的典型例子。", "vtech": [["比值题看两头", "看到自由水/结合水比值变化题 → 成对判断：比值升则代谢旺、抗逆弱；比值降则代谢弱、抗逆强。"], ["晒干烘烤分水种", "看到种子处理题 → 晒干去掉的是自由水（还能萌发），烘烤去掉的是结合水（结构破坏、失去萌发力）。"], ["缺乏症对元素", "看到贫血、甲状腺肿、抽搐等症状 → 对应元素定位：Fe 对血红蛋白、I 对甲状腺激素、Ca 对骨骼与抽搐、Mg 对叶绿素。"], ["功能题三分类", "看到无机盐功能选项 → 归到三类里核对：构成化合物、维持渗透压、维持酸碱平衡；供能和储存遗传信息都不是它的功能。"]], "vgaokao": []}}, "bio_b008": {"name": "细胞中的糖类和脂质", "sec": 8, "secTitle": "细胞中的糖类和脂质", "page": 23, "desc": "糖的分类与动植物分布；脂肪、磷脂、固醇的功能对照。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b007"], "next": ["bio_b009"], "content": {"advance": {"a": "三者基本单位虽都是葡萄糖，但葡萄糖的连接方式、分支程度和空间结构不同：淀粉有直链和支链结构，易被酶水解供能，是植物储能物质；糖原分支更多、更易快速水解，是动物储能物质；纤维素的葡萄糖以β键连接形成牢固的纤维状结构，人体缺乏分解它的酶，故不供能，只起支持作用，构成植物细胞壁。这说明多糖功能由其结构决定。", "kind": "self", "q": "淀粉、糖原、纤维素的基本单位都是葡萄糖，为什么功能却完全不同？"}, "apply": [{"ans": 1, "opts": ["含氧多、含氢少", "含氢多、含氧少", "含氮多", "相对分子质量更大"], "q": "同质量的糖类和脂肪彻底氧化，脂肪耗氧更多、放能更多，根本原因是脂肪分子（ ）", "why": "脂肪 C、H比例高、O比例低，氧化时氢与氧结合生成水需要更多氧，放能约39kJ/g，高于糖类约17kJ/g。"}, {"ans": 1, "opts": ["主要能源物质", "动物细胞膜成分并参与脂质运输", "植物细胞壁成分", "遗传物质成分"], "q": "胆固醇摄入过高有害健康，但完全不摄入也不行，因为胆固醇是（ ）", "why": "胆固醇是动物细胞膜的重要成分，还参与血液中脂质的运输，适量必需，过量才有害。"}], "basics": [{"ans": 1, "opts": ["都是2分子葡萄糖", "葡萄糖+果糖；葡萄糖+半乳糖", "葡萄糖+半乳糖；葡萄糖+果糖", "都是葡萄糖+果糖"], "q": "蔗糖和乳糖的水解产物分别是（ ）", "why": "麦芽糖水解为2分子葡萄糖，蔗糖为葡萄糖+果糖，乳糖为葡萄糖+半乳糖。"}, {"ans": 1, "opts": ["淀粉、纤维素", "糖原、纤维素", "糖原、淀粉", "脂肪、几丁质"], "q": "下列物质中，属于动物储能多糖和植物细胞壁主要成分的分别是（ ）", "why": "糖原是动物储能多糖，分肝糖原和肌糖原；纤维素是植物细胞壁主要成分，不供能。"}], "case": {"a": "糖类是主要能源物质，葡萄糖供能直接快速，肝糖原还能维持血糖稳定，长期不吃主食会导致血糖不稳、注意力下降、代谢紊乱。脂肪虽储能多（约39kJ/g），但动用和氧化较慢，是长期储备而非主要日常能源。只吃肉的减肥法还会造成纤维素和部分维生素缺乏、脂肪和胆固醇摄入过高，增加健康风险，所以不可取，应在控制总能量的前提下均衡饮食并运动。", "hints": ["糖类是什么地位，供能有什么特点", "只吃肉会缺什么，脂肪代谢有什么负担"], "q": "材料：人长时间运动时，先大量消耗血糖和糖原，后期脂肪消耗比例明显上升。有人主张不吃主食只吃肉来减肥。问题：从糖类和脂质功能角度，评价这种做法的问题。", "steps": ["第一步：糖类是主要能源物质，供能快，葡萄糖是大脑等组织的重要燃料，长期缺糖会影响正常活动", "第二步：脂肪是储能物质，供能效率高但动用慢，不能完全替代糖类的日常供能地位", "第三步：只吃肉会导致膳食纤维、某些维生素不足，蛋白质和脂肪过量还会增加肝肾和心血管负担，不符合均衡饮食"], "talk": ["糖是零钱天天花，脂肪是存折慢慢取"], "title": "案例：减肥时先消耗糖还是脂肪"}, "intro": "糖类和脂质都是能源相关分子，但分工完全不同。==糖类是主要能源物质，脂质中的脂肪是高效储能物质，1 g脂肪氧化约放39 kJ，约为糖类的2倍多，因为脂肪含氢多、含氧少。==本节考点密集：二糖由哪两个单糖拼成、多糖谁储能谁建墙，必须背准。", "learn": [{"h": "糖类分类：单糖、二糖、多糖", "p": "糖类元素组成是 **C、H、O**，多数符合 **(CH2O)n**，但有例外，如 **脱氧核糖 C5H10O4**、鼠李糖等，所以不能说所有糖都符合通式。**单糖** 不能再水解：**葡萄糖**（主要能源）、果糖、半乳糖、**核糖、脱氧核糖**（构成核酸）。**二糖** 由两分子单糖脱水缩合：==麦芽糖=2分子葡萄糖，蔗糖=葡萄糖+果糖，乳糖=葡萄糖+半乳糖；麦芽糖、蔗糖是植物特有，乳糖是动物特有。==**多糖**：**淀粉** 是植物储能，**糖原** 是动物储能（分 **肝糖原、肌糖原**），**纤维素** 是植物细胞壁成分、不供能，**几丁质** 构成甲壳类外骨骼和真菌细胞壁。"}, {"h": "脂质分类：脂肪、磷脂、固醇", "p": "脂质元素主要是 C、H、O，有些含 N、P。**脂肪** 只含 C、H、O，功能是 **储能、保温、缓冲减压**。**磷脂** 含 P、N，是构成 **细胞膜** 等生物膜的主要成分。**固醇** 包括 **胆固醇**（动物细胞膜成分、参与脂质运输）、**性激素**（促进生殖发育）、**维生素D**（促进肠道对钙磷吸收）。三类脂质功能不能张冠李戴，尤其胆固醇不是只有坏处，正常量是必需的。"}, {"h": "为什么脂肪更适合长期储能", "p": "同样1 g，糖类氧化约放 **17 kJ**，脂肪约放 **39 kJ**。原因要会解释：==脂肪分子中碳氢比例高、含氧低，氧化时需要更多氧、释放更多能量，且储能时体积小、占地少。==所以骆驼、冬眠动物、植物种子（如花生、油菜籽）多用脂肪储能。但平时细胞优先烧糖类，糖供能快，脂肪是仓库不是日常零钱，这就是糖类是主要能源物质的原因。"}], "pitfalls": ["脱氧核糖 C5H10O4 不符合 (CH2O)n 通式，不能说所有糖类都符合通式。", "纤维素是结构物质不供能，人体不能消化纤维素；糖原分肝糖原和肌糖原，肌糖原不能直接分解成葡萄糖供血糖。", "二糖组成易错：蔗糖是葡萄糖+果糖不是2个葡萄糖，乳糖含半乳糖，麦芽糖才是2个葡萄糖。"]}, "video": {"bvid": "BV1p54y177e6", "p": 11, "t": "细胞中的糖类和脂质", "dur": "62:47", "from": "锦城大同教育·杨波生物", "vtop": ["糖类按水解分三级：单糖不能水解，二糖水解出两分子单糖，多糖水解出多分子葡萄糖，基本单位都是单糖。", "脂质三类分工：脂肪储能保温，磷脂构成生物膜，固醇分胆固醇、性激素、维生素 D 三类各管一摊。", "储能多糖别混：植物用淀粉、动物用糖原；纤维素是结构物质，人不能消化、不能当能源。"], "vsum": "本课讲两类有机物：**糖类**和**脂质**。糖类由 C、H、O 组成，按水解情况分**单糖**（葡萄糖是主要能源物质，核糖、脱氧核糖是核酸的成分）、**二糖**（蔗糖、麦芽糖、乳糖）和**多糖**（淀粉、糖原、纤维素、几丁质，基本单位都是葡萄糖）。==判断一种糖先分阵营：蔗糖、麦芽糖、淀粉、纤维素是植物专属，乳糖、糖原是动物专属，葡萄糖、核糖、脱氧核糖动植物共有，归属错位就是错误选项。==**脂质**包括脂肪、磷脂和固醇：**脂肪**是良好的储能物质，还能保温、缓冲减压；**磷脂**是细胞膜等生物膜的重要成分；**固醇**中胆固醇构成动物细胞膜并参与脂质运输，性激素促进生殖器官和生殖细胞的形成，维生素 D 促进肠道对钙磷的吸收。易错提醒：同质量的脂肪比糖类放能多，因为脂肪中 H 的比例高、O 的比例低，氧化时耗氧多。", "vtech": [["糖类先分阵营", "看到一种糖的名称 → 先判植物专属、动物专属还是共有，再核对功能，归属与功能错一项即排除。"], ["储能对主语", "看到「主要储能物质」→ 先看主语：植物细胞是淀粉，动物细胞是糖原，生物体层面脂肪是良好的储能物质。"], ["脂质功能对位", "看到脂质功能选项 → 脂肪对储能保温，磷脂对构成膜，固醇三类对膜运输、生殖、钙磷吸收，错位即错。"], ["放能抓元素比例", "看到同质量糖与脂肪的放能比较 → 脂肪含 H 多、含 O 少，氧化分解耗氧多、放能约为糖类两倍以上。"]], "vgaokao": []}}, "bio_b009": {"name": "蛋白质的结构与功能", "sec": 9, "secTitle": "蛋白质是生命活动的主要承担者", "page": 28, "desc": "氨基酸通式与脱水缩合；肽键数等计算；结构多样性与五大功能；变性与盐析。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b008"], "next": ["bio_b010", "bio_b016"], "content": {"advance": {"a": "蛋白质功能多样源于结构多样：氨基酸的种类、数目、排列顺序不同形成不同的肽链，肽链盘曲折叠方式不同又形成不同的空间结构，结构决定功能。酶的活性中心能催化反应，抗体的结构能特异结合抗原起免疫作用，胰岛素的特定空间结构能与靶细胞受体结合起调节作用。三者氨基酸组成和空间结构各不相同，所以功能各异，这正是结构与功能相适应的体现。", "kind": "self", "q": "为什么蛋白质功能如此多样？请从结构角度解释，并说明酶、抗体、胰岛素同为蛋白质却功能不同。"}, "apply": [{"ans": 1, "opts": ["5100", "4218", "4214", "4400"], "q": "某蛋白质由2条肽链、51个氨基酸组成，氨基酸平均相对分子质量为100，则该蛋白质相对分子质量约为（ ）", "why": "脱水数=51-2=49，相对分子质量=51×100-18×49=5100-882=4218。"}, {"ans": 1, "opts": ["盐析、变性", "变性、盐析", "都是变性", "都是盐析"], "q": "鸡蛋煮熟后更易消化，且加盐腌制时蛋白质析出后加水又能溶解，这分别对应（ ）", "why": "煮熟是高温使蛋白质变性，空间结构展开更易被蛋白酶水解；盐析只是溶解度降低析出，加水可复溶，可逆，未变性。"}], "basics": [{"ans": 0, "opts": ["19、19", "20、20", "19、20", "20、19"], "q": "由20个氨基酸形成一条肽链，脱去的水分子数和形成的肽键数分别是（ ）", "why": "直链肽：肽键数=脱水数=氨基酸数-肽链数=20-1=19。"}, {"ans": 1, "opts": ["肽键全部断裂，不能与双缩脲试剂反应", "空间结构被破坏，肽键不断，仍可呈紫色反应", "氨基酸顺序改变", "溶解度不变，活性不变"], "q": "蛋白质变性后，下列说法正确的是（ ）", "why": "高温等使蛋白质空间结构破坏而变性，肽键不断，故仍含肽键可与双缩脲试剂呈紫色，一级结构（氨基酸顺序）不变。"}], "case": {"a": "脱去水分子49个，形成49个肽键。胰岛素相对分子质量约为51×110-18×49=4728。游离氨基至少2个，游离羧基至少2个（每条肽链至少各有一个，若R基含额外氨基或羧基则更多）。", "hints": ["肽链数是2不是1，脱水公式别漏", "游离氨基至少看肽链数"], "q": "材料：人胰岛素由A、B两条肽链共51个氨基酸组成，氨基酸平均相对分子质量约为110。问题：胰岛素形成时脱去多少水？相对分子质量约为多少？至少有多少个游离氨基？", "steps": ["第一步：脱水数=氨基酸数-肽链数=51-2=49", "第二步：相对分子质量=51×110-18×49=5610-882=4728", "第三步：每条肽链至少一端有一个游离氨基，2条链至少2个，R基上可能更多"], "talk": ["肽键等于氨减链，水量十八要扣完"], "title": "案例：胰岛素的肽链计算"}, "intro": "蛋白质是干重第一、功能最全的有机物，计算题也全在这里。==脱水缩合时，肽键数=脱去水分子数=氨基酸数-肽链数；蛋白质相对分子质量=氨基酸数×平均相对分子质量-18×脱去水分子数。==公式先记死，再理解 **R基** 和空间结构，计算和概念两头都不能丢。", "learn": [{"h": "氨基酸通式与脱水缩合", "p": "组成蛋白质的氨基酸现行教材口径有 **21种**。每个氨基酸都有一个中心碳原子，连接 **氨基（-NH2）、羧基（-COOH）、氢原子和R基**，这就是 **氨基酸结构通式**。==不同氨基酸的区别就在R基，R基决定氨基酸种类。==两个氨基酸脱去一分子水，氨基和羧基之间形成 **肽键（-CO-NH-）**，这个过程叫 **脱水缩合**，在核糖体上完成。多条链或一条长链盘曲折叠，形成有特定空间结构的蛋白质。"}, {"h": "计算三件套：肽键、水、分子量", "p": "设氨基酸数 n、肽链数 m、氨基酸平均相对分子质量 a。则 **肽键数 = 脱水数 = n - m**。**蛋白质相对分子质量 = n×a - 18×(n-m)**。**游离氨基数和游离羧基数至少等于肽链数 m**（R基上可能还有额外的氨基或羧基，所以是至少）。环状肽比较特殊：肽键数 = 氨基酸数，脱水数也等于氨基酸数，遇到环状要单独处理。做题先判断直链还是环状，再套公式。"}, {"h": "多样性、功能与变性", "p": "蛋白质结构多样性的原因有四：**氨基酸种类不同、数目不同、排列顺序不同、肽链盘曲折叠方式不同**。功能五大类要配例子：**催化**（酶）、**运输**（血红蛋白运氧）、**免疫**（抗体）、**调节**（胰岛素）、**结构**（毛发、指甲、胶原蛋白）。==高温、强酸、强碱使蛋白质变性，破坏的是空间结构，肽键不断，变性后的蛋白质仍能与双缩脲试剂呈紫色；盐析是可逆的，只是溶解度降低而析出，结构和活性不变。==变性与盐析的区别是送分也是送命题，看清是否可逆。"}], "pitfalls": ["游离氨基/羧基数是至少等于肽链数，R基上可能有额外氨基或羧基，不能直接写等于。", "变性破坏空间结构不断肽键，所以双缩脲反应仍呈紫色；说变性后肽键断裂是错的。", "环状肽的肽键数等于氨基酸数，不是氨基酸数减肽链数，套直链公式会错。"]}, "video": {"bvid": "BV1p54y177e6", "p": 13, "t": "蛋白质是生命活动的主要承担者", "dur": "105:30", "from": "锦城大同教育·杨波生物", "vtop": ["蛋白质的功能记住口诀“狗催运面条”：结构、催化、运输、免疫、调节，绝大多数酶的化学本质就是蛋白质。", "脱水缩合是本课的计算根基：一个氨基酸的羧基脱 -OH、另一个的氨基脱 -H，脱一分子水、形成一个肽键；脱去水分子数等于肽键数，等于氨基酸数减肽链数。", "算氧原子数抓公式：氧原子数等于肽键数加肽链数乘 2 再加 R 基上的氧原子数；环状肽里氨基酸数、水分子数、肽键数三者相等。"], "vsum": "本课回答一个根问题：蛋白质为什么是**生命活动的主要承担者**，以及相关的数怎么算。先看结构：蛋白质由**氨基酸**构成，氨基酸的中心碳原子上连着**氨基**、**羧基**、氢和 R 基；人体有 8 种**必需氨基酸**必须从食物中获取。功能上抓口诀“狗催运面条”：**结构蛋白**构成细胞与生物体、绝大多数**酶**起催化作用、**血红蛋白**运输氧气、**抗体**抵御病菌、蛋白质还能传递信息、调节生命活动。再看形成：氨基酸通过**脱水缩合**连接，一个羧基脱 -OH、一个氨基脱 -H，脱一分子水、形成一个**肽键**；肽链再盘曲折叠形成**空间结构**，一级到四级逐级复杂。==脱水缩合的数是全部计算的根：脱去水分子数等于肽键数，等于氨基酸数减肽链数；氧原子数等于肽键数加肽链数乘 2 再加 R 基上的氧原子数。==第二讲专攻计算：**相对分子质量**等于氨基酸总质量减 18 乘脱去水分子数；多肽分子式可以列方程反推氨基酸总数与赖氨酸个数；**环状肽**里氨基酸数、水分子数、肽键数三者相等。易错提醒：变性破坏的是空间结构、常不可逆，但盐析只是溶解度变化、加水还能复原；两个肽键的不叫二肽，二肽是由两个氨基酸脱水缩合形成的；A-B 与 B-A 是两种不同的二肽。", "vtech": [["功能题先念口诀", "看到蛋白质功能题 → 先念“狗催运面条”：结构、催化、运输、免疫、调节，五项逐一核对，绝大多数酶是蛋白质、抗体是蛋白质，这两处最爱考。"], ["脱水数先定三数", "看到脱水缩合计算题 → 先定三个数：氨基酸数、肽链数、水分子数，脱去水分子数等于肽键数等于氨基酸数减肽链数，环状肽里三者相等。"], ["氧原子数套公式", "看到氧原子数题 → 套公式：氧原子数等于肽键数加肽链数乘 2 再加 R 基上的氧原子数；问“至少”时 R 基上的氧原子数按 0 算。"], ["二肽题看个数", "看到二肽判断题 → 只数氨基酸个数：两个氨基酸脱水缩合才叫二肽，两个肽键的是三肽；A-B 与 B-A 顺序不同就是两种二肽，不能倒过来看。"]], "vgaokao": []}}, "bio_b010": {"name": "核酸的结构与功能", "sec": 10, "secTitle": "核酸是遗传信息的携带者", "page": 34, "desc": "核苷酸组成；DNA 与 RNA 的五项区别；谁的遗传物质是谁。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b009"], "next": [], "content": {"advance": {"a": "核酸分子中核苷酸的排列顺序储存着遗传信息。DNA中脱氧核苷酸的排列顺序千变万化，决定了遗传信息的多样性；特定的排列顺序又决定了特定蛋白质中氨基酸的顺序，从而控制生物性状。RNA也能储存和传递遗传信息（如RNA病毒以RNA为遗传物质，细胞中mRNA把DNA信息传递到核糖体）。所以核酸通过核苷酸序列承载、传递和表达遗传信息，是遗传信息的载体。", "kind": "self", "q": "为什么说核酸是遗传信息的载体？核苷酸的排列顺序有什么意义？"}, "apply": [{"ans": 2, "opts": ["都是DNA", "都是RNA", "RNA、DNA", "DNA、RNA"], "q": "新冠病毒和噬菌体的遗传物质分别是（ ）", "why": "新冠病毒为RNA病毒，遗传物质是RNA；噬菌体为DNA病毒，遗传物质是DNA。病毒遗传物质是DNA或RNA，因种类而异。"}, {"ans": 1, "opts": ["1种核酸、4种核苷酸", "2种核酸、8种核苷酸", "2种核酸、4种核苷酸", "1种核酸、8种核苷酸"], "q": "大肠杆菌（含拟核和质粒）含有的核酸和核苷酸种类分别是（ ）", "why": "大肠杆菌是细胞生物，同时含DNA和RNA两种核酸，故含脱氧核苷酸和核糖核苷酸共8种，遗传物质是DNA。"}], "basics": [{"ans": 1, "opts": ["4、4、1", "8、5、2", "8、4、2", "4、5、2"], "q": "组成核酸的核苷酸种类、碱基种类和五碳糖种类分别是（ ）", "why": "脱氧核苷酸4种+核糖核苷酸4种=8种核苷酸；碱基A、T、C、G、U共5种；五碳糖脱氧核糖和核糖共2种。"}, {"ans": 1, "opts": ["DNA有U，RNA有T", "DNA有T，RNA有U", "两者碱基完全相同", "DNA没有A，RNA没有C"], "q": "DNA与RNA在碱基上的区别是（ ）", "why": "DNA碱基为A、T、C、G，RNA碱基为A、U、C、G，DNA特有T，RNA特有U。"}], "case": {"a": "该核酸含尿嘧啶U而不含胸腺嘧啶T，且为单链，符合RNA的特征，所以禽流感病毒的核酸是RNA，其遗传物质是RNA。但病毒的遗传物质是DNA或RNA因病毒而异，如噬菌体、乙肝病毒的遗传物质是DNA，因此不能说所有病毒的遗传物质都是RNA，只能具体病毒具体判断。", "hints": ["含U是哪个核酸的标志，含T又是哪个", "想想噬菌体是什么病毒"], "q": "材料：禽流感病毒检测时，实验室先提取病毒核酸，发现其碱基中含U不含T，且为单链。问题：据此可判断该病毒的核酸类型和遗传物质是什么？为什么不能说所有病毒遗传物质都是这类核酸？", "steps": ["第一步：含U不含T是RNA的特征，单链也符合RNA多为单链的特点，判断为RNA", "第二步：病毒的遗传物质就是它自身的核酸，所以该病毒遗传物质是RNA", "第三步：病毒种类不同核酸不同，如噬菌体含DNA，其遗传物质是DNA，故不能一概而论"], "talk": ["有U定RNA，有细胞定DNA，病毒要分家"], "title": "案例：禽流感病毒的核酸检测"}, "intro": "核酸是遗传信息的载体，这节数字特别多，必须数清。==核苷酸共8种，碱基共5种，五碳糖共2种；DNA碱基是A、T、C、G，RNA碱基是A、U、C、G。==再记一句定生死的话：**细胞生物的遗传物质都是 DNA，病毒的遗传物质是 DNA 或 RNA**，不能一概而论。", "learn": [{"h": "基本单位：核苷酸由三部分组成", "p": "**核酸** 包括 **DNA（脱氧核糖核酸）** 和 **RNA（核糖核酸）**。基本单位是 **核苷酸**，一分子核苷酸由 **一分子磷酸 + 一分子五碳糖 + 一分子含氮碱基** 组成。五碳糖是脱氧核糖的是 **脱氧核苷酸**（4种，构成DNA），是核糖的是 **核糖核苷酸**（4种，构成RNA），所以核苷酸一共 **8种**。碱基共有 **A、T、C、G、U** 5种，五碳糖有脱氧核糖和核糖 **2种**，这组 8、5、2 数字必考。"}, {"h": "DNA与RNA的区别与分布", "p": "区别看三点：五碳糖不同（脱氧核糖 vs 核糖）、碱基不完全相同（DNA有 **T** 无U，RNA有 **U** 无T，共同的是 A、C、G）、结构不同（DNA多为双链，RNA多为单链）。分布上，==DNA主要分布在细胞核，线粒体和叶绿体中也有少量DNA；RNA主要分布在细胞质。==原核细胞没有成形细胞核，DNA主要在拟核。不要写 DNA 只在细胞核，那会漏掉线粒体和叶绿体。"}, {"h": "遗传物质的判断口径", "p": "**核酸是遗传信息的载体**，在生物体的遗传、变异和蛋白质合成中起重要作用。判断遗传物质要分对象：==所有细胞生物（原核和真核）的遗传物质都是DNA；病毒没有细胞结构，它的遗传物质是DNA或RNA，二选一。==如 **噬菌体** 的遗传物质是 DNA，**新冠病毒、HIV、流感病毒** 的遗传物质是 RNA。题目问某种生物的遗传物质，先看它有没有细胞，有细胞答DNA，无细胞的病毒再看具体种类。老教材的甲基绿吡罗红观察核酸分布实验现行教材已删，只作了解，不要当必考实验来答。"}], "pitfalls": ["核苷酸8种、碱基5种、五碳糖2种，数字不能记串；只问DNA时核苷酸是4种、碱基是4种。", "病毒遗传物质是DNA或RNA，不能说病毒遗传物质都是RNA，也不能说所有生物遗传物质都是DNA。", "DNA主要在细胞核，但线粒体、叶绿体也有；RNA主要在细胞质，细胞核中也有少量RNA。"]}, "video": {"bvid": "BV1p54y177e6", "p": 17, "t": "核酸是遗传信息的携带者", "dur": "64:14", "from": "锦城大同教育·杨波生物", "vtop": ["DNA 主要分布在细胞核中、RNA 主要分布在细胞质中，“主要”两个字是考点：两处都有对方的少量分布。", "核苷酸由磷酸、五碳糖、含氮碱基三部分构成；五碳糖是核糖就是核糖核苷酸、是脱氧核糖就是脱氧核苷酸，DNA 与 RNA 的基本单位各四种。", "遗传信息不是遗传物质：核酸是遗传物质，遗传信息是核酸上核苷酸的排列顺序；细胞生物有 8 种核苷酸、5 种碱基，病毒只有 4 种核苷酸、4 种碱基。"], "vsum": "本课回答一个根问题：**核酸**为什么是**遗传信息的携带者**。先看种类与分布：核酸分两类，**DNA**（脱氧核糖核酸）与 **RNA**（核糖核酸）；**DNA 主要分布在细胞核中**（染色体上，线粒体、叶绿体里有少量），**RNA 主要分布在细胞质中**（细胞核里也有少量）。再看结构：核酸的基本单位是**核苷酸**，由**磷酸**、**五碳糖**、**含氮碱基**三部分构成；五碳糖是**核糖**就是核糖核苷酸、是**脱氧核糖**就是脱氧核苷酸；核苷酸之间通过**脱水缩合**连成长链。==DNA 与 RNA 的区别要成串记：DNA 的基本单位是四种脱氧核苷酸、一般是双链的双螺旋结构；RNA 的基本单位是四种核糖核苷酸、一般是单链；DNA 有胸腺嘧啶、RNA 有尿嘧啶，这是两者碱基的唯一不同。==最后是功能与辨析：**核酸是细胞内携带遗传信息的物质**，遗传信息就是**核苷酸的排列顺序**，不要把遗传信息与遗传物质搞混。易错提醒：细胞生物既有 DNA 又有 RNA，核苷酸 8 种、碱基 5 种；DNA 病毒只有 DNA、RNA 病毒只有 RNA，各 4 种核苷酸、4 种碱基；脂肪不是生物大分子，高中阶段的生物大分子只有多糖、蛋白质、核酸三种。", "vtech": [["分布题抓“主要”", "看到 DNA/RNA 分布题 → 先抓“主要”两个字：DNA 主要在细胞核、RNA 主要在细胞质；“主要”意味着另一处也有少量，问“只分布在”时要警惕。"], ["单位题先定五碳糖", "看到核苷酸种类题 → 先定五碳糖：核糖对应核糖核苷酸（RNA）、脱氧核糖对应脱氧核苷酸（DNA）；再按碱基分四种，DNA 有 T 无 U、RNA 有 U 无 T。"], ["种类题按生物分", "看到核苷酸/碱基种类题 → 先按生物分：细胞生物（真核+原核）8 种核苷酸、5 种碱基；DNA 病毒 4 种核苷酸、4 种碱基；RNA 病毒同样 4 种。"], ["遗传信息看顺序", "看到遗传信息题 → 抓排列顺序：遗传信息是核苷酸的排列顺序，不是核酸本身；不同个体的核苷酸种类数目基本相同，区别在排列顺序。"]], "vgaokao": []}}, "bio_b011": {"name": "细胞膜的结构和功能", "sec": 11, "secTitle": "细胞膜的结构和功能", "page": 40, "desc": "流动镶嵌模型；三种信息交流方式；哺乳动物成熟红细胞制膜的道理。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": [], "next": ["bio_b012", "bio_b014"], "content": {"advance": {"a": "说法错误。流动性是细胞膜的结构特点，指磷脂分子和大多数蛋白质分子可以运动，如荧光标记的小鼠细胞与人细胞融合实验、变形虫的变形运动、白细胞吞噬病菌都证明膜具有流动性。选择透过性是细胞膜的功能特点，指膜对物质进出具有选择性，如活细胞能让营养物质进入、排出废物，而死细胞膜失去选择性、染料可自由进入使细胞被染色。结构上的流动性是实现选择透过等功能的基础，但两者概念不同，不能等同。", "kind": "self", "q": "有人说：细胞膜的流动性就是选择透过性，两者是一回事。请判断并说明理由，并各举一个实验证据。"}, "apply": [{"ans": 1, "opts": ["涨破是因为细胞壁被撑破", "内容物流出后剩余结构主要是细胞膜", "涨破说明细胞膜失去了选择透过性这一结构特点", "可用植物细胞重复此实验得到同样纯净的膜"], "q": "将哺乳动物成熟红细胞放入蒸馏水中，一段时间后细胞涨破。下列分析正确的是（ ）", "why": "哺乳动物红细胞无细胞壁，靠渗透吸水涨破，剩余主要是细胞膜。选择透过性是功能特点不是结构特点；植物细胞有壁不会涨破且膜不纯净。"}, {"ans": 2, "opts": ["磷脂", "胆固醇", "糖蛋白", "水"], "q": "癌细胞容易分散和转移，与细胞膜成分改变有关。研究发现癌细胞膜上某种成分减少，导致黏着性降低。该成分最可能是（ ）", "why": "糖蛋白与细胞识别、黏连有关。癌细胞膜上糖蛋白减少，细胞间黏着性降低，所以癌细胞容易扩散转移，这是高频考点。"}], "basics": [{"ans": 0, "opts": ["人成熟的红细胞", "人成熟的白细胞", "鸡的红细胞", "植物叶肉细胞"], "q": "制备纯净的细胞膜时，最佳实验材料是（ ）", "why": "人成熟红细胞无细胞核和众多细胞器，膜成分纯净。白细胞有核有细胞器；鸡红细胞有细胞核；叶肉细胞有细胞壁、细胞核和叶绿体等，均不适合。"}, {"ans": 2, "opts": ["磷脂单分子层构成膜的基本支架", "蛋白质在膜中均匀静止分布", "磷脂双分子层构成基本支架，蛋白质可镶嵌、嵌入或贯穿其中", "糖被分布在细胞膜的内表面"], "q": "下列关于细胞膜流动镶嵌模型的叙述，正确的是（ ）", "why": "基本支架是磷脂双分子层；蛋白质和磷脂大多能运动，并非静止；糖被只在膜外表面。"}, {"ans": 1, "opts": ["通过化学物质传递信息", "通过细胞直接接触传递信息", "通过胞间连丝传递信息", "通过自由扩散传递信息"], "q": "精子和卵细胞之间的识别与结合，主要体现了细胞膜哪种信息交流方式（ ）", "why": "精卵识别靠相邻细胞膜直接接触和信号分子与受体结合，属于直接接触方式；胞间连丝是植物细胞特有的通道方式。"}], "case": {"a": "(1)属于通过化学物质（如激素）传递信息的方式。(2)只有靶细胞的细胞膜外表面有与胰岛素特异性结合的受体（糖蛋白），胰岛素与受体结合后才能引发细胞内代谢变化；其他细胞缺乏该受体，不能识别胰岛素。(3)体现了细胞膜能进行细胞间的信息交流，且这种交流具有特异性，基础是膜上蛋白质（受体）和糖被的识别作用。", "hints": ["先看传递媒介：靠血液运输的化学物质", "靶细胞膜外表面有能识别胰岛素的受体，本质是糖蛋白", "信息交流离不开膜的选择性和识别能力"], "q": "材料：胰岛B细胞分泌的胰岛素随血液运往全身，只有肝细胞、肌肉细胞等靶细胞能响应并加速摄取葡萄糖，其他细胞几乎不受影响。结合细胞膜结构回答：(1)胰岛素的传递属于细胞间信息交流的哪种方式？(2)为什么只有靶细胞能响应？(3)这体现了细胞膜的什么功能特点？", "steps": ["第一步：胰岛素是化学物质，随血液到达靶细胞，属于通过化学物质传递信息的方式", "第二步：靶细胞膜上有胰岛素受体（糖蛋白），能特异性识别并结合胰岛素，其他细胞无此受体所以不响应", "第三步：识别与结合体现细胞膜进行信息交流的功能，膜成分中蛋白质和糖被决定了这种特异性"], "talk": ["看到激素、递质随体液运输就是化学物质传递；看到两细胞贴在一起就是直接接触；看到植物就想胞间连丝。"], "title": "案例：胰岛素如何让远处细胞收到降血糖信号"}, "intro": "先想一个问题：细胞为什么不会把里面的东西全漏出去，外面的东西也不会随便进来？靠的就是最外边这层 **细胞膜**。==细胞膜既是细胞的边界，又能有选择地控制物质进出，还能传递信息。== 制备纯净细胞膜有个经典选材：用 **哺乳动物成熟的红细胞**，因为它 **没有细胞核和众多细胞器**，吸水涨破后剩下的主要就是细胞膜，不会混进核膜和细胞器膜。记住这个选材理由，考试年年考。", "learn": [{"h": "一、制备细胞膜：为什么偏偏选哺乳动物成熟红细胞", "p": "选材三要点：第一，哺乳动物成熟红细胞 **无细胞核、无细胞器**，提取到的膜成分单一、纯净；第二，材料易得；第三，方法简单。实验方法是把红细胞放入 **蒸馏水** 中，红细胞靠 **渗透作用** 大量吸水涨破，内容物流出，再用 **差速离心** 法就能分离得到细胞膜。注意：鸡、鱼、蛙的红细胞都有细胞核，不能用；普通动物细胞有核有细胞器，也不能用。==只有哺乳动物成熟红细胞同时满足无核、无细胞器这两个条件。=="}, {"h": "二、细胞膜的成分：脂质为主，蛋白质决定功能", "p": "细胞膜主要由 **脂质** 和 **蛋白质** 组成，还有少量 **糖类**。比例大致记：脂质约占 50%，其中以 **磷脂** 最丰富，动物细胞膜还含少量 **胆固醇**；蛋白质约占 40%；糖类占 2%～10%。功能越复杂的细胞膜，蛋白质的种类和数量越多——比如神经细胞膜要传信号，蛋白质就多。==细胞膜功能复杂程度主要由蛋白质的种类和数量决定。== 糖类大多与蛋白质结合成 **糖蛋白**，或与脂质结合成糖脂，分布在膜外侧。"}, {"h": "三、流动镶嵌模型：基本支架加可动的蛋白质", "p": "现在公认的模型叫 **流动镶嵌模型**。内容分三层记：第一，**磷脂双分子层** 构成膜的 **基本支架**，磷脂亲水的头朝外、疏水的尾朝内；第二，蛋白质以 **镶嵌、嵌入、贯穿** 三种方式排在磷脂层中，有的在表面，有的扎进去，有的横穿整层，横穿的常形成通道；第三，膜外表面有 **糖被**，就是糖蛋白和糖脂露出的糖链，与 **细胞识别、信息交流、免疫** 有关，消化道和呼吸道上皮的糖被还有保护润滑作用。磷脂分子和大多数蛋白质都能运动，所以膜具有 **流动性**，这是结构特点；膜能选择性地让物质通过，叫 **选择透过性**，这是功能特点。两个特点千万别混：==流动性是结构特点，选择透过性是功能特点。=="}, {"h": "四、细胞膜的三大功能与信息交流的三种方式", "p": "功能一：**将细胞与外界环境分隔开**，保障内部环境相对稳定。功能二：**控制物质进出细胞**，需要的营养可以进、废物要排出、病菌大多被挡住，但这种控制是相对的，病毒有时也能溜进来。功能三：**进行细胞间的信息交流**，有三种方式要分清：①通过 **化学物质** 传递，如激素、神经递质随血液或体液到达靶细胞，与受体结合；②细胞 **直接接触** 传递，如 **精子和卵细胞的识别与结合**、免疫细胞识别抗原；③通过 **通道** 传递，如植物细胞间的 **胞间连丝**。考试最爱把三种方式混在一起让你选，一定要对号入座。"}, {"h": "五、细胞壁：植物细胞的外套，全透性", "p": "植物细胞在细胞膜外还有一层 **细胞壁**，主要成分是 **纤维素和果胶**，对细胞起 **支持和保护** 作用。细胞壁是 **全透性** 的，水和溶质都能自由通过，所以它不控制物质进出，控制进出的仍然是里面的细胞膜。细菌细胞壁成分是肽聚糖，真菌是几丁质，别跟植物搞混。==植物细胞壁全透不控质，真正控制物质进出的是细胞膜。=="}], "pitfalls": ["制备细胞膜必须用哺乳动物成熟红细胞；人的成熟红细胞可以，鸡血红细胞有细胞核，不可以。", "流动性是结构特点，选择透过性是功能特点，两者不能互换表述。", "糖被只在细胞膜外表面，膜内表面没有；糖蛋白与识别有关，但不是所有糖都与蛋白质结合，还有糖脂。", "细胞壁是全透性的，不具有选择透过性；细菌细胞壁不是纤维素和果胶，而是肽聚糖。", "细胞膜控制物质进出是相对的，不能说成绝对阻止有害物质进入。"]}, "video": {"bvid": "BV1p54y177e6", "p": 19, "t": "细胞膜的结构和功能", "dur": "65:00", "from": "锦城大同教育·杨波生物", "vtop": ["细胞膜的功能高中只考三点：一是将细胞与外界环境分隔开（最重要），二是控制物质进出细胞，三是进行细胞间的信息交流。", "细胞膜的成分记住比例：脂质约占 50%、蛋白质约占 40%、糖类约占 2% 到 10%，基本支架是磷脂双分子层。", "流动镶嵌模型的核心就两点：磷脂双分子层构成基本支架、蛋白质分子镶嵌其中，膜是流动的、不是静止的三层结构。"], "vsum": "本课进入第三章：**细胞的基本结构**，先讲**细胞膜的结构和功能**。功能上高中只考三点，要一字不落背下来：**将细胞与外界环境分隔开**（最重要，正是有了细胞膜，细胞才成为相对独立的系统）、**控制物质进出细胞**（活细胞的细胞膜具有**选择透过性**）、**进行细胞间的信息交流**（三种方式：信号分子与受体结合、细胞膜直接接触如精卵识别、形成通道让携带信息的物质通过）。再看探索历程：欧文顿发现脂溶性物质容易通过细胞，推测膜由脂质组成；制备细胞膜选**哺乳动物成熟的红细胞**，因为它没有细胞壁、没有细胞核和细胞器，吸水涨破后最容易得到纯净的细胞膜。==成分上抓比例与支架：脂质约占 50%、蛋白质约占 40%、糖类约占 2% 到 10%，**磷脂双分子层**构成膜的基本支架，蛋白质分子镶嵌其中，有贯穿、嵌入、覆盖在表面三种位置；糖类与蛋白质结合形成**糖蛋白**，与识别有关。==结构模型上：电镜下看到暗-亮-暗三层结构，罗伯特森据此提出蛋白质-脂质-蛋白质的静态三层模型，但膜不是静止的，1972 年的**流动镶嵌模型**才是正确结论：膜具有**流动性**，注射后不会留下空洞、水分子可以自由通过。易错提醒：构成细胞膜的脂质主要是磷脂，胆固醇也有但不是主要的；细胞膜的控制作用是相对的，不是绝对的。", "vtech": [["功能题背三点", "看到细胞膜功能题 → 背三点：一是将细胞与外界环境分隔开（最重要）、二是控制物质进出细胞、三是进行细胞间的信息交流；换词就可能变意，须一字不落。"], ["成分题抓比例", "看到细胞膜成分题 → 抓比例：脂质约占 50%、蛋白质约占 40%、糖类约占 2% 到 10%；问“基本支架”答磷脂双分子层，问“主要脂质”答磷脂。"], ["模型题看流动", "看到流动镶嵌模型题 → 抓“流动”二字：膜是流动的不是静止的；注射后不留空洞、水分子自由通过，都是流动性的证据；罗伯特森的三层静态模型是错的。"], ["制备题选红细胞", "看到制备细胞膜题 → 选哺乳动物成熟的红细胞：没有细胞壁、没有细胞核、没有细胞器，吸水涨破后最容易得到纯净的细胞膜。"]], "vgaokao": []}}, "bio_b012": {"name": "细胞器之间的分工合作", "sec": 12, "secTitle": "细胞器之间的分工合作", "page": 46, "desc": "八大细胞器结构功能对照；分泌蛋白的合成运输路径；生物膜系统。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b011"], "next": ["bio_b013"], "content": {"advance": {"a": "线粒体和叶绿体内都含有少量 DNA 和核糖体，能自主合成一部分自身所需的蛋白质，不完全依赖细胞核控制，所以称为半自主性细胞器；但它们的大部分蛋白质仍由核基因编码、在细胞质核糖体上合成后运入，因此离不开细胞核的控制。两者都是双层膜、DNA 呈环状、核糖体大小与细菌相近，这些特征支持内共生学说：线粒体可能起源于被原始真核细胞吞噬的好氧细菌，叶绿体可能起源于被吞噬的蓝细菌（光合细菌），考试中作为结构与功能相适应的例证使用即可。", "kind": "self", "q": "为什么说线粒体和叶绿体是半自主性细胞器？它们与原核生物有什么渊源提示？"}, "apply": [{"ans": 1, "opts": ["中心体特别发达，液泡大", "粗面内质网和高尔基体发达，线粒体较多", "叶绿体发达，基粒多", "溶酶体特别多，核糖体很少"], "q": "某细胞能大量合成分泌抗体，其细胞结构特点最可能是（ ）", "why": "抗体是分泌蛋白，需要大量核糖体合成、粗面内质网和高尔基体加工运输，线粒体供能，所以这三类结构发达。浆细胞就是典型例子。"}, {"ans": 1, "opts": ["溶酶体只存在于肺细胞中", "溶酶体内含水解酶，其膜破裂会损伤细胞自身", "线粒体是消化车间", "硅尘能促进有氧呼吸"], "q": "硅肺患者肺部细胞受损的原因是：吞噬细胞吸入硅尘后，硅尘被吞噬并进入溶酶体，但溶酶体膜被硅尘破坏，水解酶释放导致细胞死亡。这说明（ ）", "why": "溶酶体是消化车间，含多种水解酶，正常时膜将其与细胞质分隔；膜破裂后酶外泄会水解自身结构，导致细胞死亡，正好说明生物膜的分隔作用。"}], "basics": [{"ans": 1, "opts": ["核糖体和中心体", "线粒体和叶绿体", "内质网和高尔基体", "溶酶体和液泡"], "q": "下列细胞器中，具有双层膜结构的是（ ）", "why": "双层膜只有线粒体和叶绿体；核糖体、中心体无膜；内质网、高尔基体、溶酶体、液泡均为单层膜。"}, {"ans": 2, "opts": ["线粒体", "液泡", "叶绿体", "高尔基体"], "q": "在高等植物的根尖成熟区细胞中，一般不存在的细胞器是（ ）", "why": "根尖细胞不见光，无叶绿体，不能进行光合作用；根尖成熟区有大液泡，有线粒体和高尔基体。"}, {"ans": 2, "opts": ["高尔基体→内质网→核糖体→细胞膜", "核糖体→高尔基体→内质网→细胞膜", "核糖体→内质网→高尔基体→细胞膜", "内质网→核糖体→高尔基体→细胞膜"], "q": "用 3H 标记的亮氨酸追踪分泌蛋白，标记物在细胞中出现的先后顺序是（ ）", "why": "分泌蛋白在附着型核糖体上合成，进入内质网初步加工，再经囊泡到高尔基体加工包装，最后经囊泡与细胞膜融合分泌出细胞，线粒体全程供能。"}], "case": {"a": "(1)依次经过：核糖体（合成多肽）→内质网（初步加工）→囊泡→高尔基体（加工、分类、包装）→囊泡→细胞膜（分泌到细胞外）。(2)由线粒体提供能量。(3)说明生物膜系统在结构上具有一定的连续性、成分相似，可以通过囊泡相互转化（体现膜的流动性）；在功能上各细胞器分工明确又紧密合作，共同完成分泌蛋白的合成与运输，细胞是一个统一的整体。", "hints": ["按时间顺序排：先合成、再加工、再包装、最后分泌", "供能车间是线粒体，有氧呼吸主要场所", "囊泡出芽和融合说明膜之间可转化、膜具有流动性"], "q": "材料：乳腺细胞合成分泌酪蛋白到细胞外。研究者用 3H 标记氨基酸培养乳腺细胞，3 分钟时放射性出现在附有核糖体的内质网附近，17 分钟时集中到高尔基体，117 分钟时出现在靠近细胞膜的囊泡和细胞外。结合材料回答：(1)酪蛋白从合成到分泌依次经过哪些结构？(2)能量由哪种细胞器提供？(3)这一过程说明生物膜在结构和功能上有什么联系？", "steps": ["第一步：根据放射性出现的先后，判定顺序为核糖体合成→内质网加工→高尔基体再加工包装→囊泡运至细胞膜分泌", "第二步：整个合成、加工、运输过程耗能，由线粒体有氧呼吸提供 ATP", "第三步：内质网出芽形成囊泡与高尔基体融合，高尔基体再出芽与细胞膜融合，说明各种生物膜成分相似、可相互转化，功能上分工又合作"], "talk": ["分泌蛋白路线一句话：核糖体造、内质网粗加工、高尔基体精包装、囊泡送到膜外，线粒体全程供电。"], "title": "案例：从一杯牛奶蛋白看分泌蛋白的旅程"}, "intro": "如果把细胞比作一座工厂，细胞膜是围墙，细胞核是总控制室，那中间忙活的就是各种 **细胞器**——分工明确、各干一摊，又互相配合。==细胞器分工合作、生物膜系统协调统一，共同完成细胞的生命活动。== 这一节是全章分量最重的一节，膜层数、分布、功能错一个就丢分，必须逐个过。记法就一条：结构决定功能，看到双层膜、单层膜、无膜，先把分类立住，后面全顺了。", "learn": [{"h": "一、先分类：按膜层数把八大细胞器一网打尽", "p": "双层膜的只有两个：**线粒体** 和 **叶绿体**。单层膜的有四个：**内质网、高尔基体、溶酶体、液泡**。无膜的有两个：**核糖体** 和 **中心体**。==双线双叶四单层，无膜只剩核糖体和中心体。== 原核生物更简单，只有 **核糖体** 一种细胞器，没有其他膜性细胞器，也没有成形的细胞核。这一句是判断题重灾区，务必记牢。"}, {"h": "二、动力与养料：线粒体和叶绿体", "p": "**线粒体**：双层膜，内膜向内折叠形成 **嵴**，大大扩大了内膜面积，是 **有氧呼吸的主要场所**，为细胞供能，号称 **动力车间**；内含少量 **DNA 和核糖体**，能合成少量自身所需蛋白质，属于半自主性细胞器，普遍分布于动植物细胞。 **叶绿体**：双层膜，内有许多由 **类囊体薄膜** 堆叠成的 **基粒**，类囊体薄膜上分布光合色素和酶，是 **光合作用的场所**，号称 **养料制造车间** 和能量转换站，只分布在绿色植物能见光的细胞中，根尖细胞、叶表皮细胞（除保卫细胞外）一般没有。线粒体和叶绿体都能产生 ATP，但去向不同：叶绿体产生的 ATP 主要用于暗反应，线粒体产生的 ATP 供各项生命活动。"}, {"h": "三、加工与发送：内质网、高尔基体、核糖体、溶酶体", "p": "**内质网**：单层膜围成的网状结构，是 **蛋白质加工** 以及 **脂质合成** 的 **车间**，粗面内质网附有核糖体管蛋白质，滑面内质网管脂质。 **高尔基体**：单层膜，主要是对来自内质网的蛋白质进行 **加工、分类和包装**，再送出去，号称 **发送站**；在动物细胞中与 **分泌物形成** 有关，在植物细胞中与 **细胞壁的形成** 有关。 **核糖体**：无膜，由 RNA 和蛋白质组成，是 **合成蛋白质的机器**，分 **附着型**（附在粗面内质网上，合成分泌蛋白等）和 **游离型**（在细胞质基质中，合成胞内蛋白），原核真核都有。 **溶酶体**：单层膜，内含多种 **水解酶**，是 **消化车间**，能分解 **衰老、损伤的细胞器**，吞噬并杀死侵入的 **病毒和病菌**；它自己的膜不会被酶水解，与膜成分的特殊修饰有关。硅肺就是溶酶体膜受损、水解酶外泄损伤肺细胞的例子。"}, {"h": "四、调节与分裂：液泡和中心体", "p": "**液泡**：单层膜，内含 **细胞液**（含糖类、无机盐、色素、蛋白质等），主要存在于 **植物细胞**，成熟植物细胞有大液泡，能 **调节细胞渗透压、维持细胞内环境稳定和细胞坚挺**，其中色素决定花、果实的颜色（花青素），注意与叶绿体中的光合色素区分。 **中心体**：无膜，由两个互相垂直的 **中心粒** 及周围物质组成，存在于 **动物细胞和低等植物细胞** 中，与细胞的 **有丝分裂** 有关，分裂时发出星射线形成纺锤体。==高等植物细胞没有中心体，高等动物细胞没有叶绿体和大液泡、没有细胞壁。== 这三句判断题必考。"}, {"h": "五、分泌蛋白的合成运输与生物膜系统", "p": "以胰岛素、抗体、消化酶这类 **分泌蛋白** 为例，用 **同位素标记法**（如用 3H 标记亮氨酸）追踪，路径背下来：**核糖体** 合成多肽 → **内质网** 初步加工 → 囊泡 → **高尔基体** 再加工分类包装 → 囊泡 → **细胞膜** 分泌到细胞外，全程由 **线粒体供能**。注意核糖体无膜，不属于生物膜系统，但它是起点。这条路径中膜面积变化也有规律：内质网膜面积减小，高尔基体膜面积基本不变（先增后减），细胞膜面积增大。 **生物膜系统** 指细胞内由 **细胞膜、核膜和细胞器膜** 等共同组成的统一系统，核糖体、中心体无膜不算在内。它的功能有三点：①细胞膜分隔外界、维持稳定并控制进出和信息交流；②广阔的膜面积为多种 **酶提供附着位点**，使反应高效有序；③不同区室 **分隔开**，保证生命活动互不干扰、同时进行，还参与 **物质运输和能量转换**。分泌过程靠囊泡和膜融合，体现了膜的 **流动性**。"}, {"h": "六、实验：观察叶绿体和细胞质流动", "p": "常用材料是 **黑藻** 或 **藓类叶片**，叶片薄、叶绿体大而清晰。关键点：观察叶绿体 **不用染色**，直接制片在高倍镜下看形态和分布；观察 **细胞质流动** 时以 **叶绿体的运动为参照**，叶绿体转到哪，就说明细胞质流向哪，而且显微镜下看到的流动方向与实际流动方向 **一致**（不像位置是上下左右颠倒的，环流方向是一致的）。实验中可适当加温、光照或切伤叶片来加快流动。注意：健那绿（詹纳斯绿B）是观察 **线粒体** 的活体染料，不要安到叶绿体实验上。==观察叶绿体不用染色，观察线粒体才用健那绿活体染色。=="}], "pitfalls": ["高等植物细胞没有中心体；动物和低等植物才有中心体。根尖分生区细胞没有叶绿体和大液泡。", "核糖体和中心体无膜，不属于生物膜系统；线粒体、叶绿体是双层膜，其余四种细胞器是单层膜。", "原核生物只有核糖体一种细胞器，没有线粒体等其他细胞器，但部分原核生物仍能进行有氧呼吸或光合作用，靠细胞膜上的酶。", "溶酶体分解的是衰老损伤的细胞器和外来病原体，不能说它分解一切物质；其水解酶在核糖体合成、经内质网和高尔基体加工。", "分泌蛋白路径中高尔基体膜面积基本不变，内质网减小、细胞膜增大；囊泡运输体现膜的流动性，不是选择透过性。", "观察叶绿体不用染色，用健那绿的是观察线粒体；细胞质流动方向在显微镜下与实际一致。"]}, "video": {"bvid": "BV1p54y177e6", "p": 21, "t": "细胞器之间的分工合作", "dur": "116:18", "from": "锦城大同教育·杨波生物", "vtop": ["八种细胞器先按膜分三类：双层膜只有线粒体和叶绿体，单层膜是内质网、高尔基体、液泡、溶酶体，无膜只有核糖体和中心体——这张表是全课的骨架，考前先默一遍。", "分泌蛋白的路线只有一条：游离核糖体起头→粗面内质网加工折叠→囊泡→高尔基体再加工→分泌小泡→细胞膜胞吐出去，线粒体只在旁边供能、不直接参与。", "生物膜系统只算细胞内部的膜：原核细胞有细胞膜所以有生物膜、但没有生物膜系统，呼吸道黏膜之类连细胞内部都不是，更不算。"], "vsum": "本课讲第三章第二节，分两讲：第一讲是**细胞器之间的分工**，第二讲是**细胞器之间的协调配合**。开场用 C919 大飞机打比方：造飞机要若干部门分工合作，细胞里也一样，**细胞器**、细胞核这些\"部门\"配合起来完成生命活动。要研究细胞器，先得把它们分开，用的方法是**差速离心法**：先弄破细胞膜，再逐渐提高离心速率，最重的颗粒最先沉到管底，轻的后沉下来。动植物细胞普遍都有的细胞器有四种：**线粒体**、**内质网**、**高尔基体**、**核糖体**。**线粒体**是双层膜细胞器，内膜向内折叠，**有氧呼吸的主要场所**，细胞生命活动所需能量的 95% 都来自它，叫\"动力车间\"；它含少量 DNA、RNA 和核糖体，是**半自主性细胞器**。**核糖体**无膜，由蛋白质和 rRNA 组成、两个亚基，是**生产蛋白质的机器**，氨基酸脱水缩合就在它上面进行；游离核糖体合成胞内蛋白，附着在内质网上的核糖体合成的一般是分泌蛋白。**内质网**是单层膜，粗面内质网附着核糖体、光面内质网不附着，是**蛋白质等大分子物质的合成加工场所和运输通道**，光面内质网还是脂质合成的重要场所。**高尔基体**也是单层膜，扁平囊泡堆叠，对来自内质网的蛋白质**加工、分类和包装**，是\"车间\"也是\"发送站\"，还与溶酶体的形成、植物细胞壁的形成有关，是细胞内起**交通枢纽**作用的细胞器。植物细胞特有的两种：**液泡**是单层膜，里面是细胞液（含糖类、色素、无机盐、蛋白质），功能是储存营养物质、维持渗透压调节细胞内环境、充盈的液泡使植物细胞保持坚挺，成熟植物细胞才有中央大液泡；**叶绿体**是双层膜，基粒上含光合色素，是**光合作用的场所**，叫\"养料制造车间\"和\"能量转换站\"，主要在叶肉细胞和幼嫩的茎皮层细胞里。动物细胞特有的两种：**溶酶体**是单层膜，含多种水解酶，是\"消化车间\"，分解衰老损伤的细胞器、吞噬杀死侵入的病毒病菌、消化胞吞的营养物质，还与细胞自溶有关，它的水解酶由核糖体合成、经内质网和高尔基体加工，膜来自高尔基体；**中心体**无膜，由两个互相垂直的中心粒组成、主要成分是微管蛋白，分布在动物细胞和低等植物细胞中，与**有丝分裂**有关。==八种细胞器按膜一分三类：双层膜（线粒体、叶绿体）、单层膜（内质网、高尔基体、液泡、溶酶体）、无膜（核糖体、中心体），含 DNA 的是线粒体和叶绿体，含色素的是液泡和叶绿体——这张归纳表是全课最常考的点。==细胞里还有**细胞骨架**，由蛋白质纤维组成的网架结构，维持细胞形态、锚定并支撑细胞器，与运动、分裂、分化、物质运输、能量转化、信息传递都有关。易错提醒：哺乳动物成熟的红细胞没有线粒体；有中心体的不一定是动物细胞（低等植物也有）；没有叶绿体的不一定是动物细胞（植物根细胞就没有）；没有大液泡的不一定是动物细胞（幼嫩植物细胞只有小液泡）；溶酶体能储存水解酶但不能合成水解酶。教材实验是用高倍显微镜观察叶绿体和细胞质的流动：叶绿体一般是绿色、扁平椭球形，不用染色就能看到，弱光时以正面受光、强光时以侧面受光防灼伤；以叶绿体的运动为标志观察细胞质流动，细胞质是细胞代谢的主要场所，装片要随时保持有水。第二讲以**分泌蛋白**为例讲协调配合：分泌蛋白是在细胞内合成后分泌到细胞外起作用的蛋白质，包括消化酶、抗体、蛋白质类激素（如胰岛素）三类；相对的是**胞内蛋白**（如血红蛋白、呼吸酶）。科学家用**同位素标记法**研究它的行踪：用有放射性的氚（³H）标记亮氨酸，喂给豚鼠胰腺腺泡细胞，再追踪放射性出现的位置。路线是：**游离核糖体**上以氨基酸为原料合成短肽链→核糖体连同肽链转移到**粗面内质网**，继续合成并进入内质网腔加工折叠→内质网出芽形成**囊泡**运往**高尔基体**进一步修饰加工→高尔基体形成**分泌小泡**运往**细胞膜**，胞吐分泌到细胞外；**线粒体**为全过程供能，是间接参与。三个要扣的点：蛋白质的合成场所只有一个，就是核糖体；所有蛋白质的合成都起始于游离核糖体；内质网加工的是肽链，高尔基体加工的是已有空间结构的蛋白质。过程中三者的膜面积这样变：内质网减小、高尔基体先增大后减小（基本不变）、细胞膜增大。最后是**细胞的生物膜系统**：细胞内全部膜结构（细胞器膜、细胞膜、核膜等）的统称，组成成分和结构都很相似（磷脂双分子层作支架、蛋白质分布其中），功能上紧密联系：细胞膜在物质运输、能量转化、信息传递中起决定性作用并保持内环境稳定，其他膜为酶提供附着位点、把各种细胞器分隔开保证生命活动高效有序；膜与膜之间有直接相连（核外膜—内质网、内质网—细胞膜）和囊泡介导的间接相连（内质网—高尔基体—细胞膜），囊泡往来还能更新膜成分。", "vtech": [["膜分类题先画三行表", "看到问细胞器膜结构的题 → 先画表：双层膜（线粒体、叶绿体）、单层膜（内质网、高尔基体、液泡、溶酶体）、无膜（核糖体、中心体）；再看题问的是哪一行，别把内质网、高尔基体当成双层膜，也别漏了液泡和溶酶体。"], ["分泌蛋白路线题背一句话", "看到分泌蛋白合成运输题 → 背路线：游离核糖体→粗面内质网→囊泡→高尔基体→分泌小泡→细胞膜，线粒体只供能；问\"经过的细胞器\"不能算细胞膜（它不是细胞器），问\"直接参与\"不能算线粒体（它只供能不直接参与）。"], ["\"不一定\"题认两个反例", "看到\"能进行有氧呼吸的细胞一定有线粒体\"或\"能光合作用的细胞一定有叶绿体\" → 直接判错：反例是硝化细菌（有氧呼吸、无线粒体）和蓝细菌（光合作用、无叶绿体）；同样，没有叶绿体的细胞不一定是动物细胞（植物根细胞就没有）。"], ["生物膜系统题先看范围", "看到生物膜系统题 → 先看范围：只算细胞内部的膜（细胞器膜＋细胞膜＋核膜）；原核细胞只有细胞膜，有生物膜、没有生物膜系统；呼吸道黏膜、消化道黏膜是黏膜细胞构成的，不属于生物膜系统。"]], "vgaokao": []}}, "bio_b013": {"name": "细胞核的结构和功能", "sec": 13, "secTitle": "细胞核的结构和功能", "page": 54, "desc": "核膜、核孔、核仁、染色质；遗传信息库与控制中心；伞藻实验。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b012"], "next": ["bio_b024"], "content": {"advance": {"a": "观点错误。细胞核的控制作用离不开细胞质：细胞核进行 DNA 复制、转录所需的原料（如核苷酸、氨基酸）和能量（ATP）都由细胞质提供，合成的 RNA 和组装的核糖体亚基要运到细胞质中才能指导蛋白质合成，单独的细胞核没有线粒体供能、没有核糖体合成蛋白质，无法独立代谢和分裂。变形虫实验也证明，有核部分必须带细胞质才能存活，无核细胞质短期也会死亡。正如细胞核离不开细胞质，细胞质也离不开细胞核的指导，细胞各结构分工合作、相互依存，是一个统一的整体，只有保持细胞完整性才能完成各项生命活动。", "kind": "self", "q": "有人认为：既然细胞核是控制中心，那么把细胞核单独取出来培养，它应该能独立存活和分裂。请用本节知识反驳这一观点。"}, "apply": [{"ans": 1, "opts": ["细胞质控制细胞的一切生命活动", "细胞核是细胞代谢和遗传的控制中心，细胞需保持完整性", "细胞核可以独立完成生命活动", "无核部分死亡是因为失去了细胞膜"], "q": "将变形虫切成有核和无核两部分，无核部分能短期消化食物但最终死亡，有核部分能继续生长和分裂；若及时给无核部分植入另一个细胞核，它又能恢复正常生活。这组实验说明（ ）", "why": "无核不能长期存活、植入核后恢复，说明细胞核起控制作用；但细胞核也离不开细胞质提供的物质和能量，两者相互依存，细胞只有保持完整性才能完成各项生命活动。"}, {"ans": 2, "opts": ["完全由去核卵细胞决定", "与供核个体完全相同，不受任何其他因素影响", "主要由供核个体决定，但也受细胞质基因和环境影响", "与供核个体无关"], "q": "克隆猴的培育是将体细胞核移入去核卵细胞中重组发育而成。克隆猴的性状（ ）", "why": "遗传信息主要在细胞核，所以性状主要像供核者；但卵细胞细胞质中线粒体含少量 DNA，也会影响性状，加上环境因素，只能说几乎相同，不能说完全相同。"}], "basics": [{"ans": 2, "opts": ["核膜是单层膜，把核内物质与细胞质分开", "核孔是所有物质进出细胞核的通道，包括 DNA", "染色质和染色体是同一物质在不同时期的两种形态", "核仁是合成蛋白质的场所"], "q": "下列关于细胞核的叙述，正确的是（ ）", "why": "核膜是双层膜；核孔具选择性，DNA 不能出核；核仁与 rRNA 合成和核糖体形成有关，合成蛋白质的场所是核糖体。只有染色质与染色体的关系表述正确。"}, {"ans": 2, "opts": ["细胞核体积最大", "细胞核位于细胞中央", "遗传信息主要储存在细胞核的 DNA 中，DNA 控制蛋白质合成", "细胞核有核仁能形成核糖体"], "q": "细胞核被称为细胞代谢和遗传的控制中心，根本原因是（ ）", "why": "控制作用的物质基础是 DNA。DNA 储存遗传信息，通过指导蛋白质合成控制代谢和性状，体积和位置不是根本原因。"}, {"ans": 1, "opts": ["菊花形", "伞形", "中间形", "不长帽"], "q": "伞藻核移植实验中，将伞形帽伞藻的细胞核移植到去核的菊花形帽伞藻假根中，最终再生出的帽的形状是（ ）", "why": "帽的形态由细胞核决定，供核方是伞形帽伞藻，所以长出伞形帽，这直接证明细胞核控制生物性状。"}], "case": {"a": "(1)嫁接实验中假根同时含有细胞核和细胞质，移植的柄中也可能残留原细胞的物质，帽型接近假根一方既可能是核的作用，也可能是细胞质的作用，变量不单一，所以不能单独下结论。(2)核移植实验在排除原有细胞核后，只改变细胞核这一变量，再生帽完全呈现供核方的帽型，说明生物体形态建成（帽的形状）主要由细胞核控制。(3)综合说明细胞核储存遗传信息，是遗传信息库，是细胞代谢和遗传的控制中心。", "hints": ["假根里除了核还有细胞质，嫁接时柄也带少量细胞质和已有物质", "核移植排除了原有细胞核干扰，只改变核这一个变量", "帽型是遗传性状，控制性状就是控制遗传和代谢"], "q": "材料：伞藻是单细胞绿藻，分为帽、柄、假根三部分，细胞核在假根中。实验1嫁接：将伞形帽伞藻的柄嫁接到菊花形帽伞藻的假根上，再生帽呈中间偏菊花形相关性状；反之亦然，结果帽型总与假根一方更接近。实验2核移植：将一种伞藻的细胞核取出，移入已去掉核和帽的另一种伞藻假根中，再生帽完全为供核方的帽型。回答：(1)嫁接实验为什么不能单独得出细胞核控制帽型的结论？(2)核移植实验说明了什么？(3)综合两实验可得出细胞核具有什么功能？", "steps": ["第一步：嫁接时假根含细胞核和细胞质，柄中也残留原有物质，变量不唯一，不能排除细胞质影响", "第二步：核移植只替换细胞核这一个因素，结果帽型完全随供核方改变，证明帽型由细胞核决定", "第三步：帽型属于遗传性状，细胞核能决定性状，说明它是遗传信息库和控制中心"], "talk": ["看实验题先问变量唯一不唯一：嫁接有质的干扰，核移植才是决定性证据。"], "title": "案例：伞藻实验如何一步步锁定细胞核的作用"}, "intro": "一个细胞能干多少事，最终听谁指挥？答案是 **细胞核**。去核的细胞活不长，无核的成熟红细胞寿命也只有约 120 天。==细胞核是遗传信息库，是细胞代谢和遗传的控制中心。== 这一节结构不复杂，但实验多、易混点多：核孔能不能过 DNA、染色质和染色体到底啥关系、伞藻实验到底证明了什么，都要掰扯清楚。", "learn": [{"h": "一、细胞核的结构：四部分各管一摊", "p": "细胞核主要由四部分组成。 **核膜**：**双层膜**，把核内物质与细胞质分开，属于生物膜系统的一部分，膜上有酶附着。 **核孔**：核膜上的通道，实现核质之间频繁的 **物质交换和信息交流**，是 RNA、蛋白质等 **大分子物质** 进出的通道，具有选择性——比如信使 RNA 要出核去指导蛋白质合成，细胞质合成的酶、组蛋白要进核，但 **DNA 不能出核**。注意核孔不是简单的洞，它有选择性，小分子一般经核膜通过。 **核仁**：与某种 **RNA（rRNA）的合成** 以及 **核糖体的形成** 有关，蛋白质合成旺盛的细胞核仁较大；核仁在分裂前期消失、末期重现。 **染色质**：主要由 **DNA 和蛋白质** 组成，是遗传物质的载体，因易被碱性染料染成深色而得名。==核孔是大分子的通道但 DNA 不能通过，核仁管 rRNA 合成和核糖体形成。=="}, {"h": "二、染色质与染色体：同一物质，两种形态", "p": "这是最爱考的一组关系：**染色质和染色体是同一物质在细胞不同时期的两种存在形态**。分裂间期，DNA 松散成细丝状的 **染色质**，有利于 DNA 复制和转录；分裂期，染色质高度螺旋化、缩短变粗，成为圆柱状或杆状的 **染色体**，有利于遗传物质平均分配。成分完全一样，都是 DNA 加蛋白质，只是打包程度不同。==间期细丝叫染色质，分裂期粗杆叫染色体，本质是同一种物质。== 不要写成两种不同物质，也不要说染色质变成另一种物质。"}, {"h": "三、细胞核的功能：信息库加控制中心", "p": "功能就两句话，必须原样背准：第一，细胞核是 **遗传信息库**，是细胞代谢和遗传的 **控制中心**。为什么是控制中心？因为遗传信息主要储存在核内 DNA 上，DNA 控制蛋白质合成，进而控制细胞的代谢和遗传性状。细胞核控制着细胞的生老病死：哺乳动物成熟红细胞无核，寿命短；变形虫去核后代谢减弱、不能分裂。还要理解：细胞核与细胞质相互依存，核离不开质提供的原料和能量，质离不开核的指导，==细胞是一个统一的整体，结构与功能相适应，各部分协调配合。=="}, {"h": "四、经典实验：伞藻、变形虫与克隆动物说明了什么", "p": "实验一，**伞藻嫁接与核移植**：伞藻有带核的假根、柄和帽。把菊花形帽伞藻的柄嫁接到伞形帽伞藻的假根上（反之亦然），第一次再生出的帽往往呈中间类型，因为柄中残留原细胞的物质（mRNA 等）也会起作用；将该帽切除后第二次再生的帽才与 **假根（供核方）** 的帽型一致，提示帽型主要受假根中的细胞核控制。再做核移植——把一方的细胞核移入去核的另一方，长出的帽完全由 **供核方** 决定，这才排除了细胞质的干扰，是最有力的证据。实验二，**变形虫切割**：切成有核和无核两半，有核部分能存活、生长、再生并分裂，无核部分短期代谢后死亡，重新植入核后又能恢复生命活动，说明细胞核控制细胞的生命活动，细胞完整性是完成生命活动的前提。实验三，**克隆羊多莉、克隆猴**：用体细胞核移植培育出与供核个体性状几乎相同的克隆动物，说明 **已分化的动物体细胞核仍具有全能性**，且遗传性状主要由细胞核决定；同时克隆动物也有少量细胞质遗传（线粒体 DNA 来自去核卵细胞），所以说几乎相同，不能说完全相同。"}], "pitfalls": ["核孔具有选择性：DNA 不能通过核孔出核，RNA 和蛋白质可以；不能说核孔让大分子自由进出。", "染色质和染色体是同一物质在不同时期的两种形态，不是两种不同物质，成分都是 DNA 和蛋白质。", "哺乳动物成熟红细胞和植物筛管细胞无细胞核，但它们仍是细胞；原核细胞无成形细胞核，但有拟核。", "核仁与 rRNA 合成和核糖体形成有关，不是合成所有 RNA，更不是直接合成蛋白质的场所。", "克隆动物性状与供核者几乎相同而非完全相同，因为细胞质中线粒体 DNA 来自受体卵细胞，还有环境影响。"]}, "video": {"bvid": "BV1p54y177e6", "p": 25, "t": "细胞核的结构和功能", "dur": "60:40", "from": "锦城大同教育·杨波生物", "vtop": ["细胞核的功能高中只考一句话：细胞核是遗传信息库，是细胞代谢和遗传的控制中心，简称“一库两中心”，四个实验全是为这句话服务的。", "没有细胞核的真核细胞只有两种要记：哺乳动物成熟的红细胞和高等植物成熟的筛管细胞，它们都不能生长、分裂、分化，寿命短；筛管运有机物，导管运水和无机盐，成熟导管是死细胞。", "染色质和染色体是同一种物质在细胞不同时期的两种形态：间期是细丝状的染色质，分裂期高度螺旋化缩短变粗成杆状的染色体，主要成分都是 DNA 和蛋白质。"], "vsum": "本课讲第三章第三节：**细胞核的结构和功能**。开场用克隆牛引出：细胞核由母牛乙提供，小牛性状与母牛乙几乎一样，说明**性状由细胞核决定**。先补一个考点：除了**哺乳动物成熟的红细胞**和**高等植物成熟的筛管细胞**这两种极少数例外，真核细胞都有以核膜为界限的细胞核；没有细胞核的真核细胞不能生长、分裂和分化，也不能长期存在，寿命较短（人的红细胞只有 3 到 4 个月）；筛管细胞运输有机物，导管细胞运输水和无机盐，成熟的导管细胞是死细胞，只剩细胞壁。功能部分用四个实验论证：美西螈核移植证明皮肤颜色的遗传由细胞核控制（但只有一组实验、缺对照组）；蝾螈受精卵横缢证明细胞核与细胞的分裂、分化有关；变形虫切割证明没有细胞核的细胞不能存活、生长和分裂，把核放回去就能恢复；伞藻嫁接与核移植证明伞帽的形状由假根中的细胞核决定。==四个实验合起来只说一句话：细胞核是遗传信息库，是细胞代谢和遗传的控制中心，简称“一库两中心”。==结构部分：**核膜**是双层膜，把核内物质与细胞质分开，外膜与内质网相连；**核孔**是大分子进出细胞核的通道，RNA 和蛋白质能通过，DNA 不能出核，代谢旺盛的细胞核孔数量多；**核仁**与某种 RNA 的合成以及核糖体的形成有关，在细胞分裂过程中会周期性地消失和重现；**染色质**主要由 DNA 和蛋白质组成，呈细丝状，容易被碱性染料染成深色。易错提醒：染色质和染色体是同一种物质在细胞不同时期的两种形态，间期是染色质，分裂期高度螺旋化成染色体，不要当成两种东西。最后讲模型建构：概念模型是用图画等形式直观表达结构特征，数学模型是用坐标图等数学形式描述特征。", "vtech": [["功能题背“一库两中心”", "看到细胞核功能题 → 背一句话：细胞核是遗传信息库，是细胞代谢和遗传的控制中心；四个实验（美西螈、蝾螈横缢、变形虫、伞藻）全是这句话的证据，问“说明了什么”就往这句上靠。"], ["无核细胞题只认两种", "看到没有细胞核的真核细胞题 → 只认两种：哺乳动物成熟的红细胞和高等植物成熟的筛管细胞；它们都不能生长、分裂、分化，寿命短；筛管运有机物、导管运水和无机盐，成熟导管是死细胞。"], ["染色质染色体题看时期", "看到染色质与染色体题 → 看时期：同一种物质，间期是细丝状的染色质，分裂期高度螺旋化成杆状的染色体；主要成分都是 DNA 和蛋白质；问“行使遗传功能的结构”答染色质。"], ["核孔题看进出", "看到核孔题 → 抓进出：核孔是大分子进出细胞核的通道，RNA 和蛋白质能通过，DNA 不能出核；代谢越旺盛的细胞，核孔数量越多、核仁越大。"]], "vgaokao": []}}, "bio_b014": {"name": "被动运输与渗透作用", "sec": 14, "secTitle": "被动运输", "page": 62, "desc": "渗透作用的两个条件；质壁分离与复原；自由扩散与协助扩散。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b011"], "next": ["bio_b015"], "content": {"advance": {"a": "刚放入时两种溶液浓度都大于细胞液，细胞失水，都先发生质壁分离。区别在后续：K+ 和 NO3- 能被细胞通过主动运输等方式吸收进入液泡，使细胞液浓度逐渐升高，当细胞液浓度高于外界溶液时，细胞转为吸水，原生质层恢复贴近细胞壁，出现自动复原。蔗糖分子较大且不能被该细胞吸收进入液泡，细胞液浓度不会升高，细胞持续处于失水状态，所以只分离不自动复原，除非换入清水。", "kind": "self", "q": "为什么把成熟植物细胞放入 KNO3 溶液中会先质壁分离后自动复原，而放入相同浓度的蔗糖溶液中只分离不自动复原？请从物质吸收和细胞液浓度变化的角度说明。"}, "apply": [{"ans": 1, "opts": ["自动复原，液泡逐渐变大", "保持质壁分离状态不变", "细胞涨破，紫色溢出", "先复原再重新分离"], "q": "将紫色洋葱鳞片叶外表皮细胞置于 0.3 g/mL 蔗糖溶液中，观察到质壁分离。随后不换液、继续观察较长时间，细胞形态最可能（ ）", "why": "蔗糖分子不能被细胞吸收进入液泡，细胞液浓度不会因此升高，细胞持续失水后保持分离状态。只有换清水，或外界是 KNO3 等可吸收物质时才会复原。"}, {"ans": 0, "opts": ["K+ 和 NO3- 被细胞主动吸收，使细胞液浓度升高后吸水", "KNO3 使细胞壁变成了半透膜", "细胞死亡后原生质层恢复通透性", "蔗糖分子缓慢进入了液泡"], "q": "将同一洋葱表皮细胞先放入 KNO3 溶液中，细胞先发生质壁分离后又自动复原。对自动复原原因的解释正确的是（ ）", "why": "K+ 和 NO3- 可被细胞吸收进入细胞液，使细胞液浓度逐渐高于外界溶液，细胞由失水转为吸水，于是自动复原。本题材料是 KNO3 不是蔗糖，细胞仍是活的，细胞壁始终全透。"}, {"ans": 1, "opts": ["小于 0.30 mol/L", "在 0.30-0.35 mol/L 之间", "大于 0.35 mol/L", "等于 0 mol/L"], "q": "某同学用不同浓度的蔗糖溶液处理同一部位的洋葱表皮细胞，测得刚好发生质壁分离的溶液浓度约为 0.35 mol/L，浓度为 0.30 mol/L 时不分离。据此判断该细胞细胞液浓度大致为（ ）", "why": "外界浓度小于细胞液时不分离，大于细胞液时分离。临界点在 0.30 与 0.35 之间，说明细胞液浓度就在这个区间，这是测定细胞液浓度的基本方法。"}], "basics": [{"ans": 0, "opts": ["半透膜和膜两侧溶液存在浓度差", "全透膜和膜两侧溶液存在浓度差", "半透膜和膜两侧溶液浓度相等", "转运蛋白和 ATP 供能"], "q": "发生渗透作用必须同时具备的两个条件是（ ）", "why": "渗透作用的定义条件就是半透膜加两侧浓度差。没有浓度差水分子进出平衡，不发生净的渗透；全透膜不能形成渗透；转运蛋白和 ATP 是主动运输的条件。"}, {"ans": 1, "opts": ["皱缩、保持正常、涨破", "涨破、保持正常、皱缩", "保持正常、涨破、皱缩", "涨破、皱缩、保持正常"], "q": "将人体红细胞分别置于清水、0.9% NaCl 溶液和 1.5% NaCl 溶液中，依次出现的现象是（ ）", "why": "清水中外界浓度低于细胞质，红细胞吸水涨破；0.9% NaCl 是等渗溶液，保持正常形态；1.5% NaCl 浓度高于细胞质，红细胞失水皱缩。"}, {"ans": 1, "opts": ["葡萄糖进入红细胞", "O2 进入肺泡上皮细胞", "K+ 进入神经细胞", "水通过水通道蛋白进入细胞"], "q": "下列物质进出细胞的方式属于自由扩散的是（ ）", "why": "O2 是小分子气体，可直接穿过磷脂双分子层，顺浓度、不耗能、无需蛋白，属于自由扩散。葡萄糖进红细胞和水走水通道蛋白都需转运蛋白，是协助扩散；K+ 进入神经细胞常为主动运输。"}, {"ans": 1, "opts": ["细胞壁的伸缩性大于原生质层", "原生质层的伸缩性大于细胞壁", "细胞液浓度大于外界溶液浓度", "细胞已经死亡失去活性"], "q": "植物细胞发生质壁分离的内因是（ ）", "why": "细胞失水时原生质层收缩幅度比细胞壁大，才会与细胞壁分开。外因是外界浓度大于细胞液，内因是原生质层伸缩性大于细胞壁；死细胞不会发生质壁分离。"}], "case": {"a": "（1）该洋葱表皮细胞的细胞液浓度大致在 0.30-0.40 mol/L 之间。因为外界浓度低于细胞液时细胞不失水、不分离，高于细胞液时细胞失水发生质壁分离，临界浓度即接近细胞液浓度。（2）乙组细胞经高温处理已经死亡，原生质层失去选择透过性，不再相当于半透膜，蔗糖溶液与细胞液之间不能维持浓度差驱动的失水过程，因此不发生质壁分离。由此可知，质壁分离及复原可用于判断细胞的死活，活细胞能分离和复原，死细胞不能。", "hints": ["不分离说明外界浓度不高于细胞液，分离说明外界浓度高于细胞液，临界区间就在两者之间", "死细胞的原生质层失去选择透过性，不再相当于半透膜"], "q": "实验材料为紫色洋葱鳞片叶外表皮。甲组分别用 0.20、0.30、0.40、0.50 mol/L 的蔗糖溶液处理相同部位的细胞，10 分钟后观察：0.20 和 0.30 组未发生质壁分离，0.40 和 0.50 组发生质壁分离。乙组先用高温处理材料使其细胞死亡，再用 0.50 mol/L 蔗糖溶液处理，未观察到质壁分离。请回答：（1）该材料细胞液浓度的大致范围是多少？（2）乙组为什么不发生质壁分离？这说明质壁分离可以用来做什么判断？", "steps": ["先看甲组：0.30 mol/L 不分离，说明细胞液浓度大于或接近 0.30 mol/L；0.40 mol/L 分离，说明细胞液浓度小于 0.40 mol/L，合起来得到区间", "再看乙组：细胞死亡后细胞膜和液泡膜失去选择透过性，蔗糖和水都能自由进出，不再形成浓度驱动的失水收缩", "最后归纳应用：能发生质壁分离和复原的是活细胞，不能发生的多为死细胞，所以该现象可判断细胞死活"], "talk": ["测浓度找临界：不分离与刚分离之间就是细胞液浓度", "能不能质壁分离，先看细胞是不是活的"], "title": "案例：用质壁分离判断细胞液浓度并区分死活细胞"}, "intro": "细胞每时每刻都在跟外界交换物质，最基础的一类交换叫 **被动运输**，特点是顺着浓度梯度走、不消耗能量。==被动运输不需要能量，水和许多小分子就是靠这种方式进出细胞的。==\n\n这一节真正的难点是 **渗透作用**。很多同学一上来就背反方向，考试就丢分。记住一个统一说法：==水分子总是从相对含量高的一侧向相对含量低的一侧扩散，也就是从低浓度溶液向高浓度溶液扩散。== 低浓度溶液里水多，高浓度溶液里水少，这样记就不会乱。", "learn": [{"h": "渗透作用：条件就两个，方向就一句话", "p": "发生 **渗透作用** 必须同时满足两个条件：一是有 **半透膜**，二是半透膜两侧溶液有 **浓度差**。缺一个都不算渗透。半透膜只让水等小分子通过，大分子过不去。\n\n方向怎么判？别死记溶质，就盯着水看。==水从水分子相对含量高的一侧流向含量低的一侧。== 举个例子，漏斗里是蔗糖溶液、外面是清水，蔗糖出不去，水往漏斗里跑，液面上升。蔗糖溶液浓度高、水相对含量低，所以水是往高浓度一侧跑的，两个说法是一回事。"}, {"h": "动物细胞吸水失水：拿红细胞和生理盐水说清", "p": "动物细胞没有细胞壁，细胞膜就相当于一层 **半透膜**，吸水失水全看外界溶液浓度跟细胞质浓度谁高谁低。\n\n外界浓度低时，水往细胞里跑，细胞 **吸水膨胀**，红细胞甚至会涨破；外界浓度高时，水往外跑，细胞 **失水皱缩**；两者相等时，进出平衡，细胞保持正常形态。==质量分数为 0.9% 的 NaCl 溶液是红细胞的等渗溶液，所以医院输液常用生理盐水维持细胞形态。== 把红细胞放进清水中会涨破，放进浓盐水中会皱缩，这是选择题最爱考的对照。"}, {"h": "植物细胞的半透膜是谁：原生质层，不是细胞壁", "p": "成熟植物细胞跟动物细胞不一样，它有大 **中央液泡**，里面装的是 **细胞液**。真正起半透膜作用的不是细胞壁，而是 **原生质层**。\n\n原生质层包括哪几部分要背准：**细胞膜** 加 **液泡膜**，再加上两层膜之间的 **细胞质**，这三部分合起来才叫原生质层。==细胞壁是全透性的，水和溶质都能自由通过，它不决定吸水失水。== 考试常在这里挖坑，问半透膜是谁，答细胞壁就错了。"}, {"h": "质壁分离与复原：条件、现象、为什么有的能自动回来", "p": "把活的成熟植物细胞放进浓度大于细胞液的外界溶液里，细胞失水，就会发生 **质壁分离**。发生条件有三个：细胞是活的、是成熟植物细胞有中央大液泡、外界溶液浓度大于细胞液浓度。\n\n现象也要说全：**液泡变小**、**液泡颜色变深**、**原生质层与细胞壁分离**。用紫色洋葱鳞片叶外表皮做实验，就是因为液泡带紫色，看得清清楚楚。\n\n再把细胞放回清水，细胞吸水，能发生 **质壁分离复原**。这里有个高频考点：外界溶液是蔗糖时，必须换清水才能复原；但如果是 **KNO3、尿素、乙二醇** 这类能被细胞吸收的物质，细胞一边失水一边把它们吸进来，细胞液浓度慢慢升高，最后会 **自动复原**，不用换清水。==蔗糖不能被细胞吸收，所以蔗糖溶液中质壁分离后不会自动复原，KNO3 等可吸收物质则会。=="}, {"h": "被动运输分两种：自由扩散和协助扩散", "p": "被动运输按需不需要转运蛋白，分成两种。第一种是 **自由扩散**，也叫简单扩散：顺浓度梯度、不耗能、也不需要载体。常见的有水、**O2、CO2、甘油、乙醇、苯**，还有脂溶性小分子，它们能直接穿过磷脂双分子层。\n\n第二种是 **协助扩散**，也叫易化扩散：顺浓度梯度、不耗能，但必须有 **转运蛋白** 帮忙。转运蛋白分两类，一类是 **载体蛋白**，结合物质后构象改变把物质送过去；一类是 **通道蛋白**，形成通道让物质顺着通过，比如 **水通道蛋白**。\n\n经典例子一定要分清：**葡萄糖进入红细胞** 是协助扩散，因为红细胞外葡萄糖浓度高、顺浓度走，只需载体蛋白帮忙。而葡萄糖进入小肠上皮细胞是逆浓度的，那是主动运输，下一节专门讲，千万别混。==转运蛋白具有专一性，一种转运蛋白一般只能转运一种或一类物质，这也是协助扩散速率会饱和的原因。=="}, {"h": "质壁分离实验的三大应用，考试爱出大题", "p": "质壁分离不只是看现象，它有三个实用判断功能。第一，**判断细胞死活**：活细胞能发生质壁分离和复原，死细胞原生质层失去选择透过性，不会发生。第二，**测定细胞液浓度**：把同一材料分别放进一系列不同浓度的溶液里，刚好不发生质壁分离和刚发生质壁分离之间的浓度范围，就是细胞液浓度的大致范围。第三，**观察质壁分离** 本身验证原生质层相当于半透膜。答实验题时，变量是外界溶液浓度，因变量是是否发生质壁分离，结论要对应着写，不要只写现象不写结论。"}], "pitfalls": ["把渗透方向说反：水是向溶质浓度高的一侧扩散，不是向溶质浓度低的一侧；统一用水的相对含量来判断最稳，水多的一侧流向水少的一侧。", "把细胞壁当成半透膜：细胞壁全透性，植物细胞真正相当于半透膜的是原生质层（细胞膜加液泡膜加两膜间的细胞质）。", "以为蔗糖溶液中质壁分离也能自动复原：蔗糖不能被吸收，必须换清水才复原；只有 KNO3、尿素、乙二醇等可被吸收的物质才能自动复原。", "把葡萄糖进入红细胞说成主动运输：它是顺浓度、不耗能的协助扩散；葡萄糖进入小肠上皮细胞才是主动运输，两者方向不同，不能混为一谈。", "以为协助扩散不需要蛋白或需要能量：协助扩散不耗能但必须有转运蛋白，自由扩散才既不耗能也不需要转运蛋白。"]}, "video": {"bvid": "BV1p54y177e6", "p": 27, "t": "被动运输", "dur": "96:52", "from": "锦城大同教育·杨波生物", "vtop": ["渗透作用就两个条件：有半透膜、膜两侧有浓度差（物质的量浓度，也就是渗透压）；液面升高不是水单向跑过去，是单位时间内清水进蔗糖溶液的水比反方向多，双向运动别记反了。", "质壁分离认三个条件：活的、成熟的、植物细胞——根尖分生区细胞太嫩、导管细胞是死细胞，都不能发生；外因是外界溶液浓度大于细胞液浓度，内因是原生质层比细胞壁伸缩性大。", "被动运输只认两句话：顺浓度梯度、不耗能；自由扩散不用转运蛋白、协助扩散要，载体蛋白会结合、会变构像，通道蛋白不结合、不变构像。"], "vsum": "本课讲第四章第一节，分两讲：第一讲是**渗透作用**和水进出细胞的原理，第二讲是**质壁分离实验**和**被动运输**。开场是一个经典的渗透装置：长颈漏斗口蒙一层玻璃纸（赛璐玢，一种**半透膜**），里面装蔗糖溶液，倒置浸入清水，漏斗管里的液面过一段时间会升高。**半透膜**只允许离子和小分子（如水、单糖）通过，蔗糖这样的大分子过不去。**渗透作用**就是水分子或其他溶剂分子通过半透膜的扩散，是一种特殊的扩散作用，发生要两个条件：**有半透膜**，**膜两侧有浓度差**。这里的浓度指的是物质的量浓度，实质上就是**渗透压**：单位体积溶液中溶质微粒越多，渗透压越大。液面为什么升高？水分子是**双向运动**的，但单位时间内由清水进入蔗糖溶液的水分子数多于反方向的，所以蔗糖溶液体积增大、液面升高；液面不会无限升高，因为上升的水柱产生压力、加快水向外扩散，最终进出相等、达到**动态平衡**，此时两侧溶液浓度仍不相等。用纱布代替玻璃纸就不行（纱布是全透膜），烧杯里换成等浓度蔗糖溶液也不行（没有浓度差）。水进出细胞的原理同样是渗透作用。动物细胞把**细胞膜**当作半透膜：外界溶液浓度小于细胞质浓度时吸水膨胀、甚至胀破，大于时失水皱缩，等于时保持正常形态；注意这里说的浓度是**溶质的浓度**，水是从溶质低浓度往高浓度走，也就是从水相对含量高的一侧往低的一侧走，两句话并不矛盾。植物细胞的细胞壁是全透的，不能当半透膜；成熟植物细胞把**原生质层**（细胞膜＋液泡膜＋之间的细胞质）当作半透膜，比较的是**细胞液**（特指液泡里的液体）的浓度与外界溶液的浓度：吸水时中央液泡变大、细胞变得坚挺（细胞壁伸缩性小，体积不会大多少）；失水时液泡变小，**原生质层**与细胞壁分离，就是**质壁分离**。==质壁分离的原因就两点：外因是外界溶液浓度大于细胞液浓度，内因是原生质层的伸缩性大于细胞壁——而能发生质壁分离的必须是活的、成熟的植物细胞，根尖分生区细胞太嫩、导管细胞是死细胞，都不能发生。==教材实验是探究植物细胞的吸水和失水，材料是**洋葱鳞片叶外表皮**（紫色大液泡、单层细胞，细胞液有颜色才好看）：先在低倍镜下看正常形态，再用引流法滴加 **0.3 g/mL 蔗糖溶液**，看到液泡逐渐变小、紫色逐渐加深、原生质层与细胞壁分离；再滴加清水，液泡变大、紫色变浅、原生质层复贴，就是**质壁分离的复原**。全程都在低倍镜下观察，选定一个视野后不能移动装片，因为实验遵循**自身前后对照**。浓度要适中：3 g/mL 太浓会让细胞过度失水死亡、看不到复原；0.5 g/mL 也偏大，同样会致死。这个实验有三个应用：判断细胞死活、测定细胞液浓度范围（介于未发生与刚发生质壁分离的外液浓度之间）、比较不同植物细胞的细胞液浓度（发生质壁分离所需时间越短，细胞液浓度越小）。还有一种**自动复原**：用适宜浓度的硝酸钾溶液，不加清水也会自己复原，因为细胞主动吸收了 K⁺ 和 NO₃⁻，细胞液浓度变大就吸水了；葡萄糖、醋酸钾、甘油、尿素溶液里也会这样——溶质分子比水分子大得多，一开始只有水在动，溶质进得慢，所以先分离、后复原。第二讲的重点是**被动运输**：物质以扩散方式进出细胞，**不消耗能量**，方向是**顺浓度梯度**（从浓度高往浓度低），动力就是浓度梯度。分两种：**自由扩散**（也叫简单扩散），物质直接穿过磷脂分子之间的间隙，如氧气、二氧化碳等气体，甘油、乙醇、苯等脂溶性小分子有机物，还有少部分水；**协助扩散**（也叫易化扩散），需要借助膜上的**转运蛋白**，如离子和小分子有机物（葡萄糖进入红细胞就是协助扩散），大部分水也是这样进出细胞的（靠水通道蛋白）。注意葡萄糖进入大多数动物细胞是协助扩散，但肾小管细胞和小肠上皮细胞吸收葡萄糖是主动运输，下一课再讲。转运蛋白分两种：**载体蛋白**只容许与自身结合部位相适应的分子或离子通过，结合是暂时的、可分离的，每次转运自身构像都会改变，选择性很高；**通道蛋白**只容许与通道直径和形状相适配、大小和电荷相适宜的分子或离子通过，通过时不与通道蛋白结合、自身构像不变，分水通道蛋白和离子通道蛋白，选择性是相对的（钠离子通道有时也能让铵根离子通过），所以载体蛋白的选择性比通道蛋白强。影响被动运输的因素有三点：膜内外物质浓度梯度、转运蛋白的数量（只影响协助扩散）、温度（一定范围内升高则速率增大，过高会破坏膜结构）。三幅坐标图要会看：自由扩散的速率与浓度差成正比；协助扩散的速率先升后平，因为转运蛋白会饱和；被动运输不耗能，所以速率与能量供应无关。易错提醒：同种物质的运输方式可能不同（水、葡萄糖都是例子）；质壁分离复原后细胞液的浓度不等于外界溶液浓度（复原用的是清水，浓度更小）；只给一张质壁分离的静态图，判断不了当时细胞液与外界溶液谁的浓度大。", "vtech": [["渗透装置题先看两个条件", "看到漏斗、U形管这类渗透装置题 → 先看两个条件：有没有半透膜（纱布是全透膜，不算）、膜两侧有没有浓度差（等浓度不发生表观渗透）；再看水往哪走：从溶质低浓度往高浓度走，也就是从水相对含量高的一侧往低的一侧走，液面升高是因为单位时间内进来的水比出去的多。"], ["质壁分离题先认三个条件", "看到质壁分离题 → 先认三个条件：活的、成熟的、植物细胞；再分外因（外界溶液浓度＞细胞液浓度）和内因（原生质层伸缩性＞细胞壁）；做题时注意：只给一张静态图，判断不了当时细胞液和外界溶液谁的浓度大；复原后细胞液浓度也不等于外界溶液浓度。"], ["自动复原题认溶质被吸收", "看到质壁分离后没加清水就自己复原 → 想溶质被吸收：硝酸钾、葡萄糖、甘油、尿素等溶液中，细胞会主动或被动吸收溶质，细胞液浓度变大就吸水复原；一开始只有水在动，溶质分子大、进得慢，所以先分离、后复原。"], ["自由扩散协助扩散题看转运蛋白", "看到问运输方式的题 → 先看要不要转运蛋白：不要的是自由扩散（气体、甘油、乙醇、苯、少部分水），要的是协助扩散（离子、葡萄糖进红细胞、大部分水）；载体蛋白要结合、会变构像、选择性强，通道蛋白不结合、不变构像、选择性相对弱。"]], "vgaokao": []}}, "bio_b015": {"name": "主动运输与胞吞、胞吐", "sec": 15, "secTitle": "主动运输与胞吞、胞吐", "page": 69, "desc": "主动运输的三个条件；胞吞与胞吐；三种跨膜方式对比表。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b014"], "next": [], "content": {"advance": {"a": "主动运输能逆浓度梯度运输物质，使细胞不依赖外界浓度高低就能按需取舍。一方面，小肠上皮细胞即使在肠腔葡萄糖、氨基酸浓度较低时，也能通过主动运输继续吸收，保证营养物质充分进入体内；另一方面，细胞能主动吸收 K+ 等必需离子、排出 Na+ 及代谢废物和有害物质，维持细胞内适宜的离子浓度和内环境稳定。若只能被动运输，细胞将无法在低浓度环境中获取必需物质，也无法维持内外离子差异，许多生理活动将无法正常进行。", "kind": "self", "q": "为什么主动运输对细胞的生命活动具有重要意义？请结合小肠上皮细胞吸收营养物质和细胞排出废物两个方面简要说明。"}, "apply": [{"ans": 2, "opts": ["自由扩散", "协助扩散", "主动运输", "胞吞"], "q": "小肠上皮细胞能从肠腔中吸收葡萄糖，即使肠腔葡萄糖浓度低于细胞内时仍可继续吸收。这一事实说明该吸收方式是（ ）", "why": "能在浓度低的一侧向浓度高的一侧运输，即逆浓度梯度，必须消耗能量并借助载体蛋白，属于主动运输。被动运输只能顺浓度，胞吞针对大分子或颗粒。"}, {"ans": 2, "opts": ["自由扩散", "协助扩散", "主动运输", "胞吐"], "q": "某物质跨膜运输速率随氧浓度变化的曲线显示：氧浓度为零时速率较低，随氧浓度升高速率增大，最后趋于稳定。该物质的运输方式最可能是（ ）", "why": "速率受氧浓度影响说明需要呼吸供能；氧浓度为零时无氧呼吸仍供少量能量所以速率不为零；最后稳定是受载体数量限制。自由扩散和协助扩散不耗能，与氧浓度无关。"}, {"ans": 2, "opts": ["O2 进入细胞", "水分子自由扩散出细胞", "细胞通过胞吐排出分泌蛋白和通过主动运输吸收离子", "葡萄糖顺浓度进入红细胞"], "q": "用呼吸抑制剂处理细胞后，下列过程受影响最明显的是（ ）", "why": "呼吸抑制剂减少 ATP 供应，耗能过程受影响。胞吐和主动运输都耗能；O2 和水的自由扩散、葡萄糖进红细胞的协助扩散都不耗能，受影响小。"}], "basics": [{"ans": 1, "opts": ["顺浓度梯度、不需要能量", "逆浓度梯度、需要载体蛋白并消耗 ATP", "不需要转运蛋白、依靠膜的流动性", "只能运输大分子和颗粒物质"], "q": "主动运输不同于被动运输的根本特点是（ ）", "why": "主动运输的标志是逆浓度梯度运输，需要载体蛋白并消耗 ATP。A 是被动运输特点，C 和 D 描述的是胞吞胞吐。"}, {"ans": 2, "opts": ["白细胞吞噬细菌", "变形虫吞食食物颗粒", "胰岛细胞将胰岛素分泌到细胞外", "葡萄糖进入小肠上皮细胞"], "q": "下列过程属于胞吐的是（ ）", "why": "胰岛素是分泌蛋白，属于大分子，通过囊泡与细胞膜融合以胞吐方式排出。A 和 B 是胞吞，D 是主动运输。"}, {"ans": 3, "opts": ["都需要消耗 ATP", "都需要转运蛋白", "都是顺浓度梯度运输", "运输的都是小分子或离子等物质跨膜进出"], "q": "自由扩散、协助扩散和主动运输都具有的特点是（ ）", "why": "前三种方式运输的对象都是小分子或离子直接跨膜。被动运输不耗 ATP，自由扩散不需要转运蛋白，主动运输是逆浓度梯度，所以 A、B、C 都不对。"}], "case": {"a": "甲为自由扩散：运输速率与膜外浓度差成正比呈直线，不需要转运蛋白，也不消耗能量。乙为协助扩散：速率达到饱和说明需要转运蛋白且数量有限，但不依赖氧浓度、不消耗能量，只能顺浓度进行。丙为主动运输：需要能量，速率随供能增强（氧浓度升高、呼吸增强）而增大，最终因载体蛋白数量有限而饱和，可逆浓度梯度运输。", "hints": ["直线且不受载体限制的是自由扩散，饱和说明需要转运蛋白", "是否受氧浓度影响决定是否耗能，这是区分协助扩散和主动运输的关键"], "q": "研究人员测得三种物质跨膜运输的速率。甲物质的运输速率随膜外浓度增大呈直线上升，不受氧浓度影响。乙物质的运输速率随膜外浓度增大先上升后趋于饱和，也不受氧浓度影响。丙物质的运输速率随氧浓度升高而增大，最后趋于稳定。请判断甲、乙、丙分别属于哪种运输方式，并说明判断依据。", "steps": ["先看甲：速率与浓度成正比、一条直线、无饱和、无能量影响，符合自由扩散特征", "再看乙：出现饱和说明需要转运蛋白，但不受氧浓度影响说明不耗能，只能是协助扩散", "最后看丙：速率随氧浓度升高而增大说明耗能，最后饱和说明受载体数量限制，符合主动运输特征"], "talk": ["曲线判读三步：先看耗不耗能，再看要不要载体，最后看顺逆浓度", "有饱和不等于主动运输，还要看跟不跟氧浓度走"], "title": "案例：根据两条曲线判断三种物质的运输方式"}, "intro": "被动运输只能顺着浓度走，可细胞经常要做相反的事：浓度已经很高了，还要继续往里搬。这就要靠 **主动运输**，再加上处理大分子的 **胞吞** 和 **胞吐**。==主动运输能逆浓度梯度把物质搬进细胞，保证细胞按生命活动的需要主动选择吸收。==\n\n这一节考试分量很重，尤其是三种跨膜方式的对比表和速率曲线，几乎年年考。==判断一种运输方式，先看方向是顺浓度还是逆浓度，再看要不要载体、要不要能量，三点对上就不会判错。==", "learn": [{"h": "主动运输：逆着浓度搬，要载体也要能量", "p": " **主动运输** 有三个硬特征，缺一不可：方向是 **逆浓度梯度**，从低浓度一侧运到高浓度一侧；需要 **载体蛋白** 帮忙；要消耗细胞代谢提供的能量，主要是 **ATP**。\n\n典型例子要记牢：**小肠上皮细胞吸收葡萄糖和氨基酸**、细胞吸收 **无机盐离子** 如 K+、Na+、Ca2+ 等，都是主动运输。注意跟上一节对照：葡萄糖进红细胞是顺浓度的协助扩散，葡萄糖进小肠上皮细胞是逆浓度的主动运输，同一个物质、不同细胞、方式完全不同，这是最经典的对照题。\n\n意义也要会写：==主动运输保证了活细胞能按照生命活动的需要，主动选择吸收所需要的营养物质，排出代谢废物和对细胞有害的物质。=="}, {"h": "影响主动运输的因素：载体数量和能量供应", "p": "主动运输速率主要受两个因素限制。一个是 **载体蛋白的数量**，载体就那么多，全都忙起来以后，再提高外界浓度速率也不涨了，会出现 **饱和**。\n\n另一个是 **能量供应**，能量来自细胞呼吸，所以 **氧浓度**、**呼吸强度**、温度等因素都会通过影响呼吸作用间接影响主动运输。比如氧浓度为零时，细胞只能靠无氧呼吸供能，主动运输速率较低；氧浓度升高，速率先上升，到一定程度后又受载体数量限制而不再上升。==凡是影响细胞呼吸和能量供应的因素，都会影响主动运输的速率。== 抑制呼吸作用的药物、缺氧、低温，都会让主动运输变慢。"}, {"h": "胞吞和胞吐：大分子和颗粒的进出方式", "p": "蛋白质、多糖这样的大分子，还有固体颗粒，根本穿不过细胞膜，只能靠 **胞吞** 和 **胞吐**。胞吞是往里吃：细胞膜内陷把物质包起来形成囊泡送进细胞，如 **白细胞吞噬病原体**、**变形虫摄食**。胞吐是往外吐：囊泡与细胞膜融合把物质排出，如 **分泌蛋白** 的排出、神经递质的释放。\n\n这两个过程的共同点要记清：都依赖 **细胞膜的流动性**，都要 **消耗能量**，但都 **不需要载体蛋白**。==胞吞和胞吐运输的是大分子或颗粒物质，小分子和离子一般不通过这种方式跨膜。== 考试常问分泌蛋白怎么出细胞，答案是胞吐，不是自由扩散也不是主动运输。"}, {"h": "三种方式对比表：必考，逐项对清", "p": "把被动运输和主动运输放在一张表里对比，是这一章最核心的得分点。**自由扩散**：顺浓度、不需要载体、不耗能，例子是水、O2、CO2、甘油、乙醇。**协助扩散**：顺浓度、需要转运蛋白、不耗能，例子是葡萄糖进红细胞、水过水通道蛋白。**主动运输**：逆浓度、需要载体蛋白、耗能，例子是小肠上皮细胞吸收葡萄糖和氨基酸、离子吸收。\n\n胞吞胞吐单独记：方向可进可出、不需要载体、耗能、靠膜的流动性、对象是大分子或颗粒。答题时不要把胞吞胞吐硬塞进顺逆浓度的框架里，它不讨论浓度梯度。"}, {"h": "跨膜速率曲线怎么判读：看形状下结论", "p": "曲线题是这一节的压轴类型，关键看两件事：速率跟浓度的关系、速率跟氧浓度或能量的关系。\n\n第一类，横轴是膜外物质浓度：**自由扩散** 的速率与浓度差成正比，是一条过原点的 **直线**，不受载体限制；**协助扩散和主动运输** 一开始速率随浓度升高而升高，到一定浓度后因 **载体数量有限** 而达到饱和，曲线先升后平。==只要曲线出现饱和平台，就说明该运输需要转运蛋白并受其数量限制。==\n\n第二类，横轴是氧浓度：自由扩散和协助扩散不耗能，速率与氧浓度无关，是水平线；主动运输在氧浓度为零时仍有较低速率（无氧呼吸供能），随氧浓度升高而升高，最后受载体数量限制而饱和。看到曲线随氧浓度变化，就能反推它是主动运输。"}], "pitfalls": ["把葡萄糖进小肠上皮细胞和进红细胞混为一谈：前者逆浓度、耗能，是主动运输；后者顺浓度、不耗能，是协助扩散，判断依据是方向和能量，不是物质本身。", "认为胞吞胞吐需要载体蛋白：它们靠膜的流动性完成，需要能量但不需要载体，这一点常被出题人拿来设错。", "看到速率曲线饱和就只想到主动运输：协助扩散同样受载体数量限制会出现饱和，必须再结合是否耗能、是否随氧浓度变化来区分。", "认为氧浓度为零时主动运输速率就是零：无氧呼吸也能提供少量 ATP，所以速率不为零，只是较低。", "把分泌蛋白的排出说成主动运输：分泌蛋白是大分子，只能通过胞吐排出，不能直接跨膜运输。"]}, "video": {"bvid": "BV1p54y177e6", "p": 31, "t": "主动运输与胞吞、胞吐", "dur": "43:44", "from": "锦城大同教育·杨波生物", "vtop": ["主动运输就三要素：逆浓度梯度、载体蛋白、耗能——判题先看方向，离子和葡萄糖两种方式都可能走。", "胞吞胞吐运大分子，不走转运蛋白、要耗能，物质穿过 0 层膜；能证明膜有流动性，不能证明选择透过性。", "氧气浓度曲线：O₂=0 时主动运输仍有速率（无氧呼吸供能），B 点后不再升是载体蛋白饱和了。"], "vsum": "本课讲第四章第二节，分两讲：第一讲是**主动运输**，第二讲是**胞吞和胞吐**。开场先看教材例子：人体合成甲状腺激素需要**碘**，甲状腺滤泡上皮细胞内的碘浓度比血液中高 20 到 25 倍，细胞要从低浓度的血液里把碘运进高浓度的细胞内，这是**逆浓度梯度**的运输，不可能是顺浓度梯度的被动运输，只能是**主动运输**。主动运输的定义是：物质**逆浓度梯度**进行跨膜运输，需要**载体蛋白**的协助，同时需要消耗细胞内化学反应所释放的**能量**（如 ATP）。==主动运输就三要素：逆浓度梯度、载体蛋白、耗能，缺一个都不算。==注意只能说载体蛋白，不能说转运蛋白——转运蛋白还包括通道蛋白，主动运输不用通道蛋白。实例：**K⁺、Ca²⁺、Na⁺** 等离子逆浓度梯度时是主动运输，顺浓度梯度时就是协助扩散，只看离子种类会错，必须看方向；**小肠上皮细胞**从小肠液中吸收葡萄糖和氨基酸、**肾小管上皮细胞**吸收葡萄糖，都是主动运输。主动运输的意义是**主动选择吸收所需要的物质**、排出代谢废物和对细胞有害的物质，保证细胞和个体生命活动的需要。易错提醒三则：①相对分子质量小的物质和离子不一定都能自由扩散进细胞，离子运输一定需要转运蛋白，要么主动运输、要么协助扩散；②葡萄糖不一定都以协助扩散进入细胞，小肠和肾小管吸收葡萄糖是主动运输；③主动运输的结果是**加大膜内外浓度差**，不是让浓度趋于相等。第二讲是胞吞和胞吐：小分子、离子走主动运输和被动运输，**大分子物质**只能靠胞吞、胞吐进出细胞。**胞吞**是大分子与膜上的蛋白质结合，引起这部分细胞膜内陷形成小囊，囊泡从细胞膜上分离下来进入细胞内；这个过程有**选择性**，只有细胞需要的物质才会被包进来，靠膜上的蛋白质识别；吞进来的吞噬泡（吞饮泡）与**溶酶体**融合，水解酶把大分子消化成小分子再利用。**胞吐**是细胞需要外排的大分子先在细胞内形成囊泡，移动到细胞膜处融合，把大分子排出细胞，**分泌蛋白**就是这样分泌出去的。胞吞胞吐有四个特点：①主要运输大分子物质（蛋白质、多糖等），某些小分子也可以；②不需要载体蛋白、通道蛋白的协助，但需要膜上特定蛋白质的参与；③需要消耗能量；④依赖膜的流动性。==胞吞胞吐能证明膜有流动性，但不能证明选择透过性：物质是被膜包着进出的、没有直接穿过膜，穿过 0 层膜，透过性那一半体现不出来。==问题探究：游离于细胞质基质中的核糖体合成的是**胞内蛋白**，供细胞自身使用，因为蛋白质是大分子、穿不了膜，只能留在细胞内；附着在内质网上的核糖体合成的是**分泌蛋白**，进内质网腔加工→囊泡→高尔基体加工分类包装→囊泡→细胞膜胞吐出去。最后讲影响物质跨膜运输的因素和曲线分析：**物质浓度**——自由扩散的速率与浓度成正比一直上升；协助扩散和主动运输先升后平，因为转运蛋白数量有限、达到饱和后速率不再增加。**氧气浓度**——氧气影响呼吸速率、进而影响供能多少；被动运输不耗能，速率是一条水平直线；主动运输随氧气浓度增加先升后平，氧气浓度为 0 时仍有速率，靠**无氧呼吸**供能，B 点后不再升是**载体蛋白数量**饱和了。**温度**——影响膜的流动性，也影响酶的活性、进而影响呼吸速率和供能。总结：被动运输和主动运输运的都是小分子物质和离子，胞吞胞吐主要运大分子；被动运输顺浓度梯度、不耗能，自由扩散不用转运蛋白、协助扩散用转运蛋白（载体蛋白或通道蛋白）；主动运输逆浓度梯度、要载体蛋白、耗能；胞吞胞吐不走转运蛋白、要耗能。教材练习要点：果脯在腌制中慢慢变甜，是细胞死亡、膜失去选择透过性变成全透性，蔗糖自由进入，不是主动运输；脂溶性小分子易自由扩散进出细胞；葡萄糖进入红细胞要转运蛋白、不耗能，是协助扩散；大肠杆菌吸收 K⁺ 既耗能又要载体蛋白，是主动运输；胃蛋白酶原这类大分子运出细胞是胞吐；萎蔫菜叶放清水恢复含水量，靠水自由扩散和协助扩散；需要载体蛋白的是 K⁺ 被小肠绒毛上皮细胞吸收。", "vtech": [["判主动还是协助扩散，先看浓度方向", "看到离子或葡萄糖的运输题 → 先判方向：逆浓度梯度就是主动运输，顺浓度梯度就是协助扩散；别只看物质种类——K⁺、Ca²⁺、Na⁺、葡萄糖两种方式都可能走，方向才是判据。"], ["氧气浓度曲线：A 点和 B 点各看什么", "O₂=0 时主动运输速率不为零 → 靠无氧呼吸供能；B 点后速率不再升 → 载体蛋白数量饱和了；被动运输的曲线是水平直线，因为它不耗能。"], ["胞吞胞吐能不能体现选择透过性", "能体现流动性，不能体现选择透过性：胞吞有选择性（膜上蛋白质识别），但物质没有直接穿过膜、穿过 0 层膜，所以透过性那一半体现不出来。"], ["易错三句话先背下来", "小分子、离子不一定自由扩散（离子必须走转运蛋白）；葡萄糖不一定协助扩散（小肠、肾小管吸收葡萄糖是主动运输）；主动运输是加大膜内外浓度差，不是让浓度趋于相等。"]], "vgaokao": []}}, "bio_b016": {"name": "酶的作用和本质", "sec": 16, "secTitle": "降低化学反应活化能的酶", "page": 76, "desc": "活化能；过氧化氢分解对比实验；酶的本质与作用机理。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b009"], "next": ["bio_b017"], "content": {"advance": {"a": "不对。酶只是降低活化能、加快反应速率，缩短到达平衡的时间，不改变反应的平衡点，也不改变最终产物的量。反应物总量一定时，产物总量由反应物决定，与是否加酶、加哪种催化剂无关。", "kind": "self", "q": "有人说：酶降低了活化能，所以有酶时反应需要的总能量变少，产物也更多。这句话对吗？请说明理由。"}, "apply": [{"ans": 2, "opts": ["加热降低了过氧化氢分解的活化能", "肝脏研磨液提供了大量活化能", "与Fe3+相比，过氧化氢酶降低活化能的作用更显著", "4号试管最终产生的氧气总量比3号多很多"], "q": "在比较过氧化氢分解的实验中，2号试管加热后气泡增多，4号试管加肝脏研磨液后气泡更多、卫生香复燃最强。对此分析正确的是（ ）", "why": "加热是提供能量，不是降低活化能，A错；酶是降低活化能，不提供能量，B错；催化剂不改变平衡点，同量过氧化氢最终氧气总量相同，D错；酶效率更高、降低活化能更显著，选C。"}, {"ans": 0, "opts": ["煮沸使过氧化氢酶的空间结构被破坏而失活", "煮沸使肝脏中的过氧化氢被消耗完", "冷却后温度太低，氧气溶解度太高", "煮沸改变了过氧化氢的活化能数值，使反应不能发生"], "q": "某同学用煮沸后冷却的肝脏研磨液重复上述实验，气泡很少，卫生香不复燃。最合理解释是（ ）", "why": "高温使蛋白质空间结构破坏、酶变性失活，催化能力丧失，选A。实验用的过氧化氢是外加的，与肝脏本身无关。"}], "basics": [{"ans": 2, "opts": ["活化能是反应物分子储存的全部能量", "酶能降低活化能，说明酶为反应提供了能量", "分子从常态转变为容易发生反应的活跃状态所需要的能量叫活化能", "无机催化剂不能降低活化能，只有酶可以"], "q": "下列关于活化能的叙述，正确的是（ ）", "why": "活化能就是分子从常态到活跃状态需要的能量，选C。酶和无机催化剂都能降低活化能，酶只是效率更高；酶不提供能量，B、D错。"}, {"ans": 2, "opts": ["所有酶都是蛋白质", "所有酶都是RNA", "绝大多数酶是蛋白质，少数酶是RNA", "酶都是活细胞产生的无机物"], "q": "关于酶的化学本质，下列说法正确的是（ ）", "why": "酶是活细胞产生的有机物，绝大多数是蛋白质，少数是RNA（核酶），选C。"}], "case": {"a": "(1)加热能促进过氧化氢分解，说明加热为反应提供能量；Fe3+和过氧化氢酶都能催化过氧化氢分解。(2)与无机催化剂Fe3+相比，过氧化氢酶降低活化能的作用更显著，催化效率更高。(3)气泡很少、卫生香不复燃，因为煮沸使过氧化氢酶空间结构被破坏而变性失活，失去催化能力。", "hints": ["先分清加热和催化剂是两条不同的加速路径", "催化剂只改变速率，不改变最终产量"], "q": "甲、乙、丙、丁四支试管各加等量等浓度的过氧化氢溶液：甲常温，乙水浴加热，丙滴加FeCl3溶液，丁滴加新鲜肝脏研磨液。结果丁气泡最猛烈、卫生香复燃最强，丙次之，乙再次，甲最少。请回答：(1)乙与甲对比说明什么？丙、丁与甲对比说明什么？(2)丙与丁对比得出什么结论？(3)若把丁的研磨液煮沸后再加入，预测结果并说明原因。", "steps": ["第一步：乙比甲快，说明加热能给分子提供能量、加快分解。", "第二步：丙、丁比甲快，说明Fe3+和过氧化氢酶都有催化作用。", "第三步：丁比丙快得多，说明酶的催化效率远高于无机催化剂。", "第四步：煮沸使过氧化氢酶变性失活，预测气泡很少、卫生香不复燃。"], "talk": ["看到气泡和卫生香，先想速率，再想活化能：加热给能量，催化降门槛，酶降得最多。"], "title": "案例：四支试管的气泡之争"}, "intro": "细胞里每时每刻都在发生成千上万个化学反应，常温常压下本来慢得不行，为什么在细胞里就能又快又稳？靠的就是**酶**。先把一个概念钉死：分子从常态转变为容易发生化学反应的活跃状态所需要的能量，叫**活化能**。==酶的作用就是降低化学反应的活化能，让反应更容易跨过这道门槛。==\n没有催化剂时门槛高、反应慢，加了催化剂门槛降低，反应就快了，但要注意：==催化剂只缩短到达平衡的时间，不改变反应的平衡点。==", "learn": [{"h": "比较过氧化氢在不同条件下的分解——必考实验", "p": "过氧化氢不稳定，常温下也能慢慢分解成水和氧气。实验分四组：1号常温、2号加热、3号加**FeCl3溶液**（提供Fe3+，无机催化剂）、4号加**新鲜肝脏研磨液**（含过氧化氢酶）。观察两件事：一是气泡产生的多少和快慢，二是把带火星的**卫生香**插进去，看复燃程度。==加热是给反应提供能量，Fe3+和酶是降低活化能，两条路都能加快反应，但原理不同。== 结果：加热组气泡多一些，Fe3+组气泡较多、卫生香复燃较明显，肝脏研磨液组气泡最多、最猛烈、卫生香复燃最强烈。结论：酶具有**催化作用**，且**催化效率比无机催化剂高得多**。"}, {"h": "这个实验怎么做才不扣分", "p": "第一，必须用**新鲜**肝脏研磨液，放久了酶失活，气泡就起不来。第二，各试管的过氧化氢量、催化剂量要**等量**，这是控制无关变量。第三，卫生香要在气泡产生最旺时插入，太早氧气还没攒够、太晚已经散了。第四，不要用煮熟的肝脏代替，煮熟后酶已经变性失活。考试常问自变量是什么：==本实验的自变量是催化剂的种类和是否加热，因变量是过氧化氢分解速率，用气泡多少和卫生香复燃程度表示。=="}, {"h": "酶的化学本质", "p": "酶是**活细胞产生的具有催化作用的有机物**，这个定义四个词都不能丢：活细胞产生、有机物、催化作用。==绝大多数酶是蛋白质，少数酶是RNA。== 少数RNA酶有个专门名字叫**核酶**。判断题最爱挖坑：说酶都是蛋白质——错；说酶只能在细胞内起作用——错，提取出来在体外合适的条件下照样能催化，比如唾液淀粉酶在试管里也能分解淀粉。"}, {"h": "酶为什么能降低活化能", "p": "可以把反应物想成要翻过一座山，活化能就是山高。酶能和底物结合，形成酶—底物复合物，让反应物更容易进入活跃状态，相当于把山挖低了。反应结束后酶又被释放出来，本身不被消耗、性质不变，还能接着催化下一轮。==酶和其他催化剂一样，只改变化学反应的速率，不改变产物的量和反应的方向。=="}], "pitfalls": ["把加热加快反应说成降低活化能——加热是提供活化能，催化剂才是降低活化能，两者不能混。", "认为酶都是蛋白质，或认为酶离开细胞就不能起作用——少数酶是RNA，酶在细胞内外都能起作用，只要条件合适。"]}, "video": {"bvid": "BV1p54y177e6", "p": 33, "t": "降低化学反应活化能的酶（上）：酶的作用和本质", "dur": "50:36", "from": "锦城大同教育·杨波生物", "vtop": ["酶的作用原理只有一句：降低化学反应的活化能——酶本身不被消耗、不提供物质和能量、不改变反应方向和生成物量。", "比较过氧化氢分解实验要会背四支试管：常温几乎无气泡、加热较少、氯化铁较多、肝脏研磨液大量气泡，结论是酶有催化作用且效率高于无机催化剂。", "实验题先分清三种变量：自变量是人为处理步骤，因变量是过氧化氢分解速率，其余都是无关变量、控制要相同且适宜。"], "vsum": "本课讲第五章第一节，分两部分：第一部分是**酶在细胞代谢中的作用**，第二部分是**酶的本质**。开场先看教材例子：1773 年意大利科学家斯帕兰扎尼把肉块放进小巧的金属笼，让鹰吞下去，过一段时间取出来，肉块消失了。三个讨论：①为什么把肉块放进金属笼？胃有机械消化，金属笼是防止胃的机械性消化干扰实验；②什么物质使肉块消失了？消化道里的消化液，更准确地说是消化液中的各种**消化酶**；③怎样证明？直接提取消化液，放入肉块，观察肉块体积是否减小甚至消失。先讲**细胞代谢**：细胞中每时每刻都进行着的许多化学反应的统称，细胞的生活需要物质和能量，能量的释放、储存和利用都离不开这些化学反应。细胞代谢的**主要场所是细胞质基质**，**控制中心是细胞核**，它是细胞生命活动的基础。代谢会产生有害物质，比如**过氧化氢**，大量积累会毒害细胞，肝脏细胞里有较多的**过氧化氢酶**能把它分解掉。教材实验是比较过氧化氢在不同条件下的分解：四支试管都加 2 mL 过氧化氢溶液，1 号常温放置，几乎没有气泡；2 号 90℃ 左右水浴加热，较少气泡；3 号加 2 滴氯化铁溶液（**无机催化剂**，起作用的是 Fe³⁺），较多气泡；4 号加 2 滴新鲜肝脏研磨液（里面含过氧化氢酶），大量气泡。结论有两个：**酶具有催化作用**；同无机催化剂相比，**酶的催化效率更高**。衡量分解速率的指标不唯一：可以直接观察气泡产生量，也可以用带火星的卫生香（或木条）伸入试管看复燃情况——1 号、2 号不复燃，3 号发亮但不复燃，4 号复燃。实验里变量分三种：**自变量**是人为控制的、对实验对象进行处理的因素，本实验就是加热、加氯化铁、加肝脏研磨液这些处理步骤；**因变量**是因自变量改变而变化的变量，本实验是过氧化氢的分解速率；**无关变量**是除自变量外、会对实验结果造成影响的可变因素，比如肝脏研磨液的新鲜程度、底物的量和浓度、实验室温度等，控制时要**相同且适宜**——只相同还不够，量太少会看不出差别，实验就做不下去。**对照实验**是除自变量外其余因素都保持一致、并将结果进行比较的实验，要设对照组和实验组；**单一变量原则**是实验组和对照组只有一个变量在变，这样结果不同才能确定是这个变量造成的；**等量性原则**和单一变量原则说的是同一个东西，侧重点不同——等量性原则强调除自变量外的无关变量必须相等且适宜；还有**平行重复原则**，以后遇到再讲。对照实验有四种类型：**空白对照**是不给对照组做任何实验处理，本实验的 1 号试管就是空白对照；**自身对照**是对照组和实验组在同一个研究对象上进行，比如观察植物细胞质壁分离及复原；**条件对照**是给对照组施以某种实验处理，但这种处理是作为对照因素、不是所要研究的实验因素；**相互对照**是不设对照组、几个实验组之间相互对照，比如散枣嫁接实验。接着讲酶的作用原理：先记**活化能**——分子从常态转变为容易发生化学反应的活跃状态所需要的能量。酶的作用原理就是**降低化学反应的活化能**：看能量-反应过程曲线图，三条曲线是同一个反应，最上面是没有加催化剂的，中间是加无机催化剂的，最下面是加酶的；酶降低的活化能最多，所以催化效率最高。考试常问酶降低的活化能是多少：没加酶时活化能是 E₂，加酶后是 E₃，酶降低的活化能是 **E₂−E₃**，别和加酶后反应所需要的活化能 E₃ 弄混。还有一个重要结论：**酶本身不被消耗、不为化学反应提供物质和能量、也不改变反应的方向和生成物的量**，只改变反应速率——三条曲线的起点和终点都一样。加热也能加快反应，但原理不同：**加热不能降低活化能**，它是增加分子内能、给分子提供能量、增加活化分子数，相当于给汽车加油门，而加催化剂是给大山挖隧道。易错提醒四则：①酶能提高活化能——错，是降低；②酶使过氧化氢得到了能量——错，酶不提供物质和能量；③无关变量与实验结果无关——错，无关变量会影响结果；④因变量的检测指标往往不是唯一的——对，气泡量和卫生香复燃都可以。第二部分讲酶的本质，探索历程要按顺序记：最初人们认为发酵是纯化学过程，与生命活动无关；**巴斯德**认为发酵由酵母菌细胞的存在所致、需要活细胞参与；化学家**李比希**认为引起发酵的是酵母菌细胞中的某些物质，但只有在酵母菌细胞死亡并裂解后才能发挥作用；**毕希纳**发现酵母菌细胞中的某些物质在酵母菌破碎后仍能继续起催化作用；**萨姆纳**从刀豆种子中提取出脲酶，证明脲酶是蛋白质；**切赫和奥特曼**发现少数 RNA 也具有生物催化功能。结论：**绝大多数酶是蛋白质，少数酶是 RNA**；酶由活细胞产生，一般来说活细胞都能产生酶；作用场所不局限，细胞内、细胞外、体内、体外都能起作用。易错提醒五则：①酶的基本组成单位是氨基酸——不完整，RNA 酶的基本单位是核糖核苷酸；②只有具有分泌功能的细胞才能产生酶——错，一般活细胞都能产生；③酶只能在细胞内起作用——错，内外、体内外都行；④酶在反应完成后立即被降解成氨基酸——错，酶可以反复利用；⑤酶具有催化、调节等多种功能——错，只有催化，没有调节。教材练习：①关于酶的特点及本质，选 D——酶是具有催化作用的有机物（蛋白质和 RNA 都是有机物）；②与无机催化剂相比，酶的特点是催化化学反应更高效。", "vtech": [["自变量、因变量、无关变量怎么分", "看到实验题 → 先找人为改变的处理步骤，那是自变量；因自变量改变而变化的量是因变量；其余会干扰结果的量都是无关变量，答题要写“相同且适宜”，只写相同不够。"], ["对照实验四种类型，先认空白对照和自身对照", "空白对照是不给对照组做任何处理（如本实验的 1 号试管）；自身对照是同一对象前后对比（如质壁分离及复原）；条件对照和相互对照考得少，遇到再按定义判。"], ["酶降低的活化能怎么算", "没加酶时活化能是 E₂，加酶后是 E₃，酶降低的活化能是 E₂−E₃；别和“加酶后反应所需要的活化能 E₃”弄混；三条曲线起点终点相同，说明酶不改变反应方向和生成物量。"], ["酶的本质与易错点", "绝大多数酶是蛋白质、少数是 RNA；酶由活细胞产生、内外体内外都能起作用、可反复利用；易错：基本组成单位要分蛋白质酶（氨基酸）和 RNA 酶（核糖核苷酸）两种情况答。"]], "vgaokao": []}}, "bio_b017": {"name": "酶的特性", "sec": 17, "secTitle": "降低化学反应活化能的酶", "page": 80, "desc": "高效性、专一性、作用条件温和；温度与 pH 曲线；低温与高温失活的区别。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b016"], "next": ["bio_b018"], "content": {"advance": {"a": "错误在于忽略了高温使酶失活。曲线应先升后降，最高点是最适温度。低温一侧：温度低只是抑制酶活性，空间结构未破坏，升温可恢复；高温一侧：温度过高破坏蛋白质空间结构，酶变性失活，即使降温也不能恢复。", "kind": "self", "q": "画温度对酶活性影响曲线时，有同学把曲线画成随温度升高一直上升。请指出错误，并说明在最适温度两侧，酶活性下降的原因有何不同。"}, "apply": [{"ans": 1, "opts": ["斐林试剂在酸性条件下失效", "过酸过碱已使酶变性失活，调回中性也不能恢复活性", "淀粉在酸性条件下自动水解完了", "实验温度太低，酶没有活性"], "q": "用淀粉酶探究pH对酶活性的影响，某同学先将酶和淀粉在不同pH下混合后再调回中性检测，结果各组淀粉剩余量差别不大。最可能的原因是（ ）", "why": "过酸、过碱破坏酶的空间结构，失活不可逆，即使调回最适pH活性也回不来，所以各组结果接近、看不出差别，选B。做这类实验应先让酶在预设pH下处理，再与底物混合计时。"}, {"ans": 1, "opts": ["小肠温度太低", "pH过高破坏了胃蛋白酶的空间结构", "小肠里没有蛋白质底物", "胃蛋白酶被胰蛋白酶分解完了"], "q": "胃蛋白酶进入小肠（pH约8）后基本失去催化能力，主要原因是（ ）", "why": "胃蛋白酶最适pH约1.5-2，小肠pH约8远远偏离，过碱使空间结构破坏而失活，选B。"}], "basics": [{"ans": 2, "opts": ["一种酶可以催化所有类型的化学反应", "淀粉酶能催化淀粉水解，也能催化蔗糖水解", "一种酶只能催化一种或一类化学反应", "专一性说明酶的催化效率比无机催化剂高"], "q": "下列关于酶专一性的叙述，正确的是（ ）", "why": "专一性就是一种酶只能催化一种或一类反应，选C。D说的是高效性，不是专一性。"}, {"ans": 1, "opts": ["两者都永久失活", "0℃组活性恢复，100℃组活性不能恢复", "0℃组不能恢复，100℃组能恢复", "两者活性都能完全恢复"], "q": "将唾液淀粉酶分别置于0℃和100℃环境中一段时间，再都回到37℃，其活性变化是（ ）", "why": "低温只抑制活性、不破坏空间结构，回温可恢复；高温使蛋白质变性失活，不可恢复。选B。"}], "case": {"a": "(1)温水接近蛋白酶的最适温度，酶活性高；开水高温破坏酶的空间结构，使酶变性失活。(2)血渍、奶渍主要含蛋白质，洗衣粉中的蛋白酶能专一地催化蛋白质水解，体现了酶的专一性。(3)不会完全丧失。低温只是抑制酶活性、不破坏空间结构，温度恢复后活性可以恢复。", "hints": ["血渍奶渍的主要成分是蛋白质，对应蛋白酶", "区分低温抑制和高温失活"], "q": "加酶洗衣粉说明书写着：用温水浸泡效果好，不要用开水烫洗；对血渍、奶渍效果好，对油渍要配合去油成分。请用酶的特性解释：(1)为什么温水好、开水不好？(2)为什么对血渍奶渍效果好，体现了酶的什么特性？(3)如果把洗衣粉水放在冰箱里冻一晚再拿出来化开用，效果会完全丧失吗？", "steps": ["第一步：蛋白酶有最适温度，温水接近最适温度，活性高、去污快。", "第二步：开水高温使蛋白酶变性失活，去污能力丧失。", "第三步：蛋白酶专一催化蛋白质水解，所以对血渍奶渍有效，体现专一性。", "第四步：低温只抑制活性，化开回温后活性可恢复，效果不会完全丧失。"], "talk": ["记酶的脾气就六个字：高温死、低温睡，酸碱过头也死。"], "title": "案例：洗衣粉广告背后的酶"}, "intro": "酶有三个脾气，考试年年考：**高效性**、**专一性**、**作用条件较温和**。高效性是和无机催化剂比出来的，专一性是和底物一一对应，温和则体现在温度和pH都有一个最合适的点。==温度和pH偏离最适值，酶活性就下降，过酸、过碱或高温会让酶永久失活。==\n这里先埋一个最爱考的坑：==低温只是抑制酶的活性，温度回升活性可以恢复；高温造成的失活不可恢复。==", "learn": [{"h": "高效性和专一性怎么理解", "p": "**高效性**：酶的催化效率一般比无机催化剂高很多倍，所以细胞里只需要很少的酶就能催动大量反应。**专一性**：==一种酶只能催化一种或一类化学反应。== 经典实验：淀粉酶分别作用于淀粉和蔗糖，淀粉组加**斐林试剂**水浴加热后出现砖红色沉淀，说明淀粉被水解成了还原糖；蔗糖组不变色。这里有个细节必须说清：**蔗糖本身不是还原糖**，不变色正是因为淀粉酶不能水解蔗糖，不要误以为是试剂失效。锁和钥匙的关系就是专一性最直观的比喻。"}, {"h": "温度和pH曲线怎么读", "p": "在一定范围内，温度升高、酶活性升高，到**最适温度**时活性最高，再升高就迅速下降，高温下蛋白质空间结构被破坏、**变性失活**。pH曲线同理，有一个**最适pH**，过酸过碱都会破坏空间结构。读曲线记住三点：==最适点之前活性低是被抑制，不是失活；最适点之后高温、过酸、过碱造成的下降往往不可恢复。== 不同酶最适条件不同：**唾液淀粉酶**最适温度约37℃、接近中性，**胃蛋白酶**最适pH约1.5-2，**胰蛋白酶**最适pH约8。把胃蛋白酶放到pH 8的环境，它会失活，而不是活性更高。"}, {"h": "酶活性到底指什么", "p": "**酶活性**指酶催化一定化学反应的能力，一般用单位时间内底物的消耗量或产物的生成量来表示。影响酶活性的因素主要是**温度**和**pH**，底物浓度和酶浓度影响的是反应速率，不要和活性混为一谈：在酶量固定、底物充足时速率快，不等于单个酶的活性变高了。做影响因素实验时，自变量只设一个，温度、pH、底物量等无关变量必须等量且适宜。"}], "pitfalls": ["把低温失活当成永久失活——低温只抑制活性、不破坏空间结构，升温后活性恢复；高温、过酸、过碱才是不可逆失活。", "淀粉酶对蔗糖实验中，认为蔗糖组不变色是因为蔗糖是还原糖被消耗了——蔗糖本身是非还原糖，不变色是因为没有被水解。", "认为底物浓度越大酶活性越高——底物浓度影响反应速率，不改变酶活性本身。"]}, "video": {"bvid": "BV1p54y177e6", "p": 35, "t": "降低化学反应活化能的酶（二）", "dur": "71:25", "from": "锦城大同教育·杨波生物", "vtop": ["过酸、过碱或温度过高都会破坏酶的空间结构使酶永久失活，而且高温失活不可逆，低温只降低活性、升温后活性可以恢复。", "酶制剂适宜低温保存（常用0–4℃，长期保存-20～-80℃），绝不能保存在最适温度下，否则活性会白白流失。", "探究温度或pH对酶活性影响时，选材要排除自变量自身对结果的影响：温度实验不用过氧化氢酶，pH实验不用淀粉酶。"], "vsum": "本课是第五章第一节的第二课时，继续讲**降低化学反应活化能的酶**。开场先回顾上节课：**酶是活细胞产生的、具有催化作用的有机物**，一般来说活细胞都能产生酶，因为活细胞内的化学反应几乎都需要酶来起催化作用；酶的化学本质绝大多数是**蛋白质**，少数是**RNA**，不论哪种都属于有机物。接着讲酶的三个特性。第一个特性是**高效性**：和无机催化剂相比，酶的催化效率更高——过氧化氢酶催化过氧化氢分解的实验里，加酶的一组过氧化氢分解速率更快、产生的氧气也更多；原因是酶比无机催化剂更显著地**降低化学反应的活化能**，酶的催化效率是无机催化剂的**10的7次方到10的13次方倍**。第二个特性是**专一性**：每一种酶只能催化**一种或者一类**化学反应，比如过氧化氢酶只能催化过氧化氢分解，科学家从刀豆种子中提取的**脲酶**只能催化尿素分解为氨和二氧化碳；无机催化剂则没有专一性，比如酸既能催化蛋白质水解，也能催化脂肪和淀粉的水解。第三个特性是**作用条件较温和**：酶所催化的化学反应条件比较温和，**过酸、过碱或者温度过高都会破坏酶的空间结构**，使蛋白质变性、酶永久失活——因为绝大多数酶的化学本质是蛋白质，而过酸、过碱或高温都会破坏蛋白质的空间结构。**低温**则不一样：低温只使酶的活性降低，不破坏空间结构，酶不会失活，升到适宜温度后活性还能恢复；所以**酶制剂适宜在低温下保存**，随取随用的一般保存在**0到4摄氏度**，需要长期保存的保存在**-20到-80摄氏度**。接着讲温度对酶活性的影响：横坐标是温度、纵坐标是反应速率（可以反映酶活性的大小），曲线先升后降；**在一定条件下酶活性最大时的温度称为该酶的最适温度**，达到最适温度之前，酶促反应速率随温度升高而加快，超过最适温度后随温度升高而下降；高温段的曲线会与横坐标相交（反应速率为零，说明酶已变性失活），低温段没有交点；高温变性失活后即使再降温，活性也**无法恢复**。补充不同生物的最适温度：动物体内酶的最适温度一般在**35到40摄氏度**，接近动物的正常体温，所以发高烧时体内消化酶活性下降，会食欲不振、消化不良；植物体内酶的最适温度是**40到50摄氏度**，比动物稍高；细菌、真菌体内酶的最适温度相差很大，有的甚至可达**70摄氏度**，这是长期进化的结果。再讲pH对酶活性的影响：曲线同样先升后降，**酶活性最大时对应的pH称为该酶的最适pH**，pH偏高或偏低，酶促反应速率都会明显降低；过酸或过碱同样会破坏酶的空间结构，导致酶永久失活；动物体内酶的最适pH一般在**6.5到8.0**之间，植物体内酶一般在**4.5到6.5**，但有特例——**胃蛋白酶**存在于胃酸中，它的最适pH约为**1.5**。细胞内各项生命活动能有序进行，除了适宜的温度和pH，还与酶的分布有关：比如绿色植物叶肉细胞中，与光合作用有关的酶分布在叶绿体里，与呼吸作用有关的酶分布在线粒体和细胞质基质里。接着是判断题练习：二肽酶只能催化二肽的水解，不能催化三肽、四肽、五肽等其他肽的水解，体现了专一性（催化一类反应）；催化脂肪水解的酶应该是脂肪酶，说成蛋白酶是错的；酶在最适温度下活性最高是对的，但说酶适合在最适温度下保存是错的——最适温度下酶活性高，不用它催化反应时活性会白白流失，所以要低温保存。接下来是实验设计，这是本课的难点。**高效性**的实验设计思路：遵循对照原则，实验组在底物中加酶（生物催化剂），对照组加无机催化剂，一段时间后比较底物分解速率或产物生成速率。**专一性**的实验设计有两种方法：一是相同的酶、不同的底物（酶A能分解底物A、不能分解底物B）；二是相同的底物、不同的酶（酶A能分解底物A、酶B不能分解底物A）。具体例子用淀粉酶对淀粉和蔗糖的水解：试管一加2毫升可溶性淀粉溶液，试管二加2毫升蔗糖溶液，量相同（无关变量相同且适宜），淀粉和蔗糖都是非还原糖，分解后都产生还原糖，可用**斐林试剂**检测，出现砖红色沉淀说明分解了；不能用碘液代替斐林试剂——碘液只能和淀粉发生颜色反应，蔗糖和它的分解产物果糖、葡萄糖都不会和碘液发生颜色反应，蔗糖分解与否都看不出来。然后是**探究温度对酶活性的影响**的实验：原理是温度影响淀粉酶的活性，从而影响淀粉的水解速率，淀粉遇碘液变蓝，可根据是否出现蓝色以及蓝色的深浅判断酶活性；实验设三组，分别放在冰水（0摄氏度）、60摄氏度的温水和沸水（100摄氏度）中；做法是取两支试管，一支装2毫升淀粉酶溶液、一支装2毫升可溶性淀粉溶液，先分别在设定温度下水浴保温5分钟，再混合摇匀、继续保温数分钟，然后取出滴加碘液观察；一定要先分别保温再混合，因为酶促反应速度很快，先混合再保温可能还没放进冰水反应就完了，要保证反应开始时就是在设定的温度下进行；结果是60摄氏度组无蓝色（淀粉被完全分解），冰水组和沸水组呈蓝色，结论是酶发挥催化作用需要适宜的温度，温度过高或过低都会影响酶活性。做这个实验还要注意：自变量是温度，pH是无关变量，要保持相同且**适宜**（调到最适pH，不能调到0.1这种不适宜的值）；不能用斐林试剂检测，因为斐林试剂鉴定还原糖需要水浴加热，会改变设定好的温度；也不能用过氧化氢和过氧化氢酶做材料，因为加热本身就会促进过氧化氢分解，分不清氧气增多是酶活性增加还是温度升高的结果。接着是**探究pH对酶活性的影响**的实验：用过氧化氢酶分解过氧化氢，产生水和氧气，通过氧气产生量判断分解速率和酶活性；设三组，一号试管加1毫升蒸馏水（中性），二号加1毫升盐酸（酸性），三号加1毫升氢氧化钠（碱性），每支试管先注入等量的过氧化氢酶（2滴）；关键是先把酶溶液调节到实验要求的pH再与反应底物混合，不能先混合再调pH——先混合的话过氧化氢酶可能已经把过氧化氢全部分解完了，再调pH不起作用；结果是中性试管有大量气泡，过酸、过碱的试管没有气泡，结论是酶发挥催化作用需要适宜的pH，pH偏高或偏低都会影响酶活性。思考题：探究pH对酶活性的影响时不能用淀粉酶分解淀粉的实验，因为酸性条件下淀粉本身就会发生水解；这里要记住选材原则——**选择实验材料时注意排除自变量自身对实验结果的影响**，探究温度不用过氧化氢酶、探究pH不用淀粉酶，都是这个道理。接着是几组**曲线分析**：第一组是高效性的曲线，横坐标是时间，纵坐标是反应达到平衡的情况，加酶的反应最先达到平衡，加无机催化剂的次之，不加催化剂的最慢，但三者最终都达到同一个平衡点——酶只能缩短达到化学平衡所需要的时间，**不能改变化学反应的平衡点，也不能改变生成物的量**；第二组是专一性的曲线，横坐标是底物A的浓度，酶B不能催化底物A，速率与未加酶时一样；第三组是底物浓度对酶促反应速率的影响，底物浓度较低时速率与底物浓度成正比，超过一定范围后速率不再随底物浓度增加而加快，此时的限制因素是**酶的数量**，和协助扩散中转运蛋白数量限制速率是一个道理；第四组是酶浓度的影响，底物充足时酶促反应速率与酶浓度成正比，适量增加酶浓度反应速率加快但生成物量不变，适量增加底物浓度反应速率加快且生成物量也增加。最后要分清两类影响因素：温度和pH是通过影响**酶活性**来影响酶促反应速率的，酶浓度和底物浓度不影响酶活性，而是通过影响底物与酶的接触来影响酶促反应速率。课末是易错提醒与教材练习题：酶促反应速率既可以用反应物消耗速率表示，也可以用产物生成速率表示；探究pH的实验不选淀粉做材料是因为酸能促进淀粉水解；探究影响酶活性的条件至少要设置三组实验；同一种酶取自不同细胞时最适温度可能不一样，比如市售α-淀粉酶是从细菌细胞中提取的，和人体唾液淀粉酶的最适温度就有差别；教材练习题里，嫩肉粉起作用的是蛋白酶（肌肉组织主要由蛋白质构成），新鲜糯玉米85摄氏度热烫2分钟能保持甜味是因为加热破坏了将可溶性糖转化为淀粉的酶的活性，去除植物细胞壁用纤维素酶（细胞壁的成分是纤维素和果胶），酶活性与温度的关系图里T2时反应活化能是最低的（不是最高），最适温度下从A点升温10摄氏度酶活性降低、反应速率下降，在B点加入少量同样的酶反应速率会提高。最后总结：本课讲了酶的三个特性、影响酶活性的温度和pH条件，以及怎样设计实验探究高效性、专一性和作用条件，课后作业是完成课后作业18。", "vtech": [["最适温度、最适pH：两个定义一个套路", "在一定条件下酶活性最大时对应的温度叫最适温度，对应的pH叫最适pH；低于最适值时酶促反应速率随温度或pH升高而加快，超过后随之下降，两条曲线都是先升后降；过酸、过碱或温度过高都会破坏酶的空间结构，导致酶永久失活。"], ["三组最适值数字：动物、植物与胃蛋白酶", "动物体内酶最适温度一般35–40℃（接近正常体温），植物体内酶40–50℃，细菌、真菌体内酶有的可达70℃；动物体内酶最适pH一般6.5–8.0，植物体内酶4.5–6.5，胃蛋白酶最适pH约1.5是特例——它存在于胃酸中。"], ["温度实验：三组温度与“分别保温再混合”", "三组分别放在冰水0℃、60℃温水和沸水100℃中，淀粉酶溶液与可溶性淀粉溶液各取2毫升，先分别在设定温度下水浴保温5分钟再混合摇匀；先混合再保温是错的——酶促反应快，还没放进冰水反应可能已经完了；结果60℃组滴碘液无蓝色（淀粉被完全分解），冰水组和沸水组呈蓝色。"], ["酶浓度、底物浓度：速率变，生成物量未必变", "底物充足时酶促反应速率与酶浓度成正比，适量增加酶浓度速率加快但生成物量不变；适量增加底物浓度速率加快且生成物量也增加；底物浓度较低时速率与底物浓度成正比，超过一定范围后限制因素是酶的数量；酶只能缩短达到化学平衡的时间，不能改变化学平衡点和生成物量。"]], "vgaokao": []}}, "bio_b018": {"name": "细胞的能量“货币”ATP", "sec": 18, "secTitle": "细胞的能量“货币”ATP", "page": 86, "desc": "ATP 结构简式；ATP 与 ADP 相互转化与能量流向。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b017"], "next": ["bio_b019"], "content": {"advance": {"a": "酶不同：水解用ATP水解酶，合成用ATP合成酶。能量不同：水解释放能量供吸能反应，合成需要吸收细胞呼吸或光合作用释放的能量。场所不完全相同：水解发生在需要能量的各个部位，合成主要在线粒体、叶绿体和细胞质基质。因此不是可逆反应。但反应前后的物质是ATP和ADP，二者可以反复互相转化，所以物质可循环，能量不可循环。", "kind": "self", "q": "为什么说ATP和ADP的相互转化不是可逆反应，但物质是可以循环的？请从酶、能量和场所三个角度说明。"}, "apply": [{"ans": 1, "opts": ["肌肉中储存了大量ATP备用", "ATP和ADP的转化迅速，合成与水解保持动态平衡", "运动时细胞不需要消耗ATP", "ADP可以不耗能量直接变成ATP"], "q": "剧烈运动时肌肉细胞中ATP含量不会大幅下降，其原因是（ ）", "why": "ATP含量少但转化迅速，消耗多少就通过细胞呼吸及时合成多少，总量相对稳定，选B。ADP合成ATP需要能量输入，D错。"}, {"ans": 1, "opts": ["DNA的基本单位之一", "RNA的基本单位之一——腺嘌呤核糖核苷酸", "腺嘌呤脱氧核苷酸", "游离的腺嘌呤和核糖"], "q": "ATP脱去两个磷酸基团后的物质是（ ）", "why": "ATP去掉两个磷酸后剩腺苷一磷酸，即腺嘌呤核糖核苷酸，是RNA的基本单位之一，选B。五碳糖是核糖，与DNA无关。"}], "basics": [{"ans": 1, "opts": ["腺嘌呤、普通化学键", "腺苷、一种特殊的化学键", "腺嘌呤核糖核苷酸、高能碳键", "脱氧核糖、磷酸键"], "q": "ATP结构简式中A和～分别代表（ ）", "why": "A是腺苷（腺嘌呤+核糖），～是一种特殊的化学键，结构简式为A-P～P～P，选B。"}, {"ans": 2, "opts": ["葡萄糖氧化分解", "光合作用的光反应", "主动运输吸收离子", "淀粉水解成葡萄糖"], "q": "下列生命活动主要由ATP水解直接供能的是（ ）", "why": "主动运输是吸能过程，由ATP水解供能，选C。葡萄糖氧化分解和光反应是产生ATP的放能过程，淀粉水解本身不耗ATP。"}], "case": {"a": "(1)ATP。(2)ATP是活细胞的直接能源物质，活微生物细胞内含有ATP，数量与活菌量正相关；细胞死亡后ATP很快降解，所以检出的ATP越多，活微生物污染越严重。(3)ATP是细胞内能量转换的纽带：放能反应释放的能量先合成ATP，吸能反应再通过ATP水解获得能量。", "hints": ["活细胞都要靠ATP供能，死细胞的ATP会很快降解", "ATP是放能反应和吸能反应之间的纽带"], "q": "荧光素在荧光素酶催化下，需要ATP供能才能被激活，与氧反应发出荧光。食品厂用这种原理做卫生检测：涂抹取样后加荧光素和荧光素酶，发光越强，说明样品中ATP越多、微生物污染越严重。请回答：(1)该检测中直接供能的物质是什么？(2)为什么样品中ATP多就提示微生物多？(3)这说明ATP在能量转换中起什么作用？", "steps": ["第一步：发光反应由ATP水解直接供能。", "第二步：活的微生物细胞内含有ATP，细胞死亡后ATP迅速分解，所以ATP量能反映活菌多少。", "第三步：ATP把放能反应释放的能量转移给吸能反应使用，是能量流通的货币。"], "talk": ["凡是问直接能源、直接供能，答案永远先想ATP，别答葡萄糖和脂肪。"], "title": "案例：萤火虫发光与ATP检测试剂盒"}, "intro": "细胞干活要耗能，能量不能像电线一样直接接过来，得有一种东西负责送货，这就是**ATP**，被称为细胞的能量**货币**。它不是仓库，而是零钱包：赚进来马上花出去，周转极快。==ATP水解释放的能量可以直接用于各项生命活动，ATP合成时又把呼吸作用和光合作用释放的能量存进来。==\n记住定位：==ATP在细胞内含量很少但转化迅速，总量保持相对稳定，它是直接能源物质，不是储能物质。==", "learn": [{"h": "ATP长什么样", "p": "ATP中文名是**腺苷三磷酸**。结构拆开看：**腺苷**由**腺嘌呤**加**核糖**组成，后面连着**三个磷酸基团**。结构简式写作 **A-P～P～P**，其中～表示一种**特殊的化学键**，教材旧称高能磷酸键，这个键不稳定、水解时释放大量能量。离腺苷最远的那个磷酸基团最容易脱落，脱落后ATP变成**ADP**（腺苷二磷酸）。考试画结构或排序时，先找核糖，再数磷酸基团，别把腺嘌呤画成别的碱基。"}, {"h": "ATP和ADP如何互相转化", "p": "**水解供能**：ATP水解成ADP和Pi，释放能量，用于**吸能反应**，比如**主动运输**、**肌肉收缩**、**神经传导**、大脑思考、物质合成等。**合成储能**：ADP加Pi加能量合成ATP，能量来自**细胞呼吸**和**光合作用**这类**放能反应**。两个方向用的酶不同、场所和能量来源也不同，所以这不是一个可逆反应，只是物质可以循环。==能量不能循环利用，ATP和ADP这种物质可以反复循环使用。== 就像钱可以反复流通，但花掉的能量不会自己回来。"}, {"h": "ATP和RNA的关系——小而高频的考点", "p": "把ATP去掉两个磷酸基团，剩下的就是**腺嘌呤核糖核苷酸**，正好是构成**RNA**的一种基本单位。==ATP脱去两个磷酸基团后是RNA的基本组成单位之一。== 这句话反过来也常考：RNA的基本单位中含有腺嘌呤的那一种，其结构和ATP去掉两个磷酸后的结构相同。注意不要说成DNA的单位，ATP里的五碳糖是核糖，不是脱氧核糖。"}], "pitfalls": ["把ATP当成储能物质——脂肪、糖原才是储能物质，ATP是直接能源物质、流通货币，含量少、周转快。", "认为ATP和ADP的转化是可逆反应——两个方向的酶、能量来源和场所都不同，不是可逆反应，只是物质循环。", "把ATP中的A说成腺嘌呤——A代表腺苷，是腺嘌呤加核糖。"]}, "video": {"bvid": "BV1p54y177e6", "p": 37, "t": "细胞的能量“货币”ATP", "dur": "48:56", "from": "锦城大同教育·杨波生物", "vtop": ["ATP 是细胞的直接能源物质，不是主要的能源物质——主要的能源物质是糖类，ATP 只是直接供能。", "结构简式 A—P～P～P 用口诀“123”记：1 个腺苷、2 个高能磷酸键、3 个磷酸基团。", "ATP 与 ADP 的转化不是可逆反应：物质上可逆、能量上不可逆，合成用 ATP 合酶、水解用 ATP 水解酶。"], "vsum": "本课讲第五章第二节，讲细胞的能量“货币”**ATP**。开场先看教材例子：杜牧《秋夕》里“天阶夜色凉如水，卧看牵牛织女星”，夜空中与星光媲美的点点流萤，萤火虫发光不是为了好看，和孔雀开屏一样是**求偶行为**，发光需要细胞提供能量，给细胞提供能量的物质就是 ATP。第一个知识点是 ATP 的功能：**ATP 是驱动细胞生命活动的直接能源物质**，能直接给细胞提供能量。注意 **ATP 不等于能量**：能量是一种形式，ATP 是储存能量的一种物质。ATP 的结构：元素组成是 **C、H、O、N、P** 五种，和核酸的组成元素相同，原因在结构里——ATP 由一分子**腺嘌呤**、一分子**核糖**和三分子的**磷酸基团**构成，和核苷酸（磷酸+五碳糖+含氮碱基）很像；一分子腺嘌呤和一分子核糖共同构成的结构叫**腺苷**，用大写字母 A 表示，所以 ATP 的中文名称是**腺苷三磷酸**。三个磷酸基团从靠近核糖的往外编号为 **α、β、γ**。和核苷酸的区别有三点：核苷酸只有一分子磷酸基团，ATP 有三个；核苷酸的五碳糖可以是核糖或脱氧核糖，ATP 的五碳糖只能是**核糖**；核苷酸的含氮碱基有腺嘌呤、鸟嘌呤、胞嘧啶、胸腺嘧啶、尿嘧啶五种，ATP 的碱基只能是**腺嘌呤**。ATP 脱掉远离腺苷的 γ 磷酸基团就变成 **ADP（腺苷二磷酸）**，再脱一个变成 **AMP（腺苷一磷酸）**，三者可以相互转化。ATP 的结构简式写作 **A—P～P～P**：A 代表腺苷，P 是磷酸基团，中间的短横线“—”是普通化学键，两个波浪线“～”是**高能磷酸键**，断裂时会释放出较多的能量，所以 ATP 分子含有**两个**高能磷酸键。口诀“**123**”帮你记：1 个腺苷、2 个高能磷酸键、3 个磷酸基团。ATP 有两个特点：①**不稳定**，因为相邻的磷酸基团都带负电荷、同种电荷相互排斥，一分子 ATP 含 4 个负电荷，末端的 γ 磷酸基团有较高的转移势能、容易脱掉；②**水解是放能过程**，远离腺苷的那个高能磷酸键断裂，末端磷酸基团脱下、携带着能量与其他分子结合，1 mol ATP 水解释放的能量高达 **30.54 kJ**，所以 ATP 是高能磷酸化合物。易错提醒三则：①ATP 由一个腺嘌呤和三个磷酸基团构成——错，应为一个腺苷（或一个腺嘌呤+一个核糖）加三个磷酸基团；②ATP 含三个特殊化学键——错，是两个；③ATP 是细胞内主要的能源物质——错，ATP 是**直接能源物质**，主要的能源物质是**糖类**。顺带复习细胞内的能源物质：能源物质包括糖类、脂肪、蛋白质和 ATP；**主要能源物质是糖类**（细胞呼吸的底物主要是糖类）；储能物质有脂肪、淀粉、糖原，淀粉只存在于植物细胞、糖原只存在于动物细胞，**主要储能物质是脂肪**（1 g 脂肪氧化分解放 39000 J，1 g 糖原只有 17000 J）；**直接能源物质是 ATP**；能量的**最终来源是太阳能**（人吃食物，食物最终来自植物的光合作用）。第二个重点是 **ATP 与 ADP 的相互转化**：ADP 加上游离的磷酸 Pi 再加上能量，在 **ATP 合酶**催化下合成 ATP；ATP 合酶广泛分布于**线粒体内膜、叶绿体类囊体膜和细菌质膜**上，质子（H⁺）顺电化学梯度流动时催化 ADP 和磷酸合成 ATP。合成 ATP 所需要的能量，对动物、人、真菌和大多数细菌来说来自**呼吸作用**，对绿色植物来说来自**呼吸作用和光合作用**。ATP 水解脱掉 γ 磷酸基团变成 ADP 并释放能量，用的酶是 **ATP 水解酶**，和合成用的 ATP 合酶不是同一种酶。**ATP 与 ADP 的相互转化不是可逆反应**：物质上可逆（游离的磷酸可以反复利用），能量上不可逆（合成的能量来自呼吸作用和光合作用，水解释放的能量用于细胞的各项吸能反应），酶也不一样、反应场所也有区别。相互转化的特点有两点：①**时刻不停地发生、处于动态平衡**，细胞内 ATP 的含量很少、不能大量储存，挣多少用多少，靠快速转化供能；②能量供应机制在所有生物的细胞内都一样，体现了**生物界的统一性**。ATP 的利用：细胞中**绝大多数**需要能量的生命活动都是由 ATP 直接提供能量的（并非全部，还有 GTP、CTP、UTP 等，高中不用掌握）。实例有主动运输、生物发电（电鳐）、生物发光（萤火虫）、肌肉收缩、细胞内各种吸能反应（合成反应）、大脑思考。ATP 中的能量可以直接转化成六种形式：**渗透能**（主动运输）、**机械能**（肌肉收缩、精子尾部摆动）、**电能**（生物发电、大脑思考）、**化学能**（吸能反应）、**光能**（萤火虫发光）、**热能**（维持体温）。ATP 为主动运输供能的原理以**钙泵**为例：参与 Ca²⁺ 主动运输的载体蛋白是一种能催化 ATP 水解的酶，叫 **Ca²⁺-ATP 酶**，又叫**钙泵**。过程是：膜内侧的 Ca²⁺ 与载体蛋白相应位点结合→酶活性被激活→ATP 末端磷酸基团脱离、与载体蛋白结合（**载体蛋白磷酸化**，能量转移）→载体蛋白空间结构改变，结合位点转向膜外侧→Ca²⁺ 释放到膜外；每消耗 1 分子 ATP 可将 2 个 Ca²⁺ 从膜内转移到膜外。类似的还有**钠钾泵**（Na⁺-K⁺-ATP 酶），每消耗 1 分子 ATP，泵出 3 个 Na⁺、泵入 2 个 K⁺。最后理解“**ATP 是细胞内流通的能量‘货币’**”：**吸能反应**（细胞需要吸收能量）一般与 ATP 水解相联系，由 ATP 水解提供能量；**放能反应**与 ATP 合成相联系，放出的能量储存在 ATP 里；能量通过 ATP 分子在吸能反应和放能反应之间流通。注意吸能反应和放能反应是针对细胞说的，不是针对 ATP 说的。易错提醒三则：①细胞内储存有大量的 ATP——错，ATP 含量很少，靠快速转化供能；②吸能反应伴随着 ATP 的合成、放能反应伴随着 ATP 的水解——说反了，吸能反应伴随 ATP 水解，放能反应伴随 ATP 合成；③人在饥饿时细胞中 ATP 与 ADP 的含量难以达到动态平衡——错，健康人都能保持动态平衡。萤火虫发光的原理：尾部发光细胞里有**荧光素和荧光素酶**，荧光素接受 ATP 提供的能量后被激活，在荧光素酶催化下与氧发生化学反应，形成氧化荧光素并发出荧光。教材练习要点：①能准确表示 ATP 结构的简式是 B 选项——腺苷与第一个磷酸基团之间是普通化学键，后面两个是特殊化学键；②能直接给细胞生命活动提供能量的是 ATP；③关于 ATP 的叙述错误的是 B——ATP 合成所需能量由磷酸提供是错的，应来自呼吸作用和光合作用；④离子泵：选 C——动物一氧化碳中毒会降低离子泵跨膜运输离子的速率（CO 中毒→血红蛋白结合氧的能力下降→供氧不足→有氧呼吸减弱→ATP 减少）；⑤关于水稻细胞内 ATP 的叙述错误的是 B——只能由细胞呼吸产生是错的，水稻细胞还能进行光合作用。", "vtech": [["直接、主要、储能、最终：四种地位别搞混", "看到能源物质题 → 先问地位：直接能源物质是 ATP，主要能源物质是糖类，主要储能物质是脂肪，最终能量来源是太阳能；“ATP 是主要的能源物质”是典型错句。"], ["ATP 与 ADP 转化不是可逆反应", "物质上可逆（Pi 可反复利用），能量上不可逆：合成的能量来自呼吸作用（植物还有光合作用），水解释放的能量用于吸能反应；两种酶也不一样（ATP 合酶 vs ATP 水解酶）。"], ["钙泵和钠钾泵的数字", "钙泵：每消耗 1 分子 ATP 转移 2 个 Ca²⁺（膜内→膜外）；钠钾泵：每消耗 1 分子 ATP 泵出 3 个 Na⁺、泵入 2 个 K⁺；离子泵跨膜运输是主动运输，离不开 ATP 水解。"], ["结构简式与口诀“123”", "A—P～P～P：A 是腺苷（腺嘌呤+核糖），“—”是普通化学键，“～”是高能磷酸键；口诀 123：1 个腺苷、2 个高能磷酸键、3 个磷酸基团；ATP 含 4 个负电荷、1 mol 水解释放 30.54 kJ。"]], "vgaokao": []}}, "bio_b019": {"name": "有氧呼吸与无氧呼吸", "sec": 19, "secTitle": "细胞呼吸的原理和应用", "page": 90, "desc": "有氧呼吸三阶段的场所与产物；两种无氧呼吸类型；总反应式与能量账。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b018"], "next": ["bio_b020", "bio_b021"], "content": {"advance": {"a": "总反应式：C6H12O6+6H2O+6O2→（酶）6CO2+12H2O+能量。氧气在第三阶段与[H]结合，氧元素最终进入生成的水中。水在第三阶段生成（第二阶段还消耗水）。第三阶段将前两阶段产生的[H]全部氧化，[H]与氧结合释放的能量最多，所以合成的ATP最多。", "kind": "self", "q": "写出有氧呼吸总反应式，并说明式中氧气的最终去向、水的产生阶段，以及为什么第三阶段产生的ATP最多。"}, "apply": [{"ans": 1, "opts": ["CO2释放量立刻变为零", "培养液中出现酒精，葡萄糖消耗速度加快以维持ATP供应", "线粒体数量迅速增加", "丙酮酸不再产生"], "q": "将酵母菌培养液由通气改为密封，一段时间后检测到的变化是（ ）", "why": "密封后酵母菌转入无氧呼吸产酒精，由于无氧呼吸每分子葡萄糖产ATP少，要消耗更多葡萄糖来维持供能，选B。无氧呼吸仍产生CO2，A错。"}, {"ans": 1, "opts": ["低温低氧使呼吸作用完全停止，有机物不再消耗", "低温降低酶活性、低氧抑制有氧呼吸，使呼吸强度减弱、有机物消耗减少", "低氧促进无氧呼吸产生大量ATP供水果使用", "低温使水果细胞光合作用增强"], "q": "水果在低温、低氧条件下储存保鲜时间长，其原理是（ ）", "why": "保鲜是减弱呼吸、减少消耗，不是停止呼吸；呼吸完全停止细胞会死亡腐烂。选B。"}], "basics": [{"ans": 2, "opts": ["第一阶段，细胞质基质", "第二阶段，线粒体基质", "第三阶段，线粒体内膜", "三个阶段一样多"], "q": "有氧呼吸产生ATP最多、且消耗氧气的阶段是（ ）", "why": "第三阶段[H]与O2结合生成水，释放大量能量、合成大量ATP，场所是线粒体内膜，选C。"}, {"ans": 2, "opts": ["酵母菌", "苹果果肉细胞", "人体骨骼肌细胞", "水稻根细胞长期淹水时"], "q": "下列生物或部位进行无氧呼吸产生乳酸的是（ ）", "why": "人体骨骼肌无氧呼吸产乳酸，选C。酵母菌和苹果果肉产酒精和CO2。"}], "case": {"a": "(1)无氧呼吸（产乳酸型），场所是细胞质基质。(2)运动时能量需求大，肌肉细胞在进行无氧呼吸的同时，有氧呼吸也加强，葡萄糖彻底氧化分解产生大量CO2，经血液运输排出，所以两种呼吸同时存在。(3)无氧呼吸只在第一阶段释放少量能量，第二阶段不释放能量，葡萄糖中大部分能量储存在乳酸中未释放，生成ATP少，无法长时间满足剧烈运动的能量需求。", "hints": ["肌肉细胞同时存在有氧和无氧两种呼吸", "比较每分子葡萄糖在两种方式下转移到ATP的能量"], "q": "长跑后半程，运动员腿部肌肉酸胀、力量下降，休息一段时间后酸胀感消失。检测发现：剧烈运动时肌肉细胞中乳酸含量升高，血液中CO2排出量也明显增加。请回答：(1)肌肉细胞产生乳酸的呼吸方式和场所是什么？(2)为什么同时CO2排出量也增加？(3)从能量角度解释为什么单靠这种方式不能持久供能。", "steps": ["第一步：供氧不足时肌肉细胞无氧呼吸，丙酮酸在细胞质基质转成乳酸。", "第二步：大部分细胞仍在进行有氧呼吸，葡萄糖彻底氧化产生CO2，所以CO2排出增加，两种方式并存。", "第三步：无氧呼吸第二阶段不释放能量，大部分能量留在乳酸中，产ATP少，供能效率低，不能持久。"], "talk": ["看到乳酸想无氧、看到CO2不急着下结论：产乳酸不放CO2，放CO2的可能是有氧或产酒精。"], "title": "案例：马拉松后半程的腿为什么发酸"}, "intro": "细胞呼吸就是把葡萄糖这类有机物氧化分解、把能量转到ATP里的过程，是本章计算和方程式的重灾区。有氧时走三步，无氧时走两步，第一步完全相同。==有氧呼吸第一阶段在细胞质基质，第二阶段在线粒体基质，第三阶段在线粒体内膜。==\n场所千万别背反，考试最爱在这里挖坑。再记住总数：==1 mol葡萄糖彻底氧化约释放2870 kJ能量，其中约977 kJ转移到ATP中，效率约34%，其余以热能形式散失。==", "learn": [{"h": "有氧呼吸三阶段逐个拆", "p": "第一阶段（**细胞质基质**）：1分子**葡萄糖**分解成2分子**丙酮酸**，产生少量**[H]**和少量ATP，不需要氧气。第二阶段（**线粒体基质**）：丙酮酸和**水**彻底分解成**CO2**，产生大量[H]和少量ATP，也不需要氧气直接参加。第三阶段（**线粒体内膜**）：前两步产生的[H]和**氧气**结合生成**水**，释放大量能量、合成**大量ATP**，这一步必须有氧。==氧气只在第三阶段被消耗，水在第二阶段被消耗、在第三阶段被生成。== 总反应式：**C6H12O6+6H2O+6O2→（酶）6CO2+12H2O+能量**。"}, {"h": "无氧呼吸：第一步相同，第二步分家", "p": "场所全程在**细胞质基质**。第一阶段和有氧呼吸完全一样：葡萄糖到丙酮酸、少量ATP。第二阶段不释放能量，丙酮酸的去向分两型：**产酒精型**：丙酮酸转成**酒精+CO2**，见于**酵母菌**、苹果果实等；**产乳酸型**：丙酮酸转成**乳酸**，见于人体肌肉细胞、**乳酸菌**、**马铃薯块茎**、**玉米胚**等。==因为第二阶段不释放能量、葡萄糖中的能量大部分还留在酒精或乳酸里，所以无氧呼吸释放的总能量远少于有氧呼吸。== 还有一个高频判断：产乳酸型不产生CO2，产酒精型才产生CO2。"}, {"h": "细胞呼吸原理在生活中的应用", "p": "给农作物**松土**是为了透气、促进根的有氧呼吸，防止无氧呼吸产酒精毒害根细胞。用**低温、低氧**条件储存水果蔬菜，是降低呼吸强度、减少有机物消耗，不是把呼吸停掉。皮肤伤口要透气、抑制厌氧菌的无氧呼吸。酿酒用酵母菌：==先通气让酵母菌有氧呼吸大量繁殖，后密封让它无氧呼吸产酒精。== 跑步后肌肉酸痛，是肌肉细胞无氧呼吸产生了乳酸。每个应用题都要能倒推回原理：控制氧气和温度，就是在控制呼吸类型和强度。"}], "pitfalls": ["把三阶段场所记反——第一阶段在细胞质基质，不是线粒体；只有第二、三阶段在线粒体。", "认为无氧呼吸第二阶段也释放大量能量——第二阶段不释放能量，这是无氧呼吸总能量少的原因。", "认为所有无氧呼吸都产生CO2——产乳酸型不产生CO2，只有产酒精型产生CO2。", "总反应式漏掉水：反应物有6H2O参加，生成物是12H2O，不能互相抵消后写错系数。"]}, "video": {"bvid": "BV1p54y177e6", "p": 39, "t": "细胞呼吸的原理和应用", "dur": "126:45", "from": "锦城大同教育·杨波生物", "vtop": ["有氧呼吸分三个阶段记场所和产物：第一阶段在细胞质基质把葡萄糖分解成 2 分子丙酮酸和 4 分子 [H]，第二阶段在线粒体基质产生二氧化碳，第三阶段在线粒体内膜生成水并释放大量能量，1 mol 葡萄糖共生成 32 mol ATP、转化效率约 34%。", "无氧呼吸全程只在细胞质基质进行，第一阶段与有氧呼吸第一阶段完全相同，第二阶段不产能，产物按酶的种类分产乳酸式和产酒精加二氧化碳式，人体细胞只能产乳酸。", "氧气浓度为 5% 时二氧化碳释放总量最少，所以储存粮食、水果和蔬菜要用低氧而不是无氧环境，粮食还要干燥、水果蔬菜还要一定湿度。"], "vsum": "本课讲第五章第三节**细胞呼吸的原理和应用**，分两讲：第一讲是探究酵母菌细胞呼吸的方式加有氧呼吸，第二讲是无氧呼吸加影响因素与应用。开场先看教材例子：酵母菌细胞富含蛋白质，可以用作饲料添加剂，培养时要通气或者震荡，让它大量繁殖；利用酵母菌生产葡萄酒时却需要密封发酵。三个问题：为什么都是培养酵母菌，有的需要通气、有的却需要密封？为什么通气有利于酵母菌大量繁殖，而密封环境不利于大量繁殖？密封发酵时酵母菌把有机物转化为酒精，对它自身又有什么意义？先分清两个概念：**呼吸**是人体的肺与外界环境进行气体交换，也就是平时呼气和吸气的过程，又叫呼吸运动；**呼吸作用**是细胞内有机物氧化分解并且释放能量的过程，也叫**细胞呼吸**。酵母菌是真菌、真核生物，代谢类型是**异养兼性厌氧型**：异养是只能利用现成的有机物，兼性厌氧是**有氧和无氧条件下都能正常生活**，所以它既能进行**有氧呼吸**，也能进行**无氧呼吸**。检测产物有两套办法：**二氧化碳**用**澄清石灰水**检测，变浑浊说明有二氧化碳，浑浊的程度能判断二氧化碳含量的多少；还可以用**溴麝香草酚蓝溶液**，它本身是蓝色，遇到二氧化碳由**蓝变绿再变黄**，变色时间越短说明二氧化碳越多。**酒精**用**酸性重铬酸钾溶液**检测，本身是橙色，遇到酒精由**橙变灰绿**，一定要在酸性条件下用，酸性条件靠加**浓硫酸**提供，因为重铬酸钾在碱性或中性条件下作用很微弱，而且硫酸根能参与生成灰绿色的硫酸铬。实验装置是两组实验组相互对照：A 瓶和 B 瓶都装等量酵母菌培养液，加等量质量分数 5% 的葡萄糖溶液，变量就是**有无氧气**，其他无关变量保持相同且适宜；葡萄糖溶液要先煮沸消毒杀死杂菌，冷却后再加入酵母菌，不然高温会把酵母菌烫死。A 瓶前面多一个装 10% 氢氧化钠溶液的锥形瓶，用来除去通入空气里的二氧化碳，再接橡皮球或气泵通气，提供有氧环境；不能用澄清石灰水代替氢氧化钠来除二氧化碳，因为澄清石灰水吸收二氧化碳有一定限度、吸不完。B 瓶直接密封，提供无氧环境。检测二氧化碳时把导管通入澄清石灰水或溴麝香草酚蓝溶液；检测酒精时从 A、B 瓶各取等量培养液，加酸性重铬酸钾溶液观察变色，而且要**适当延长培养时间**，等葡萄糖耗尽再测，因为葡萄糖是还原糖，也会被重铬酸钾氧化、颜色反应和酒精相同，会干扰结果。实验结论：酵母菌在有氧和无氧条件下都能进行细胞呼吸，**有氧条件下产生大量的二氧化碳和水，无氧条件下产生酒精和少量的二氧化碳**；有氧条件利于大量繁殖，无氧条件进行酒精发酵，所以酿酒要密封。这个实验属于**对比实验**：只设置两个或两个以上的实验组，通过对结果的比较分析来探究某种因素的影响，也叫相互对照实验，是对照实验的一种。易错提醒：葡萄糖溶液煮沸后要冷却再加酵母菌；气体使澄清石灰水变浑浊只能说明有二氧化碳，不能直接断定就是有氧呼吸，因为无氧呼吸也产生二氧化碳；重铬酸钾要在酸性条件下用；两组都是实验组，没有对照组。接着讲**有氧呼吸**：对大多数生物来说，有氧呼吸是细胞呼吸的主要形式。**有氧呼吸的主要场所是线粒体**，真核细胞里有氧呼吸的场所是线粒体和细胞质基质；线粒体内膜折叠形成**嵴**，增大膜面积，给有氧呼吸有关的酶提供更多附着位点。原核细胞没有线粒体，但部分原核细胞（如硝化细菌、蓝细菌、根瘤菌）含有有氧呼吸的酶，也能进行有氧呼吸，场所在细胞质基质和细胞膜上。有氧呼吸的总反应式以葡萄糖为例：葡萄糖加氧气加水，在酶的作用下生成二氧化碳和水并释放能量，生成大量 ATP。注意底物**主要是葡萄糖**，但不只有葡萄糖，其他有机物也可以参加有氧呼吸；反应物里的水不能省掉，它参加第二阶段，生成物里的水是第三阶段产生的；反应式里写的是能量，不能写成 ATP，因为大部分能量以热能形式散失了；箭头上面的酶不能漏，各阶段的酶种类也不一样。有氧呼吸分**三个阶段**：**第一阶段在细胞质基质**，1 分子葡萄糖在酶的作用下分解成 2 分子**丙酮酸**和 4 分子**[H]**，释放少量能量，一部分以热能散失、一部分生成少量 ATP，也叫**糖酵解**；**第二阶段在线粒体基质**，2 分子丙酮酸和 6 分子水生成 20 分子 [H] 和 6 分子二氧化碳，释放少量能量，也叫**三羧酸循环**，二氧化碳就是在这个阶段产生的；**第三阶段在线粒体内膜**，前面两阶段产生的 24 分子 [H] 和 6 分子氧气生成 12 分子水，释放大量能量，也叫**氧化磷酸化**。葡萄糖不能进入线粒体分解，因为线粒体里没有分解葡萄糖的酶，分解葡萄糖的酶只分布在细胞质基质里；有机物彻底分解发生在第二、三阶段，所以有氧呼吸的主要场所是线粒体。能量上，1 mol 葡萄糖有氧呼吸共释放 **2870 kJ**，其中 **977.28 kJ** 储存在 ATP 里，剩下 1892.72 kJ 以热能散失；每合成 1 mol ATP 需要 30.54 kJ，所以 1 mol 葡萄糖共生成 **32 mol ATP**，能量转化效率约 **34%**。氧的去向：氧气里的氧全部进入生成的水，葡萄糖和反应物水里的氧全部进入二氧化碳。易错提醒：葡萄糖不是有氧呼吸唯一利用的物质；不是所有真核细胞都能进行有氧呼吸，哺乳动物成熟的红细胞和蛔虫细胞没有线粒体，不能进行有氧呼吸；有氧呼吸的实质不是葡萄糖在线粒体中彻底氧化分解，而是在氧的参与下通过多种酶的作用，把葡萄糖等有机物彻底氧化分解，产生二氧化碳和水，释放能量、生成大量 ATP。教材练习题：把酵母菌培养液离心，得到只含细胞质基质的上清液和只含细胞器的沉淀物，分别加等量等浓度葡萄糖溶液，在有氧条件下只有未离心处理的完整酵母菌（丙试管）能产生二氧化碳和水，因为甲只有细胞质基质、只能完成第一阶段，乙只有细胞器、葡萄糖进不了线粒体。第二讲讲**无氧呼吸**：整个过程都发生在**细胞质基质**，分两个阶段。**第一阶段与有氧呼吸的第一阶段完全相同**，1 分子葡萄糖分解成 2 分子丙酮酸和 4 分子 [H]，释放少量能量。**第二阶段**也在细胞质基质，2 分子丙酮酸和 4 分子 [H] 在酶的作用下生成 2 分子乳酸，或者生成 2 分子酒精和 2 分子二氧化碳，**第二阶段不产能**，写反应式时别把 [H] 漏掉。按酶的种类不同分两种：产物是乳酸的用**乳酸脱氢酶**，叫**产乳酸式**；产物是酒精和二氧化碳的用**乙醇脱氢酶**，老师简称为产酒气式，写的时候别漏了二氧化碳。反应式后面一定要加“**少量能量**”，以区别于有氧呼吸释放的大量能量；写乳酸和酒精的分子式后面要加括号注明是哪种物质，因为 C₃H₆O₃ 和 C₂H₆O 都是同分异构体、可能代表别的物质。产物归属要记牢：动物细胞和人体细胞无氧呼吸的产物只有乳酸；大多数植物细胞产酒精和二氧化碳，玉米胚乳、甜菜块根、马铃薯块茎这三个特例产乳酸；微生物里乳酸菌只能产乳酸，酵母菌产酒精和二氧化碳。能量上，1 mol 葡萄糖无氧呼吸分解成乳酸只释放 **196.65 kJ**，其中 61.08 kJ 储存在 ATP 里，正好生成 **2 mol ATP**，剩下 135.57 kJ 以热能散失；大部分能量没有释放出来，还储存在乳酸或酒精这些没有彻底分解的有机产物里。**无氧呼吸**的概念是：在没有氧气参与的情况下，葡萄糖等有机物经过不完全分解、释放少量能量的过程；酵母菌、乳酸菌等微生物的无氧呼吸也叫**发酵**，但工业上的发酵不一定是无氧呼吸，比如醋酸发酵用的醋酸菌是需氧菌、只能进行有氧呼吸。**细胞呼吸**除了提供能量，还是生物体**代谢的枢纽**，蛋白质、糖类和脂质的代谢都能通过细胞呼吸联系起来。易错提醒：无氧呼吸没有氧气参与，但 [H] 不会积累，第二阶段还要用它当反应物；马铃薯块茎无氧呼吸的产物是乳酸，不是酒精和二氧化碳；人体产生二氧化碳的细胞呼吸方式一定是有氧呼吸，因为人体细胞不能进行产酒精式的无氧呼吸；无氧呼吸只有第一阶段释放少量能量，第二阶段不产能；必须是释放出来的那部分能量才说大部分以热能散失、少部分储存在 ATP 里，无氧条件下葡萄糖里的大部分能量根本没释放出来。应用要会联系生活：包扎伤口用**透气的消毒纱布或创可贴**，是为了避免厌氧病原菌繁殖，不是为了保证伤口处细胞的有氧呼吸，因为伤口处细胞不能直接利用外界氧气，要靠血红蛋白输送；酿酒前期先适宜通气让酵母菌有氧呼吸大量繁殖，后期再密封发酵产酒精；花盆土壤板结要松土透气，既利于根细胞有氧呼吸，也利于土壤里需氧微生物分解有机物、供植物吸收无机盐；储藏水果粮食要降低温度、降低氧气含量来减弱呼吸作用、减少有机物消耗，注意是**低氧而非无氧**；破伤风芽孢杆菌是厌氧菌，伤口深或被锈钉扎伤后深处无氧、容易大量繁殖，要打破伤风针；提倡慢跑这种有氧运动，是为了避免肌细胞供氧不足进行无氧呼吸、乳酸大量积累使肌肉酸胀乏力。影响细胞呼吸的因素分内部和外部：内部因素有遗传特性、生长发育时期、器官类型，一般幼苗期呼吸速率高、成熟期低；外部因素是重点。**温度**通过影响酶的活性来影响呼吸速率，最适温度一般在 **25 到 35 摄氏度**，低温储存食品、大棚夜间和阴天适当降温都是利用低温降低酶活性，温水和面发得快是因为温度高、酶活性高、呼吸快、产生大量二氧化碳。**氧气**是有氧呼吸的反应物，氧气含量影响有氧呼吸速率，同时氧气对无氧呼吸有**抑制作用**；看坐标图：横坐标是氧气含量，纵坐标是二氧化碳释放量，无氧呼吸释放的二氧化碳随氧气增多而下降，有氧呼吸释放的二氧化碳随氧气增多而上升，两者相加是总量曲线；氧气浓度为 0 时只进行无氧呼吸，0 到 10% 两种呼吸同时进行，**10% 时无氧呼吸消失**，10% 以上只进行有氧呼吸；二氧化碳释放总量在氧气浓度 **5%** 时最少，说明这时有机物消耗最少，所以储存粮食水果蔬菜要用低氧环境，粮食还要干燥，水果蔬菜还要一定湿度。**水分**既是有氧呼吸的反应物，又是生化反应的介质，在一定范围内呼吸速率随含水量增加而加快，粮食入仓前要晾晒减少自由水、降低呼吸速率，干种子萌发前浸泡是提高含水量、加快呼吸。**二氧化碳**是细胞呼吸的最终产物，积累过多会抑制细胞呼吸，所以适当增加二氧化碳浓度也有利于水果蔬菜保鲜。最后比较有氧呼吸和无氧呼吸：不同点是反应条件（要不要氧气）、反应场所、分解产物（有氧是二氧化碳和水、无氧是乳酸或酒精加二氧化碳）、能量转化和特点（有氧彻底氧化分解、能量完全释放，无氧不彻底分解、能量没有完全释放）；相同点是实质都是分解有机物、释放能量、生成 ATP，意义都是为生物提供能量、作为代谢枢纽；联系是第一阶段从葡萄糖到丙酮酸完全相同，之后在不同条件、场所和酶的作用下沿不同途径形成不同产物。判断呼吸方式有**三看法**：一看反应物和产物，消耗氧气或产物中有水的一定存在有氧呼吸，有酒精或乳酸生成的一定存在无氧呼吸；二看物质的量关系，不消耗氧气却释放二氧化碳的只能是产酒精式无氧呼吸，不消耗氧气也不释放二氧化碳的可能是产乳酸式无氧呼吸或细胞已死亡，二氧化碳释放量等于氧气吸收量时只进行有氧呼吸，或同时进行有氧呼吸和产乳酸式无氧呼吸；三看场所，只在细胞质基质中进行的是无氧呼吸，有线粒体参与的一定存在有氧呼吸，但这只针对真核细胞，原核细胞不论哪种呼吸场所都在细胞质基质里。数量关系要会算：消耗等量葡萄糖时，有氧呼吸与产酒精式无氧呼吸的二氧化碳产生量之比是 **3:1**；产生等量二氧化碳时，两者消耗葡萄糖量之比是 **1:3**；两者同时进行时，氧气吸收量与二氧化碳释放总量之比等于 **3:4** 说明速率相等，小于 3:4 说明有氧呼吸速率小于无氧呼吸速率，大于 3:4 则相反。课后作业是完成课后作业 21。", "vtech": [["三阶段场所与产物先对表", "第一阶段在细胞质基质：1 分子葡萄糖→2 丙酮酸＋4[H]＋少量能量；第二阶段在线粒体基质：2 丙酮酸＋6 水→20[H]＋6 二氧化碳＋少量能量；第三阶段在线粒体内膜：24[H]＋6 氧气→12 水＋大量能量；三阶段别名糖酵解、三羧酸循环、氧化磷酸化。"], ["无氧呼吸两类产物看酶", "产乳酸式用乳酸脱氢酶，产物是 2 乳酸；产酒精式用乙醇脱氢酶，产物是 2 酒精＋2 二氧化碳，写的时候别漏了二氧化碳；反应式后面一定要写“少量能量”，第二阶段不产能；人体细胞只能产乳酸，酵母菌产酒精加二氧化碳，玉米胚乳、甜菜块根、马铃薯块茎这三个植物特例产乳酸。"], ["检测题先看试剂与颜色", "二氧化碳：澄清石灰水变浑浊，浑浊程度看多少；溴麝香草酚蓝由蓝变绿再变黄，变色时间越短二氧化碳越多；酒精：酸性重铬酸钾由橙变灰绿，酸性条件靠浓硫酸提供；测酒精要适当延长培养时间，等葡萄糖耗尽再测，否则葡萄糖的还原性会干扰。"], ["氧气曲线抓 5% 与 10% 两个点", "氧气浓度为 0 时只进行无氧呼吸，0 到 10% 两种呼吸同时进行，10% 时无氧呼吸消失；二氧化碳释放总量在氧气浓度 5% 时最少，所以低氧储存最省有机物；温度通过影响酶活性起作用，最适温度一般在 25 到 35 摄氏度。"]], "vgaokao": []}}, "bio_b020": {"name": "探究酵母菌细胞呼吸的方式", "sec": 20, "secTitle": "细胞呼吸的原理和应用", "page": 91, "desc": "有氧、无氧两套装置；CO₂ 与酒精的检测方法；对比实验的设计与结论。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b019"], "next": [], "content": {"advance": {"a": "可用溴麝香草酚蓝溶液，颜色由蓝变绿再变黄。有氧条件下酵母菌进行有氧呼吸，葡萄糖彻底氧化分解，单位时间产生CO2更多，所以溶液变黄更快；无氧呼吸只在第一阶段之后由丙酮酸转化产生少量CO2，变色较慢。", "kind": "self", "q": "本实验除了用澄清石灰水，还可以用什么试剂检测CO2？写出颜色变化顺序，并说明为什么有氧组该试剂变色更快。"}, "apply": [{"ans": 1, "opts": ["NaOH浓度太高", "无氧装置未静置耗氧就连接石灰水，瓶内残留氧气使酵母进行了较长时间的有氧呼吸", "石灰水量太少", "培养温度偏低"], "q": "某同学发现无氧组石灰水浑浊程度与有氧组差不多，且培养液中只检出微量酒精。最可能的操作失误是（ ）", "why": "无氧瓶内若残留氧气，酵母先进行有氧呼吸产生大量CO2，石灰水浑浊程度就会接近有氧组，酒精也少，选B。"}, {"ans": 1, "opts": ["该实验需要再设置一组不加酵母的空白对照", "有氧组和无氧组互为对照，属于对比实验", "两组石灰水变浑浊的速度相同说明呼吸强度相同", "用斐林试剂可以直接检测酒精"], "q": "关于该实验的叙述，正确的是（ ）", "why": "两套装置互为对照、是对比实验，不需要空白对照，选B。有氧组浑浊更快、程度更深，C错；斐林试剂测还原糖不测酒精，D错。"}], "basics": [{"ans": 1, "opts": ["为酵母菌提供营养", "吸收空气中的CO2，排除其对检测的干扰", "杀死空气中的杂菌", "促进酵母菌有氧呼吸"], "q": "探究酵母菌呼吸方式的实验中，有氧装置中10% NaOH溶液的作用是（ ）", "why": "NaOH吸收通入空气中的CO2，保证石灰水变浑浊是由酵母呼吸产生的CO2引起的，选B。"}, {"ans": 1, "opts": ["斐林试剂，无色变砖红色", "酸性重铬酸钾，橙色变灰绿色", "溴麝香草酚蓝，蓝变绿再变黄", "澄清石灰水，无色变浑浊"], "q": "检测酵母培养液中是否产生酒精，应使用的试剂和颜色变化是（ ）", "why": "酒精使酸性重铬酸钾由橙色变灰绿色，选B。溴麝香草酚蓝和石灰水检测的是CO2。"}], "case": {"a": "(1)无氧装置刚装好时瓶内含有空气、培养液中也溶有氧气，酵母菌先进行有氧呼吸，产生大量CO2且不产生酒精，所以石灰水浑浊、重铬酸钾不变色不能证明发生了无氧呼吸。(2)将无氧装置装好后先封口静置一段时间，待酵母菌将瓶内氧气消耗完，再连接澄清石灰水进行检测。(3)无氧组石灰水浑浊程度小于有氧组，且培养液使酸性重铬酸钾变灰绿色（有酒精）；有氧组浑浊程度大，培养液不变灰绿色（无酒精）。", "hints": ["装瓶时瓶内和培养液里都溶有氧气", "无氧呼吸产CO2少、有酒精；有氧呼吸产CO2多、无酒精"], "q": "某小组按课本搭好无氧装置后立即连接澄清石灰水，30分钟后石灰水明显浑浊，取培养液加酸性重铬酸钾不变色。老师说这组数据不能证明酵母菌进行了无氧呼吸。请回答：(1)老师质疑的理由是什么？(2)应如何改进操作？(3)改进后预期无氧组与有氧组在石灰水浑浊和酒精检测上有何差异？", "steps": ["第一步：立即连接时瓶内残留氧气未耗完，酵母先做有氧呼吸，CO2多且不产酒精，与现象吻合。", "第二步：改进是装瓶后先封口静置一段时间，耗尽氧气后再连接石灰水。", "第三步：预期无氧组浑浊程度较浅、检出酒精；有氧组浑浊程度深、无酒精。"], "talk": ["实验题先查氧：有氧组先除空气CO2，无氧组先耗瓶内O2，两头都不能漏。"], "title": "案例：一套被质疑的无氧装置"}, "intro": "这个实验是本章的实验题模板：探究**酵母菌**在有氧和无氧下分别怎么呼吸。装置、试剂、颜色变化、结论，四个点全是给分点。==有氧和无氧两套装置互为对照，属于对比实验，没有单独的空白对照组。==\n检测方法先记牢：==CO2能使澄清石灰水变浑浊，也能使溴麝香草酚蓝溶液由蓝变绿再变黄；酒精在酸性条件下能使橙色的重铬酸钾溶液变成灰绿色。==", "learn": [{"h": "两套装置分别怎么搭", "p": "**有氧装置**：锥形瓶装质量分数**10%的NaOH溶液**，先吸收通入空气中的CO2，保证后面石灰水变浑浊只来自酵母呼吸；接着是酵母培养液瓶，最后接**澄清石灰水**。**无氧装置**：酵母培养液瓶直接接澄清石灰水，中间不通空气。==无氧装置装好后要先封口静置一段时间，让酵母把瓶内原有的氧气耗完，再连接石灰水，否则一开始测到的其实是有氧呼吸的结果。== 这个静置细节是实验题最爱考的操作理由。"}, {"h": "检测产物看什么现象", "p": "测CO2有两条路：一看石灰水**浑浊程度**，有氧组浑浊更明显，说明产生的CO2多；二用**溴麝香草酚蓝溶液**，颜色按**蓝→绿→黄**变化，变黄越快说明CO2越多。测酒精只能取培养液出来检测：加入**酸性重铬酸钾**，由**橙色变灰绿色**说明有酒精。结果：有氧组无灰绿色（无酒精），无氧组出现灰绿色（有酒精）。注意重铬酸钾必须在酸性条件下用，题干没给酸性条件时要自己点出来。"}, {"h": "变量和对照怎么表述才规范", "p": "自变量是**氧气的有无**（是否通气），因变量是CO2产生量和是否有酒精产生。无关变量如酵母菌量、培养液浓度、温度等必须**等量且适宜**。本实验两组互为对照，是**对比实验**，不要写成还缺一个空白对照。结论规范写法：==酵母菌在有氧条件下产生大量CO2、不产生酒精；在无氧条件下产生少量CO2和酒精，说明酵母菌既能进行有氧呼吸，也能进行无氧呼吸，是兼性厌氧菌。=="}], "pitfalls": ["漏掉NaOH的作用——它吸收空气中的CO2，排除空气中CO2对石灰水的干扰，不是给酵母提供营养。", "无氧装置一装好就立刻接石灰水——应先封口静置耗尽瓶内氧气，否则对照不成立。", "把溴麝香草酚蓝的颜色变化写反——是蓝变绿再变黄，不是黄变蓝。", "说本实验缺少空白对照组——有氧无氧互为对照的对比实验不需要空白对照。"]}, "video": {"bvid": "BV1p54y177e6", "p": 39, "t": "细胞呼吸的原理和应用", "dur": "126:45", "from": "锦城大同教育·杨波生物", "vtop": ["有氧呼吸分三个阶段记场所和产物：第一阶段在细胞质基质把葡萄糖分解成 2 分子丙酮酸和 4 分子 [H]，第二阶段在线粒体基质产生二氧化碳，第三阶段在线粒体内膜生成水并释放大量能量，1 mol 葡萄糖共生成 32 mol ATP、转化效率约 34%。", "无氧呼吸全程只在细胞质基质进行，第一阶段与有氧呼吸第一阶段完全相同，第二阶段不产能，产物按酶的种类分产乳酸式和产酒精加二氧化碳式，人体细胞只能产乳酸。", "氧气浓度为 5% 时二氧化碳释放总量最少，所以储存粮食、水果和蔬菜要用低氧而不是无氧环境，粮食还要干燥、水果蔬菜还要一定湿度。"], "vsum": "本课讲第五章第三节**细胞呼吸的原理和应用**，分两讲：第一讲是探究酵母菌细胞呼吸的方式加有氧呼吸，第二讲是无氧呼吸加影响因素与应用。开场先看教材例子：酵母菌细胞富含蛋白质，可以用作饲料添加剂，培养时要通气或者震荡，让它大量繁殖；利用酵母菌生产葡萄酒时却需要密封发酵。三个问题：为什么都是培养酵母菌，有的需要通气、有的却需要密封？为什么通气有利于酵母菌大量繁殖，而密封环境不利于大量繁殖？密封发酵时酵母菌把有机物转化为酒精，对它自身又有什么意义？先分清两个概念：**呼吸**是人体的肺与外界环境进行气体交换，也就是平时呼气和吸气的过程，又叫呼吸运动；**呼吸作用**是细胞内有机物氧化分解并且释放能量的过程，也叫**细胞呼吸**。酵母菌是真菌、真核生物，代谢类型是**异养兼性厌氧型**：异养是只能利用现成的有机物，兼性厌氧是**有氧和无氧条件下都能正常生活**，所以它既能进行**有氧呼吸**，也能进行**无氧呼吸**。检测产物有两套办法：**二氧化碳**用**澄清石灰水**检测，变浑浊说明有二氧化碳，浑浊的程度能判断二氧化碳含量的多少；还可以用**溴麝香草酚蓝溶液**，它本身是蓝色，遇到二氧化碳由**蓝变绿再变黄**，变色时间越短说明二氧化碳越多。**酒精**用**酸性重铬酸钾溶液**检测，本身是橙色，遇到酒精由**橙变灰绿**，一定要在酸性条件下用，酸性条件靠加**浓硫酸**提供，因为重铬酸钾在碱性或中性条件下作用很微弱，而且硫酸根能参与生成灰绿色的硫酸铬。实验装置是两组实验组相互对照：A 瓶和 B 瓶都装等量酵母菌培养液，加等量质量分数 5% 的葡萄糖溶液，变量就是**有无氧气**，其他无关变量保持相同且适宜；葡萄糖溶液要先煮沸消毒杀死杂菌，冷却后再加入酵母菌，不然高温会把酵母菌烫死。A 瓶前面多一个装 10% 氢氧化钠溶液的锥形瓶，用来除去通入空气里的二氧化碳，再接橡皮球或气泵通气，提供有氧环境；不能用澄清石灰水代替氢氧化钠来除二氧化碳，因为澄清石灰水吸收二氧化碳有一定限度、吸不完。B 瓶直接密封，提供无氧环境。检测二氧化碳时把导管通入澄清石灰水或溴麝香草酚蓝溶液；检测酒精时从 A、B 瓶各取等量培养液，加酸性重铬酸钾溶液观察变色，而且要**适当延长培养时间**，等葡萄糖耗尽再测，因为葡萄糖是还原糖，也会被重铬酸钾氧化、颜色反应和酒精相同，会干扰结果。实验结论：酵母菌在有氧和无氧条件下都能进行细胞呼吸，**有氧条件下产生大量的二氧化碳和水，无氧条件下产生酒精和少量的二氧化碳**；有氧条件利于大量繁殖，无氧条件进行酒精发酵，所以酿酒要密封。这个实验属于**对比实验**：只设置两个或两个以上的实验组，通过对结果的比较分析来探究某种因素的影响，也叫相互对照实验，是对照实验的一种。易错提醒：葡萄糖溶液煮沸后要冷却再加酵母菌；气体使澄清石灰水变浑浊只能说明有二氧化碳，不能直接断定就是有氧呼吸，因为无氧呼吸也产生二氧化碳；重铬酸钾要在酸性条件下用；两组都是实验组，没有对照组。接着讲**有氧呼吸**：对大多数生物来说，有氧呼吸是细胞呼吸的主要形式。**有氧呼吸的主要场所是线粒体**，真核细胞里有氧呼吸的场所是线粒体和细胞质基质；线粒体内膜折叠形成**嵴**，增大膜面积，给有氧呼吸有关的酶提供更多附着位点。原核细胞没有线粒体，但部分原核细胞（如硝化细菌、蓝细菌、根瘤菌）含有有氧呼吸的酶，也能进行有氧呼吸，场所在细胞质基质和细胞膜上。有氧呼吸的总反应式以葡萄糖为例：葡萄糖加氧气加水，在酶的作用下生成二氧化碳和水并释放能量，生成大量 ATP。注意底物**主要是葡萄糖**，但不只有葡萄糖，其他有机物也可以参加有氧呼吸；反应物里的水不能省掉，它参加第二阶段，生成物里的水是第三阶段产生的；反应式里写的是能量，不能写成 ATP，因为大部分能量以热能形式散失了；箭头上面的酶不能漏，各阶段的酶种类也不一样。有氧呼吸分**三个阶段**：**第一阶段在细胞质基质**，1 分子葡萄糖在酶的作用下分解成 2 分子**丙酮酸**和 4 分子**[H]**，释放少量能量，一部分以热能散失、一部分生成少量 ATP，也叫**糖酵解**；**第二阶段在线粒体基质**，2 分子丙酮酸和 6 分子水生成 20 分子 [H] 和 6 分子二氧化碳，释放少量能量，也叫**三羧酸循环**，二氧化碳就是在这个阶段产生的；**第三阶段在线粒体内膜**，前面两阶段产生的 24 分子 [H] 和 6 分子氧气生成 12 分子水，释放大量能量，也叫**氧化磷酸化**。葡萄糖不能进入线粒体分解，因为线粒体里没有分解葡萄糖的酶，分解葡萄糖的酶只分布在细胞质基质里；有机物彻底分解发生在第二、三阶段，所以有氧呼吸的主要场所是线粒体。能量上，1 mol 葡萄糖有氧呼吸共释放 **2870 kJ**，其中 **977.28 kJ** 储存在 ATP 里，剩下 1892.72 kJ 以热能散失；每合成 1 mol ATP 需要 30.54 kJ，所以 1 mol 葡萄糖共生成 **32 mol ATP**，能量转化效率约 **34%**。氧的去向：氧气里的氧全部进入生成的水，葡萄糖和反应物水里的氧全部进入二氧化碳。易错提醒：葡萄糖不是有氧呼吸唯一利用的物质；不是所有真核细胞都能进行有氧呼吸，哺乳动物成熟的红细胞和蛔虫细胞没有线粒体，不能进行有氧呼吸；有氧呼吸的实质不是葡萄糖在线粒体中彻底氧化分解，而是在氧的参与下通过多种酶的作用，把葡萄糖等有机物彻底氧化分解，产生二氧化碳和水，释放能量、生成大量 ATP。教材练习题：把酵母菌培养液离心，得到只含细胞质基质的上清液和只含细胞器的沉淀物，分别加等量等浓度葡萄糖溶液，在有氧条件下只有未离心处理的完整酵母菌（丙试管）能产生二氧化碳和水，因为甲只有细胞质基质、只能完成第一阶段，乙只有细胞器、葡萄糖进不了线粒体。第二讲讲**无氧呼吸**：整个过程都发生在**细胞质基质**，分两个阶段。**第一阶段与有氧呼吸的第一阶段完全相同**，1 分子葡萄糖分解成 2 分子丙酮酸和 4 分子 [H]，释放少量能量。**第二阶段**也在细胞质基质，2 分子丙酮酸和 4 分子 [H] 在酶的作用下生成 2 分子乳酸，或者生成 2 分子酒精和 2 分子二氧化碳，**第二阶段不产能**，写反应式时别把 [H] 漏掉。按酶的种类不同分两种：产物是乳酸的用**乳酸脱氢酶**，叫**产乳酸式**；产物是酒精和二氧化碳的用**乙醇脱氢酶**，老师简称为产酒气式，写的时候别漏了二氧化碳。反应式后面一定要加“**少量能量**”，以区别于有氧呼吸释放的大量能量；写乳酸和酒精的分子式后面要加括号注明是哪种物质，因为 C₃H₆O₃ 和 C₂H₆O 都是同分异构体、可能代表别的物质。产物归属要记牢：动物细胞和人体细胞无氧呼吸的产物只有乳酸；大多数植物细胞产酒精和二氧化碳，玉米胚乳、甜菜块根、马铃薯块茎这三个特例产乳酸；微生物里乳酸菌只能产乳酸，酵母菌产酒精和二氧化碳。能量上，1 mol 葡萄糖无氧呼吸分解成乳酸只释放 **196.65 kJ**，其中 61.08 kJ 储存在 ATP 里，正好生成 **2 mol ATP**，剩下 135.57 kJ 以热能散失；大部分能量没有释放出来，还储存在乳酸或酒精这些没有彻底分解的有机产物里。**无氧呼吸**的概念是：在没有氧气参与的情况下，葡萄糖等有机物经过不完全分解、释放少量能量的过程；酵母菌、乳酸菌等微生物的无氧呼吸也叫**发酵**，但工业上的发酵不一定是无氧呼吸，比如醋酸发酵用的醋酸菌是需氧菌、只能进行有氧呼吸。**细胞呼吸**除了提供能量，还是生物体**代谢的枢纽**，蛋白质、糖类和脂质的代谢都能通过细胞呼吸联系起来。易错提醒：无氧呼吸没有氧气参与，但 [H] 不会积累，第二阶段还要用它当反应物；马铃薯块茎无氧呼吸的产物是乳酸，不是酒精和二氧化碳；人体产生二氧化碳的细胞呼吸方式一定是有氧呼吸，因为人体细胞不能进行产酒精式的无氧呼吸；无氧呼吸只有第一阶段释放少量能量，第二阶段不产能；必须是释放出来的那部分能量才说大部分以热能散失、少部分储存在 ATP 里，无氧条件下葡萄糖里的大部分能量根本没释放出来。应用要会联系生活：包扎伤口用**透气的消毒纱布或创可贴**，是为了避免厌氧病原菌繁殖，不是为了保证伤口处细胞的有氧呼吸，因为伤口处细胞不能直接利用外界氧气，要靠血红蛋白输送；酿酒前期先适宜通气让酵母菌有氧呼吸大量繁殖，后期再密封发酵产酒精；花盆土壤板结要松土透气，既利于根细胞有氧呼吸，也利于土壤里需氧微生物分解有机物、供植物吸收无机盐；储藏水果粮食要降低温度、降低氧气含量来减弱呼吸作用、减少有机物消耗，注意是**低氧而非无氧**；破伤风芽孢杆菌是厌氧菌，伤口深或被锈钉扎伤后深处无氧、容易大量繁殖，要打破伤风针；提倡慢跑这种有氧运动，是为了避免肌细胞供氧不足进行无氧呼吸、乳酸大量积累使肌肉酸胀乏力。影响细胞呼吸的因素分内部和外部：内部因素有遗传特性、生长发育时期、器官类型，一般幼苗期呼吸速率高、成熟期低；外部因素是重点。**温度**通过影响酶的活性来影响呼吸速率，最适温度一般在 **25 到 35 摄氏度**，低温储存食品、大棚夜间和阴天适当降温都是利用低温降低酶活性，温水和面发得快是因为温度高、酶活性高、呼吸快、产生大量二氧化碳。**氧气**是有氧呼吸的反应物，氧气含量影响有氧呼吸速率，同时氧气对无氧呼吸有**抑制作用**；看坐标图：横坐标是氧气含量，纵坐标是二氧化碳释放量，无氧呼吸释放的二氧化碳随氧气增多而下降，有氧呼吸释放的二氧化碳随氧气增多而上升，两者相加是总量曲线；氧气浓度为 0 时只进行无氧呼吸，0 到 10% 两种呼吸同时进行，**10% 时无氧呼吸消失**，10% 以上只进行有氧呼吸；二氧化碳释放总量在氧气浓度 **5%** 时最少，说明这时有机物消耗最少，所以储存粮食水果蔬菜要用低氧环境，粮食还要干燥，水果蔬菜还要一定湿度。**水分**既是有氧呼吸的反应物，又是生化反应的介质，在一定范围内呼吸速率随含水量增加而加快，粮食入仓前要晾晒减少自由水、降低呼吸速率，干种子萌发前浸泡是提高含水量、加快呼吸。**二氧化碳**是细胞呼吸的最终产物，积累过多会抑制细胞呼吸，所以适当增加二氧化碳浓度也有利于水果蔬菜保鲜。最后比较有氧呼吸和无氧呼吸：不同点是反应条件（要不要氧气）、反应场所、分解产物（有氧是二氧化碳和水、无氧是乳酸或酒精加二氧化碳）、能量转化和特点（有氧彻底氧化分解、能量完全释放，无氧不彻底分解、能量没有完全释放）；相同点是实质都是分解有机物、释放能量、生成 ATP，意义都是为生物提供能量、作为代谢枢纽；联系是第一阶段从葡萄糖到丙酮酸完全相同，之后在不同条件、场所和酶的作用下沿不同途径形成不同产物。判断呼吸方式有**三看法**：一看反应物和产物，消耗氧气或产物中有水的一定存在有氧呼吸，有酒精或乳酸生成的一定存在无氧呼吸；二看物质的量关系，不消耗氧气却释放二氧化碳的只能是产酒精式无氧呼吸，不消耗氧气也不释放二氧化碳的可能是产乳酸式无氧呼吸或细胞已死亡，二氧化碳释放量等于氧气吸收量时只进行有氧呼吸，或同时进行有氧呼吸和产乳酸式无氧呼吸；三看场所，只在细胞质基质中进行的是无氧呼吸，有线粒体参与的一定存在有氧呼吸，但这只针对真核细胞，原核细胞不论哪种呼吸场所都在细胞质基质里。数量关系要会算：消耗等量葡萄糖时，有氧呼吸与产酒精式无氧呼吸的二氧化碳产生量之比是 **3:1**；产生等量二氧化碳时，两者消耗葡萄糖量之比是 **1:3**；两者同时进行时，氧气吸收量与二氧化碳释放总量之比等于 **3:4** 说明速率相等，小于 3:4 说明有氧呼吸速率小于无氧呼吸速率，大于 3:4 则相反。课后作业是完成课后作业 21。", "vtech": [["三阶段场所与产物先对表", "第一阶段在细胞质基质：1 分子葡萄糖→2 丙酮酸＋4[H]＋少量能量；第二阶段在线粒体基质：2 丙酮酸＋6 水→20[H]＋6 二氧化碳＋少量能量；第三阶段在线粒体内膜：24[H]＋6 氧气→12 水＋大量能量；三阶段别名糖酵解、三羧酸循环、氧化磷酸化。"], ["无氧呼吸两类产物看酶", "产乳酸式用乳酸脱氢酶，产物是 2 乳酸；产酒精式用乙醇脱氢酶，产物是 2 酒精＋2 二氧化碳，写的时候别漏了二氧化碳；反应式后面一定要写“少量能量”，第二阶段不产能；人体细胞只能产乳酸，酵母菌产酒精加二氧化碳，玉米胚乳、甜菜块根、马铃薯块茎这三个植物特例产乳酸。"], ["检测题先看试剂与颜色", "二氧化碳：澄清石灰水变浑浊，浑浊程度看多少；溴麝香草酚蓝由蓝变绿再变黄，变色时间越短二氧化碳越多；酒精：酸性重铬酸钾由橙变灰绿，酸性条件靠浓硫酸提供；测酒精要适当延长培养时间，等葡萄糖耗尽再测，否则葡萄糖的还原性会干扰。"], ["氧气曲线抓 5% 与 10% 两个点", "氧气浓度为 0 时只进行无氧呼吸，0 到 10% 两种呼吸同时进行，10% 时无氧呼吸消失；二氧化碳释放总量在氧气浓度 5% 时最少，所以低氧储存最省有机物；温度通过影响酶活性起作用，最适温度一般在 25 到 35 摄氏度。"]], "vgaokao": []}}, "bio_b021": {"name": "捕获光能的色素和叶绿体", "sec": 21, "secTitle": "光合作用与能量转化", "page": 97, "desc": "四条色素带的顺序与吸收光谱；色素提取分离实验规范；恩格尔曼实验。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b019"], "next": ["bio_b022"], "content": {"advance": {"a": "细、直、齐是为了让各色素从同一起点、沿同一水平线开始扩散，分离出的色素带整齐平行、便于比较顺序和宽度；细线太粗或不齐会使色素带重叠、歪斜，看不清分界。层析液若触及滤液细线，色素会直接溶解到层析液中，滤纸上得不到色素带，分离实验彻底失败，所以液面只能低于细线，靠毛细作用让层析液带着色素向上扩散。", "kind": "self", "q": "为什么滤液细线要细、直、齐，且层析液不能触及滤液细线？两条要求分别对应什么实验结果问题？"}, "apply": [{"ans": 1, "opts": ["层析时间太短", "研磨时未加CaCO3，叶绿素被破坏", "滤液细线画得太粗", "无水乙醇加得太多"], "q": "某同学做色素分离实验，滤纸条上只出现了胡萝卜素和叶黄素两条带，叶绿素a、b不见了。最可能的原因是（ ）", "why": "叶绿素比类胡萝卜素更容易被破坏，未加CaCO3时研磨产生的有机酸破坏叶绿素，只剩类胡萝卜素两条带，选B。"}, {"ans": 1, "opts": ["细菌喜欢强光", "叶绿体受光时释放氧气，好氧细菌趋向氧气多的地方", "光照使水温升高，细菌趋向温暖处", "叶绿体能产生葡萄糖吸引细菌"], "q": "恩格尔曼用极细光束照射水绵时，好氧细菌聚集在叶绿体被照部位。该现象说明（ ）", "why": "好氧细菌聚集在氧气浓度高的地方，聚集说明被照的叶绿体释放了氧气，证明叶绿体是光合作用放氧的场所，选B。"}], "basics": [{"ans": 2, "opts": ["叶绿素a，蓝绿色", "叶绿素b，黄绿色", "胡萝卜素，橙黄色", "叶黄素，黄色"], "q": "纸层析分离色素时，滤纸条上最上端的色素带及其颜色是（ ）", "why": "胡萝卜素溶解度最大、扩散最快，位于最上端，呈橙黄色，选C。"}, {"ans": 2, "opts": ["使研磨更充分", "溶解色素", "防止色素被破坏", "加速层析分离"], "q": "提取色素时加入CaCO3的作用是（ ）", "why": "CaCO3中和有机酸、防止色素被破坏，选C。研磨充分靠SiO2，溶解色素靠无水乙醇。"}], "case": {"a": "(1)优先选红光灯和蓝紫光灯。叶绿素主要吸收红光和蓝紫光，类胡萝卜素主要吸收蓝紫光，这两种光被色素吸收利用的比例最高。(2)色素对绿光吸收最少，绿光补光利用率低、效果差。(3)基本合理。白光是复合光，含有红光和蓝紫光等成分，能被色素吸收用于光合作用，只是能量中包含吸收较少的绿光等成分，针对性略差。", "hints": ["先想叶绿素和类胡萝卜素分别主要吸收什么光", "白光是复合光，包含红光和蓝紫光"], "q": "北方冬季大棚种植番茄，光照不足，农户要选补光灯：有红光灯、蓝紫光灯、绿光灯三种，价格相近。结合色素吸收光谱的知识，请回答：(1)应优先选择哪两种灯？依据是什么？(2)为什么不选绿光灯？(3)有农户说白光灯效果和彩色灯一样，是否合理？", "steps": ["第一步：叶绿素主要吸收红光和蓝紫光，类胡萝卜素主要吸收蓝紫光，所以红光和蓝紫光补光效率最高。", "第二步：色素对绿光吸收最少，绿光大多被反射或透过，利用率最低。", "第三步：白光含红光和蓝紫光成分，也能被利用，说法基本合理，只是针对性不如单色光。"], "talk": ["补光选红加蓝紫，绿光最差——和叶片为什么是绿色的是同一个道理。"], "title": "案例：温室大棚该用什么颜色的灯补光"}, "intro": "光合作用先得抓住光，抓光靠**色素**，色素住在**叶绿体**里。这一节两个实验加一个结构，顺序和颜色错一个全盘扣分。先把四条色素带钉死：从上到下是**胡萝卜素、叶黄素、叶绿素a、叶绿素b**。==含量最多的是叶绿素a，扩散最快的是胡萝卜素。==\n再记吸收规律：==叶绿素主要吸收红光和蓝紫光，类胡萝卜素主要吸收蓝紫光，对绿光吸收最少，所以叶片呈绿色。==", "learn": [{"h": "提取色素：每一步操作都有理由", "p": "用**无水乙醇**提取色素，因为色素能溶解在有机溶剂中。加**SiO2**是为了研磨更充分，让细胞破裂、色素释放；加**CaCO3**是为了防止研磨中色素被破坏（中和有机酸）。过滤后收集滤液。画滤液细线时要求**细、直、齐**，还要重复画几次攒够色素量，画完等干了再画下一次。==层析时层析液绝对不能没过滤液细线，否则色素直接溶进层析液，纸上就分不出色素带。== 这句话几乎是原题原问，年年有人错。"}, {"h": "纸层析分离：四条带背顺序带颜色", "p": "原理：不同色素在层析液中的**溶解度**不同，溶解度大的随层析液在滤纸上扩散快，反之慢，于是分开。从上到下：**胡萝卜素（橙黄色）**溶解度最大、跑得最远；**叶黄素（黄色）**第二；**叶绿素a（蓝绿色）**第三，但带最宽，因为**含量最多**；**叶绿素b（黄绿色）**最下面、扩散最慢。分清两个最：扩散最快是胡萝卜素，含量最多是叶绿素a，考试就爱把这两个搅在一起。秋天叶子变黄，是因为低温下叶绿素分解，类胡萝卜素的颜色显出来了。"}, {"h": "叶绿体结构和恩格尔曼实验", "p": "**叶绿体**有**双层膜**，内部有许多**基粒**，基粒由**类囊体**堆叠而成，色素就分布在**类囊体薄膜**上；基质中含少量**DNA**和光合作用需要的酶。**恩格尔曼实验**：用水绵和**好氧细菌**做材料，没有氧气时细菌均匀分布；用极细光束照射，只有照到叶绿体的部位细菌聚集；完全曝光时细菌聚集在叶绿体受光部位。==恩格尔曼实验直接证明：氧气是由叶绿体释放的，叶绿体是光合作用的场所。== 选好氧细菌当指示剂、用极细光束做对照，是这个实验设计最巧妙的地方。"}], "pitfalls": ["色素带顺序记错——从上到下是胡萝卜素、叶黄素、叶绿素a、叶绿素b，口诀：胡黄a b，颜色橙黄、黄色、蓝绿、黄绿。", "把SiO2和CaCO3作用写反——SiO2助研磨，CaCO3护色素。", "认为叶绿素主要吸收绿光——恰恰相反，绿光吸收最少被反射，叶片才显绿色。", "层析液没过滤液细线还能补救——不能，色素会溶入层析液，分离失败。"]}, "video": {"bvid": "BV1p54y177e6", "p": 43, "t": "光合作用与能量转化（一）", "dur": "58:25", "from": "锦城大同教育·杨波生物", "vtop": ["四条色素带从上往下是胡萝卜素、叶黄素、叶绿素a、叶绿素b，口诀“胡黄AB”——扩散快慢看溶解度、带宽看含量。", "叶绿素a和叶绿素b主要吸收蓝紫光和红光，类胡萝卜素主要吸收蓝紫光；绿光吸收最少、被反射出来，所以叶片是绿色的。", "叶绿体是光合作用的场所，但不是唯一场所——蓝细菌没有叶绿体也能进行光合作用；叶绿体是植物细胞特有的细胞器，但不是所有植物细胞都有，如根尖细胞。"], "vsum": "本课讲第五章第四节光合作用与能量转化（一），讲捕获光能的色素和叶绿体的结构。开场先看玉米白化苗：白化苗叶片里不含绿色色素，种子中储存的养分耗尽就会死去，可见叶片中的色素可能与光能的捕获有关——只有含绿色色素的细胞才能进行光合作用、合成积累有机物，这里的绿色色素就是**光合色素**。第一个重点是绿叶中色素的**提取与分离**实验，分为提取和分离两大部分。先讲提取的原理：绿叶中的色素是有机物，根据**相似相溶**原理能溶解在有机溶剂中，教材用的溶剂是**无水乙醇**；没有无水乙醇时，可以用体积分数为95%的乙醇加上适量的**无水碳酸钠**来代替，因为无水碳酸钠能吸收水分。实验用品：无水乙醇是提取用的溶剂；**二氧化硅**是坚硬的固体，研磨时加入有助于研磨得更充分；**碳酸钙**是防止研磨时色素分子被破坏；过滤用**单层尼龙布**，不能用滤纸代替，因为滤纸吸附性强，会把色素分子吸附在上面，导致滤液里色素含量低、后续现象不明显甚至不出现。提取的具体步骤：第一步取材，称取**5克**绿叶（比如菠菜叶），尽量选新鲜又嫩的绿叶——放久的叶子发黄是叶绿素被破坏了，嫩叶的叶绿素含量更高，现象更明显；去掉叶脉、剪碎，加入少许二氧化硅和碳酸钙，研磨破坏细胞结构、释放出色素分子；再加入**5到10毫升**无水乙醇，迅速研磨，过滤得到滤液，用棉塞将试管口塞紧，防止空气中的氧气破坏色素。对着光看滤液呈绿色、背着光看呈红色，这种现象叫**叶绿素荧光现象**，了解即可。接下来是分离：用**纸层析法**，原理是不同色素在**层析液**中的溶解度不同，溶解度高的随层析液在滤纸上扩散得快，溶解度低的扩散得慢，扩散时间相同、速度不同，最终在滤纸上分层、实现分离。老师用钢笔字滴水扩散打比方帮助理解。滤纸条的准备：用干燥的**定性滤纸**（湿滤纸会影响层析液扩散），剪成宽度略小于试管直径、长度略小于试管长度的滤纸条，在一端剪去两脚——这样色素扩散的起点相同，能得到平整的色素带；距去角一端1厘米处用铅笔画一条细线；再用毛细吸管吸取少量滤液，沿铅笔线均匀画出一条滤液细线，要求**细、直、齐**，等干了之后再重复画一两次（没干就画会扩散变粗、色素带重叠），也可以用盖玻片蘸取少量滤液轻压在铅笔线处画线。分离操作：将适量层析液倒入试管（层析液是**石油醚、丙酮和苯**的混合物，都是有机溶剂），把滤纸条有滤液细线的一端朝下轻轻插入层析液中，注意**不能让滤液细线触及层析液**（否则色素直接溶解在层析液里，几乎没有色素再往滤纸上扩散），用棉塞塞紧试管口。实验结果：滤纸条上出现**四条色素带**，从上往下依次是**胡萝卜素、叶黄素、叶绿素a、叶绿素b**，口诀“**胡黄AB**”。扩散起点相同、时间相同，扩散路程不同说明扩散速度不同：最上面扩散最远的胡萝卜素在层析液中溶解度最高，最下面扩散最慢的叶绿素b溶解度最低；色素带的宽度反映色素的相对含量，最宽的第三条叶绿素a含量最多，最窄的第一条胡萝卜素含量最少。四种色素的颜色也要记住：胡萝卜素**橙黄色**、叶黄素**黄色**、叶绿素a**蓝绿色**、叶绿素b**黄绿色**；叶绿素a和叶绿素b都属于绿色这一大范围，叶绿素b比叶绿素a更稳定一些。秋天叶片变黄的原因：低温下叶绿素被分解，绿色的色素没了，剩下的橙黄色、黄色的类胡萝卜素的颜色就显现出来了。四种色素的共同功能是**吸收、传递和转化光能**。再看叶绿素分子的结构：分为头部和尾部，头部是**卟啉环**，尾部是植醇；卟啉环中间有一个**镁离子**，不稳定——在酸性环境下，镁离子会被氢离子取代，变成不再是绿色的褐色的**去镁叶绿素**，叶绿素分子就相当于被破坏了。这就解释了为什么研磨时要加碳酸钙：植物细胞的液泡里含有有机酸，研磨破坏细胞结构后有机酸释放出来，叶绿素就处在酸性环境中，镁离子会被氢离子取代；加入碳酸钙可以中和这些酸性物质，保住镁离子，从而保护叶绿素分子在研磨时不被破坏。影响叶绿素合成的因素有三个：**光照**是必需的、缺一不可（黄豆芽在黑暗环境下发芽长出来是黄色的，就是因为没有光照、不能合成叶绿素）；**温度**通过影响酶的活性来影响叶绿素的合成，低温还会导致叶绿素分解；**矿质元素**（叶绿素合成需要镁、氮等元素）。异常现象分析：色素带颜色过浅有六个可能原因——未加二氧化硅或研磨不充分；用了放置数天的绿叶或绿叶用量太少；一次加入大量无水乙醇导致提取液浓度太低；未加碳酸钙或加入过少导致色素被破坏；画滤液细线次数过少；层析液触及滤液细线但时间不长；色素带重叠是因为滤液细线画得太粗；完全看不见色素带，可能是忘了画滤液细线（只画了铅笔线），或是滤液细线触及层析液时间较长、色素全部溶解在层析液中。接着看绿叶中色素的**吸收光谱**：叶绿素a和叶绿素b**主要吸收蓝紫光和红光**，类胡萝卜素（胡萝卜素和叶黄素）**主要吸收蓝紫光**；注意是“主要吸收”，其他色光也有一些吸收。光合作用利用的光都是**可见光**，波长大于700纳米的红外光和波长小于400纳米的紫外光这些不可见光，色素不能吸收利用。叶绿素a、叶绿素b和类胡萝卜素在绿光区吸收都非常低，绿光吸收得最少、被反射出来，所以叶片呈现绿色。应用：大棚里给蔬菜补光，功率相同的情况下应选**蓝紫光或红光**，因为植物对这两种光的利用效率更高。四个易错提醒：①提取色素时加碳酸钙的目的是使研磨更充分——错，那是二氧化硅的作用，碳酸钙是防止色素被破坏；②绿叶中含量越多的色素在滤纸条上扩散得越快——错，扩散快慢和色素在层析液中的溶解度有关，和含量无关；③叶绿素a和叶绿素b只吸收红光和蓝紫光——错，是“主要吸收”，其他色光也有吸收；④植物叶片之所以呈现绿色是因为叶片中的叶绿体吸收了绿光——错，绿光是吸收最少的、被反射出来才看到绿色。第二个知识点是**叶绿体的结构**适于进行光合作用：叶绿体是进行光合作用的场所，是植物细胞特有的细胞器，但**并非所有植物细胞都含有叶绿体**，比如植物的根尖细胞就不含叶绿体。叶绿体的形态一般为扁平的椭球形或球形，少数是其他形态（水绵的叶绿体就是螺旋带状）。叶绿体是双层膜的细胞器，最外面是**外膜**、里面是**内膜**，教材图上内外膜画成不同颜色只是为了区分，实际上内外膜都是无色透明的，而且内外膜的膜面积几乎相等；叶绿体增大膜面积靠的是**类囊体**堆叠成**基粒**——许多扁平的圆盘状结构类囊体堆积形成基粒，类囊体同样是有膜的结构；**基质**里分布有与光合作用有关的酶。叶绿体和线粒体一样是**半自主细胞器**，因为内部含有少量的DNA、RNA和核糖体，能自己合成部分需要的酶。叶绿体是进行光合作用的场所，但**不是唯一场所**：蓝细菌没有叶绿体也能进行光合作用。**恩格尔曼的两个实验**：第一个实验在黑暗环境中用极细的光束照射水绵，好氧细菌只分布在叶绿体有光束照射的部位——有光才能进行光合作用、释放氧气，供好氧细菌利用；第二个实验用透过三棱镜的光照射水绵临时装片，好氧细菌主要分布在叶绿体蓝紫光与红光照射的部位，正好对应叶绿素主要吸收红光和蓝紫光。这两个实验证明叶绿体能够吸收光能用于光合作用、释放氧气，是进行光合作用的场所。叶绿体捕获光能进行光合作用的物质基础有两个：一是能吸收光能的色素分子（光合色素），二是与光合作用有关的酶——蓝细菌虽然没有叶绿体，但它的光合片层上分布有光合色素和与光合作用有关的酶，所以依然能进行光合作用。注意细胞内含色素的细胞器除了叶绿体还有**液泡**（如花青素），但只有叶绿体里的光合色素才能参与光合作用，液泡里的色素不能。三个易错提醒：①没有叶绿体的生物无法进行光合作用——错，蓝细菌可以；②植物细胞都含有叶绿体——错，根尖细胞就没有；③在植物细胞内能进行光合作用的色素分布在叶绿体以及液泡中——错，液泡里的色素不能参与光合作用。教材练习题：第一题判断叶绿体结构与功能的表述——“叶绿体中只有叶绿素吸收的光能才能用于光合作用”是错的，类胡萝卜素吸收的光能也能用于光合作用；“叶绿体的类囊体上有巨大的膜面积，有利于充分吸收光能”是对的；“植物叶片之所以呈现绿色是因为叶片中的叶绿体吸收了绿光”是错的，绿光是被反射出来的。第二题选关于高等植物细胞色素叙述错误的一项，选A——“所有植物细胞中都含有四种色素”是错的，并不是所有植物细胞都有叶绿体，而且有的植物细胞既有叶绿体、液泡里还可能有其他色素；其余选项都对：有些植物细胞的液泡中也含有色素、叶绿素和类胡萝卜素都可以吸收光、植物细胞内的光合色素主要包括叶绿素和类胡萝卜素两大类。最后总结：本课学的是捕获光能的色素（胡萝卜素、叶黄素、叶绿素a、叶绿素b）与叶绿体的结构，重点是色素提取与分离实验的原理、过程、步骤和注意事项，四种色素都分布在类囊体的薄膜上。", "vtech": [["提取还是分离：溶剂别用混", "提取色素用无水乙醇（没有就用体积分数95%的乙醇加适量无水碳酸钠代替），分离色素用层析液（石油醚、丙酮和苯的混合物）；研磨时加二氧化硅助研磨更充分、加碳酸钙防色素被破坏，两者作用别互换。"], ["四条色素带：胡黄AB", "从上往下依次是胡萝卜素（橙黄色）、叶黄素（黄色）、叶绿素a（蓝绿色）、叶绿素b（黄绿色）；扩散最快的是胡萝卜素，在层析液中溶解度最高；带最宽的是叶绿素a，含量最多；扩散快慢看溶解度、带宽看含量。"], ["碳酸钙为什么能保护叶绿素", "叶绿素头部是卟啉环，中间有个镁离子；酸性环境下镁离子会被氢离子取代，变成褐色的去镁叶绿素；研磨会释放液泡里的有机酸，加入碳酸钙中和酸性物质，就保住了镁离子、保住了叶绿素。"], ["吸收光谱与易错点", "叶绿素a、b主要吸收蓝紫光和红光，类胡萝卜素主要吸收蓝紫光；红外光（波长大于700纳米）和紫外光（波长小于400纳米）不能利用；叶片呈绿色是因为绿光吸收最少、被反射出来，不是吸收了绿光；大棚补光功率相同时选蓝紫光或红光效率更高。"]], "vgaokao": []}}, "bio_b022": {"name": "光合作用的原理", "sec": 22, "secTitle": "光合作用与能量转化", "page": 100, "desc": "光反应与碳反应的场所、物质与能量变化；条件骤变时 C₃、C₅ 含量分析。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b021"], "next": ["bio_b023"], "content": {"advance": {"a": "说法错误。暗反应本身不直接需要光，但它的原料供应离不开光反应：C3还原所需的ATP和NADPH都由光反应产生，且不能长期储存。夜间没有光反应，ATP和NADPH很快耗尽，C3还原停止，暗反应随之停止，所以植物夜间不能靠暗反应合成糖类，反而要靠细胞呼吸消耗有机物。", "kind": "self", "q": "有人认为暗反应既然不直接需要光，植物在夜间也能靠暗反应合成糖类。请评价这一说法。"}, "apply": [{"ans": 1, "opts": ["C3减少，C5增多", "C3增多，C5减少", "两者都增多", "两者都减少"], "q": "在光照充足时突然停止光照，短时间内叶绿体中C3和C5含量的变化是（ ）", "why": "停光后ATP和NADPH减少，C3还原受阻，C3堆积增多；C5再生减少，C5减少。选B。"}, {"ans": 1, "opts": ["C3增多，C5减少，糖类增多", "C3减少，C5增多，糖类减少", "C3减少，C5减少，糖类增多", "C3增多，C5增多，糖类减少"], "q": "在光照不变时突然降低CO2浓度，短时间内C3、C5和糖类的变化是（ ）", "why": "CO2减少使固定减慢，C3生成减少；固定消耗的C5减少，C5相对增多；原料和中间物都少，糖类合成减少。选B。"}], "basics": [{"ans": 1, "opts": ["叶绿体基质，必须有光", "类囊体薄膜，必须有光", "类囊体薄膜，有光无光均可", "叶绿体基质，有光无光均可"], "q": "光反应发生的场所和必需条件是（ ）", "why": "光反应在类囊体薄膜上进行，必须有光，完成水的光解和ATP、NADPH的形成，选B。"}, {"ans": 1, "opts": ["光合作用的场所是叶绿体", "光合作用释放的O2全部来自H2O", "CO2中的碳转化成了糖类", "光合作用能产生ATP"], "q": "鲁宾和卡门实验的结论是（ ）", "why": "鲁宾和卡门用同位素示踪证明O2来自水，选B。碳路径是卡尔文探明的，场所是恩格尔曼证明的。"}], "case": {"a": "(1)首先影响光反应，光反应生成的ATP和NADPH减少，氧气释放也减少。(2)C3的还原需要光反应提供ATP和NADPH，光反应减弱后C3还原速率下降，C3消耗减少、相对堆积，含量上升；C5是C3还原过程中再生的，再生减少，且CO2固定仍消耗C5，所以C5含量下降。(3)暗反应依赖光反应持续供应ATP和NADPH，长时间无光，ATP和NADPH耗尽，C3还原无法进行，暗反应最终停止。", "hints": ["先定位光反应产物ATP和NADPH", "C3的变化看还原这条去路，C5看再生这条来源"], "q": "晴天正午大棚内光合速率很高，一片乌云飘过，光照在几分钟内明显减弱，其他条件不变。检测发现这几分钟内叶肉细胞中C3含量上升、C5含量下降、糖类积累速度变慢。请回答：(1)光照减弱首先影响哪个阶段？该阶段产物如何变化？(2)解释C3上升、C5下降的原因。(3)若乌云久久不散，暗反应最终会怎样？", "steps": ["第一步：光照减弱直接削弱光反应，ATP和NADPH生成减少。", "第二步：C3还原需要ATP和NADPH，还原变慢，C3消耗减少而固定仍在生成，C3堆积上升。", "第三步：C5由C3还原再生，再生量减少，C5下降；乌云久留，ATP和NADPH耗尽，暗反应随之停止。"], "talk": ["骤变题三步走：先卡光反应或先卡固定，再看谁堆积、谁断供，C3C5永不一起同向乱动。"], "title": "案例：阴天午后大棚里的连锁反应"}, "intro": "光合作用分两步走：先在类囊体上抓光产能量，再在基质里用能量固定二氧化碳。**光反应**和**暗反应**（也叫碳反应）场所、条件、产物全不同，是表格对比题的常客。==光反应为暗反应提供ATP和NADPH，暗反应为光反应提供ADP、Pi和NADP+，两步互相咬合、谁也离不开谁。==\n本节真正的难点在最后：条件突然变了，**C3、C5、糖类**谁多谁少，这是全国卷年年考的分析题，必须练成本能。", "learn": [{"h": "探索历程：三个实验定三件事", "p": "**希尔反应**：离体叶绿体在有合适电子受体的水中，光照下能释放氧气，说明水的光解和氧气释放可以独立于CO2固定进行。**鲁宾和卡门**用**同位素示踪**（氧的同位素分别标记水和CO2）证明：==光合作用释放的O2全部来自H2O，不是来自CO2。== **卡尔文**用碳的同位素示踪，探明了CO2中的碳转化成有机物的路径，即**卡尔文循环**。**阿尔农**发现：光照下叶绿体能合成ATP，光合作用中产生了ATP。注意希尔反应别和鲁宾卡门混：希尔是离体叶绿体放氧，鲁宾卡门是定氧的来源。"}, {"h": "光反应和暗反应对照记", "p": "**光反应**：场所**类囊体薄膜**，条件是**必须有光**。做三件事：水的光解产生**O2、H+和电子**；形成**ATP**；形成**NADPH**。能量变化是光能转成ATP和NADPH中的化学能。**暗反应**：场所**叶绿体基质**，分两步——**CO2固定**：CO2和**C5**结合生成**C3**；**C3还原**：C3在ATP和NADPH提供的能量和氢下被还原，生成**糖类**，同时再生C5。==暗反应有光无光均可进行，但受光反应制约：没有光反应供ATP和NADPH，暗反应很快就会停。== 总反应可概括为CO2+H2O→（光能、叶绿体）（CH2O）+O2，物质上水变成氧气、CO2变成糖，能量上光能存进有机物。"}, {"h": "条件骤变分析：本节最值钱的方法", "p": "分析套路只有一句：先看直接影响哪一步，再推中间物。**光照突然减弱**：光反应变弱，ATP和NADPH减少，C3还原变慢，C3消耗少所以**C3增多**；C5是还原过程再生的，再生少所以**C5减少**；糖类合成减少。**CO2浓度突然降低**：CO2固定变慢，C3生成少所以**C3减少**；C3少了，还原消耗的C5来源不变、固定消耗的C5变少，所以**C5增多**；糖类减少。反过来光照增强、CO2增多，结论全部取反。==记住一对口诀：光减则C3升C5降，碳减则C3降C5升。== 短时间内的变化只看来源和去路哪头被卡住，被卡住去路的就堆积，被断了来源的就减少。"}], "pitfalls": ["说O2来自CO2——鲁宾和卡门已证明O2全部来自水的光解。", "认为暗反应只能在无光时进行——暗反应有光无光均可，只是需要光反应提供ATP和NADPH，长期无光也会停。", "骤变分析把C3和C5推反——方法是看来源与去路：去路受阻则堆积（增多），来源中断则减少。", "把NADPH的作用漏掉——C3还原既需要ATP供能，也需要NADPH供能并作还原剂（提供氢）。"]}, "video": {"bvid": "BV1p54y177e6", "p": 45, "t": "光合作用与能量转化（二）", "dur": "122:15", "from": "锦城大同教育·杨波生物", "vtop": ["光合作用释放的氧气全部来自水，不是来自二氧化碳——1941 年鲁宾和卡门用同位素标记实验证明的。", "光反应在类囊体薄膜上进行，暗反应在叶绿体基质中进行；光反应为暗反应提供 ATP 和 NADPH，暗反应为光反应提供 ADP、Pi 和 NADP⁺，两者不能长期独立进行。", "真正光合速率等于净光合速率加呼吸速率；氧气的产生量、二氧化碳的固定量、葡萄糖的生成量表示总光合，释放量、吸收量、积累量表示净光合。"], "vsum": "本课是光合作用的第二讲，分两集：第一集讲光合作用的原理与过程，第二集讲光合作用强度和影响它的因素。先复习概念：**光合作用**是指绿色植物通过**叶绿体**，利用光能将**二氧化碳**和**水**转化成储存着能量的**有机物**，并且释放出**氧气**的过程，产物有机物主要就是**糖类**。反应式要会写两条：一般形式是二氧化碳加水生成糖类加氧气；算葡萄糖时用 6CO₂＋12H₂O→C₆H₁₂O₆＋6H₂O＋6O₂。注意光合作用既消耗水又生成水，但消耗的水比生成的水多，所以教材的反应式把产物里的水省掉了。光合作用的反应式和有氧呼吸的反应式刚好互为倒置：光合作用的反应物就是有氧呼吸的产物，产物就是有氧呼吸的反应物，记住有氧呼吸的反应式就能倒过来写出光合作用的反应式。接下来是探索光合作用原理的实验。19 世纪末科学界普遍认为二氧化碳的碳和氧被分开，氧释放成氧气，碳和水结合成甲醛再缩合成糖；到了 1928 年发现甲醛对植物有毒害、也不能通过光合作用转化成糖，这个观点被否定了。1937 年英国科学家**希尔**做实验：在离体的叶绿体悬浮液中加入铁盐或其他氧化剂，发现水的光解能产生氧气。1941 年美国科学家**鲁宾和卡门**用**同位素标记**法：第一组用 ¹⁸O 标记水、给正常二氧化碳，植物释放的氧气含 ¹⁸O；第二组用 ¹⁸O 标记二氧化碳、给正常水，释放的氧气不含 ¹⁸O，两组对比得出结论——光合作用释放的氧气**全部来自水**。1954 年美国科学家**阿尔农**发现，在光照下叶绿体可以合成 **ATP**，这一过程总与水的光解相伴随。两道思考题要会答：希尔的实验能不能说明氧气中的氧全部来自水？不能，它只说明离体叶绿体在适当条件下能发生水的光解释放氧气，没有排除悬浮液里其他含氧物质的干扰。希尔的实验能不能说明水的光解与糖的合成不是同一个反应？能，因为合成糖需要二氧化碳提供碳，而水的光解悬浮液里没有二氧化碳，所以水光解时没有发生糖的合成。光合作用的过程分两个阶段。**光反应阶段**必须有光照才能进行，场所是**类囊体薄膜**，因为光合色素和有关酶分布在类囊体薄膜上。光反应有三个主要反应：第一，**水的光解**——光合色素吸收光能后夺取水分子中氧元素的电子，水被分解成氧气和氢离子；第二，ADP 加 Pi 再加上光能合成 **ATP**，注意合成 ATP 这一步会生成水；第三，NADP⁺ 加氢离子生成 **NADPH**，中文名**还原型辅酶Ⅱ**，和细胞呼吸里的还原型辅酶Ⅰ（NADH）是两种不同的物质，但都可以简写为 [H]。光能的去路有三条：分解水，转化成 ATP 里活跃的化学能，储存在 NADPH 的化学能里。**暗反应阶段**不需要光照，有光没光都能进行，场所是**叶绿体基质**，因为与暗反应有关的酶分布在叶绿体基质里。暗反应是一个循环过程，由卡尔文发现，又叫**卡尔文循环**。第一步是**二氧化碳的固定**：**C₅**（五碳化合物）加一分子二氧化碳生成两分子 **C₃**（三碳化合物），这一步也有水分子参与，数量关系可以用元素守恒自己推——5 个碳加 1 个碳等于 6 个碳，所以要生成两个三碳化合物。第二步是**三碳化合物的还原**：C₃ 在 ATP 提供能量、NADPH 提供能量和氢的作用下被还原，一部分还原成糖类等有机物，另一部分还原成 C₅，维持循环。还原出来的糖类一部分在细胞质中转化成**蔗糖**，另一部分在叶绿体中形成**淀粉**暂时储存，需要时再分解成葡萄糖进入细胞质。能量变化是 ATP 和 NADPH 里**活跃的化学能**转化成有机物里**稳定的化学能**。光反应和暗反应相互影响、相互制约：光反应为暗反应提供 ATP 和 NADPH，暗反应为光反应提供 ADP、Pi 和 **NADP⁺**，两者都不能长期独立进行。易错提醒四则：①植物在夜晚不能进行光反应，也不能长期进行暗反应，因为暗反应需要光反应提供物质和能量；②ATP 的移动方向是从叶绿体基质到类囊体薄膜（在基质中生成 ADP，在类囊体薄膜上消耗 ADP 合成 ATP）；③光合作用产生的 ATP 只能用于暗反应，不能为细胞内其他生命活动提供能量；④用 ¹⁴C 标记二氧化碳追踪碳的转移途径是二氧化碳→三碳化合物→糖类和五碳化合物。含量变化题是常考题型，只问短时间内怎么变，分析时从生成和消耗两个方面综合判断：光照由强到弱、二氧化碳供应不变时，ATP 和 NADPH 生成减少，三碳化合物的还原减慢，所以 C₃ 增多、C₅ 减少、有机物合成减少；二氧化碳供应由充足到不足、光照不变时，二氧化碳固定减慢，C₃ 生成减少、C₃ 减少、C₅ 增多、ATP 和 NADPH 因为消耗减少而积累升高；反过来光照由弱变强、或二氧化碳由不足变充足时，结论刚好相反。教材练习题要点：光合作用生成葡萄糖的反应式里，氧气中的氧全部来自水（12 个水中的氧），二氧化碳里的氧进入葡萄糖和水；暗反应不是只能在黑暗中进行，有光无光都能进行；叶绿体不同于线粒体的特点是能分解水产生氧气和氢离子；叶绿体基质只能进行暗反应、消耗 ATP，不能合成 ATP，所以不能合成 ATP 的场所是叶绿体基质。第二集先讲**光合作用强度**，指植物在单位时间内通过光合作用制造糖类的数量，也就是**光合速率**。影响因素有外部因素和内部因素：外部因素有土壤水分、二氧化碳浓度、温度、光照时间长短、光照强度、光的成分等，内部因素有叶片成熟程度、叶龄、植物种类等。衡量光合速率的指标不唯一：可以从原料消耗量衡量，比如单位时间内二氧化碳的消耗量；也可以从产物生成量衡量，比如单位时间内有机物的生成量、氧气的生成量。但叶片质量的增加量（有机物积累量）不能直接衡量光合速率，因为有光时植物既进行光合作用又进行细胞呼吸，测到的增加量是光合作用与呼吸作用的差值，这个差值就叫**净光合速率**，也叫**表观光合速率**：净光合速率＝实际光合速率－呼吸速率，所以**真正光合速率＝净光合速率＋呼吸速率**，真正光合速率也叫实际光合速率或总光合速率。黑暗条件下植物只能进行呼吸作用，所以黑暗条件下测得的数值表示呼吸速率，比如二氧化碳释放量或氧气吸收量。总光合速率和净光合速率的表示要分清：用氧气表示时，氧气的**产生量**是总光合速率，氧气的**释放量**是净光合速率；用二氧化碳表示时，二氧化碳的**固定量**或**消耗量**是总光合速率，二氧化碳的**吸收量**是净光合速率；用葡萄糖表示时，葡萄糖的**生成量**是总光合速率，葡萄糖的**积累量**是净光合速率。教材实验探究环境因素对光合作用强度的影响：用直径 0.6 厘米的打孔器打出圆形小叶片 30 片，尽量避开叶脉；抽气排出叶片细胞间隙的空气，叶片下沉后放入黑暗处盛有清水的烧杯中待用；分组倒入等量富含二氧化碳的清水，可以往清水里吹气，也可以用质量分数 1% 到 2% 的**碳酸氢钠溶液**；给予强、中、弱三种光照，可以用三种不同功率的灯泡；记录同一时间段内各装置中圆形小叶片浮起的数量，光合速率越大、产生氧气越多越快，上浮的叶片就越多。接着讲**化能合成作用**：硝化细菌把氨氧化成亚硝酸、再把亚硝酸氧化成硝酸，释放的化学能把二氧化碳和水合成糖类；硫细菌把硫化氢氧化成硫酸盐，氢细菌把氢气氧化成水，铁细菌氧化铁，这些细菌都属于**自养生物**。自养生物分两类：利用光能把无机物转变成有机物的叫光能自养生物，利用化学能的叫化能自养生物；能进行光合作用的生物是自养生物，但自养生物不都是利用光能的。影响因素第一个是**光照强度**：光是光合作用的能量来源，直接影响光反应阶段，制约 ATP 和 NADPH 的生成。在光照强度—二氧化碳吸收量曲线上，A 点光照强度为零，植物只进行呼吸作用，OA 段表示呼吸速率；AB 段呼吸速率大于光合速率，二氧化碳仍释放到外界；B 点光合速率等于呼吸速率，细胞与外界没有气体交换，B 点对应的光照强度叫**光补偿点**；光照强度继续增大，光合速率加快到一定程度后不再加快，对应最大光合速率的最小光照强度叫**光饱和点**，注意光饱和点不是曲线最高点 C 点；光照过强时光合速率甚至会下降，因为强光会灼伤细胞。把横坐标下移，曲线就表示总光合速率。阴生植物的光补偿点和光饱和点都比阳生植物低，所以间作套种时要搭配种类，让阳生植物利用大部分光能，透过的少量光能刚好被中间的阴生植物利用；阴雨天适当补充光照、及时给大棚除霜除雾都能提高产量。第二个是**二氧化碳浓度**：二氧化碳是光合作用的原料，经叶片表面的气孔进入叶肉细胞的叶绿体。在一定范围内光合速率随二氧化碳浓度增加而加快；光合速率等于呼吸速率时对应的二氧化碳浓度叫**二氧化碳补偿点**，达到最大光合速率时对应的最小二氧化碳浓度叫**二氧化碳饱和点**。C₃ 植物的曲线不从原点开始，必须二氧化碳浓度达到一定值才能进行光合作用；C₄ 植物能利用低浓度的二氧化碳，曲线从原点开始，高中不要求掌握两者的区分。农业上合理密植、通风能增大二氧化碳浓度，增施农家肥也能间接增大二氧化碳浓度，因为土壤里的微生物分解农家肥里的有机物会释放二氧化碳。第三个是**温度**：温度主要通过影响酶的活性来影响光合速率，主要是影响暗反应阶段的酶，温度还会影响气孔的开闭。一般植物光合作用的最适温度是 25 摄氏度，这节课图里的植物最适温度在 32 到 33 摄氏度。冬季温室栽培白天适当提高温度、晚上适当降低温度，可以减少呼吸作用消耗的有机物；新疆的瓜果特别甜，就是因为昼夜温差大，白天温度高、光合作用强、生成大量有机物，晚上温度低、呼吸作用弱、消耗的有机物少，有机物积累得多。第四个是**水分**：水既是光合作用的原料，又是体内各种化学反应的介质，还能影响气孔开闭。气孔由两个保卫细胞构成，保卫细胞失水皱缩时气孔关闭，吸水膨胀时气孔开放，因为保卫细胞外侧壁薄、吸水后向外侧膨胀，把内侧壁拉开，气孔就打开了。植物一天的光合速率曲线：凌晨到早上四五点只有呼吸作用、释放二氧化碳，日出后光合速率逐渐加快，中午两点左右出现一个下降，这就是**光合午休现象**——中午温度过高、蒸腾作用过强，植物为减少水分散失关闭气孔，吸收的二氧化碳减少，光合速率暂时降低。最后是**光质**：在可见光范围内，不同波长的光下光合作用效率不同，红光和蓝紫光下光合作用强度较大，绿光下最弱；叶绿素主要吸收红光和蓝光，类胡萝卜素主要吸收蓝紫光。大棚的塑料薄膜要选无色的，因为太阳光是复合光、功率相同，红色薄膜只透过红光、其他色光都被吸收掉了，利用到的光反而更少；人工补光时功率相同，补红光和蓝光最好。", "vtech": [["氧气来源看标记实验", "希尔 1937 年离体叶绿体加铁盐实验只能说明水光解产生氧气，不能证明氧全来自水；鲁宾和卡门 1941 年用 ¹⁸O 分别标记水和二氧化碳，证明释放的氧气全部来自水；1954 年阿尔农发现光照下叶绿体合成 ATP 总与水的光解相伴随。"], ["光暗反应分工与互供", "光反应在类囊体薄膜：水光解产生 O₂ 和 H⁺，ADP＋Pi 合成 ATP，NADP⁺ 生成 NADPH（还原型辅酶Ⅱ）；暗反应在叶绿体基质：C₅＋CO₂ 生成 2C₃，C₃ 还原成糖类和 C₅；光反应产生的 ATP 只能用于暗反应，不能用于其他生命活动。"], ["含量变化题只看短时间、两头分析", "光照或 CO₂ 改变时，C₃、C₅、ATP、NADPH 的含量变化只分析短时间，从生成和消耗两个方面综合判断：光照由强变弱、CO₂ 不变时 C₃ 增多、C₅ 减少；CO₂ 由充足变不足、光照不变时 C₃ 减少、C₅ 增多、ATP 和 NADPH 积累升高。"], ["补偿点与饱和点别认错点", "光补偿点是光合速率等于呼吸速率时对应的光照强度（B 点），光饱和点是达到最大光合速率时对应的最小光照强度（不是曲线最高点 C 点）；阴生植物的光补偿点和光饱和点都比阳生植物低；二氧化碳补偿点和饱和点同理，C₃ 植物曲线不从原点开始，C₄ 植物能利用低浓度二氧化碳。"]], "vgaokao": []}}, "bio_b023": {"name": "影响光合作用强度的环境因素", "sec": 23, "secTitle": "光合作用与能量转化", "page": 105, "desc": "总光合＝净光合＋呼吸；光强、CO₂、温度曲线与农业应用；沉水叶片探究实验。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b022"], "next": [], "content": {"advance": {"a": "NaHCO3溶液能为光合作用提供CO2，并维持CO2浓度相对稳定，排除CO2浓度变化对实验的干扰，使自变量只有光照强度。改变台灯距离时，台灯发热会使水温变化，温度也是影响光合的因素，属于无关变量干扰，应使用LED冷光源或在台灯与烧杯间加隔热装置，并保持各组水温一致、叶片数量和大小一致等。", "kind": "self", "q": "在探究光照强度对光合作用强度的影响（沉水叶片）实验中，为什么要用NaHCO3溶液而不是清水？台灯距离改变时还要注意什么无关变量问题？"}, "apply": [{"ans": 1, "opts": ["两者都升高", "两者都降低，以适应弱光环境利用有限光能", "补偿点升高、饱和点降低", "都不变，因为是遗传决定的"], "q": "将阳生植物移至遮阴处一段时间，其光补偿点和光饱和点的预期变化是（ ）", "why": "长期弱光下植物会调整为在较低光强下就能达到补偿和饱和，补偿点和饱和点都降低，与阴生植物特征一致，选B。"}, {"ans": 1, "opts": ["夜间降低大棚温度", "白天向大棚内通入适量CO2", "收获后及时翻耕土地", "给大棚覆盖黑色遮阳网"], "q": "大棚种植时，下列措施中主要目的是提高光合强度的是（ ）", "why": "通入CO2提高了光合的原料浓度，直接提高光合强度，选B。夜间降温是减弱呼吸、减少消耗，目的不同；黑色遮阳网会减弱光强。"}], "basics": [{"ans": 2, "opts": ["3个单位", "5个单位", "7个单位", "2个单位"], "q": "在光照下测得某叶片单位时间O2释放量为5个单位，黑暗中O2吸收量为2个单位，则该叶片总光合速率相当于O2产生量（ ）", "why": "总光合等于净光合加呼吸，5加2等于7，选C。光下释放的是净值，必须补上呼吸消耗的部分。"}, {"ans": 1, "opts": ["光合作用完全停止的点", "光合速率等于呼吸速率，净光合为零的点", "光合速率达到最大的点", "呼吸作用停止的点"], "q": "光补偿点的含义是（ ）", "why": "补偿点时总光合等于呼吸，有机物不增不减，净光合为零，选B。速率最大的转折是光饱和点。"}], "case": {"a": "(1)上午光照充足，植物光合速率大于呼吸速率，从罩内净吸收CO2，所以CO2浓度持续下降。(2)CO2浓度趋于平稳，说明植物吸收的CO2与呼吸释放的CO2相等，总光合速率等于呼吸速率，净光合速率为零。(3)会上升。此时限制光合的主要因素是罩内过低的CO2浓度，通入新鲜空气提高了CO2浓度，暗反应加快，光合速率随之提高。", "hints": ["罩内CO2变化反映的是净光合", "CO2降到很低时，它本身就成了限制因素"], "q": "将一盆长势良好的植物放在密闭玻璃罩内，给予充足光照，连续测定罩内CO2浓度。结果：上午CO2浓度持续下降，中午前后降到最低并趋于平稳，下午又缓慢变化。请回答：(1)上午CO2下降的原因是什么？(2)中午前后CO2浓度趋于平稳时，植物的光合速率与呼吸速率是什么关系？(3)若此时打开玻璃罩通入新鲜空气，短时间内光合速率会如何变化？为什么？", "steps": ["第一步：上午光合大于呼吸，植物净吸收CO2，罩内浓度下降。", "第二步：浓度平稳说明吸收与释放相等，总光合等于呼吸，净光合为零，到达CO2补偿状态。", "第三步：通入新鲜空气提高了CO2浓度，解除限制，光合速率短时间内上升。"], "talk": ["罩内气体题只抓一个词：变化量等于净光合，浓度不变就是光合呼吸打平了。"], "title": "案例：一盆植物在密闭玻璃罩里的一天"}, "intro": "最后一节讲怎么量光合、什么因素管着它，曲线题占一半分。先分清两个速率：你测到的永远是**表观光合速率**（净光合），真正的总光合藏在里面。==真正光合速率等于表观光合速率加呼吸速率。==\n曲线题不难，难在拐点：==拐点之前限制因素是横轴本身，拐点之后横轴不再是限制因素，要换别的因素想。== 把这句话练熟，本节的图题就通了大半。", "learn": [{"h": "光合强度怎么表示，总净怎么换算", "p": "**光合作用强度**可以用单位时间内**O2释放量**、**CO2吸收量**或**有机物积累量**来表示，但从气体交换测到的都是**净光合**（表观光合），因为细胞同时在呼吸消耗O2、释放CO2。关系式：**总光合等于净光合加呼吸**。黑暗中测到的O2吸收量或CO2释放量就是呼吸速率。做题时看到容器里气体变化，先问自己这是净值还是总值：==光下测到的气体变化是净光合，黑暗中测到的气体变化是呼吸速率，两者相加才是总光合。== 这是计算题的第一道关。"}, {"h": "四大因素曲线逐个过", "p": "**光照强度**：光强为零时只有呼吸，曲线从负值出发；随光强增大，净光合上升，过**光补偿点**（净光合为零、总光合等于呼吸）后开始积累有机物；到**光饱和点**后曲线走平，再加光也不涨，此时限制因素变成CO2浓度或温度。**阴生植物**的补偿点和饱和点都比阳生植物低，曲线整体靠左。**CO2浓度**：曲线形状和光强类似，太低时光合受限，升高到饱和后走平。**温度**：主要通过影响**酶活性**影响光合，先升后降，有最适温度。**水分和矿质元素**：缺水气孔关闭、CO2进不来；缺镁影响叶绿素合成，缺氮磷钾影响酶和ATP等物质合成，都会拉低光合。"}, {"h": "探究实验：沉水叶片为什么会上浮", "p": "用打孔器取圆形小叶片，**抽气**让叶片里的气体排出、充满水，叶片就沉到水底。光照下叶片光合作用产生O2，气体攒多了叶片浮力增大就**上浮**。用**台灯与烧杯的距离**控制光照强度（距离越近光越强），用**NaHCO3溶液**提供CO2并维持浓度稳定。记录单位时间内上浮的叶片数，或全部上浮所需时间，比较光合强度。==叶片上浮靠的是光合放出的氧气，测的是净光合：只有净光合为正、放氧多于耗氧，叶片才会上浮。== 实验前抽气这一步不能省，叶片里原有气体不排掉，一开始就浮着，实验没法做。"}, {"h": "农业应用和曲线判读方法", "p": "应用全是原理的翻译：**合理密植**让叶片受光均匀又不互相遮挡；大棚**增施CO2**（如施有机肥靠微生物分解放CO2）提高光合；**正其行，通其风**保证CO2流通供应；温室**补光**延长光照并增强光强；昼夜温差大时白天光合强、夜里呼吸弱，积累多。曲线判读固定三步：==第一步看横轴是什么自变量、纵轴是净光合还是总光合；第二步找拐点，明确补偿点和饱和点的含义；第三步在饱和段想限制因素转换，答案往往是CO2浓度、温度等其他因素。=="}], "pitfalls": ["把光下测到的O2释放量当成总光合——那是净光合，总光合要再加上呼吸消耗的O2。", "认为光饱和点之后光合不再受任何因素影响——只是不受光强影响了，CO2浓度和温度仍是限制因素。", "把光补偿点说成光合为零——补偿点时总光合等于呼吸，净光合为零，光合作用本身并不为零。", "沉水叶片实验忘了抽气的目的——抽气是排出叶片组织间隙的气体使叶片下沉，不是杀死叶片细胞。"]}, "video": {"bvid": "BV1p54y177e6", "p": 45, "t": "光合作用与能量转化（二）", "dur": "122:15", "from": "锦城大同教育·杨波生物", "vtop": ["光合作用释放的氧气全部来自水，不是来自二氧化碳——1941 年鲁宾和卡门用同位素标记实验证明的。", "光反应在类囊体薄膜上进行，暗反应在叶绿体基质中进行；光反应为暗反应提供 ATP 和 NADPH，暗反应为光反应提供 ADP、Pi 和 NADP⁺，两者不能长期独立进行。", "真正光合速率等于净光合速率加呼吸速率；氧气的产生量、二氧化碳的固定量、葡萄糖的生成量表示总光合，释放量、吸收量、积累量表示净光合。"], "vsum": "本课是光合作用的第二讲，分两集：第一集讲光合作用的原理与过程，第二集讲光合作用强度和影响它的因素。先复习概念：**光合作用**是指绿色植物通过**叶绿体**，利用光能将**二氧化碳**和**水**转化成储存着能量的**有机物**，并且释放出**氧气**的过程，产物有机物主要就是**糖类**。反应式要会写两条：一般形式是二氧化碳加水生成糖类加氧气；算葡萄糖时用 6CO₂＋12H₂O→C₆H₁₂O₆＋6H₂O＋6O₂。注意光合作用既消耗水又生成水，但消耗的水比生成的水多，所以教材的反应式把产物里的水省掉了。光合作用的反应式和有氧呼吸的反应式刚好互为倒置：光合作用的反应物就是有氧呼吸的产物，产物就是有氧呼吸的反应物，记住有氧呼吸的反应式就能倒过来写出光合作用的反应式。接下来是探索光合作用原理的实验。19 世纪末科学界普遍认为二氧化碳的碳和氧被分开，氧释放成氧气，碳和水结合成甲醛再缩合成糖；到了 1928 年发现甲醛对植物有毒害、也不能通过光合作用转化成糖，这个观点被否定了。1937 年英国科学家**希尔**做实验：在离体的叶绿体悬浮液中加入铁盐或其他氧化剂，发现水的光解能产生氧气。1941 年美国科学家**鲁宾和卡门**用**同位素标记**法：第一组用 ¹⁸O 标记水、给正常二氧化碳，植物释放的氧气含 ¹⁸O；第二组用 ¹⁸O 标记二氧化碳、给正常水，释放的氧气不含 ¹⁸O，两组对比得出结论——光合作用释放的氧气**全部来自水**。1954 年美国科学家**阿尔农**发现，在光照下叶绿体可以合成 **ATP**，这一过程总与水的光解相伴随。两道思考题要会答：希尔的实验能不能说明氧气中的氧全部来自水？不能，它只说明离体叶绿体在适当条件下能发生水的光解释放氧气，没有排除悬浮液里其他含氧物质的干扰。希尔的实验能不能说明水的光解与糖的合成不是同一个反应？能，因为合成糖需要二氧化碳提供碳，而水的光解悬浮液里没有二氧化碳，所以水光解时没有发生糖的合成。光合作用的过程分两个阶段。**光反应阶段**必须有光照才能进行，场所是**类囊体薄膜**，因为光合色素和有关酶分布在类囊体薄膜上。光反应有三个主要反应：第一，**水的光解**——光合色素吸收光能后夺取水分子中氧元素的电子，水被分解成氧气和氢离子；第二，ADP 加 Pi 再加上光能合成 **ATP**，注意合成 ATP 这一步会生成水；第三，NADP⁺ 加氢离子生成 **NADPH**，中文名**还原型辅酶Ⅱ**，和细胞呼吸里的还原型辅酶Ⅰ（NADH）是两种不同的物质，但都可以简写为 [H]。光能的去路有三条：分解水，转化成 ATP 里活跃的化学能，储存在 NADPH 的化学能里。**暗反应阶段**不需要光照，有光没光都能进行，场所是**叶绿体基质**，因为与暗反应有关的酶分布在叶绿体基质里。暗反应是一个循环过程，由卡尔文发现，又叫**卡尔文循环**。第一步是**二氧化碳的固定**：**C₅**（五碳化合物）加一分子二氧化碳生成两分子 **C₃**（三碳化合物），这一步也有水分子参与，数量关系可以用元素守恒自己推——5 个碳加 1 个碳等于 6 个碳，所以要生成两个三碳化合物。第二步是**三碳化合物的还原**：C₃ 在 ATP 提供能量、NADPH 提供能量和氢的作用下被还原，一部分还原成糖类等有机物，另一部分还原成 C₅，维持循环。还原出来的糖类一部分在细胞质中转化成**蔗糖**，另一部分在叶绿体中形成**淀粉**暂时储存，需要时再分解成葡萄糖进入细胞质。能量变化是 ATP 和 NADPH 里**活跃的化学能**转化成有机物里**稳定的化学能**。光反应和暗反应相互影响、相互制约：光反应为暗反应提供 ATP 和 NADPH，暗反应为光反应提供 ADP、Pi 和 **NADP⁺**，两者都不能长期独立进行。易错提醒四则：①植物在夜晚不能进行光反应，也不能长期进行暗反应，因为暗反应需要光反应提供物质和能量；②ATP 的移动方向是从叶绿体基质到类囊体薄膜（在基质中生成 ADP，在类囊体薄膜上消耗 ADP 合成 ATP）；③光合作用产生的 ATP 只能用于暗反应，不能为细胞内其他生命活动提供能量；④用 ¹⁴C 标记二氧化碳追踪碳的转移途径是二氧化碳→三碳化合物→糖类和五碳化合物。含量变化题是常考题型，只问短时间内怎么变，分析时从生成和消耗两个方面综合判断：光照由强到弱、二氧化碳供应不变时，ATP 和 NADPH 生成减少，三碳化合物的还原减慢，所以 C₃ 增多、C₅ 减少、有机物合成减少；二氧化碳供应由充足到不足、光照不变时，二氧化碳固定减慢，C₃ 生成减少、C₃ 减少、C₅ 增多、ATP 和 NADPH 因为消耗减少而积累升高；反过来光照由弱变强、或二氧化碳由不足变充足时，结论刚好相反。教材练习题要点：光合作用生成葡萄糖的反应式里，氧气中的氧全部来自水（12 个水中的氧），二氧化碳里的氧进入葡萄糖和水；暗反应不是只能在黑暗中进行，有光无光都能进行；叶绿体不同于线粒体的特点是能分解水产生氧气和氢离子；叶绿体基质只能进行暗反应、消耗 ATP，不能合成 ATP，所以不能合成 ATP 的场所是叶绿体基质。第二集先讲**光合作用强度**，指植物在单位时间内通过光合作用制造糖类的数量，也就是**光合速率**。影响因素有外部因素和内部因素：外部因素有土壤水分、二氧化碳浓度、温度、光照时间长短、光照强度、光的成分等，内部因素有叶片成熟程度、叶龄、植物种类等。衡量光合速率的指标不唯一：可以从原料消耗量衡量，比如单位时间内二氧化碳的消耗量；也可以从产物生成量衡量，比如单位时间内有机物的生成量、氧气的生成量。但叶片质量的增加量（有机物积累量）不能直接衡量光合速率，因为有光时植物既进行光合作用又进行细胞呼吸，测到的增加量是光合作用与呼吸作用的差值，这个差值就叫**净光合速率**，也叫**表观光合速率**：净光合速率＝实际光合速率－呼吸速率，所以**真正光合速率＝净光合速率＋呼吸速率**，真正光合速率也叫实际光合速率或总光合速率。黑暗条件下植物只能进行呼吸作用，所以黑暗条件下测得的数值表示呼吸速率，比如二氧化碳释放量或氧气吸收量。总光合速率和净光合速率的表示要分清：用氧气表示时，氧气的**产生量**是总光合速率，氧气的**释放量**是净光合速率；用二氧化碳表示时，二氧化碳的**固定量**或**消耗量**是总光合速率，二氧化碳的**吸收量**是净光合速率；用葡萄糖表示时，葡萄糖的**生成量**是总光合速率，葡萄糖的**积累量**是净光合速率。教材实验探究环境因素对光合作用强度的影响：用直径 0.6 厘米的打孔器打出圆形小叶片 30 片，尽量避开叶脉；抽气排出叶片细胞间隙的空气，叶片下沉后放入黑暗处盛有清水的烧杯中待用；分组倒入等量富含二氧化碳的清水，可以往清水里吹气，也可以用质量分数 1% 到 2% 的**碳酸氢钠溶液**；给予强、中、弱三种光照，可以用三种不同功率的灯泡；记录同一时间段内各装置中圆形小叶片浮起的数量，光合速率越大、产生氧气越多越快，上浮的叶片就越多。接着讲**化能合成作用**：硝化细菌把氨氧化成亚硝酸、再把亚硝酸氧化成硝酸，释放的化学能把二氧化碳和水合成糖类；硫细菌把硫化氢氧化成硫酸盐，氢细菌把氢气氧化成水，铁细菌氧化铁，这些细菌都属于**自养生物**。自养生物分两类：利用光能把无机物转变成有机物的叫光能自养生物，利用化学能的叫化能自养生物；能进行光合作用的生物是自养生物，但自养生物不都是利用光能的。影响因素第一个是**光照强度**：光是光合作用的能量来源，直接影响光反应阶段，制约 ATP 和 NADPH 的生成。在光照强度—二氧化碳吸收量曲线上，A 点光照强度为零，植物只进行呼吸作用，OA 段表示呼吸速率；AB 段呼吸速率大于光合速率，二氧化碳仍释放到外界；B 点光合速率等于呼吸速率，细胞与外界没有气体交换，B 点对应的光照强度叫**光补偿点**；光照强度继续增大，光合速率加快到一定程度后不再加快，对应最大光合速率的最小光照强度叫**光饱和点**，注意光饱和点不是曲线最高点 C 点；光照过强时光合速率甚至会下降，因为强光会灼伤细胞。把横坐标下移，曲线就表示总光合速率。阴生植物的光补偿点和光饱和点都比阳生植物低，所以间作套种时要搭配种类，让阳生植物利用大部分光能，透过的少量光能刚好被中间的阴生植物利用；阴雨天适当补充光照、及时给大棚除霜除雾都能提高产量。第二个是**二氧化碳浓度**：二氧化碳是光合作用的原料，经叶片表面的气孔进入叶肉细胞的叶绿体。在一定范围内光合速率随二氧化碳浓度增加而加快；光合速率等于呼吸速率时对应的二氧化碳浓度叫**二氧化碳补偿点**，达到最大光合速率时对应的最小二氧化碳浓度叫**二氧化碳饱和点**。C₃ 植物的曲线不从原点开始，必须二氧化碳浓度达到一定值才能进行光合作用；C₄ 植物能利用低浓度的二氧化碳，曲线从原点开始，高中不要求掌握两者的区分。农业上合理密植、通风能增大二氧化碳浓度，增施农家肥也能间接增大二氧化碳浓度，因为土壤里的微生物分解农家肥里的有机物会释放二氧化碳。第三个是**温度**：温度主要通过影响酶的活性来影响光合速率，主要是影响暗反应阶段的酶，温度还会影响气孔的开闭。一般植物光合作用的最适温度是 25 摄氏度，这节课图里的植物最适温度在 32 到 33 摄氏度。冬季温室栽培白天适当提高温度、晚上适当降低温度，可以减少呼吸作用消耗的有机物；新疆的瓜果特别甜，就是因为昼夜温差大，白天温度高、光合作用强、生成大量有机物，晚上温度低、呼吸作用弱、消耗的有机物少，有机物积累得多。第四个是**水分**：水既是光合作用的原料，又是体内各种化学反应的介质，还能影响气孔开闭。气孔由两个保卫细胞构成，保卫细胞失水皱缩时气孔关闭，吸水膨胀时气孔开放，因为保卫细胞外侧壁薄、吸水后向外侧膨胀，把内侧壁拉开，气孔就打开了。植物一天的光合速率曲线：凌晨到早上四五点只有呼吸作用、释放二氧化碳，日出后光合速率逐渐加快，中午两点左右出现一个下降，这就是**光合午休现象**——中午温度过高、蒸腾作用过强，植物为减少水分散失关闭气孔，吸收的二氧化碳减少，光合速率暂时降低。最后是**光质**：在可见光范围内，不同波长的光下光合作用效率不同，红光和蓝紫光下光合作用强度较大，绿光下最弱；叶绿素主要吸收红光和蓝光，类胡萝卜素主要吸收蓝紫光。大棚的塑料薄膜要选无色的，因为太阳光是复合光、功率相同，红色薄膜只透过红光、其他色光都被吸收掉了，利用到的光反而更少；人工补光时功率相同，补红光和蓝光最好。", "vtech": [["氧气来源看标记实验", "希尔 1937 年离体叶绿体加铁盐实验只能说明水光解产生氧气，不能证明氧全来自水；鲁宾和卡门 1941 年用 ¹⁸O 分别标记水和二氧化碳，证明释放的氧气全部来自水；1954 年阿尔农发现光照下叶绿体合成 ATP 总与水的光解相伴随。"], ["光暗反应分工与互供", "光反应在类囊体薄膜：水光解产生 O₂ 和 H⁺，ADP＋Pi 合成 ATP，NADP⁺ 生成 NADPH（还原型辅酶Ⅱ）；暗反应在叶绿体基质：C₅＋CO₂ 生成 2C₃，C₃ 还原成糖类和 C₅；光反应产生的 ATP 只能用于暗反应，不能用于其他生命活动。"], ["含量变化题只看短时间、两头分析", "光照或 CO₂ 改变时，C₃、C₅、ATP、NADPH 的含量变化只分析短时间，从生成和消耗两个方面综合判断：光照由强变弱、CO₂ 不变时 C₃ 增多、C₅ 减少；CO₂ 由充足变不足、光照不变时 C₃ 减少、C₅ 增多、ATP 和 NADPH 积累升高。"], ["补偿点与饱和点别认错点", "光补偿点是光合速率等于呼吸速率时对应的光照强度（B 点），光饱和点是达到最大光合速率时对应的最小光照强度（不是曲线最高点 C 点）；阴生植物的光补偿点和光饱和点都比阳生植物低；二氧化碳补偿点和饱和点同理，C₃ 植物曲线不从原点开始，C₄ 植物能利用低浓度二氧化碳。"]], "vgaokao": []}}, "bio_b024": {"name": "有丝分裂的过程", "sec": 24, "secTitle": "细胞的增殖", "page": 110, "desc": "细胞周期；四期特征口诀；染色体、DNA、染色单体数量变化；动植物有丝分裂区别。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b013"], "next": ["bio_b025", "bio_b026"], "content": {"advance": {"a": "中期时每条染色体的着丝粒排列在赤道板上，染色体高度螺旋化，形态稳定、轮廓和数目最清晰，便于观察和计数，故为最佳时期。细胞不能无限长大有两个原因：一是相对表面积限制，细胞体积越大，相对表面积（表面积与体积之比）越小，细胞与外界物质交换的效率越低，难以满足生命活动需要；二是核质比限制，细胞核所能控制的细胞质范围有限，细胞过大时细胞核负担过重。因此细胞生长到一定大小就会分裂或停止生长。", "kind": "self", "q": "为什么说中期是观察染色体形态和数目的最佳时期？细胞不能无限长大的原因又是什么？请分别说明。"}, "apply": [{"ans": 0, "opts": ["16条、8条", "8条、8条", "16条、16条", "8条、4条"], "q": "某二倍体生物体细胞染色体数为8条。该细胞有丝分裂后期和末期结束时，每个子细胞的染色体数分别是（ ）", "why": "后期着丝粒分裂，染色体暂时加倍为16条；末期细胞一分为二，每个子细胞恢复为8条，与亲代相同。"}, {"ans": 2, "opts": ["动物细胞纺锤体由细胞两极直接发出纺锤丝形成", "植物细胞末期靠细胞膜内凹缢裂分成两个细胞", "动物细胞有中心体，末期细胞膜内凹缢裂", "两者的染色体行为变化完全不同"], "q": "下列关于动植物细胞有丝分裂的叙述，正确的是（ ）", "why": "动物细胞由中心体形成纺锤体，末期细胞膜内凹缢裂；植物细胞由两极发出纺锤丝形成纺锤体，末期形成细胞板。两者的染色体行为基本一致。"}, {"ans": 3, "opts": ["分裂前期", "分裂中期", "分裂后期", "分裂末期结束形成的子细胞"], "q": "将体细胞置于培养液中连续观察，测得一个细胞周期内DNA含量变化为2n→4n→2n。DNA含量为4n的阶段不包括（ ）", "why": "S期复制完成后到末期结束前，DNA始终是4n，包括前期、中期、后期；子细胞形成后DNA已均分，恢复为2n。"}], "basics": [{"ans": 1, "opts": ["G1期", "S期", "G2期", "分裂期"], "q": "在细胞周期中，DNA分子复制主要发生在（ ）", "why": "分裂间期分G1、S、G2三期：G1和G2主要合成蛋白质，只有S期进行DNA复制，这是数量变化题的起点。"}, {"ans": 1, "opts": ["核膜、核仁逐渐消失", "着丝粒分裂，染色体数目加倍", "染色体的着丝粒排列在赤道板上", "赤道板位置形成细胞板"], "q": "有丝分裂后期最主要的特点是（ ）", "why": "后期着丝粒分裂，姐妹染色单体分开成为独立染色体并移向两极，染色体数目加倍。A是前期，C是中期，D是植物细胞末期。"}], "case": {"a": "（1）有丝分裂后期。依据：着丝粒分裂后染色体数目加倍为12条，且分开的染色体在纺锤丝牵引下移向细胞两极。（2）子细胞中染色体为6条、DNA为6个，与亲代细胞相同，保证了遗传性状的稳定传递。", "hints": ["先看染色体数：12条是正常6条的2倍，什么事件能让染色体翻倍？", "再看DNA数没跟着翻倍，说明复制早就完成了，现在动的是着丝粒。"], "q": "某植物体细胞染色体数为2n=6。观察其根尖细胞有丝分裂装片，看到一个细胞内有12条染色体、12个DNA分子，且染色体正被纺锤丝牵引移向两极。问：（1）该细胞处于什么时期？判断依据是什么？（2）该细胞分裂结束形成的子细胞中染色体和DNA各是多少？", "steps": ["染色体数由6变为12，说明着丝粒已经分裂，姐妹染色单体已分开成为独立染色体", "染色体正移向两极，符合后期的动态特征，故为有丝分裂后期", "后期只是暂时加倍，末期均分后子细胞恢复亲代水平"], "talk": ["看到染色体翻倍先想后期，看到DNA翻倍先想S期。"], "title": "案例：数一数各时期的染色体和DNA"}, "intro": "真核细胞最主要的增殖方式就是**有丝分裂**，考试考的就是这一套：一会儿让你认图判断时期，一会儿让你数**DNA**、**染色体**和**染色单体**，每年都换着花样考，但翻来覆去就那几个点。先把大框架记住：==连续分裂的细胞，从一次分裂完成时开始，到下一次分裂完成时为止，是一个细胞周期==，它包括**分裂间期**和**分裂期**两段，间期长、分裂期短，千万别画反。\n\n间期不是休息，是在干活备料：**G1期**合成蛋白质，**S期**完成**DNA复制**，**G2期**再合成蛋白质。==分裂间期约占细胞周期的90%—95%，所以显微镜下看到的大多数细胞都处在间期==。把四期特征、数量变化和动植物区别这三块吃透，这一节的分就稳了。", "learn": [{"h": "有丝分裂四期特征：记口诀，看标志", "p": "**前期**记住一句口诀——**膜仁消失显两体**：**染色质**高度螺旋化变成**染色体**，**核膜**、**核仁**逐渐消失，细胞两极发出纺锤丝形成**纺锤体**。染色体散乱分布在纺锤体中央，每条染色体由两条**姐妹染色单体**组成，共用一个**着丝粒**。\n\n**中期**最好认：每条染色体的**着丝粒**都排列在细胞中央的一个平面上，这个平面叫**赤道板**。注意赤道板不是真实结构，是假想的平面。==中期染色体形态稳定、数目清晰，是观察和计数染色体的最佳时期==。\n\n**后期**只抓一个动作：**着丝粒分裂**，姐妹染色单体分开成为两条独立的染色体，在纺锤丝牵引下移向细胞两极。==着丝粒一分裂，染色体数目立刻加倍==，细胞两极各有一套与亲代完全相同的染色体。\n\n**末期**跟前期正好相反，口诀是**两消两现重开始**：染色体变成染色质，纺锤体消失，**核膜、核仁重新出现**，最后细胞质分裂，变成两个子细胞。"}, {"h": "数量变化规律：抓住复制和着丝粒分裂两个节点", "p": "数量变化题别死记表格，盯住两个关键事件就行。第一个事件是**S期DNA复制**：==DNA复制只让DNA数目加倍，不让染色体数目加倍，但染色单体从无到有==。比如原来2n条染色体、2n个DNA，复制后还是2n条染色体，但变成4n个DNA、4n条染色单体，因为每条染色体都带了两条姐妹染色单体。\n\n第二个事件是**后期着丝粒分裂**：==着丝粒分裂，染色单体消失，染色体数目加倍==。原来2n条染色体，后期暂时变成4n条，DNA数目不变，还是4n个。\n\n到了**末期**，细胞一分为二，每个子细胞又恢复到2n条染色体、2n个DNA、0条染色单体。一句话捋顺：间期复制后DNA是4n、染色体是2n；后期染色体追上来到4n；末期两个数一起回到2n。做题时先定时期，再套这个规律，就不会乱。"}, {"h": "动植物有丝分裂的区别：只比两个地方", "p": "动物细胞和高等植物细胞的有丝分裂，过程大同小异，考试爱考的只有两处不同。第一处在**前期**，看**纺锤体的来源**：动物细胞有**中心体**，由中心体发出的星射线形成纺锤体；高等植物细胞没有中心体，由==细胞两极直接发出纺锤丝形成纺锤体==。\n\n第二处在**末期**，看**细胞质怎么分开**：植物细胞在赤道板的位置出现**细胞板**，细胞板向四周扩展形成新的**细胞壁**，把细胞分成两个；动物细胞没有细胞壁，是**细胞膜从中部向内凹陷**，最后缢裂成两个子细胞。\n\n注意低等植物细胞比较特殊，它既有中心体又有细胞壁，两套特点都占，别一棍子打死。"}, {"h": "有丝分裂的意义、无丝分裂和细胞不能无限长大", "p": "有丝分裂为什么重要？因为它把亲代细胞的染色体精确复制，再平均分给两个子细胞。==有丝分裂保证了亲代和子代细胞之间遗传性状的稳定性==，这对生物遗传至关重要。说白了，子细胞的**DNA**跟亲代一模一样，靠的就是这套复制加均分。\n\n还有一种简单的分裂叫**无丝分裂**：分裂时没有**纺锤体**和**染色体**的出现，核先延长再缢裂，比如**蛙的红细胞**的分裂。注意哺乳动物成熟红细胞连细胞核都没有，那是另一回事，别混。\n\n细胞为什么不能无限长大？两个原因：一是**相对表面积**限制，==细胞体积越大，相对表面积越小，物质运输效率越低==，养不活自己；二是**核质比**限制，细胞核的控制范围有限，细胞太大了核管不过来。所以细胞越小，相对表面积越大，运输效率越高，这也是生物多由小细胞组成的原因。"}], "pitfalls": ["赤道板不是真实存在的结构，只是一个假想平面；细胞板才是真实结构，出现在植物细胞末期，两者别混。", "DNA复制后染色体数目不加倍，着丝粒分裂后DNA数目不加倍。加倍要看清问的是谁：DNA加倍在S期，染色体加倍在后期。", "染色单体只在复制后到着丝粒分裂前存在。前期、中期有单体，后期和末期没有单体，别数错。", "细胞周期只适用于连续分裂的细胞。已高度分化的细胞、减数分裂的细胞都没有细胞周期；且必须从分裂完成时算起，间期在前、分裂期在后。"]}, "video": {"bvid": "BV1p54y177e6", "p": 51, "t": "细胞的增殖", "dur": "124:51", "from": "锦城大同教育·杨波生物", "vtop": ["细胞周期只属于连续分裂的细胞：从一次分裂完成到下一次分裂完成为止，间期长、分裂期短，间期里完成 DNA 复制和有关蛋白质合成。", "有丝分裂认时期抓标志：中期着丝点排在赤道板上、形态固定数目清晰；后期着丝点分裂、染色单体消失、染色体数暂时加倍。", "数曲线只看核 DNA：核 DNA 2N→4N→2N，染色体数后期才加倍，染色单体只在前中期有，1:2:2 只在有染色单体时成立。"], "vsum": "本课讲第六章第一节，讲**细胞的增殖**，分两讲。第一讲开场先算一道题：象和鼠个体大小相差悬殊，细胞大小差多少？动物细胞直径一般 20–30 微米，取小鼠 20 微米、大象 30 微米，直径比 2:3，用球体体积公式算体积比是 8:27——个体大小的差异主要来自**细胞数量**的多少，不是细胞大小。一个受精卵变成多细胞个体，细胞数量增多靠**细胞增殖**，种类增多靠**细胞分化**（第六章第二节再讲）。第一个重点是**细胞增殖**与**细胞周期**：细胞增殖是细胞通过分裂增加细胞数量的过程，常和细胞分裂同义；细胞周期是从一次分裂完成开始，到下一次分裂完成为止，只有**连续分裂的细胞**才有，比如受精卵、根尖分生区细胞、茎的形成层细胞、皮肤生发层细胞和各种干细胞。一次细胞周期分**分裂间期**和**分裂期**：间期做物质准备，处在两次分裂之间，所以叫间期；间期占大头——蚕豆根尖分生区细胞周期 17.3 小时、间期 15.3 小时，小鼠十二指肠上皮细胞周期 15.3 小时、间期 13.5 小时；不同细胞周期长短不同，即使同一个体也一般不同，人肝细胞和宫颈癌细胞周期都是 22 小时，间期时长却不一样。第二个重点是**有丝分裂**，分前、中、后、末四个时期，是人为划分的。分裂间期主要进行 **DNA 的复制和有关蛋白质的合成**。前期：细丝状的**染色质**螺旋缠绕变成短棒状的**染色体**，细胞两极发出**纺锤丝**（蛋白质）形成纺锤体，核膜、核仁消失；染色质和染色体是同一种物质，只是形态不同，数染色体只数数量、不看形状。中期：染色体进一步螺旋、缩短变粗，形态比较固定、数目比较清晰，**着丝点**整齐排列在**赤道板**上，是观察染色体形态和数目的最佳时期。后期：**着丝点分裂**，姐妹染色单体分开变成两条染色体，分别移向细胞两极，染色单体消失，染色体数目暂时加倍。末期：染色体变回染色质，纺锤体消失，核膜、核仁重现；植物细胞在赤道板位置出现**细胞板**，向四周扩展成新的细胞壁；染色体、纺锤体出现与核膜、核仁消失，前期和末期刚好相反。间期还能细分为 **G1 期**（DNA 合成前期，合成蛋白质）、**S 期**（DNA 合成期）、**G2 期**（DNA 合成后期），有丝分裂期又叫 **M 期**。第三个重点是**动物细胞**的有丝分裂，和植物大体相同，不同有三处：间期**中心体**由一组倍增为两组；前期中心体移向两极、发出**星射线**形成纺锤体，不是两极发纺锤丝；末期没有细胞板，靠细胞膜从中部向内凹陷、形成收缩环把细胞**缢裂**成两个——答题写“缢裂”不写“分裂”。问与动物细胞有丝分裂有关的细胞器，要加上中心体、去掉高尔基体（高尔基体与细胞壁形成有关，动物细胞没有细胞壁）。**有丝分裂的意义**有两点：第一，把亲代细胞的染色体经过复制（关键是染色体内 DNA 的复制）后**精确地平均分配**到两个子细胞中——平均分配的只是细胞核内的 DNA，细胞质 DNA 是随机分配的，细胞器也随机分配，只有中心体例外、是平均分配的；第二，染色体上有遗传物质 DNA，这样就在亲代和子代之间保持了**遗传的稳定性**。**癌细胞**是遗传物质发生改变、不受机体控制、能连续分裂的恶性增殖细胞。最后一个知识点是**无丝分裂**：过程是核延长→核缢裂→细胞质缢裂，同样先进行 DNA 复制，子细胞的遗传物质和亲代一样；特点是分裂过程没有出现纺锤丝和染色体的变化，速度比较快；蛙的红细胞能进行无丝分裂，低等植物中普遍存在，高等植物的胚乳细胞、薄壁细胞、表皮细胞、根冠细胞和动物的某些腺体细胞也能进行。易错提醒：蛙生长发育过程中体细胞增殖仅靠有丝分裂——错，还要靠无丝分裂。第二讲先问细胞为什么不能无限长大。原因一是细胞大小影响**物质运输效率**：用边长 2、4、8 毫米的正方体模拟细胞，表面积分别是 24、96、384，体积分别是 8、64、512，相对表面积从 3 降到 1.5 再到 0.75；把三个模型放进葡萄糖溶液相同时间、假设扩散深度都是 0.5 毫米，葡萄糖扩散的体积占总体积分别是 7/8、37/64、169/512，细胞越大、表面积与体积之比越小，运输效率越低。原因二是**细胞核是细胞的控制中心**，细胞太大、细胞核的控制作用就有限，就像一个班主任管 50 个学生还行、管 200 个就管不过来。接着做教材实验**观察根尖分生区组织细胞的有丝分裂**：原理是根尖分生区细胞能连续分裂、有细胞周期；高倍显微镜下根据染色体的存在状态判断所处时期；染色体容易被碱性染料着色。步骤是解离→漂洗→染色→制片：解离液是质量分数 15% 的盐酸和体积分数 95% 的酒精按 1:1 混合，3–5 分钟，目的是使组织中的细胞相互分离开来，细胞在解离时已经死亡，解离到根尖酥软、镊子一碾就散即可，解离过度会妨碍染色；漂洗用清水、10 分钟以上，洗去多余解离液；染色用质量浓度 0.01 或 0.02 g/mL 的龙胆紫溶液（龙胆紫溶于质量分数 2% 的醋酸配成）或醋酸洋红液，3–5 分钟；制片是取根尖放载玻片上、加一滴清水、用镊子弄碎、盖上盖玻片、拇指轻压使细胞分散开。观察时先低倍镜找到分生区细胞，再换高倍镜辨认各时期，视野里处于分裂间期的细胞数量最多。最后看三条数量曲线：细胞核内 DNA 数在间期从 2N 复制到 4N，复制发生在 S 期，画图时前面要留一段平的 G1 期、后面留 G2 期，末期一分为二又回到 2N；**染色单体**数只有 0 和 4N 两个值，S 期出现、后期着丝点分裂时归 0；**染色体**数只有 2N 和 4N，后期加倍、末期减半；每条染色体上的 DNA 含量在 S 期从 1 条变 2 条，后期开始又从 2 条变回 1 条。有染色单体时（前期、中期）染色体数:染色单体数:核 DNA 数 = 1:2:2，没有染色单体时（后期、末期）染色体数:核 DNA 数 = 1:1。教材习题：洋葱根尖细胞有 16 条染色体，“分裂期细胞数量较多”是错的，间期细胞才多；“间期染色体复制后为 32 条”也是错的，间期染色体数不加倍，加倍只在后期。", "vtech": [["细胞周期先问“连续分裂”", "看到细胞周期题 → 先问是不是连续分裂的细胞：受精卵、根尖分生区、茎形成层、皮肤生发层、干细胞才有；不同细胞周期长短不同，同一体也不一样——人肝细胞和宫颈癌细胞都是 22 小时，间期时长却不同。"], ["前中后末抓标志性变化", "前期染色质螺旋成染色体、纺锤体出现、核膜核仁消失；中期着丝点排赤道板、形态固定数目清晰，是看染色体最好的时期；后期着丝点分裂、染色单体消失、染色体数加倍；末期核膜核仁重现，植物出现细胞板，动物细胞膜向内凹陷缢裂。"], ["动物细胞三处不同记时期", "间期中心体由一组倍增为两组；前期中心体移向两极发出星射线形成纺锤体，不是两极发纺锤丝；末期没有细胞板，靠细胞膜向内凹陷、收缩环缢裂成两个细胞；问有关细胞器要加上中心体、去掉高尔基体。"], ["曲线题先定 2N、4N、0 三个数", "核 DNA：间期 2N→S 期复制→4N，末期一分为二回 2N；染色单体只有 0 和 4N 两个值，S 期出现、后期着丝点分裂时归 0；染色体数只有 2N 和 4N，后期加倍、末期减半；有染色单体时染色体:染色单体:核 DNA = 1:2:2，无染色单体时是 1:1。"]], "vgaokao": []}}, "bio_b025": {"name": "观察根尖分生区组织细胞的有丝分裂", "sec": 25, "secTitle": "细胞的增殖", "page": 116, "desc": "解离、漂洗、染色、制片四步；分生区细胞特征；间期细胞为何最多。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b024"], "next": [], "content": {"advance": {"a": "根尖分生区细胞分裂旺盛、能连续进行有丝分裂，且细胞排列紧密、呈正方形、细胞核大，容易观察到处于不同分裂时期的细胞；而伸长区和成熟区细胞已停止分裂、趋于分化，观察不到分裂期细胞。不能精确测定各时期时长：本实验中细胞已被解离液杀死，只能统计某一时刻各时期细胞的数目；各时期细胞数所占比例可大致反映各时期在细胞周期中时长的相对长短（间期细胞最多说明间期最长），但无法测得每个时期的精确时长。", "kind": "self", "q": "为什么观察有丝分裂要选用根尖分生区细胞，而不是伸长区或成熟区细胞？本实验能否用来精确测定细胞周期各时期的时长？说明理由。"}, "apply": [{"ans": 2, "opts": ["该同学统计时出现了错误", "分生区细胞基本不进行分裂", "分裂间期在细胞周期中占的时间最长", "分裂期细胞都被解离液杀死了"], "q": "某同学观察洋葱根尖装片，在视野中统计到间期细胞约占92%。这一结果最合理的解释是（ ）", "why": "间期约占细胞周期的90%—95%，任一时刻取样，绝大多数细胞都处于间期，与统计结果吻合。解离杀死的是全部细胞，不只分裂期细胞。"}, {"ans": 3, "opts": ["漂洗的目的是洗去解离液，防止解离过度并便于染色", "压片的目的是使细胞分散开来", "应先在低倍镜下找到分生区，再换高倍镜观察", "通过连续观察一个细胞，可记录它完整的分裂过程"], "q": "下列关于该实验操作的叙述，错误的是（ ）", "why": "解离时盐酸已杀死细胞，装片上是死细胞，只能观察到静态画面，不能连续观察同一个细胞的分裂全过程。"}], "basics": [{"ans": 2, "opts": ["清水", "解离液", "甲紫溶液", "体积分数为95%的酒精"], "q": "在观察根尖分生区组织细胞有丝分裂的实验中，使染色体着色的试剂是（ ）", "why": "甲紫溶液是碱性染料，能使染色体着色便于观察；解离液由盐酸和酒精混合而成，作用是使细胞分离开。"}, {"ans": 1, "opts": ["醋酸洋红，使染色体着色", "盐酸和酒精1:1混合，使组织细胞相互分离", "清水，洗去解离液", "甲紫溶液，使细胞分散"], "q": "解离液的成分和作用分别是（ ）", "why": "解离液为盐酸与酒精按1:1混合，溶解细胞间物质使细胞分离开；漂洗才用清水，染色才用甲紫溶液。"}], "case": {"a": "错误一：解离时间过短。后果是细胞间物质未充分溶解，细胞相互重叠、分散不开，视野中细胞成团看不清。错误二：未漂洗直接染色。后果是残留解离液中的盐酸影响甲紫溶液对染色体的着色，染色过浅；同时解离液继续作用还会使解离过度。规范流程应为解离→漂洗→染色→制片，四步缺一不可、顺序不可颠倒。", "hints": ["细胞重叠对应哪一步没做到位？想想解离的作用。", "染色浅又没漂洗，想想酸性解离液对碱性染料的影响。"], "q": "某同学按实验步骤制作洋葱根尖装片，显微镜下发现：细胞重叠严重、几乎看不清染色体，且染色很浅。他回忆操作时为了赶时间，根尖在解离液中只泡了1分钟，之后直接滴加甲紫溶液染色，没有漂洗。请指出他的两个错误操作，并说明各自造成的后果。", "steps": ["细胞重叠严重，说明细胞没有分离开，对应解离不充分：解离时间过短，细胞间物质未充分溶解", "染色浅，说明染色受干扰：未漂洗，残留的盐酸（酸性）妨碍碱性染料甲紫与染色体结合，且解离可能继续过度", "正确做法：解离3—5分钟至根尖酥软，清水漂洗约10分钟后再染色"], "talk": ["实验分析题先定位步骤：重叠查解离，着色查漂洗和染色。"], "title": "案例：装片看不清，问题出在哪一步"}, "intro": "这个实验是必修1少数几个必考实验之一，考的不难，就是考细节：试剂叫什么、步骤为什么这么排、先看什么后看什么。==本实验的流程是解离、漂洗、染色、制片，四步顺序不能颠倒==，颠倒了每一步都有对应的错误后果，这是出题人最爱挖的坑。\n\n还有一个高频判断：**装片中的细胞大多数处于分裂间期**。同学总以为做的是有丝分裂实验就该满眼分裂期，恰恰相反，因为间期最长。==视野里间期细胞最多，恰恰证明间期在细胞周期中占的时间最长==。把这两条主线抓住，再记清几个试剂的作用，实验题就没什么可怕的。", "learn": [{"h": "四步操作：每一步在干什么", "p": "第一步**解离**：把根尖放进**解离液**里，解离液是**盐酸和酒精按1:1混合**配成的。作用是溶解细胞之间的果胶层，==使组织中的细胞相互分离开来==，同时盐酸会杀死细胞。不解离，细胞叠在一起根本看不清。\n\n第二步**漂洗**：用**清水**漂洗约10分钟，==洗去解离液，防止解离过度，同时便于染色==。这步不能省：盐酸是酸性，会妨碍碱性染料着色，不洗干净染色效果就差。\n\n第三步**染色**：用**甲紫溶液**（就是原来常说的龙胆紫溶液）或**醋酸洋红**染色3—5分钟，作用是==使染色体着色，便于观察==。这两种染料都是碱性染料，跟染色体亲和力强。新教材统一用甲紫溶液这个名称，答题按新教材写。\n\n第四步**制片**：把根尖弄碎、盖上盖玻片，再加一片载玻片轻轻压一下，叫**压片**，目的是使细胞分散开、铺成薄薄一层。压的时候用力要均匀，别把玻片压碎。"}, {"h": "怎么在显微镜下找到分裂期细胞", "p": "观察有讲究顺序：==先用低倍镜找到分生区，再换高倍镜仔细观察==。分生区在根尖的尖端一小段，怎么认？**分生区细胞排列紧密、呈正方形、细胞核较大**，有的正在分裂；伸长区和成熟区细胞细长，不会分裂，别在那儿浪费时间。\n\n换到高倍镜后慢慢移动装片，分裂期细胞占比小，要多找几个视野。认时期还是老办法：看**染色体**行为——散乱分布是前期，排在中央是中期，分开移向两极是后期，重新成团被核膜包起来是末期。\n\n要接受一个事实：==装片中的细胞已经被盐酸杀死，观察到的是死细胞，只能看到各个时期的静态画面，看不到连续的动态分裂过程==。想看全过程，只能靠不同细胞拼起来推断。"}, {"h": "实验结论和常见现象解释", "p": "本实验有两个必记结论。第一，==视野中处于分裂间期的细胞最多==，原因是间期占细胞周期90%—95%，时间最长，绝大多数细胞正好处在这一阶段。第二，分生区细胞能进行有丝分裂，所以这里才能同时看到间期和四个分裂时期的细胞。\n\n再解释两个常考现象：如果**解离不充分**，细胞重叠，视野里一片糊；如果**解离过度或漂洗不净**，根尖过于酥软或染色过浅。还有同学问为什么看不清染色体——多半是染色时间不够，或漂洗没洗净解离液干扰了染色。答实验分析题，就从这四步里找原因，哪步出问题，哪步就是答案。"}], "pitfalls": ["漂洗在染色之前，不能颠倒：先染色再漂洗会把染料洗掉，且解离液残留会影响染色，顺序是解离→漂洗→染色→制片。", "染色体着色用的是甲紫溶液（或醋酸洋红），不是健那绿、不是苏丹III；健那绿是染线粒体的，别张冠李戴。", "看到的细胞是死细胞，不能说观察到了一个细胞完整的连续分裂过程；也不能说细胞周期各时期时长可直接由一个细胞测出。", "分生区细胞呈正方形、排列紧密；伸长区细胞明显伸长、无分裂能力，别把伸长区当分生区找分裂期细胞。"]}, "video": {"bvid": "BV1p54y177e6", "p": 51, "t": "细胞的增殖", "dur": "124:51", "from": "锦城大同教育·杨波生物", "vtop": ["细胞周期只属于连续分裂的细胞：从一次分裂完成到下一次分裂完成为止，间期长、分裂期短，间期里完成 DNA 复制和有关蛋白质合成。", "有丝分裂认时期抓标志：中期着丝点排在赤道板上、形态固定数目清晰；后期着丝点分裂、染色单体消失、染色体数暂时加倍。", "数曲线只看核 DNA：核 DNA 2N→4N→2N，染色体数后期才加倍，染色单体只在前中期有，1:2:2 只在有染色单体时成立。"], "vsum": "本课讲第六章第一节，讲**细胞的增殖**，分两讲。第一讲开场先算一道题：象和鼠个体大小相差悬殊，细胞大小差多少？动物细胞直径一般 20–30 微米，取小鼠 20 微米、大象 30 微米，直径比 2:3，用球体体积公式算体积比是 8:27——个体大小的差异主要来自**细胞数量**的多少，不是细胞大小。一个受精卵变成多细胞个体，细胞数量增多靠**细胞增殖**，种类增多靠**细胞分化**（第六章第二节再讲）。第一个重点是**细胞增殖**与**细胞周期**：细胞增殖是细胞通过分裂增加细胞数量的过程，常和细胞分裂同义；细胞周期是从一次分裂完成开始，到下一次分裂完成为止，只有**连续分裂的细胞**才有，比如受精卵、根尖分生区细胞、茎的形成层细胞、皮肤生发层细胞和各种干细胞。一次细胞周期分**分裂间期**和**分裂期**：间期做物质准备，处在两次分裂之间，所以叫间期；间期占大头——蚕豆根尖分生区细胞周期 17.3 小时、间期 15.3 小时，小鼠十二指肠上皮细胞周期 15.3 小时、间期 13.5 小时；不同细胞周期长短不同，即使同一个体也一般不同，人肝细胞和宫颈癌细胞周期都是 22 小时，间期时长却不一样。第二个重点是**有丝分裂**，分前、中、后、末四个时期，是人为划分的。分裂间期主要进行 **DNA 的复制和有关蛋白质的合成**。前期：细丝状的**染色质**螺旋缠绕变成短棒状的**染色体**，细胞两极发出**纺锤丝**（蛋白质）形成纺锤体，核膜、核仁消失；染色质和染色体是同一种物质，只是形态不同，数染色体只数数量、不看形状。中期：染色体进一步螺旋、缩短变粗，形态比较固定、数目比较清晰，**着丝点**整齐排列在**赤道板**上，是观察染色体形态和数目的最佳时期。后期：**着丝点分裂**，姐妹染色单体分开变成两条染色体，分别移向细胞两极，染色单体消失，染色体数目暂时加倍。末期：染色体变回染色质，纺锤体消失，核膜、核仁重现；植物细胞在赤道板位置出现**细胞板**，向四周扩展成新的细胞壁；染色体、纺锤体出现与核膜、核仁消失，前期和末期刚好相反。间期还能细分为 **G1 期**（DNA 合成前期，合成蛋白质）、**S 期**（DNA 合成期）、**G2 期**（DNA 合成后期），有丝分裂期又叫 **M 期**。第三个重点是**动物细胞**的有丝分裂，和植物大体相同，不同有三处：间期**中心体**由一组倍增为两组；前期中心体移向两极、发出**星射线**形成纺锤体，不是两极发纺锤丝；末期没有细胞板，靠细胞膜从中部向内凹陷、形成收缩环把细胞**缢裂**成两个——答题写“缢裂”不写“分裂”。问与动物细胞有丝分裂有关的细胞器，要加上中心体、去掉高尔基体（高尔基体与细胞壁形成有关，动物细胞没有细胞壁）。**有丝分裂的意义**有两点：第一，把亲代细胞的染色体经过复制（关键是染色体内 DNA 的复制）后**精确地平均分配**到两个子细胞中——平均分配的只是细胞核内的 DNA，细胞质 DNA 是随机分配的，细胞器也随机分配，只有中心体例外、是平均分配的；第二，染色体上有遗传物质 DNA，这样就在亲代和子代之间保持了**遗传的稳定性**。**癌细胞**是遗传物质发生改变、不受机体控制、能连续分裂的恶性增殖细胞。最后一个知识点是**无丝分裂**：过程是核延长→核缢裂→细胞质缢裂，同样先进行 DNA 复制，子细胞的遗传物质和亲代一样；特点是分裂过程没有出现纺锤丝和染色体的变化，速度比较快；蛙的红细胞能进行无丝分裂，低等植物中普遍存在，高等植物的胚乳细胞、薄壁细胞、表皮细胞、根冠细胞和动物的某些腺体细胞也能进行。易错提醒：蛙生长发育过程中体细胞增殖仅靠有丝分裂——错，还要靠无丝分裂。第二讲先问细胞为什么不能无限长大。原因一是细胞大小影响**物质运输效率**：用边长 2、4、8 毫米的正方体模拟细胞，表面积分别是 24、96、384，体积分别是 8、64、512，相对表面积从 3 降到 1.5 再到 0.75；把三个模型放进葡萄糖溶液相同时间、假设扩散深度都是 0.5 毫米，葡萄糖扩散的体积占总体积分别是 7/8、37/64、169/512，细胞越大、表面积与体积之比越小，运输效率越低。原因二是**细胞核是细胞的控制中心**，细胞太大、细胞核的控制作用就有限，就像一个班主任管 50 个学生还行、管 200 个就管不过来。接着做教材实验**观察根尖分生区组织细胞的有丝分裂**：原理是根尖分生区细胞能连续分裂、有细胞周期；高倍显微镜下根据染色体的存在状态判断所处时期；染色体容易被碱性染料着色。步骤是解离→漂洗→染色→制片：解离液是质量分数 15% 的盐酸和体积分数 95% 的酒精按 1:1 混合，3–5 分钟，目的是使组织中的细胞相互分离开来，细胞在解离时已经死亡，解离到根尖酥软、镊子一碾就散即可，解离过度会妨碍染色；漂洗用清水、10 分钟以上，洗去多余解离液；染色用质量浓度 0.01 或 0.02 g/mL 的龙胆紫溶液（龙胆紫溶于质量分数 2% 的醋酸配成）或醋酸洋红液，3–5 分钟；制片是取根尖放载玻片上、加一滴清水、用镊子弄碎、盖上盖玻片、拇指轻压使细胞分散开。观察时先低倍镜找到分生区细胞，再换高倍镜辨认各时期，视野里处于分裂间期的细胞数量最多。最后看三条数量曲线：细胞核内 DNA 数在间期从 2N 复制到 4N，复制发生在 S 期，画图时前面要留一段平的 G1 期、后面留 G2 期，末期一分为二又回到 2N；**染色单体**数只有 0 和 4N 两个值，S 期出现、后期着丝点分裂时归 0；**染色体**数只有 2N 和 4N，后期加倍、末期减半；每条染色体上的 DNA 含量在 S 期从 1 条变 2 条，后期开始又从 2 条变回 1 条。有染色单体时（前期、中期）染色体数:染色单体数:核 DNA 数 = 1:2:2，没有染色单体时（后期、末期）染色体数:核 DNA 数 = 1:1。教材习题：洋葱根尖细胞有 16 条染色体，“分裂期细胞数量较多”是错的，间期细胞才多；“间期染色体复制后为 32 条”也是错的，间期染色体数不加倍，加倍只在后期。", "vtech": [["细胞周期先问“连续分裂”", "看到细胞周期题 → 先问是不是连续分裂的细胞：受精卵、根尖分生区、茎形成层、皮肤生发层、干细胞才有；不同细胞周期长短不同，同一体也不一样——人肝细胞和宫颈癌细胞都是 22 小时，间期时长却不同。"], ["前中后末抓标志性变化", "前期染色质螺旋成染色体、纺锤体出现、核膜核仁消失；中期着丝点排赤道板、形态固定数目清晰，是看染色体最好的时期；后期着丝点分裂、染色单体消失、染色体数加倍；末期核膜核仁重现，植物出现细胞板，动物细胞膜向内凹陷缢裂。"], ["动物细胞三处不同记时期", "间期中心体由一组倍增为两组；前期中心体移向两极发出星射线形成纺锤体，不是两极发纺锤丝；末期没有细胞板，靠细胞膜向内凹陷、收缩环缢裂成两个细胞；问有关细胞器要加上中心体、去掉高尔基体。"], ["曲线题先定 2N、4N、0 三个数", "核 DNA：间期 2N→S 期复制→4N，末期一分为二回 2N；染色单体只有 0 和 4N 两个值，S 期出现、后期着丝点分裂时归 0；染色体数只有 2N 和 4N，后期加倍、末期减半；有染色单体时染色体:染色单体:核 DNA = 1:2:2，无染色单体时是 1:1。"]], "vgaokao": []}}, "bio_b026": {"name": "细胞分化与细胞的全能性", "sec": 26, "secTitle": "细胞的分化", "page": 118, "desc": "分化的实质是基因选择性表达；全能性大小比较；干细胞与骨髓移植。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b024"], "next": ["bio_b027"], "content": {"advance": {"a": "该观点错误。细胞分化的实质是基因的选择性表达，分化过程中遗传物质保持不变，不同细胞只是表达的基因不同，合成的蛋白质不同，因而形态功能不同，基因并未丢失。正因分化细胞的细胞核仍保留全套遗传信息，已分化细胞才仍具有全能性：胡萝卜韧皮部细胞经组织培养发育成完整植株、克隆羊多莉的培育，都证明了这一点。关系是：分化程度越高，细胞全能性越低，全能性的表达越困难；但分化不改变遗传物质，这是全能性存在的物质基础。", "kind": "self", "q": "有人认为细胞分化就是基因丢失的过程，所以分化后的细胞不可能再发育成完整个体。请用本节知识反驳这一观点，并说明细胞分化与细胞全能性的关系。"}, "apply": [{"ans": 1, "opts": ["DNA不同，蛋白质相同", "DNA相同，mRNA和蛋白质不完全相同", "DNA和蛋白质都完全相同", "DNA相同，mRNA完全相同"], "q": "比较人的肝细胞和肌细胞，下列叙述正确的是（ ）", "why": "两种细胞都来自同一受精卵的有丝分裂，DNA相同；因基因选择性表达不同，mRNA和蛋白质不完全相同，形态功能才不同。"}, {"ans": 1, "opts": ["动物体细胞的全能性已经表达", "已分化动物细胞的细胞核具有全能性", "动物细胞培养可直接得到完整个体", "细胞分化是完全可逆的"], "q": "克隆羊多莉的培育成功证明了（ ）", "why": "多莉是将乳腺细胞的细胞核移入去核卵细胞后发育而成的，证明的是细胞核的全能性；动物体细胞本身的全能性受限制，不能直接培养成个体。"}, {"ans": 1, "opts": ["无限增殖的能力", "分化为各种血细胞的潜能", "吞噬并杀死癌细胞的能力", "产生抗体的能力"], "q": "骨髓移植能有效治疗白血病，其生物学原理是造血干细胞具有（ ）", "why": "造血干细胞能增殖分化为红细胞、白细胞、血小板等各种血细胞，移植后可重建患者正常的造血系统，故能治疗白血病。"}], "basics": [{"ans": 1, "opts": ["细胞中遗传物质发生改变", "基因的选择性表达", "细胞数目的增多", "细胞形态的暂时变化"], "q": "细胞分化的实质是（ ）", "why": "分化时DNA不变，不同细胞选择表达不同基因，合成的mRNA和蛋白质不同，从而表现出不同的形态和功能。"}, {"ans": 1, "opts": ["造血干细胞", "受精卵", "生殖细胞", "胡萝卜韧皮部细胞"], "q": "下列细胞中，全能性最高的是（ ）", "why": "全能性大小：受精卵大于生殖细胞大于体细胞；造血干细胞和韧皮部细胞都属于已分化的体细胞，全能性低于受精卵。"}], "case": {"a": "（1）说明高度分化的植物细胞仍具有全能性，即仍有发育成完整个体的潜能。（2）韧皮部细胞的细胞核含有该物种全套遗传信息，组织培养过程通过有丝分裂产生后代细胞，子代细胞的DNA与亲代一致，故新植株与供体遗传性状一致。（3）涉及细胞分裂（有丝分裂使细胞数目增多）、脱分化（由分化状态回到未分化状态形成愈伤组织）和再分化（形成根、茎、叶等组织器官）。", "hints": ["单个分化细胞长成完整个体，对应哪个概念？", "遗传一致想有丝分裂的特点：子细胞DNA与亲代相同。"], "q": "科学家取胡萝卜根的韧皮部细胞，置于适宜的培养基中培养，单个细胞先脱分化形成愈伤组织，再分化出根、茎、叶，最终长成一株完整的胡萝卜，且其叶片形态与供体植株一致。问：（1）该实验说明高度分化的植物细胞具有什么特性？（2）培养出的植株与供体遗传性状一致的原因是什么？（3）愈伤组织形成过程涉及细胞的哪些生命活动？", "steps": ["韧皮部细胞是已高度分化的植物体细胞，却发育成完整个体，说明其具有全能性", "全能性的基础是细胞核内含有发育成完整个体所需的全套遗传信息，分化并未使基因丢失", "培养过程靠有丝分裂增殖保证遗传稳定，靠脱分化和再分化形成不同组织器官"], "talk": ["单个细胞长成完整个体，答案直奔全能性；遗传一致，直奔有丝分裂。"], "title": "案例：胡萝卜组织培养说明了什么"}, "intro": "一个人全身细胞的**DNA**几乎完全一样，为什么肝细胞、肌细胞、神经细胞长得完全不同、干的活也完全不同？答案就藏在**细胞分化**里。==细胞分化的实质是基因的选择性表达：DNA不变，只是不同细胞打开的基因不同==，这一句是整节的命门，选择题、材料题反复考。\n\n再往深一层：既然分化后的细胞把大部分基因关掉了，它还能变回胚胎、长成完整个体吗？**细胞全能性**回答的就是这个问题。==已分化的细胞仍然具有发育成完整个体的潜能==，胡萝卜能、克隆羊也能，区别只在实现的难易。这节概念多，但抓住实质和比较大小两条线就不乱。", "learn": [{"h": "细胞分化：概念、实质和特点", "p": "**细胞分化**是指在个体发育中，由一个或一种细胞增殖产生的后代，在**形态、结构和生理功能**上发生**稳定性差异**的过程。比如受精卵经有丝分裂产生大量细胞，再分化出肌肉、神经、血液等各种细胞，进而组成组织和器官。\n\n实质必须背准：分化不是基因丢了，而是**基因的选择性表达**。==不同细胞中DNA相同，但mRNA和蛋白质的种类不同==，比如胰岛B细胞里胰岛素基因打开、其他基因沉默，肌细胞里肌动蛋白基因打开。考试常拿血红蛋白、胰岛素这类具体蛋白质设问，看细胞里有什么蛋白质，就知道哪类基因在表达。\n\n特点记四个词：**持久性**（贯穿整个生命进程，胚胎期最强）、**普遍性**（多细胞生物普遍存在）、**稳定性**和**不可逆性**（正常情况下分化后一般不能回到未分化状态）。意义也有一句：==细胞分化是多细胞生物个体发育的基础，使细胞趋向专门化，有利于提高生理功能的效率==。"}, {"h": "细胞全能性：证据和大小比较", "p": "**细胞的全能性**是指已分化的细胞仍然具有发育成完整个体或分化成其他各种细胞的潜能。为什么分化了还有全能性？因为分化细胞的**细胞核**里还保存着全套遗传信息，一个基因都没少。\n\n证据记两个经典案例：植物看**斯图尔德**的实验——把**胡萝卜韧皮部细胞**放在培养基中培养，长成了完整的胡萝卜植株，证明高度分化的植物细胞具有全能性；动物看**克隆羊多莉**——用乳腺细胞的细胞核移植到去核卵细胞中，发育成一只羊。注意多莉证明的是==动物细胞的细胞核具有全能性==，而不是整个动物体细胞直接培养成个体，因为动物体细胞全能性受到很大限制，至今不能像植物那样直接培养成个体。\n\n全能性大小比较是高频考点，记三组：==受精卵大于生殖细胞大于体细胞；植物细胞大于动物细胞；分裂能力强的细胞大于分裂能力弱的细胞==。总规律：分化程度越高，全能性越低；分化程度越低，全能性越高，两者呈负相关。"}, {"h": "干细胞：还没完全分化的潜力股", "p": "**干细胞**是一类还没有完全分化、具有较强分裂和分化潜能的细胞，可以理解为细胞中的后备军。按来源分两类：**胚胎干细胞**来自早期胚胎，能分化成多种类型的细胞，全能性较高；**成体干细胞**存在于成体组织中，如骨髓中的**造血干细胞**，能分化出红细胞、白细胞、血小板等各种血细胞，但分化方向相对受限。\n\n应用题最爱考**骨髓移植治疗白血病**：白血病患者的造血干细胞功能异常，不能正常造血；移植健康供者的造血干细胞后，这些干细胞在患者体内增殖分化，重建正常的造血和免疫系统，从而治病。原理一句话：利用干细胞的分裂和分化潜能，替换掉病变的造血系统。答题时把造血干细胞能分化为各种血细胞这一点点明即可。"}], "pitfalls": ["分化过程中遗传物质不变：DNA相同，不同的是mRNA和蛋白质。若选项说分化使基因丢失或改变，一律错。", "克隆羊多莉证明的是动物细胞核的全能性，不能表述为动物体细胞具有全能性并已表达；植物组织培养才证明植物体细胞全能性的表达。", "全能性高低与分化程度高低相反：受精卵分化程度最低、全能性最高；高度分化的神经细胞全能性很低，别记反。", "分化一般不可逆，但离体条件下高度分化的植物细胞可经脱分化再形成新个体，这是全能性表达，不等于体内分化可随意逆转。"]}, "video": {"bvid": "BV1p54y177e6", "p": 55, "t": "细胞的分化", "dur": "49:17", "from": "锦城大同教育·杨波生物", "vtop": ["细胞分化的实质是基因的选择性表达：分化后的细胞仍含本物种全套基因，变的只是哪些基因在表达——同一个体不同细胞的基因组成相同、表达情况不同。", "全能性不等于表现出全能性：一般活细胞理论上都有全能性（哺乳动物成熟红细胞没有细胞核，要除外），但要表现出来，必须发育成完整个体或分化出各种细胞。", "植物细胞全能性易于表达（组织培养：脱分化成愈伤组织、再分化成完整植株），动物体细胞全能性受细胞质限制，只能说细胞核具有全能性——受精卵和早期胚胎细胞除外。"], "vsum": "本课讲第六章第二节，讲**细胞的分化**。开场先看教材例子：在人体内，**红细胞**的寿命为 120 天左右，**白细胞**的寿命只有 5 到 7 天，这些血细胞都是失去分裂能力的细胞。教材提了两个问题：为什么健康人的血细胞数量不会随着血细胞的死亡而减少？因为机体会不断产生新的血细胞补充到血液中去；骨髓与血细胞的形成有什么关系？因为红细胞、白细胞和血小板都有共同的起源——**造血干细胞**，它主要存在于骨髓里，能通过增殖分化形成这三种血细胞，所以向白血病患者移植正常的骨髓，让正常的干细胞产生正常的血细胞，就能达到治疗白血病的目的。造血干细胞变成红细胞、白细胞、血小板时，细胞的种类增加了，细胞种类的增加依靠的就是细胞的分化。第一个重点是**细胞分化及其意义**。细胞分化的概念是：在**个体发育**中，由一个或一种细胞增殖产生的后代，在**形态、结构和生理功能**上发生**稳定性差异**的过程。一个细胞比如受精卵，一种细胞比如造血干细胞，都能分化；以红细胞和白细胞为例，哺乳动物成熟的红细胞是两面凹的圆盘状，白细胞一般是球形，形态结构不同，功能也不同——红细胞主要运输氧气，白细胞是免疫细胞、帮助机体抵御病原体。所谓稳定性，是指分化后的细胞一般维持分化后的状态直到死亡。接着看分化的过程和实质：受精卵含有本物种全套的遗传物质，比如 ABCD 四个基因，分裂产生的两个子细胞也都含有全套基因；分化时，上面那个子细胞只表达 A 和 C 基因，下面那个只表达 B 和 C 基因，表达不同，形态结构和功能就不同了，但分化后的细胞仍然含有全套基因，没表达的基因还在细胞里。所以细胞分化一般不会改变遗传物质，实质就是**基因的选择性表达**——在个体发育过程中，不同种类的细胞中遗传信息的表达情况不同。基因表达主要是合成蛋白质，有的蛋白质是结构蛋白、构成细胞结构，有的蛋白质是酶、参与细胞内的生理功能，表达的蛋白质不同，细胞的结构和生理过程就不同。分化有四个特点：①**普遍性**，在生物界中普遍存在，是生物个体发育的基础——没有分化，受精卵不可能变成一个完整的婴儿；但并非一切生物都能分化，病毒连细胞都不是，某些单细胞生物也不能分化；②**持久性**，发生在生物体的整个生命进程中，小孩、成年人、老年人身体里造血干细胞都在分化产生血细胞补充死亡的细胞，在胚胎时期达到最大限度；③**稳定性**或**不可逆性**，一般来说分化后的细胞将一直保持分化后的状态直到死亡，但少数特殊情况下，在离体或人工培养的条件下，某些高度分化的细胞可以恢复分裂和分化能力；④**遗传物质的不变性**，一般情况下分化后的细胞内遗传物质不发生改变。分化的结果是形成不同形态、结构和功能的细胞，不同类型的细胞构成不同的组织和器官，比如上皮细胞构成上皮组织，骨骼肌细胞构成肌肉组织，软骨细胞、神经细胞也是分化产生的。分化的意义有两点：一是生物个体发育的基础，没有分化人体不能完成正常发育；二是使多细胞生物体的细胞**趋向专门化**，有利于提高各种生理功能的效率——叶肉细胞含大量叶绿体、能充分表达合成叶绿体的基因，更好地完成光合作用；表皮细胞不含叶绿体，细胞壁外面形成角质层、起保护作用；储藏细胞也不含叶绿体，储藏大量有机物供植物体使用。接着看分化的变与不变：变的是细胞的形态、结构和生理功能，细胞器的种类和数目、细胞质基质的成分和功能，蛋白质的种类、数量和功能，以及基因的选择性表达；不变的是细胞的数量和细胞内的遗传物质——分化不改变细胞数目，细胞数目靠增殖改变，分化后的细胞都含本物种全套遗传信息。易错提醒三则：①同一个体的小肠上皮细胞和平滑肌细胞所含的基因是不同的——错，同一个体都来自一个受精卵，遗传物质相同；②蛙的红细胞和人的红细胞形态不同的原因是基因选择性表达的结果——错，这是两个不同物种，基因本身就不同，选择性表达是同一个体或同一物种内部的事；③同一细胞内往往含有不同的蛋白质，这是基因选择性表达的结果——错，同一细胞内基因不同、表达了就会产生不同蛋白质，与选择性表达无关，而且分化说的是后代之间的差异，不是一个细胞内部。第二个重点是**细胞的全能性**。概念是：细胞经过分裂和分化后，仍然具有产生**完整有机体**或分化成**其他各种细胞**的潜能和特性。未分化的细胞如受精卵、动物和人体的早期胚胎细胞、植物体的分生组织细胞都具有全能性；细胞是否具有全能性，与是否经过分裂和分化没有必然联系；一般来说活细胞理论上都具有全能性，但有的细胞除外，比如**哺乳动物成熟的红细胞**等。植物细胞全能性的表达就是**植物组织培养**：科学家利用胡萝卜的韧皮部细胞，取一部分放到含有营养物质和植物激素的特定培养液中，先经过**脱分化**形成细胞团块——**愈伤组织**，也就是恢复了分裂和分化能力的薄壁细胞，再经过**再分化**产生根、茎、叶，最终形成一株完整的植株。所以植物组织培养就是利用植物的细胞、组织或器官进行离体培养，经过脱分化和再分化培育成完整植株，属于植物无性繁殖的一种；结论是高度分化的植物细胞仍然具有发育成完整植株的能力，植物细胞具有全能性。动物方面说的是**动物细胞核的全能性**：非洲爪蟾的核移植实验，先用紫外线处理蛙卵使细胞核失活、得到去核的卵细胞，再把蝌蚪肠上皮细胞的细胞核移植进去，得到的细胞经过增殖和分化发育成完整的蝌蚪，而且克隆蝌蚪的性状和提供细胞核的那只蝌蚪一样；还有克隆羊多利，以及我国科学家首次完成的克隆猴中中和华华。这说明已分化的动物细胞的细胞核具有全能性，但到目前为止科学家还没有把一个动物体细胞直接培育成完整个体，因为动物体细胞全能性的表达受**细胞质**的限制；例外的是动物的受精卵和早期胚胎细胞，这两种细胞可以直接说细胞具有全能性。接着讲**干细胞**：特点是具有分裂和分化能力，在动物和人体内数量比较少，比如骨髓中的造血干细胞能不断产生红细胞、白细胞和血小板。按分化潜能不同，干细胞分为三类：**全能干细胞**（受精卵、早期卵裂的细胞，能分化成组成该机体的各种细胞）、**多能干细胞**（胚胎干细胞、造血干细胞、骨髓间充质干细胞，只能分化成多种细胞）、**单能干细胞**，又叫**专能干细胞**（神经干细胞、小肠上皮干细胞，通常只能分化成一种或关系密切的两种细胞）。还要注意两点：一是并非所有干细胞都要分化，部分干细胞保留分裂能力、进行自我更新，源源不断地产生新的干细胞；二是只有全能干细胞是未分化的细胞，多能和单能干细胞都是已经分化的细胞，只不过分化程度没有高度分化。细胞具有全能性的原因是：已分化的细胞一般都有一套和受精卵完全相同的遗传物质，所以仍有发育成完整新个体的潜能；哺乳动物成熟的红细胞除外，因为它没有细胞核，细胞核内的遗传物质在发育过程中逐渐退化掉了。植物细胞全能性实现的条件是：离体状态、水、无机盐、有机营养及激素（如生长素、细胞分裂素）、适宜的温度等外界条件。动植物细胞全能性的区别是：植物细胞的全能性易于表达，动物细胞的全能性受到极大限制，但动物细胞核的全能性仍然可以表达。分化程度与全能性的关系：一般情况下，细胞分化程度不断提高，全能性逐渐变小，但分化程度高的细胞全能性不一定低，比如**生殖细胞**（精子和卵子）是高度分化的细胞，全能性却较高；除了生殖细胞之外的体细胞，全能性小于生殖细胞，生殖细胞的全能性又小于受精卵。分裂与分化的关系：一般来说细胞分化程度越高，分裂能力越低，大部分分化细胞失去了分裂能力，但小部分高度分化的细胞仍然具有分裂能力，比如小肠上皮细胞和平滑肌细胞。易错提醒四则：①成熟个体体内的所有细胞都已经高度分化——错，成年人、老年人身体里都有干细胞在增殖分化、补充新细胞；②种子发育成完整个体体现了细胞的全能性——错，种子里面含有一个植物的幼体，长大只是自然生长的过程，就像婴儿长大成人不能体现细胞的全能性；③壁虎断尾后重新长出尾巴体现了细胞的全能性——错，全能性的体现要么发育成完整植株（个体），要么分化出各种细胞，壁虎只长出了尾巴部分的细胞；④造血干细胞分化出各种血细胞体现了细胞的全能性——错，虽然有各种两个字，但只是各种血细胞，除非说能分化出组成这个个体所需的各种细胞才可以。问题探究：细胞具有全能性，不等于细胞表现出全能性——只要有细胞核的活细胞一般都具有全能性，但要表现出全能性，必须发育成一个完整的个体，或者分化出各种细胞。教材习题要点：①受精卵没有分化，所以没有全能性——错，是否分化与是否具有全能性没有必然联系，受精卵没有分化但仍具有全能性；②细胞的分化程度越高，表现出来的全能性就越弱——对，注意这里说的是表现出来的全能性，改成具有的全能性就错了，生殖细胞就是特例；③把自体骨髓干细胞植入胰腺后分化为胰岛样细胞、替代损伤的胰岛 B 细胞治疗糖尿病——选 D，骨髓干细胞与胰岛 B 细胞基因组成相同、基因表达情况不同；④多细胞生物体内存在各种形态结构和功能上有差异的细胞——选 D，不同细胞中基因的选择性表达；⑤蛙的细胞中最容易表达出全能性的是受精卵——选 C，神经细胞、肌肉细胞、口腔上皮细胞都是高度分化的体细胞，只有受精卵是未分化的细胞。最后小结：本课学了细胞分化的概念、特点（普遍性、持久性、不可逆性、遗传物质的不变性）、意义和实质，以及细胞全能性的概念、植物细胞全能性的条件、动植物全能性的差异和应用——植物是组织培养、能快速繁殖，动物是克隆；课后作业是完成课后作业 28，下节课评讲。", "vtech": [["分化后遗传物质变没变：没变", "分化是基因的选择性表达：分化后的细胞仍含本物种全套基因，只是表达的基因不同；同一个体的小肠上皮细胞和平滑肌细胞基因组成相同，错说成不同是典型易错点。"], ["分化的四个特点要会区分", "普遍性（生物界普遍存在、个体发育的基础，但病毒和某些单细胞生物不能分化）、持久性（贯穿整个生命进程，胚胎时期达到最大限度）、稳定性或不可逆性（一般保持分化状态直到死亡，离体或人工培养条件下某些高度分化细胞可恢复）、遗传物质的不变性。"], ["全能性表达的两个条件：发育成完整个体或分化出各种细胞", "种子长成植株、壁虎断尾长尾巴、造血干细胞分化出各种血细胞都不能体现全能性——种子含幼体只是自然生长，后两者只分化出部分细胞，不是各种细胞；具有全能性不等于表现出全能性。"], ["干细胞三类与全能性大小排序", "按分化潜能分全能干细胞（受精卵、早期卵裂细胞）、多能干细胞（胚胎干细胞、造血干细胞、骨髓间充质干细胞）、单能或专能干细胞（神经干细胞、小肠上皮干细胞）；体细胞全能性小于生殖细胞，生殖细胞小于受精卵；分化程度越高分裂能力一般越低，但小肠上皮细胞和平滑肌细胞这类高度分化细胞仍能分裂。"]], "vgaokao": []}}, "bio_b027": {"name": "细胞的衰老和死亡", "sec": 27, "secTitle": "细胞的衰老和死亡", "page": 123, "desc": "衰老细胞的特征；自由基与端粒学说；凋亡与坏死的对比。", "criteria": ["能复述本节核心概念与关键数据", "能说清实验的变量、对照与结论", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清推理过程"], "diag": null, "pre": ["bio_b026"], "next": [], "content": {"advance": {"a": "原因：凋亡由基因决定，是细胞自动结束生命的过程；坏死由极端物理、化学等不利因素或病理性刺激引起。过程：凋亡主动、有序，细胞皱缩并形成凋亡小体被吞噬；坏死被动、无序，细胞肿胀直至膜破裂。结果：凋亡不泄漏内容物、不引发炎症；坏死时细胞膜破裂，内容物释放，常引发炎症反应。对机体影响：凋亡对机体有利，如胎儿指间细胞凋亡使手指分开、蝌蚪尾的消失；坏死对机体有害，如烫伤后皮肤细胞死亡、严重污染导致的组织细胞死亡。", "kind": "self", "q": "请从原因、过程、结果和对机体的影响四个方面比较细胞凋亡与细胞坏死，并各举一例。"}, "apply": [{"ans": 1, "opts": ["色素沉积；酶活性降低", "酪氨酸酶活性降低致黑色素减少；色素逐渐积累沉积", "水分减少；细胞核体积增大", "呼吸速率减慢；细胞膜通透性改变"], "q": "老年人头发变白、皮肤出现老年斑，分别对应的衰老特征是（ ）", "why": "头发变白是黑色素细胞中酪氨酸酶活性降低、黑色素合成减少；老年斑是衰老细胞内色素逐渐积累沉积的结果，两者不可对调。"}, {"ans": 1, "opts": ["两者都由基因决定，对机体都有利", "凋亡是主动有序的过程，坏死常引发炎症反应", "坏死是程序性死亡，凋亡是被动死亡", "两者都会使细胞膜破裂并释放内容物"], "q": "关于细胞凋亡与细胞坏死的比较，正确的是（ ）", "why": "凋亡由基因决定、主动有序、不引发炎症、对机体有利；坏死由不利因素引起、被动无序、细胞膜破裂释放内容物，常引发炎症、对机体有害。"}, {"ans": 2, "opts": ["老年人的皮肤细胞", "成年人的肌肉细胞", "胚胎细胞", "衰老的造血干细胞"], "q": "端粒学说认为细胞衰老与端粒缩短有关。据此推测，下列细胞中端粒相对最长的是（ ）", "why": "端粒随分裂次数增加而逐渐缩短，胚胎细胞分裂次数最少、最为年轻，端粒相对最长；衰老个体细胞分裂次数多，端粒较短。"}], "basics": [{"ans": 2, "opts": ["细胞内水分减少，体积变小", "细胞内多种酶的活性降低", "细胞核体积减小，染色质收缩", "细胞膜通透性改变，物质运输功能降低"], "q": "下列哪项不是衰老细胞的特征（ ）", "why": "衰老细胞的细胞核体积是增大而不是减小，并伴随核膜内折、染色质收缩、染色加深。其余三项均为衰老特征。"}, {"ans": 1, "opts": ["烫伤后皮肤细胞死亡", "被病原体感染的细胞被机体清除", "骨折处骨细胞受损死亡", "极端低温导致细胞冻死"], "q": "下列生命现象中属于细胞凋亡的是（ ）", "why": "被病原体感染的细胞被清除是基因控制的程序性死亡，对机体有利，属凋亡；其余都是不利因素导致的被动死亡，属坏死。"}], "case": {"a": "（1）属于细胞凋亡。理由：蝌蚪尾的消失是其发育过程中由基因决定的、自动结束生命的程序性死亡，是正常发育所必需的，对机体有利。（2）属于细胞坏死。区别在于结果：凋亡时细胞有序解体，不引发炎症；坏死时细胞膜破裂，内容物释放到细胞外，引起周围组织发炎溃烂，对机体有害。", "hints": ["正常发育、按程序进行，关键词是基因决定。", "破裂、发炎是不利因素致死的典型信号。"], "q": "蝌蚪发育成青蛙的过程中，尾巴逐渐缩短直至消失；与此同时，某只蝌蚪因水体严重污染，尾部部分细胞肿胀破裂、周围组织发炎溃烂。问：（1）正常发育中尾的消失属于哪种细胞死亡方式？判断理由是什么？（2）污染导致的尾部细胞死亡属于哪种方式？与前者在结果上有何不同？", "steps": ["尾的消失发生在正常发育的固定阶段，是受基因调控的程序性过程，符合凋亡定义", "凋亡过程细胞有序解体、不破裂泄漏内容物，不引发炎症，对个体发育有利", "污染致死由外界不利因素引起，细胞膜破裂、内容物释放并引发炎症，属于坏死，对机体有害"], "talk": ["发育程序里消失的是凋亡，外力打死还发炎的是坏死。"], "title": "案例：蝌蚪尾巴消失是凋亡还是坏死"}, "intro": "人老了，是因为细胞老了。这节收尾整章，考的点很集中：**衰老细胞的特征**要能一条条说出来，**细胞凋亡**和**细胞坏死**的区别是每年必考的对比题。先立住一句话：==细胞凋亡是由基因决定的细胞自动结束生命的过程，对机体有利；细胞坏死是受不利因素影响的被动死亡，对机体有害==，这组对比定住了，后面全是细节补充。\n\n还有一层关系容易考混：个体衰老不等于每个细胞都衰老。==多细胞生物体内，细胞的普遍衰老才意味着个体的衰老==，年轻人体内也有衰老细胞，衰老个体内也有新细胞。把特征、两种学说、两种死亡方式理清，这节就结束了。", "learn": [{"h": "衰老细胞的特征：五条对照着记", "p": "衰老细胞的变化可以顺着细胞结构一条条推。**水分减少**，细胞萎缩，**体积变小**，新陈代谢速率减慢。细胞内多种**酶的活性降低**，比如头发基部的黑色素细胞中**酪氨酸酶活性降低**，黑色素合成减少，所以老人头发变白。**色素逐渐积累沉积**，比如老年斑，就是色素堆在皮肤细胞里。\n\n细胞核的变化：==细胞核体积增大，核膜内折，染色质收缩、染色加深==。细胞膜的变化：**通透性改变**，物质运输功能降低。还有**呼吸速率减慢**。答简答题时把这五条按水分、酶、色素、细胞核、细胞膜的顺序写，条理清楚不丢分。\n\n个体与细胞衰老的关系分两种情况：**单细胞生物**，细胞衰老就是个体衰老，两者一致；**多细胞生物**，体内细胞总在不断更新，个体衰老是细胞普遍衰老的反映，但两者不完全同步。"}, {"h": "细胞衰老的原因：两种学说知道结论即可", "p": "衰老原因考得浅，记住两个学说的名字和核心结论就行。一是**自由基学说**：细胞代谢产生的**自由基**会攻击DNA、蛋白质和生物膜等，使细胞逐渐衰老；辐射、氧化等因素都会增加自由基。二是**端粒学说**：==染色体两端的端粒会随细胞分裂次数增加而逐渐缩短，端粒内侧的正常DNA受损，细胞就会衰老==。\n\n联系实际只点到为止：我国人口老龄化程度加深，关注老年健康、坚持健康生活方式（合理饮食、适度锻炼、减少自由基损伤因素）有助于延缓衰老。考试若出社会议题材料，落点一般就是健康生活和关爱老人，不用展开长篇大论。"}, {"h": "细胞凋亡与细胞坏死：必考对比", "p": "**细胞凋亡**是由**基因决定的**细胞编程序死亡，是主动的、有序的。例子要会举：**胎儿手发育时指间细胞的凋亡**使五指分开、**蝌蚪发育中尾的消失**、**被病原体感染的细胞被清除**，还有人体红细胞、白细胞的正常消亡。==细胞凋亡对多细胞生物完成正常发育、维持内部环境稳定、抵御外界干扰起关键作用==，对机体有利。\n\n**细胞坏死**则是在种种**不利因素**（如极端物理、化学因素或严重病理性刺激）影响下，细胞代谢受损中断引起的死亡，是被动的、无序的。坏死时**细胞膜破裂**，内容物释放出来，常引发周围组织**炎症反应**，对机体有害。\n\n对比抓四点：原因上凋亡由基因控制、坏死由不利因素导致；过程上凋亡有序、坏死无序；结果上凋亡不引发炎症、坏死引发炎症；意义上凋亡有利、坏死有害。选择题给出烫伤后皮肤细胞死亡、骨折等情境，一般都是坏死；给出胚胎发育、细胞更新情境，一般都是凋亡。"}], "pitfalls": ["白头发是酪氨酸酶活性降低导致黑色素减少，不是色素沉积；老年斑才是色素沉积，两个现象的原因别对调。", "衰老细胞体积变小，但细胞核体积增大；呼吸速率和物质运输功能都是降低，不是增强，注意方向词。", "细胞凋亡不等于细胞坏死：胎儿指间细胞消失、蝌蚪尾消失是凋亡，不是坏死；外伤、烫伤导致的细胞死亡是坏死。", "个体衰老不等于所有细胞都衰老：多细胞生物年轻个体内也有衰老细胞，衰老个体内也有分裂产生的新细胞。"]}, "video": {"bvid": "BV1p54y177e6", "p": 57, "t": "细胞的衰老和死亡", "dur": "35:13", "from": "锦城大同教育·杨波生物", "vtop": ["细胞衰老的五个特征用口诀“一大一小一多三低”记：核大、细胞小、色素多，膜运输、酶活性、代谢速率三低。", "细胞衰老不等于个体衰老：单细胞生物细胞衰老就是个体衰老；多细胞生物任何年龄体内都有衰老细胞，个体衰老是组成细胞的普遍衰老。", "细胞凋亡是基因决定的程序性死亡、对机体有利；细胞坏死是被动死亡、对机体有害——判断看主动/被动和有利/有害。"], "vsum": "本课是必修一第六章第三节、也是必修一的最后一节，讲**细胞的衰老和死亡**。开场从教材例子引入：人到一定年龄会长白头发，而且越来越多，原因是毛囊细胞合成黑色素的功能下降了；老师留下三个问题：老年人白头发的形成与毛囊细胞衰老有什么关系、老年人体内有没有幼嫩的细胞、年轻人体内有没有衰老的细胞、细胞衰老与个体衰老有什么关系。第一个重点是**细胞的衰老**：细胞衰老是细胞的生理状态和化学反应发生复杂变化的过程，最终表现为细胞的形态、结构和功能发生变化。**细胞衰老的五个特征**要重点掌握：①**细胞膜通透性改变，物质运输功能下降**——老年人肠胃消化吸收不好就是这个原因；②**细胞核体积增大、核膜内折、染色质收缩、染色加深**——染色质收缩会影响 DNA 的复制，因为 DNA 就位于染色质上；③**细胞内水分减少，细胞萎缩、体积变小**——老年人皮肤失去弹性就是水分减少；注意这里体积变小指的是细胞的体积，和②的细胞核体积增大不要记混；④**细胞内多种酶的活性降低，呼吸速率减慢、新陈代谢速率减慢**——不是所有酶都降低，与衰老相关的酶活性反而升高；老年人冬天更怕冷，就是呼吸作用有关酶的活性下降、产热不足；⑤**细胞内色素逐渐积累，妨碍细胞内物质的交流和传递**——积累的主要是**脂褐素**，不是黑色素，老年斑就是褐色的。白头发的成因：毛囊里的黑色素细胞衰老，里面的**酪氨酸酶**活性下降，酪氨酸转变成黑色素减少，头发就逐渐变白。五个特征用口诀“**一大一小一多三低**”记：一大是细胞核体积变大、染色质收缩染色加深；一小是细胞内水分减少、细胞萎缩变小；一多是细胞内色素（脂褐素）增多；三低是细胞膜物质运输功能降低、酶的活性降低、代谢速率降低。易错提醒：衰老细胞染色质收缩影响 DNA 复制；“所有酶活性都降低”是错的，只是多种酶；“细胞核体积减小”是错的，增大的是核、减小的是细胞；“物质运输功能增强”是错的，是减弱。第二个内容是细胞衰老的原因，目前被大家接受的有两个学说：**自由基学说**——**自由基**是异常活泼的带电分子或基团，经辐射、有害物质入侵、细胞内氧化反应等产生，会攻击破坏生物分子：攻击磷脂分子会产生更多自由基，像雪崩一样越破坏越严重；攻击 DNA 会引起基因突变；攻击蛋白质会使蛋白质活性下降，最终细胞衰老。**端粒学说**——**端粒**是每条染色体两端的特殊序列 DNA 与蛋白质的复合体；每次细胞分裂后，端粒的 DNA 序列就缩短一截，分裂次数越多端粒越短，短到损伤端粒内侧正常基因的 DNA 序列，细胞活动就异常、发生衰老；人体细胞通常只能分裂 **50 到 60 次**，可能就是这个原因。第三个内容是**细胞衰老与个体衰老的关系**，要分两类：**单细胞生物**一个细胞就是一个个体，单个细胞的衰老或死亡就是个体的衰老或死亡；**多细胞生物**细胞的衰老和死亡不等于个体的衰老和死亡——无论小孩、成人还是老年人，体内总有一部分细胞处于衰老和死亡状态，比如红细胞寿命只有 **120 天**、白细胞只有 **5 到 7 天**、小肠上皮细胞只有 **1 到 2 天**；反过来，**个体衰老的过程是组成个体的细胞普遍衰老的过程**，但不是所有细胞都衰老，老年人体内也有幼嫩的细胞和还在增殖分化的干细胞。还有一个核移植实验：年轻人的体细胞去核后与老年人的细胞核融合，细胞不分裂；老年人的体细胞去核后与年轻人的细胞核融合，细胞还能分裂而且比较旺盛，说明细胞分裂受细胞核控制，**细胞核是细胞生命活动的控制中心**，衰老细胞的分裂会逐渐减少甚至停止。易错提醒：端粒不是存在于所有细胞中，只有有染色体的细胞才有端粒；同一种体细胞端粒长度与有丝分裂能力成正相关；自由基不只攻击蛋白质，攻击磷脂和 DNA 同样导致衰老；衰老的生物体中并非所有细胞都衰老；多细胞生物幼嫩的个体中也有衰老的细胞。第二个重点是**细胞的死亡**，主要有**细胞凋亡**和**细胞坏死**两种方式，其中凋亡是细胞死亡的主要形式。**细胞凋亡**是由**基因所决定的细胞自动结束生命的过程**，受严格的遗传机制程序性调控，所以又叫**细胞的程序性死亡**。凋亡有三种类型：①个体发育中细胞的程序性死亡，比如胎儿手指形成过程中指间细胞的死亡；②成熟生物体中细胞的自然更新，比如红细胞、白细胞衰老死亡后由新细胞补充；③被病原体感染的细胞的清除。凋亡的意义有三点：对多细胞生物体完成正常发育有重要作用（没有凋亡手指不能正常形成）；维持内部环境的稳定（衰老死亡的细胞不清除就会在体内堆积成废物）；抵御外界各种因素的干扰（清除被病原体感染的细胞）。总之**细胞凋亡对机体是有利的**。**细胞坏死**则是在极端的物理、化学因素或严重的病理性刺激等种种不利因素影响下，细胞正常代谢活动受损或中断引起的细胞损伤或死亡，比如烫伤后皮肤黏膜脱落、骨折时部分骨细胞死亡、吸烟者肺部细胞因尼古丁作用死亡；坏死是**被动死亡**，对机体**有害**。判断凋亡还是坏死有两个方法：看主动还是被动，主动的是凋亡、被动的是坏死；看对机体有利还是有害，有利的是凋亡、有害的是坏死。易错提醒：被病原体感染的细胞被清除是凋亡不是坏死，因为清除它们能维持机体正常生命活动、对机体有利。教材补充内容**细胞自噬**：在一定条件下，细胞将受损或功能退化的细胞结构等通过**溶酶体**降解后再利用；动物细胞通过溶酶体，植物细胞通过具有类似功能的**液泡**完成；自噬的实质是细胞内的一种膜内吞，形成具有双层膜、裹挟着底物的自噬泡，再与溶酶体或液泡融合，里面的水解酶把底物分解成小分子供细胞再次利用。自噬有三个作用：营养缺乏时获得维持生存所需的物质和能量；细胞受到损伤或衰老时清除受损或衰老的细胞器；微生物入侵时清除感染的微生物和毒素；有些激烈的细胞自噬可能诱导细胞凋亡。易错提醒：细胞凋亡过程中并非所有酶活性都下降，与凋亡有关的酶活性反而升高；凋亡从根本上看是由基因决定的程序性死亡；细胞的衰老和凋亡是正常的生命活动，坏死才是异常的。最后讲了教材上的四道练习题：衰老的生物体中并非所有细胞都衰老；端粒受损可能导致细胞衰老；细胞凋亡是自主有序的死亡、对生物体有利；细胞死亡与细胞凋亡不是同一概念，而是包含关系；“细胞不能继续分化”不是细胞衰老的特征；哺乳动物成熟红细胞没有细胞核和众多细胞器、只能进行无氧呼吸、不产生二氧化碳，衰老后控制其凋亡的基因无法表达，因为它没有细胞核、没有染色体、没有基因；衰老细胞新陈代谢速率是减慢不是加快。最后总结：本课学了细胞衰老的五个特征（口诀“一大一小一多三低”）、自由基学说和端粒学说、细胞衰老与个体衰老的关系，以及细胞死亡（凋亡与坏死的区别）和细胞自噬；作业是复习后完成课后作业，下节课评讲。", "vtech": [["口诀“一大一小一多三低”", "一大：细胞核体积变大、染色质收缩、染色加深；一小：细胞内水分减少、细胞萎缩、体积变小；一多：细胞内色素（脂褐素）增多；三低：细胞膜物质运输功能降低、多种酶活性降低、代谢速率降低。注意核大与细胞小别记反，酶降低是“多种”不是“所有”。"], ["色素积累≠黑色素", "衰老细胞内积累的是脂褐素（老年斑就是褐色的）；黑色素合成在减少——毛囊黑色素细胞衰老、酪氨酸酶活性下降，酪氨酸转变成黑色素减少，才长白头发。"], ["端粒学说与分裂上限", "端粒是每条染色体两端的特殊DNA序列与蛋白质的复合体；每次分裂端粒缩短一截，短到损伤内侧正常基因序列就衰老；人体细胞通常只能分裂50到60次。端粒只存在于有染色体的细胞中，同种体细胞端粒越长、有丝分裂能力越强。"], ["凋亡vs坏死：两看判断", "一看主动还是被动：凋亡是基因决定的主动结束生命（程序性死亡），坏死是外界不利因素下被动死亡；二看对机体有利还是有害：凋亡有利、坏死有害。易错：被病原体感染的细胞被清除是凋亡，不是坏死。"]], "vgaokao": []}}}, "units": {"u_bio_1": {"id": "u_bio_1", "name": "细胞是生命活动的基本单位", "secs": "第一节", "pageFrom": 2, "pageTo": 8, "members": ["bio_b001", "bio_b002"], "video": {"bvid": "BV1p54y177e6", "p": 1, "t": "细胞是生命活动的基本单位", "dur": "55:24", "from": "锦城大同教育·杨波生物", "vtop": ["细胞学说把动植物统一到细胞层面：一切动植物都由细胞发育而来，但它不涉及原核细胞和病毒。", "病毒没有细胞结构，却必须寄生在活细胞里才能繁殖，这恰恰反证了细胞是生命活动的基本单位。", "生命系统九个层次从细胞起步、到生物圈封顶：最基本的是细胞，种群的判断要同时满足同种、同区域、全部个体。"], "vsum": "本课回答一个根问题：为什么说**细胞是生命活动的基本单位**。先看**细胞学说**：施莱登、施旺提出一切动植物都由细胞发育而来，魏尔肖补充「新细胞由老细胞分裂产生」；学说揭示了细胞的统一性和生物体结构的统一性。再看证据链：单细胞生物一个细胞完成全部生命活动，多细胞生物靠分化细胞协作，**病毒**无细胞结构、必须寄生在活细胞中繁殖。==判断生命活动是否离不开细胞，就抓一条：有没有细胞结构、能不能独立完成生命活动；病毒是反例式特例，离不开活细胞恰恰说明细胞是基本单位。==最后是**生命系统的结构层次**：细胞→组织→器官→系统→个体→种群→群落→生态系统→生物圈。易错提醒：魏尔肖是学说的补充者不是建立者；「一个池塘的全部鱼」不是种群，因为鱼不止一个物种。", "vtech": [["学说内容落笔三句", "看到细胞学说简答题 → 按三句写：一切动植物由细胞发育而来、并由细胞和细胞产物构成；细胞是相对独立的单位；新细胞由老细胞分裂产生。"], ["病毒题先抓结构", "看到病毒相关选项 → 先核三条：无细胞结构、只有核酸加蛋白质外壳、必须寄生在活细胞内，错一条即排除。"], ["层次排序钉两头", "看到结构层次排序题 → 先定最小是细胞、最大是生物圈，再查中间：植物没有系统这一层，单细胞生物一个细胞就是个体。"], ["种群判断三条件", "看到「某区域的全部某种生物」→ 逐项核对同种、同区域、全部个体，缺任何一个都不是种群。"]], "vgaokao": []}}, "u_bio_2": {"id": "u_bio_2", "name": "细胞的多样性和统一性", "secs": "第二节", "pageFrom": 9, "pageTo": 14, "members": ["bio_b003", "bio_b004"], "video": {"bvid": "BV1p54y177e6", "p": 3, "t": "细胞的多样性和统一性", "dur": "91:22", "from": "锦城大同教育·杨波生物", "vtop": ["原核与真核的分界只有一条：有没有以核膜为界限的细胞核；原核细胞只有拟核，细胞器只有核糖体一种。", "高倍镜口诀：低倍找、高倍看，换镜后只动细准焦；放大倍数等于目镜乘物镜，放大的是长度不是面积。", "显微镜成的是倒像：物像偏向哪边，玻片就往哪边移（同向移动），与直觉相反。"], "vsum": "本课两大块：先学**高倍显微镜的使用**，再按有没有真正的细胞核给细胞分类。显微镜抓三件事：结构（目镜、物镜、转换器、粗/细准焦螺旋）、步骤（对光→低倍观察→把像移到中央→转高倍→调细准焦）、成像规律（**倒像**、放大倍数＝目镜×物镜）。==换上高倍镜后视野变暗，只能用细准焦螺旋和反光镜、光圈调，绝不能再动粗准焦——会压碎玻片、丢失物像。==分类部分：**真核细胞**有以核膜为界限的细胞核，**原核细胞**只有**拟核**、只有**核糖体**一种细胞器；原核生物包括细菌、蓝细菌、支原体等。多样性背后是**统一性**：都具细胞膜、细胞质、核糖体，都以 DNA 为遗传物质。易错提醒：蓝细菌能进行光合作用但没有叶绿体；支原体没有细胞壁；病毒没有细胞结构，不属于原核生物。", "vtech": [["高倍镜四步", "看到显微镜操作题 → 按序写：对光、低倍镜下找到物像、把物像移到视野中央、转动转换器换高倍镜后只调细准焦螺旋。"], ["倒像同向移", "看到物像偏在视野左上方 → 玻片也向左上方移动，因为显微镜成倒像，像的移动方向与玻片相反。"], ["分类先看核", "看到细胞分类题 → 先看有无核膜包被的细胞核定真核原核，再验证：细胞器只剩核糖体的是原核细胞。"], ["蓝细菌陷阱", "看到「蓝藻有叶绿体」→ 判错：蓝细菌是原核生物，没有叶绿体，靠含藻蓝素和叶绿素的光合片层进行光合作用。"]], "vgaokao": []}}, "u_bio_3": {"id": "u_bio_3", "name": "细胞中的元素和化合物", "secs": "第一节", "pageFrom": 16, "pageTo": 19, "members": ["bio_b005", "bio_b006"], "video": {"bvid": "BV1p54y177e6", "p": 7, "t": "细胞中的元素和化合物", "dur": "72:32", "from": "锦城大同教育·杨波生物", "vtop": ["元素排序分干重鲜重：含量最高的元素都是 O，最基本元素是 C，基本元素是 C、H、O、N 四个。", "三组鉴定记牢：还原糖配斐林试剂（水浴、砖红色），脂肪配苏丹III（橘黄色），蛋白质配双缩脲试剂（先 A 后 B、紫色）。", "斐林与双缩脲成分相同用法不同：斐林等量混合现配现用，双缩脲先加 NaOH 再加 CuSO4 且不加热。"], "vsum": "本课两段：先认**元素与化合物**的家底，再练**三大有机物的鉴定**实验。元素部分抓排序与分类：**大量元素**（C、H、O、N、P、S、K、Ca、Mg）与**微量元素**（Fe、Mn、Zn、Cu、B、Mo 等）都不可或缺，区别只在含量多少；生物界与非生物界的**统一性**看元素种类、**差异性**看元素含量。==化合物里水含量最高、蛋白质是最多的有机物；三大鉴定实验是本课的得分点：还原糖加斐林试剂水浴出砖红色沉淀，脂肪被苏丹III 染成橘黄色，蛋白质遇双缩脲试剂变紫色。==补讲的金晶生物一集专攻鉴定实验的材料与步骤细节，正好和主讲互补。易错提醒：蔗糖和淀粉不是还原糖、斐林试剂测不出来；双缩脲试剂不加热、不用等量混合出题最爱在这两处设套。", "vtech": [["排序先问干鲜", "看到元素含量排序题 → 先确认是干重还是鲜重再下笔，两个条件下 H、N 的相对位置不同，最容易混。"], ["鉴定先对试剂", "看到鉴定材料题 → 先定检什么：还原糖斐林（水浴）、脂肪苏丹III、蛋白质双缩脲、淀粉碘液，试剂对不上直接排除。"], ["铜试剂辨析三处", "看到斐林与双缩脲比较题 → 抓三处不同：混合方式（等量混合/先 A 后 B）、要不要加热（水浴/不加热）、CuSO4 浓度与滴数。"], ["材料避开颜色", "看到选鉴定材料题 → 还原糖用苹果、梨等近白色材料避开颜色干扰，脂肪用花生种子，蛋白质用豆浆或稀释蛋清。"]], "vgaokao": []}}, "u_bio_4": {"id": "u_bio_4", "name": "细胞中的无机物", "secs": "第二节", "pageFrom": 20, "pageTo": 22, "members": ["bio_b007"], "video": {"bvid": "BV1p54y177e6", "p": 9, "t": "细胞中的无机物", "dur": "45:56", "from": "锦城大同教育·杨波生物", "vtop": ["水是细胞中含量最多的化合物：自由水能流动，结合水被束缚；两者的比值决定代谢强弱，比值高则代谢旺、抗逆差。", "无机盐大多以离子形式存在，三大功能：构成复杂化合物、维持渗透压、维持酸碱平衡。", "晒干种子失去自由水（代谢最低、利于保存，还能萌发），烘烤失去结合水（结构破坏、不能再萌发）。"], "vsum": "本课讲细胞里的两类无机物：**水**和**无机盐**。水按状态分**自由水**（可自由流动，是良好溶剂，参与物质运输和代谢反应）和**结合水**（与其他物质结合，是细胞结构的重要组成成分）。**自由水与结合水的比值**是核心考点：比值升高时代谢旺盛、抗逆性下降；比值降低则相反，种子晒干储存、植物越冬靠的都是比值降低。==判断抗逆性看结合水占比（越高越抗旱抗寒），判断代谢强弱看自由水占比，两个方向正好相反，别记反。==**无机盐**只占 1% 到 1.5%，大多以**离子**形式存在，功能有三：组成复杂化合物（Fe²⁺ 之于血红蛋白、Mg²⁺ 之于叶绿素、I 之于甲状腺激素）、维持**渗透压**、维持**酸碱平衡**。易错提醒：无机盐含量少不等于不重要，缺铁性贫血、地方性甲状腺肿都是缺乏症的典型例子。", "vtech": [["比值题看两头", "看到自由水/结合水比值变化题 → 成对判断：比值升则代谢旺、抗逆弱；比值降则代谢弱、抗逆强。"], ["晒干烘烤分水种", "看到种子处理题 → 晒干去掉的是自由水（还能萌发），烘烤去掉的是结合水（结构破坏、失去萌发力）。"], ["缺乏症对元素", "看到贫血、甲状腺肿、抽搐等症状 → 对应元素定位：Fe 对血红蛋白、I 对甲状腺激素、Ca 对骨骼与抽搐、Mg 对叶绿素。"], ["功能题三分类", "看到无机盐功能选项 → 归到三类里核对：构成化合物、维持渗透压、维持酸碱平衡；供能和储存遗传信息都不是它的功能。"]], "vgaokao": []}}, "u_bio_5": {"id": "u_bio_5", "name": "细胞中的糖类和脂质", "secs": "第三节", "pageFrom": 23, "pageTo": 27, "members": ["bio_b008"], "video": {"bvid": "BV1p54y177e6", "p": 11, "t": "细胞中的糖类和脂质", "dur": "62:47", "from": "锦城大同教育·杨波生物", "vtop": ["糖类按水解分三级：单糖不能水解，二糖水解出两分子单糖，多糖水解出多分子葡萄糖，基本单位都是单糖。", "脂质三类分工：脂肪储能保温，磷脂构成生物膜，固醇分胆固醇、性激素、维生素 D 三类各管一摊。", "储能多糖别混：植物用淀粉、动物用糖原；纤维素是结构物质，人不能消化、不能当能源。"], "vsum": "本课讲两类有机物：**糖类**和**脂质**。糖类由 C、H、O 组成，按水解情况分**单糖**（葡萄糖是主要能源物质，核糖、脱氧核糖是核酸的成分）、**二糖**（蔗糖、麦芽糖、乳糖）和**多糖**（淀粉、糖原、纤维素、几丁质，基本单位都是葡萄糖）。==判断一种糖先分阵营：蔗糖、麦芽糖、淀粉、纤维素是植物专属，乳糖、糖原是动物专属，葡萄糖、核糖、脱氧核糖动植物共有，归属错位就是错误选项。==**脂质**包括脂肪、磷脂和固醇：**脂肪**是良好的储能物质，还能保温、缓冲减压；**磷脂**是细胞膜等生物膜的重要成分；**固醇**中胆固醇构成动物细胞膜并参与脂质运输，性激素促进生殖器官和生殖细胞的形成，维生素 D 促进肠道对钙磷的吸收。易错提醒：同质量的脂肪比糖类放能多，因为脂肪中 H 的比例高、O 的比例低，氧化时耗氧多。", "vtech": [["糖类先分阵营", "看到一种糖的名称 → 先判植物专属、动物专属还是共有，再核对功能，归属与功能错一项即排除。"], ["储能对主语", "看到「主要储能物质」→ 先看主语：植物细胞是淀粉，动物细胞是糖原，生物体层面脂肪是良好的储能物质。"], ["脂质功能对位", "看到脂质功能选项 → 脂肪对储能保温，磷脂对构成膜，固醇三类对膜运输、生殖、钙磷吸收，错位即错。"], ["放能抓元素比例", "看到同质量糖与脂肪的放能比较 → 脂肪含 H 多、含 O 少，氧化分解耗氧多、放能约为糖类两倍以上。"]], "vgaokao": []}}, "u_bio_6": {"id": "u_bio_6", "name": "蛋白质是生命活动的主要承担者", "secs": "第四节", "pageFrom": 28, "pageTo": 33, "members": ["bio_b009"], "video": {"bvid": "BV1p54y177e6", "p": 13, "t": "蛋白质是生命活动的主要承担者", "dur": "105:30", "from": "锦城大同教育·杨波生物", "vtop": ["蛋白质的功能记住口诀“狗催运面条”：结构、催化、运输、免疫、调节，绝大多数酶的化学本质就是蛋白质。", "脱水缩合是本课的计算根基：一个氨基酸的羧基脱 -OH、另一个的氨基脱 -H，脱一分子水、形成一个肽键；脱去水分子数等于肽键数，等于氨基酸数减肽链数。", "算氧原子数抓公式：氧原子数等于肽键数加肽链数乘 2 再加 R 基上的氧原子数；环状肽里氨基酸数、水分子数、肽键数三者相等。"], "vsum": "本课回答一个根问题：蛋白质为什么是**生命活动的主要承担者**，以及相关的数怎么算。先看结构：蛋白质由**氨基酸**构成，氨基酸的中心碳原子上连着**氨基**、**羧基**、氢和 R 基；人体有 8 种**必需氨基酸**必须从食物中获取。功能上抓口诀“狗催运面条”：**结构蛋白**构成细胞与生物体、绝大多数**酶**起催化作用、**血红蛋白**运输氧气、**抗体**抵御病菌、蛋白质还能传递信息、调节生命活动。再看形成：氨基酸通过**脱水缩合**连接，一个羧基脱 -OH、一个氨基脱 -H，脱一分子水、形成一个**肽键**；肽链再盘曲折叠形成**空间结构**，一级到四级逐级复杂。==脱水缩合的数是全部计算的根：脱去水分子数等于肽键数，等于氨基酸数减肽链数；氧原子数等于肽键数加肽链数乘 2 再加 R 基上的氧原子数。==第二讲专攻计算：**相对分子质量**等于氨基酸总质量减 18 乘脱去水分子数；多肽分子式可以列方程反推氨基酸总数与赖氨酸个数；**环状肽**里氨基酸数、水分子数、肽键数三者相等。易错提醒：变性破坏的是空间结构、常不可逆，但盐析只是溶解度变化、加水还能复原；两个肽键的不叫二肽，二肽是由两个氨基酸脱水缩合形成的；A-B 与 B-A 是两种不同的二肽。", "vtech": [["功能题先念口诀", "看到蛋白质功能题 → 先念“狗催运面条”：结构、催化、运输、免疫、调节，五项逐一核对，绝大多数酶是蛋白质、抗体是蛋白质，这两处最爱考。"], ["脱水数先定三数", "看到脱水缩合计算题 → 先定三个数：氨基酸数、肽链数、水分子数，脱去水分子数等于肽键数等于氨基酸数减肽链数，环状肽里三者相等。"], ["氧原子数套公式", "看到氧原子数题 → 套公式：氧原子数等于肽键数加肽链数乘 2 再加 R 基上的氧原子数；问“至少”时 R 基上的氧原子数按 0 算。"], ["二肽题看个数", "看到二肽判断题 → 只数氨基酸个数：两个氨基酸脱水缩合才叫二肽，两个肽键的是三肽；A-B 与 B-A 顺序不同就是两种二肽，不能倒过来看。"]], "vgaokao": []}}, "u_bio_7": {"id": "u_bio_7", "name": "核酸是遗传信息的携带者", "secs": "第五节", "pageFrom": 34, "pageTo": 38, "members": ["bio_b010"], "video": {"bvid": "BV1p54y177e6", "p": 17, "t": "核酸是遗传信息的携带者", "dur": "64:14", "from": "锦城大同教育·杨波生物", "vtop": ["DNA 主要分布在细胞核中、RNA 主要分布在细胞质中，“主要”两个字是考点：两处都有对方的少量分布。", "核苷酸由磷酸、五碳糖、含氮碱基三部分构成；五碳糖是核糖就是核糖核苷酸、是脱氧核糖就是脱氧核苷酸，DNA 与 RNA 的基本单位各四种。", "遗传信息不是遗传物质：核酸是遗传物质，遗传信息是核酸上核苷酸的排列顺序；细胞生物有 8 种核苷酸、5 种碱基，病毒只有 4 种核苷酸、4 种碱基。"], "vsum": "本课回答一个根问题：**核酸**为什么是**遗传信息的携带者**。先看种类与分布：核酸分两类，**DNA**（脱氧核糖核酸）与 **RNA**（核糖核酸）；**DNA 主要分布在细胞核中**（染色体上，线粒体、叶绿体里有少量），**RNA 主要分布在细胞质中**（细胞核里也有少量）。再看结构：核酸的基本单位是**核苷酸**，由**磷酸**、**五碳糖**、**含氮碱基**三部分构成；五碳糖是**核糖**就是核糖核苷酸、是**脱氧核糖**就是脱氧核苷酸；核苷酸之间通过**脱水缩合**连成长链。==DNA 与 RNA 的区别要成串记：DNA 的基本单位是四种脱氧核苷酸、一般是双链的双螺旋结构；RNA 的基本单位是四种核糖核苷酸、一般是单链；DNA 有胸腺嘧啶、RNA 有尿嘧啶，这是两者碱基的唯一不同。==最后是功能与辨析：**核酸是细胞内携带遗传信息的物质**，遗传信息就是**核苷酸的排列顺序**，不要把遗传信息与遗传物质搞混。易错提醒：细胞生物既有 DNA 又有 RNA，核苷酸 8 种、碱基 5 种；DNA 病毒只有 DNA、RNA 病毒只有 RNA，各 4 种核苷酸、4 种碱基；脂肪不是生物大分子，高中阶段的生物大分子只有多糖、蛋白质、核酸三种。", "vtech": [["分布题抓“主要”", "看到 DNA/RNA 分布题 → 先抓“主要”两个字：DNA 主要在细胞核、RNA 主要在细胞质；“主要”意味着另一处也有少量，问“只分布在”时要警惕。"], ["单位题先定五碳糖", "看到核苷酸种类题 → 先定五碳糖：核糖对应核糖核苷酸（RNA）、脱氧核糖对应脱氧核苷酸（DNA）；再按碱基分四种，DNA 有 T 无 U、RNA 有 U 无 T。"], ["种类题按生物分", "看到核苷酸/碱基种类题 → 先按生物分：细胞生物（真核+原核）8 种核苷酸、5 种碱基；DNA 病毒 4 种核苷酸、4 种碱基；RNA 病毒同样 4 种。"], ["遗传信息看顺序", "看到遗传信息题 → 抓排列顺序：遗传信息是核苷酸的排列顺序，不是核酸本身；不同个体的核苷酸种类数目基本相同，区别在排列顺序。"]], "vgaokao": []}}, "u_bio_8": {"id": "u_bio_8", "name": "细胞膜的结构和功能", "secs": "第一节", "pageFrom": 40, "pageTo": 45, "members": ["bio_b011"], "video": {"bvid": "BV1p54y177e6", "p": 19, "t": "细胞膜的结构和功能", "dur": "65:00", "from": "锦城大同教育·杨波生物", "vtop": ["细胞膜的功能高中只考三点：一是将细胞与外界环境分隔开（最重要），二是控制物质进出细胞，三是进行细胞间的信息交流。", "细胞膜的成分记住比例：脂质约占 50%、蛋白质约占 40%、糖类约占 2% 到 10%，基本支架是磷脂双分子层。", "流动镶嵌模型的核心就两点：磷脂双分子层构成基本支架、蛋白质分子镶嵌其中，膜是流动的、不是静止的三层结构。"], "vsum": "本课进入第三章：**细胞的基本结构**，先讲**细胞膜的结构和功能**。功能上高中只考三点，要一字不落背下来：**将细胞与外界环境分隔开**（最重要，正是有了细胞膜，细胞才成为相对独立的系统）、**控制物质进出细胞**（活细胞的细胞膜具有**选择透过性**）、**进行细胞间的信息交流**（三种方式：信号分子与受体结合、细胞膜直接接触如精卵识别、形成通道让携带信息的物质通过）。再看探索历程：欧文顿发现脂溶性物质容易通过细胞，推测膜由脂质组成；制备细胞膜选**哺乳动物成熟的红细胞**，因为它没有细胞壁、没有细胞核和细胞器，吸水涨破后最容易得到纯净的细胞膜。==成分上抓比例与支架：脂质约占 50%、蛋白质约占 40%、糖类约占 2% 到 10%，**磷脂双分子层**构成膜的基本支架，蛋白质分子镶嵌其中，有贯穿、嵌入、覆盖在表面三种位置；糖类与蛋白质结合形成**糖蛋白**，与识别有关。==结构模型上：电镜下看到暗-亮-暗三层结构，罗伯特森据此提出蛋白质-脂质-蛋白质的静态三层模型，但膜不是静止的，1972 年的**流动镶嵌模型**才是正确结论：膜具有**流动性**，注射后不会留下空洞、水分子可以自由通过。易错提醒：构成细胞膜的脂质主要是磷脂，胆固醇也有但不是主要的；细胞膜的控制作用是相对的，不是绝对的。", "vtech": [["功能题背三点", "看到细胞膜功能题 → 背三点：一是将细胞与外界环境分隔开（最重要）、二是控制物质进出细胞、三是进行细胞间的信息交流；换词就可能变意，须一字不落。"], ["成分题抓比例", "看到细胞膜成分题 → 抓比例：脂质约占 50%、蛋白质约占 40%、糖类约占 2% 到 10%；问“基本支架”答磷脂双分子层，问“主要脂质”答磷脂。"], ["模型题看流动", "看到流动镶嵌模型题 → 抓“流动”二字：膜是流动的不是静止的；注射后不留空洞、水分子自由通过，都是流动性的证据；罗伯特森的三层静态模型是错的。"], ["制备题选红细胞", "看到制备细胞膜题 → 选哺乳动物成熟的红细胞：没有细胞壁、没有细胞核、没有细胞器，吸水涨破后最容易得到纯净的细胞膜。"]], "vgaokao": []}}, "u_bio_9": {"id": "u_bio_9", "name": "细胞器之间的分工合作", "secs": "第二节", "pageFrom": 46, "pageTo": 53, "members": ["bio_b012"], "video": {"bvid": "BV1p54y177e6", "p": 21, "t": "细胞器之间的分工合作", "dur": "116:18", "from": "锦城大同教育·杨波生物", "vtop": ["八种细胞器先按膜分三类：双层膜只有线粒体和叶绿体，单层膜是内质网、高尔基体、液泡、溶酶体，无膜只有核糖体和中心体——这张表是全课的骨架，考前先默一遍。", "分泌蛋白的路线只有一条：游离核糖体起头→粗面内质网加工折叠→囊泡→高尔基体再加工→分泌小泡→细胞膜胞吐出去，线粒体只在旁边供能、不直接参与。", "生物膜系统只算细胞内部的膜：原核细胞有细胞膜所以有生物膜、但没有生物膜系统，呼吸道黏膜之类连细胞内部都不是，更不算。"], "vsum": "本课讲第三章第二节，分两讲：第一讲是**细胞器之间的分工**，第二讲是**细胞器之间的协调配合**。开场用 C919 大飞机打比方：造飞机要若干部门分工合作，细胞里也一样，**细胞器**、细胞核这些\"部门\"配合起来完成生命活动。要研究细胞器，先得把它们分开，用的方法是**差速离心法**：先弄破细胞膜，再逐渐提高离心速率，最重的颗粒最先沉到管底，轻的后沉下来。动植物细胞普遍都有的细胞器有四种：**线粒体**、**内质网**、**高尔基体**、**核糖体**。**线粒体**是双层膜细胞器，内膜向内折叠，**有氧呼吸的主要场所**，细胞生命活动所需能量的 95% 都来自它，叫\"动力车间\"；它含少量 DNA、RNA 和核糖体，是**半自主性细胞器**。**核糖体**无膜，由蛋白质和 rRNA 组成、两个亚基，是**生产蛋白质的机器**，氨基酸脱水缩合就在它上面进行；游离核糖体合成胞内蛋白，附着在内质网上的核糖体合成的一般是分泌蛋白。**内质网**是单层膜，粗面内质网附着核糖体、光面内质网不附着，是**蛋白质等大分子物质的合成加工场所和运输通道**，光面内质网还是脂质合成的重要场所。**高尔基体**也是单层膜，扁平囊泡堆叠，对来自内质网的蛋白质**加工、分类和包装**，是\"车间\"也是\"发送站\"，还与溶酶体的形成、植物细胞壁的形成有关，是细胞内起**交通枢纽**作用的细胞器。植物细胞特有的两种：**液泡**是单层膜，里面是细胞液（含糖类、色素、无机盐、蛋白质），功能是储存营养物质、维持渗透压调节细胞内环境、充盈的液泡使植物细胞保持坚挺，成熟植物细胞才有中央大液泡；**叶绿体**是双层膜，基粒上含光合色素，是**光合作用的场所**，叫\"养料制造车间\"和\"能量转换站\"，主要在叶肉细胞和幼嫩的茎皮层细胞里。动物细胞特有的两种：**溶酶体**是单层膜，含多种水解酶，是\"消化车间\"，分解衰老损伤的细胞器、吞噬杀死侵入的病毒病菌、消化胞吞的营养物质，还与细胞自溶有关，它的水解酶由核糖体合成、经内质网和高尔基体加工，膜来自高尔基体；**中心体**无膜，由两个互相垂直的中心粒组成、主要成分是微管蛋白，分布在动物细胞和低等植物细胞中，与**有丝分裂**有关。==八种细胞器按膜一分三类：双层膜（线粒体、叶绿体）、单层膜（内质网、高尔基体、液泡、溶酶体）、无膜（核糖体、中心体），含 DNA 的是线粒体和叶绿体，含色素的是液泡和叶绿体——这张归纳表是全课最常考的点。==细胞里还有**细胞骨架**，由蛋白质纤维组成的网架结构，维持细胞形态、锚定并支撑细胞器，与运动、分裂、分化、物质运输、能量转化、信息传递都有关。易错提醒：哺乳动物成熟的红细胞没有线粒体；有中心体的不一定是动物细胞（低等植物也有）；没有叶绿体的不一定是动物细胞（植物根细胞就没有）；没有大液泡的不一定是动物细胞（幼嫩植物细胞只有小液泡）；溶酶体能储存水解酶但不能合成水解酶。教材实验是用高倍显微镜观察叶绿体和细胞质的流动：叶绿体一般是绿色、扁平椭球形，不用染色就能看到，弱光时以正面受光、强光时以侧面受光防灼伤；以叶绿体的运动为标志观察细胞质流动，细胞质是细胞代谢的主要场所，装片要随时保持有水。第二讲以**分泌蛋白**为例讲协调配合：分泌蛋白是在细胞内合成后分泌到细胞外起作用的蛋白质，包括消化酶、抗体、蛋白质类激素（如胰岛素）三类；相对的是**胞内蛋白**（如血红蛋白、呼吸酶）。科学家用**同位素标记法**研究它的行踪：用有放射性的氚（³H）标记亮氨酸，喂给豚鼠胰腺腺泡细胞，再追踪放射性出现的位置。路线是：**游离核糖体**上以氨基酸为原料合成短肽链→核糖体连同肽链转移到**粗面内质网**，继续合成并进入内质网腔加工折叠→内质网出芽形成**囊泡**运往**高尔基体**进一步修饰加工→高尔基体形成**分泌小泡**运往**细胞膜**，胞吐分泌到细胞外；**线粒体**为全过程供能，是间接参与。三个要扣的点：蛋白质的合成场所只有一个，就是核糖体；所有蛋白质的合成都起始于游离核糖体；内质网加工的是肽链，高尔基体加工的是已有空间结构的蛋白质。过程中三者的膜面积这样变：内质网减小、高尔基体先增大后减小（基本不变）、细胞膜增大。最后是**细胞的生物膜系统**：细胞内全部膜结构（细胞器膜、细胞膜、核膜等）的统称，组成成分和结构都很相似（磷脂双分子层作支架、蛋白质分布其中），功能上紧密联系：细胞膜在物质运输、能量转化、信息传递中起决定性作用并保持内环境稳定，其他膜为酶提供附着位点、把各种细胞器分隔开保证生命活动高效有序；膜与膜之间有直接相连（核外膜—内质网、内质网—细胞膜）和囊泡介导的间接相连（内质网—高尔基体—细胞膜），囊泡往来还能更新膜成分。", "vtech": [["膜分类题先画三行表", "看到问细胞器膜结构的题 → 先画表：双层膜（线粒体、叶绿体）、单层膜（内质网、高尔基体、液泡、溶酶体）、无膜（核糖体、中心体）；再看题问的是哪一行，别把内质网、高尔基体当成双层膜，也别漏了液泡和溶酶体。"], ["分泌蛋白路线题背一句话", "看到分泌蛋白合成运输题 → 背路线：游离核糖体→粗面内质网→囊泡→高尔基体→分泌小泡→细胞膜，线粒体只供能；问\"经过的细胞器\"不能算细胞膜（它不是细胞器），问\"直接参与\"不能算线粒体（它只供能不直接参与）。"], ["\"不一定\"题认两个反例", "看到\"能进行有氧呼吸的细胞一定有线粒体\"或\"能光合作用的细胞一定有叶绿体\" → 直接判错：反例是硝化细菌（有氧呼吸、无线粒体）和蓝细菌（光合作用、无叶绿体）；同样，没有叶绿体的细胞不一定是动物细胞（植物根细胞就没有）。"], ["生物膜系统题先看范围", "看到生物膜系统题 → 先看范围：只算细胞内部的膜（细胞器膜＋细胞膜＋核膜）；原核细胞只有细胞膜，有生物膜、没有生物膜系统；呼吸道黏膜、消化道黏膜是黏膜细胞构成的，不属于生物膜系统。"]], "vgaokao": []}}, "u_bio_10": {"id": "u_bio_10", "name": "细胞核的结构和功能", "secs": "第三节", "pageFrom": 54, "pageTo": 60, "members": ["bio_b013"], "video": {"bvid": "BV1p54y177e6", "p": 25, "t": "细胞核的结构和功能", "dur": "60:40", "from": "锦城大同教育·杨波生物", "vtop": ["细胞核的功能高中只考一句话：细胞核是遗传信息库，是细胞代谢和遗传的控制中心，简称“一库两中心”，四个实验全是为这句话服务的。", "没有细胞核的真核细胞只有两种要记：哺乳动物成熟的红细胞和高等植物成熟的筛管细胞，它们都不能生长、分裂、分化，寿命短；筛管运有机物，导管运水和无机盐，成熟导管是死细胞。", "染色质和染色体是同一种物质在细胞不同时期的两种形态：间期是细丝状的染色质，分裂期高度螺旋化缩短变粗成杆状的染色体，主要成分都是 DNA 和蛋白质。"], "vsum": "本课讲第三章第三节：**细胞核的结构和功能**。开场用克隆牛引出：细胞核由母牛乙提供，小牛性状与母牛乙几乎一样，说明**性状由细胞核决定**。先补一个考点：除了**哺乳动物成熟的红细胞**和**高等植物成熟的筛管细胞**这两种极少数例外，真核细胞都有以核膜为界限的细胞核；没有细胞核的真核细胞不能生长、分裂和分化，也不能长期存在，寿命较短（人的红细胞只有 3 到 4 个月）；筛管细胞运输有机物，导管细胞运输水和无机盐，成熟的导管细胞是死细胞，只剩细胞壁。功能部分用四个实验论证：美西螈核移植证明皮肤颜色的遗传由细胞核控制（但只有一组实验、缺对照组）；蝾螈受精卵横缢证明细胞核与细胞的分裂、分化有关；变形虫切割证明没有细胞核的细胞不能存活、生长和分裂，把核放回去就能恢复；伞藻嫁接与核移植证明伞帽的形状由假根中的细胞核决定。==四个实验合起来只说一句话：细胞核是遗传信息库，是细胞代谢和遗传的控制中心，简称“一库两中心”。==结构部分：**核膜**是双层膜，把核内物质与细胞质分开，外膜与内质网相连；**核孔**是大分子进出细胞核的通道，RNA 和蛋白质能通过，DNA 不能出核，代谢旺盛的细胞核孔数量多；**核仁**与某种 RNA 的合成以及核糖体的形成有关，在细胞分裂过程中会周期性地消失和重现；**染色质**主要由 DNA 和蛋白质组成，呈细丝状，容易被碱性染料染成深色。易错提醒：染色质和染色体是同一种物质在细胞不同时期的两种形态，间期是染色质，分裂期高度螺旋化成染色体，不要当成两种东西。最后讲模型建构：概念模型是用图画等形式直观表达结构特征，数学模型是用坐标图等数学形式描述特征。", "vtech": [["功能题背“一库两中心”", "看到细胞核功能题 → 背一句话：细胞核是遗传信息库，是细胞代谢和遗传的控制中心；四个实验（美西螈、蝾螈横缢、变形虫、伞藻）全是这句话的证据，问“说明了什么”就往这句上靠。"], ["无核细胞题只认两种", "看到没有细胞核的真核细胞题 → 只认两种：哺乳动物成熟的红细胞和高等植物成熟的筛管细胞；它们都不能生长、分裂、分化，寿命短；筛管运有机物、导管运水和无机盐，成熟导管是死细胞。"], ["染色质染色体题看时期", "看到染色质与染色体题 → 看时期：同一种物质，间期是细丝状的染色质，分裂期高度螺旋化成杆状的染色体；主要成分都是 DNA 和蛋白质；问“行使遗传功能的结构”答染色质。"], ["核孔题看进出", "看到核孔题 → 抓进出：核孔是大分子进出细胞核的通道，RNA 和蛋白质能通过，DNA 不能出核；代谢越旺盛的细胞，核孔数量越多、核仁越大。"]], "vgaokao": []}}, "u_bio_11": {"id": "u_bio_11", "name": "被动运输", "secs": "第一节", "pageFrom": 62, "pageTo": 68, "members": ["bio_b014"], "video": {"bvid": "BV1p54y177e6", "p": 27, "t": "被动运输", "dur": "96:52", "from": "锦城大同教育·杨波生物", "vtop": ["渗透作用就两个条件：有半透膜、膜两侧有浓度差（物质的量浓度，也就是渗透压）；液面升高不是水单向跑过去，是单位时间内清水进蔗糖溶液的水比反方向多，双向运动别记反了。", "质壁分离认三个条件：活的、成熟的、植物细胞——根尖分生区细胞太嫩、导管细胞是死细胞，都不能发生；外因是外界溶液浓度大于细胞液浓度，内因是原生质层比细胞壁伸缩性大。", "被动运输只认两句话：顺浓度梯度、不耗能；自由扩散不用转运蛋白、协助扩散要，载体蛋白会结合、会变构像，通道蛋白不结合、不变构像。"], "vsum": "本课讲第四章第一节，分两讲：第一讲是**渗透作用**和水进出细胞的原理，第二讲是**质壁分离实验**和**被动运输**。开场是一个经典的渗透装置：长颈漏斗口蒙一层玻璃纸（赛璐玢，一种**半透膜**），里面装蔗糖溶液，倒置浸入清水，漏斗管里的液面过一段时间会升高。**半透膜**只允许离子和小分子（如水、单糖）通过，蔗糖这样的大分子过不去。**渗透作用**就是水分子或其他溶剂分子通过半透膜的扩散，是一种特殊的扩散作用，发生要两个条件：**有半透膜**，**膜两侧有浓度差**。这里的浓度指的是物质的量浓度，实质上就是**渗透压**：单位体积溶液中溶质微粒越多，渗透压越大。液面为什么升高？水分子是**双向运动**的，但单位时间内由清水进入蔗糖溶液的水分子数多于反方向的，所以蔗糖溶液体积增大、液面升高；液面不会无限升高，因为上升的水柱产生压力、加快水向外扩散，最终进出相等、达到**动态平衡**，此时两侧溶液浓度仍不相等。用纱布代替玻璃纸就不行（纱布是全透膜），烧杯里换成等浓度蔗糖溶液也不行（没有浓度差）。水进出细胞的原理同样是渗透作用。动物细胞把**细胞膜**当作半透膜：外界溶液浓度小于细胞质浓度时吸水膨胀、甚至胀破，大于时失水皱缩，等于时保持正常形态；注意这里说的浓度是**溶质的浓度**，水是从溶质低浓度往高浓度走，也就是从水相对含量高的一侧往低的一侧走，两句话并不矛盾。植物细胞的细胞壁是全透的，不能当半透膜；成熟植物细胞把**原生质层**（细胞膜＋液泡膜＋之间的细胞质）当作半透膜，比较的是**细胞液**（特指液泡里的液体）的浓度与外界溶液的浓度：吸水时中央液泡变大、细胞变得坚挺（细胞壁伸缩性小，体积不会大多少）；失水时液泡变小，**原生质层**与细胞壁分离，就是**质壁分离**。==质壁分离的原因就两点：外因是外界溶液浓度大于细胞液浓度，内因是原生质层的伸缩性大于细胞壁——而能发生质壁分离的必须是活的、成熟的植物细胞，根尖分生区细胞太嫩、导管细胞是死细胞，都不能发生。==教材实验是探究植物细胞的吸水和失水，材料是**洋葱鳞片叶外表皮**（紫色大液泡、单层细胞，细胞液有颜色才好看）：先在低倍镜下看正常形态，再用引流法滴加 **0.3 g/mL 蔗糖溶液**，看到液泡逐渐变小、紫色逐渐加深、原生质层与细胞壁分离；再滴加清水，液泡变大、紫色变浅、原生质层复贴，就是**质壁分离的复原**。全程都在低倍镜下观察，选定一个视野后不能移动装片，因为实验遵循**自身前后对照**。浓度要适中：3 g/mL 太浓会让细胞过度失水死亡、看不到复原；0.5 g/mL 也偏大，同样会致死。这个实验有三个应用：判断细胞死活、测定细胞液浓度范围（介于未发生与刚发生质壁分离的外液浓度之间）、比较不同植物细胞的细胞液浓度（发生质壁分离所需时间越短，细胞液浓度越小）。还有一种**自动复原**：用适宜浓度的硝酸钾溶液，不加清水也会自己复原，因为细胞主动吸收了 K⁺ 和 NO₃⁻，细胞液浓度变大就吸水了；葡萄糖、醋酸钾、甘油、尿素溶液里也会这样——溶质分子比水分子大得多，一开始只有水在动，溶质进得慢，所以先分离、后复原。第二讲的重点是**被动运输**：物质以扩散方式进出细胞，**不消耗能量**，方向是**顺浓度梯度**（从浓度高往浓度低），动力就是浓度梯度。分两种：**自由扩散**（也叫简单扩散），物质直接穿过磷脂分子之间的间隙，如氧气、二氧化碳等气体，甘油、乙醇、苯等脂溶性小分子有机物，还有少部分水；**协助扩散**（也叫易化扩散），需要借助膜上的**转运蛋白**，如离子和小分子有机物（葡萄糖进入红细胞就是协助扩散），大部分水也是这样进出细胞的（靠水通道蛋白）。注意葡萄糖进入大多数动物细胞是协助扩散，但肾小管细胞和小肠上皮细胞吸收葡萄糖是主动运输，下一课再讲。转运蛋白分两种：**载体蛋白**只容许与自身结合部位相适应的分子或离子通过，结合是暂时的、可分离的，每次转运自身构像都会改变，选择性很高；**通道蛋白**只容许与通道直径和形状相适配、大小和电荷相适宜的分子或离子通过，通过时不与通道蛋白结合、自身构像不变，分水通道蛋白和离子通道蛋白，选择性是相对的（钠离子通道有时也能让铵根离子通过），所以载体蛋白的选择性比通道蛋白强。影响被动运输的因素有三点：膜内外物质浓度梯度、转运蛋白的数量（只影响协助扩散）、温度（一定范围内升高则速率增大，过高会破坏膜结构）。三幅坐标图要会看：自由扩散的速率与浓度差成正比；协助扩散的速率先升后平，因为转运蛋白会饱和；被动运输不耗能，所以速率与能量供应无关。易错提醒：同种物质的运输方式可能不同（水、葡萄糖都是例子）；质壁分离复原后细胞液的浓度不等于外界溶液浓度（复原用的是清水，浓度更小）；只给一张质壁分离的静态图，判断不了当时细胞液与外界溶液谁的浓度大。", "vtech": [["渗透装置题先看两个条件", "看到漏斗、U形管这类渗透装置题 → 先看两个条件：有没有半透膜（纱布是全透膜，不算）、膜两侧有没有浓度差（等浓度不发生表观渗透）；再看水往哪走：从溶质低浓度往高浓度走，也就是从水相对含量高的一侧往低的一侧走，液面升高是因为单位时间内进来的水比出去的多。"], ["质壁分离题先认三个条件", "看到质壁分离题 → 先认三个条件：活的、成熟的、植物细胞；再分外因（外界溶液浓度＞细胞液浓度）和内因（原生质层伸缩性＞细胞壁）；做题时注意：只给一张静态图，判断不了当时细胞液和外界溶液谁的浓度大；复原后细胞液浓度也不等于外界溶液浓度。"], ["自动复原题认溶质被吸收", "看到质壁分离后没加清水就自己复原 → 想溶质被吸收：硝酸钾、葡萄糖、甘油、尿素等溶液中，细胞会主动或被动吸收溶质，细胞液浓度变大就吸水复原；一开始只有水在动，溶质分子大、进得慢，所以先分离、后复原。"], ["自由扩散协助扩散题看转运蛋白", "看到问运输方式的题 → 先看要不要转运蛋白：不要的是自由扩散（气体、甘油、乙醇、苯、少部分水），要的是协助扩散（离子、葡萄糖进红细胞、大部分水）；载体蛋白要结合、会变构像、选择性强，通道蛋白不结合、不变构像、选择性相对弱。"]], "vgaokao": []}}, "u_bio_12": {"id": "u_bio_12", "name": "主动运输与胞吞、胞吐", "secs": "第二节", "pageFrom": 69, "pageTo": 74, "members": ["bio_b015"], "video": {"bvid": "BV1p54y177e6", "p": 31, "t": "主动运输与胞吞、胞吐", "dur": "43:44", "from": "锦城大同教育·杨波生物", "vtop": ["主动运输就三要素：逆浓度梯度、载体蛋白、耗能——判题先看方向，离子和葡萄糖两种方式都可能走。", "胞吞胞吐运大分子，不走转运蛋白、要耗能，物质穿过 0 层膜；能证明膜有流动性，不能证明选择透过性。", "氧气浓度曲线：O₂=0 时主动运输仍有速率（无氧呼吸供能），B 点后不再升是载体蛋白饱和了。"], "vsum": "本课讲第四章第二节，分两讲：第一讲是**主动运输**，第二讲是**胞吞和胞吐**。开场先看教材例子：人体合成甲状腺激素需要**碘**，甲状腺滤泡上皮细胞内的碘浓度比血液中高 20 到 25 倍，细胞要从低浓度的血液里把碘运进高浓度的细胞内，这是**逆浓度梯度**的运输，不可能是顺浓度梯度的被动运输，只能是**主动运输**。主动运输的定义是：物质**逆浓度梯度**进行跨膜运输，需要**载体蛋白**的协助，同时需要消耗细胞内化学反应所释放的**能量**（如 ATP）。==主动运输就三要素：逆浓度梯度、载体蛋白、耗能，缺一个都不算。==注意只能说载体蛋白，不能说转运蛋白——转运蛋白还包括通道蛋白，主动运输不用通道蛋白。实例：**K⁺、Ca²⁺、Na⁺** 等离子逆浓度梯度时是主动运输，顺浓度梯度时就是协助扩散，只看离子种类会错，必须看方向；**小肠上皮细胞**从小肠液中吸收葡萄糖和氨基酸、**肾小管上皮细胞**吸收葡萄糖，都是主动运输。主动运输的意义是**主动选择吸收所需要的物质**、排出代谢废物和对细胞有害的物质，保证细胞和个体生命活动的需要。易错提醒三则：①相对分子质量小的物质和离子不一定都能自由扩散进细胞，离子运输一定需要转运蛋白，要么主动运输、要么协助扩散；②葡萄糖不一定都以协助扩散进入细胞，小肠和肾小管吸收葡萄糖是主动运输；③主动运输的结果是**加大膜内外浓度差**，不是让浓度趋于相等。第二讲是胞吞和胞吐：小分子、离子走主动运输和被动运输，**大分子物质**只能靠胞吞、胞吐进出细胞。**胞吞**是大分子与膜上的蛋白质结合，引起这部分细胞膜内陷形成小囊，囊泡从细胞膜上分离下来进入细胞内；这个过程有**选择性**，只有细胞需要的物质才会被包进来，靠膜上的蛋白质识别；吞进来的吞噬泡（吞饮泡）与**溶酶体**融合，水解酶把大分子消化成小分子再利用。**胞吐**是细胞需要外排的大分子先在细胞内形成囊泡，移动到细胞膜处融合，把大分子排出细胞，**分泌蛋白**就是这样分泌出去的。胞吞胞吐有四个特点：①主要运输大分子物质（蛋白质、多糖等），某些小分子也可以；②不需要载体蛋白、通道蛋白的协助，但需要膜上特定蛋白质的参与；③需要消耗能量；④依赖膜的流动性。==胞吞胞吐能证明膜有流动性，但不能证明选择透过性：物质是被膜包着进出的、没有直接穿过膜，穿过 0 层膜，透过性那一半体现不出来。==问题探究：游离于细胞质基质中的核糖体合成的是**胞内蛋白**，供细胞自身使用，因为蛋白质是大分子、穿不了膜，只能留在细胞内；附着在内质网上的核糖体合成的是**分泌蛋白**，进内质网腔加工→囊泡→高尔基体加工分类包装→囊泡→细胞膜胞吐出去。最后讲影响物质跨膜运输的因素和曲线分析：**物质浓度**——自由扩散的速率与浓度成正比一直上升；协助扩散和主动运输先升后平，因为转运蛋白数量有限、达到饱和后速率不再增加。**氧气浓度**——氧气影响呼吸速率、进而影响供能多少；被动运输不耗能，速率是一条水平直线；主动运输随氧气浓度增加先升后平，氧气浓度为 0 时仍有速率，靠**无氧呼吸**供能，B 点后不再升是**载体蛋白数量**饱和了。**温度**——影响膜的流动性，也影响酶的活性、进而影响呼吸速率和供能。总结：被动运输和主动运输运的都是小分子物质和离子，胞吞胞吐主要运大分子；被动运输顺浓度梯度、不耗能，自由扩散不用转运蛋白、协助扩散用转运蛋白（载体蛋白或通道蛋白）；主动运输逆浓度梯度、要载体蛋白、耗能；胞吞胞吐不走转运蛋白、要耗能。教材练习要点：果脯在腌制中慢慢变甜，是细胞死亡、膜失去选择透过性变成全透性，蔗糖自由进入，不是主动运输；脂溶性小分子易自由扩散进出细胞；葡萄糖进入红细胞要转运蛋白、不耗能，是协助扩散；大肠杆菌吸收 K⁺ 既耗能又要载体蛋白，是主动运输；胃蛋白酶原这类大分子运出细胞是胞吐；萎蔫菜叶放清水恢复含水量，靠水自由扩散和协助扩散；需要载体蛋白的是 K⁺ 被小肠绒毛上皮细胞吸收。", "vtech": [["判主动还是协助扩散，先看浓度方向", "看到离子或葡萄糖的运输题 → 先判方向：逆浓度梯度就是主动运输，顺浓度梯度就是协助扩散；别只看物质种类——K⁺、Ca²⁺、Na⁺、葡萄糖两种方式都可能走，方向才是判据。"], ["氧气浓度曲线：A 点和 B 点各看什么", "O₂=0 时主动运输速率不为零 → 靠无氧呼吸供能；B 点后速率不再升 → 载体蛋白数量饱和了；被动运输的曲线是水平直线，因为它不耗能。"], ["胞吞胞吐能不能体现选择透过性", "能体现流动性，不能体现选择透过性：胞吞有选择性（膜上蛋白质识别），但物质没有直接穿过膜、穿过 0 层膜，所以透过性那一半体现不出来。"], ["易错三句话先背下来", "小分子、离子不一定自由扩散（离子必须走转运蛋白）；葡萄糖不一定协助扩散（小肠、肾小管吸收葡萄糖是主动运输）；主动运输是加大膜内外浓度差，不是让浓度趋于相等。"]], "vgaokao": []}}, "u_bio_13": {"id": "u_bio_13", "name": "降低化学反应活化能的酶（上）：酶的作用和本质", "secs": "第一节", "pageFrom": 76, "pageTo": 79, "members": ["bio_b016"], "video": {"bvid": "BV1p54y177e6", "p": 33, "t": "降低化学反应活化能的酶（上）：酶的作用和本质", "dur": "50:36", "from": "锦城大同教育·杨波生物", "vtop": ["酶的作用原理只有一句：降低化学反应的活化能——酶本身不被消耗、不提供物质和能量、不改变反应方向和生成物量。", "比较过氧化氢分解实验要会背四支试管：常温几乎无气泡、加热较少、氯化铁较多、肝脏研磨液大量气泡，结论是酶有催化作用且效率高于无机催化剂。", "实验题先分清三种变量：自变量是人为处理步骤，因变量是过氧化氢分解速率，其余都是无关变量、控制要相同且适宜。"], "vsum": "本课讲第五章第一节，分两部分：第一部分是**酶在细胞代谢中的作用**，第二部分是**酶的本质**。开场先看教材例子：1773 年意大利科学家斯帕兰扎尼把肉块放进小巧的金属笼，让鹰吞下去，过一段时间取出来，肉块消失了。三个讨论：①为什么把肉块放进金属笼？胃有机械消化，金属笼是防止胃的机械性消化干扰实验；②什么物质使肉块消失了？消化道里的消化液，更准确地说是消化液中的各种**消化酶**；③怎样证明？直接提取消化液，放入肉块，观察肉块体积是否减小甚至消失。先讲**细胞代谢**：细胞中每时每刻都进行着的许多化学反应的统称，细胞的生活需要物质和能量，能量的释放、储存和利用都离不开这些化学反应。细胞代谢的**主要场所是细胞质基质**，**控制中心是细胞核**，它是细胞生命活动的基础。代谢会产生有害物质，比如**过氧化氢**，大量积累会毒害细胞，肝脏细胞里有较多的**过氧化氢酶**能把它分解掉。教材实验是比较过氧化氢在不同条件下的分解：四支试管都加 2 mL 过氧化氢溶液，1 号常温放置，几乎没有气泡；2 号 90℃ 左右水浴加热，较少气泡；3 号加 2 滴氯化铁溶液（**无机催化剂**，起作用的是 Fe³⁺），较多气泡；4 号加 2 滴新鲜肝脏研磨液（里面含过氧化氢酶），大量气泡。结论有两个：**酶具有催化作用**；同无机催化剂相比，**酶的催化效率更高**。衡量分解速率的指标不唯一：可以直接观察气泡产生量，也可以用带火星的卫生香（或木条）伸入试管看复燃情况——1 号、2 号不复燃，3 号发亮但不复燃，4 号复燃。实验里变量分三种：**自变量**是人为控制的、对实验对象进行处理的因素，本实验就是加热、加氯化铁、加肝脏研磨液这些处理步骤；**因变量**是因自变量改变而变化的变量，本实验是过氧化氢的分解速率；**无关变量**是除自变量外、会对实验结果造成影响的可变因素，比如肝脏研磨液的新鲜程度、底物的量和浓度、实验室温度等，控制时要**相同且适宜**——只相同还不够，量太少会看不出差别，实验就做不下去。**对照实验**是除自变量外其余因素都保持一致、并将结果进行比较的实验，要设对照组和实验组；**单一变量原则**是实验组和对照组只有一个变量在变，这样结果不同才能确定是这个变量造成的；**等量性原则**和单一变量原则说的是同一个东西，侧重点不同——等量性原则强调除自变量外的无关变量必须相等且适宜；还有**平行重复原则**，以后遇到再讲。对照实验有四种类型：**空白对照**是不给对照组做任何实验处理，本实验的 1 号试管就是空白对照；**自身对照**是对照组和实验组在同一个研究对象上进行，比如观察植物细胞质壁分离及复原；**条件对照**是给对照组施以某种实验处理，但这种处理是作为对照因素、不是所要研究的实验因素；**相互对照**是不设对照组、几个实验组之间相互对照，比如散枣嫁接实验。接着讲酶的作用原理：先记**活化能**——分子从常态转变为容易发生化学反应的活跃状态所需要的能量。酶的作用原理就是**降低化学反应的活化能**：看能量-反应过程曲线图，三条曲线是同一个反应，最上面是没有加催化剂的，中间是加无机催化剂的，最下面是加酶的；酶降低的活化能最多，所以催化效率最高。考试常问酶降低的活化能是多少：没加酶时活化能是 E₂，加酶后是 E₃，酶降低的活化能是 **E₂−E₃**，别和加酶后反应所需要的活化能 E₃ 弄混。还有一个重要结论：**酶本身不被消耗、不为化学反应提供物质和能量、也不改变反应的方向和生成物的量**，只改变反应速率——三条曲线的起点和终点都一样。加热也能加快反应，但原理不同：**加热不能降低活化能**，它是增加分子内能、给分子提供能量、增加活化分子数，相当于给汽车加油门，而加催化剂是给大山挖隧道。易错提醒四则：①酶能提高活化能——错，是降低；②酶使过氧化氢得到了能量——错，酶不提供物质和能量；③无关变量与实验结果无关——错，无关变量会影响结果；④因变量的检测指标往往不是唯一的——对，气泡量和卫生香复燃都可以。第二部分讲酶的本质，探索历程要按顺序记：最初人们认为发酵是纯化学过程，与生命活动无关；**巴斯德**认为发酵由酵母菌细胞的存在所致、需要活细胞参与；化学家**李比希**认为引起发酵的是酵母菌细胞中的某些物质，但只有在酵母菌细胞死亡并裂解后才能发挥作用；**毕希纳**发现酵母菌细胞中的某些物质在酵母菌破碎后仍能继续起催化作用；**萨姆纳**从刀豆种子中提取出脲酶，证明脲酶是蛋白质；**切赫和奥特曼**发现少数 RNA 也具有生物催化功能。结论：**绝大多数酶是蛋白质，少数酶是 RNA**；酶由活细胞产生，一般来说活细胞都能产生酶；作用场所不局限，细胞内、细胞外、体内、体外都能起作用。易错提醒五则：①酶的基本组成单位是氨基酸——不完整，RNA 酶的基本单位是核糖核苷酸；②只有具有分泌功能的细胞才能产生酶——错，一般活细胞都能产生；③酶只能在细胞内起作用——错，内外、体内外都行；④酶在反应完成后立即被降解成氨基酸——错，酶可以反复利用；⑤酶具有催化、调节等多种功能——错，只有催化，没有调节。教材练习：①关于酶的特点及本质，选 D——酶是具有催化作用的有机物（蛋白质和 RNA 都是有机物）；②与无机催化剂相比，酶的特点是催化化学反应更高效。", "vtech": [["自变量、因变量、无关变量怎么分", "看到实验题 → 先找人为改变的处理步骤，那是自变量；因自变量改变而变化的量是因变量；其余会干扰结果的量都是无关变量，答题要写“相同且适宜”，只写相同不够。"], ["对照实验四种类型，先认空白对照和自身对照", "空白对照是不给对照组做任何处理（如本实验的 1 号试管）；自身对照是同一对象前后对比（如质壁分离及复原）；条件对照和相互对照考得少，遇到再按定义判。"], ["酶降低的活化能怎么算", "没加酶时活化能是 E₂，加酶后是 E₃，酶降低的活化能是 E₂−E₃；别和“加酶后反应所需要的活化能 E₃”弄混；三条曲线起点终点相同，说明酶不改变反应方向和生成物量。"], ["酶的本质与易错点", "绝大多数酶是蛋白质、少数是 RNA；酶由活细胞产生、内外体内外都能起作用、可反复利用；易错：基本组成单位要分蛋白质酶（氨基酸）和 RNA 酶（核糖核苷酸）两种情况答。"]], "vgaokao": []}}, "u_bio_14": {"id": "u_bio_14", "name": "降低化学反应活化能的酶（下）：酶的特性", "secs": "第一节", "pageFrom": 80, "pageTo": 85, "members": ["bio_b017"], "video": {"bvid": "BV1p54y177e6", "p": 35, "t": "降低化学反应活化能的酶（二）", "dur": "71:25", "from": "锦城大同教育·杨波生物", "vtop": ["过酸、过碱或温度过高都会破坏酶的空间结构使酶永久失活，而且高温失活不可逆，低温只降低活性、升温后活性可以恢复。", "酶制剂适宜低温保存（常用0–4℃，长期保存-20～-80℃），绝不能保存在最适温度下，否则活性会白白流失。", "探究温度或pH对酶活性影响时，选材要排除自变量自身对结果的影响：温度实验不用过氧化氢酶，pH实验不用淀粉酶。"], "vsum": "本课是第五章第一节的第二课时，继续讲**降低化学反应活化能的酶**。开场先回顾上节课：**酶是活细胞产生的、具有催化作用的有机物**，一般来说活细胞都能产生酶，因为活细胞内的化学反应几乎都需要酶来起催化作用；酶的化学本质绝大多数是**蛋白质**，少数是**RNA**，不论哪种都属于有机物。接着讲酶的三个特性。第一个特性是**高效性**：和无机催化剂相比，酶的催化效率更高——过氧化氢酶催化过氧化氢分解的实验里，加酶的一组过氧化氢分解速率更快、产生的氧气也更多；原因是酶比无机催化剂更显著地**降低化学反应的活化能**，酶的催化效率是无机催化剂的**10的7次方到10的13次方倍**。第二个特性是**专一性**：每一种酶只能催化**一种或者一类**化学反应，比如过氧化氢酶只能催化过氧化氢分解，科学家从刀豆种子中提取的**脲酶**只能催化尿素分解为氨和二氧化碳；无机催化剂则没有专一性，比如酸既能催化蛋白质水解，也能催化脂肪和淀粉的水解。第三个特性是**作用条件较温和**：酶所催化的化学反应条件比较温和，**过酸、过碱或者温度过高都会破坏酶的空间结构**，使蛋白质变性、酶永久失活——因为绝大多数酶的化学本质是蛋白质，而过酸、过碱或高温都会破坏蛋白质的空间结构。**低温**则不一样：低温只使酶的活性降低，不破坏空间结构，酶不会失活，升到适宜温度后活性还能恢复；所以**酶制剂适宜在低温下保存**，随取随用的一般保存在**0到4摄氏度**，需要长期保存的保存在**-20到-80摄氏度**。接着讲温度对酶活性的影响：横坐标是温度、纵坐标是反应速率（可以反映酶活性的大小），曲线先升后降；**在一定条件下酶活性最大时的温度称为该酶的最适温度**，达到最适温度之前，酶促反应速率随温度升高而加快，超过最适温度后随温度升高而下降；高温段的曲线会与横坐标相交（反应速率为零，说明酶已变性失活），低温段没有交点；高温变性失活后即使再降温，活性也**无法恢复**。补充不同生物的最适温度：动物体内酶的最适温度一般在**35到40摄氏度**，接近动物的正常体温，所以发高烧时体内消化酶活性下降，会食欲不振、消化不良；植物体内酶的最适温度是**40到50摄氏度**，比动物稍高；细菌、真菌体内酶的最适温度相差很大，有的甚至可达**70摄氏度**，这是长期进化的结果。再讲pH对酶活性的影响：曲线同样先升后降，**酶活性最大时对应的pH称为该酶的最适pH**，pH偏高或偏低，酶促反应速率都会明显降低；过酸或过碱同样会破坏酶的空间结构，导致酶永久失活；动物体内酶的最适pH一般在**6.5到8.0**之间，植物体内酶一般在**4.5到6.5**，但有特例——**胃蛋白酶**存在于胃酸中，它的最适pH约为**1.5**。细胞内各项生命活动能有序进行，除了适宜的温度和pH，还与酶的分布有关：比如绿色植物叶肉细胞中，与光合作用有关的酶分布在叶绿体里，与呼吸作用有关的酶分布在线粒体和细胞质基质里。接着是判断题练习：二肽酶只能催化二肽的水解，不能催化三肽、四肽、五肽等其他肽的水解，体现了专一性（催化一类反应）；催化脂肪水解的酶应该是脂肪酶，说成蛋白酶是错的；酶在最适温度下活性最高是对的，但说酶适合在最适温度下保存是错的——最适温度下酶活性高，不用它催化反应时活性会白白流失，所以要低温保存。接下来是实验设计，这是本课的难点。**高效性**的实验设计思路：遵循对照原则，实验组在底物中加酶（生物催化剂），对照组加无机催化剂，一段时间后比较底物分解速率或产物生成速率。**专一性**的实验设计有两种方法：一是相同的酶、不同的底物（酶A能分解底物A、不能分解底物B）；二是相同的底物、不同的酶（酶A能分解底物A、酶B不能分解底物A）。具体例子用淀粉酶对淀粉和蔗糖的水解：试管一加2毫升可溶性淀粉溶液，试管二加2毫升蔗糖溶液，量相同（无关变量相同且适宜），淀粉和蔗糖都是非还原糖，分解后都产生还原糖，可用**斐林试剂**检测，出现砖红色沉淀说明分解了；不能用碘液代替斐林试剂——碘液只能和淀粉发生颜色反应，蔗糖和它的分解产物果糖、葡萄糖都不会和碘液发生颜色反应，蔗糖分解与否都看不出来。然后是**探究温度对酶活性的影响**的实验：原理是温度影响淀粉酶的活性，从而影响淀粉的水解速率，淀粉遇碘液变蓝，可根据是否出现蓝色以及蓝色的深浅判断酶活性；实验设三组，分别放在冰水（0摄氏度）、60摄氏度的温水和沸水（100摄氏度）中；做法是取两支试管，一支装2毫升淀粉酶溶液、一支装2毫升可溶性淀粉溶液，先分别在设定温度下水浴保温5分钟，再混合摇匀、继续保温数分钟，然后取出滴加碘液观察；一定要先分别保温再混合，因为酶促反应速度很快，先混合再保温可能还没放进冰水反应就完了，要保证反应开始时就是在设定的温度下进行；结果是60摄氏度组无蓝色（淀粉被完全分解），冰水组和沸水组呈蓝色，结论是酶发挥催化作用需要适宜的温度，温度过高或过低都会影响酶活性。做这个实验还要注意：自变量是温度，pH是无关变量，要保持相同且**适宜**（调到最适pH，不能调到0.1这种不适宜的值）；不能用斐林试剂检测，因为斐林试剂鉴定还原糖需要水浴加热，会改变设定好的温度；也不能用过氧化氢和过氧化氢酶做材料，因为加热本身就会促进过氧化氢分解，分不清氧气增多是酶活性增加还是温度升高的结果。接着是**探究pH对酶活性的影响**的实验：用过氧化氢酶分解过氧化氢，产生水和氧气，通过氧气产生量判断分解速率和酶活性；设三组，一号试管加1毫升蒸馏水（中性），二号加1毫升盐酸（酸性），三号加1毫升氢氧化钠（碱性），每支试管先注入等量的过氧化氢酶（2滴）；关键是先把酶溶液调节到实验要求的pH再与反应底物混合，不能先混合再调pH——先混合的话过氧化氢酶可能已经把过氧化氢全部分解完了，再调pH不起作用；结果是中性试管有大量气泡，过酸、过碱的试管没有气泡，结论是酶发挥催化作用需要适宜的pH，pH偏高或偏低都会影响酶活性。思考题：探究pH对酶活性的影响时不能用淀粉酶分解淀粉的实验，因为酸性条件下淀粉本身就会发生水解；这里要记住选材原则——**选择实验材料时注意排除自变量自身对实验结果的影响**，探究温度不用过氧化氢酶、探究pH不用淀粉酶，都是这个道理。接着是几组**曲线分析**：第一组是高效性的曲线，横坐标是时间，纵坐标是反应达到平衡的情况，加酶的反应最先达到平衡，加无机催化剂的次之，不加催化剂的最慢，但三者最终都达到同一个平衡点——酶只能缩短达到化学平衡所需要的时间，**不能改变化学反应的平衡点，也不能改变生成物的量**；第二组是专一性的曲线，横坐标是底物A的浓度，酶B不能催化底物A，速率与未加酶时一样；第三组是底物浓度对酶促反应速率的影响，底物浓度较低时速率与底物浓度成正比，超过一定范围后速率不再随底物浓度增加而加快，此时的限制因素是**酶的数量**，和协助扩散中转运蛋白数量限制速率是一个道理；第四组是酶浓度的影响，底物充足时酶促反应速率与酶浓度成正比，适量增加酶浓度反应速率加快但生成物量不变，适量增加底物浓度反应速率加快且生成物量也增加。最后要分清两类影响因素：温度和pH是通过影响**酶活性**来影响酶促反应速率的，酶浓度和底物浓度不影响酶活性，而是通过影响底物与酶的接触来影响酶促反应速率。课末是易错提醒与教材练习题：酶促反应速率既可以用反应物消耗速率表示，也可以用产物生成速率表示；探究pH的实验不选淀粉做材料是因为酸能促进淀粉水解；探究影响酶活性的条件至少要设置三组实验；同一种酶取自不同细胞时最适温度可能不一样，比如市售α-淀粉酶是从细菌细胞中提取的，和人体唾液淀粉酶的最适温度就有差别；教材练习题里，嫩肉粉起作用的是蛋白酶（肌肉组织主要由蛋白质构成），新鲜糯玉米85摄氏度热烫2分钟能保持甜味是因为加热破坏了将可溶性糖转化为淀粉的酶的活性，去除植物细胞壁用纤维素酶（细胞壁的成分是纤维素和果胶），酶活性与温度的关系图里T2时反应活化能是最低的（不是最高），最适温度下从A点升温10摄氏度酶活性降低、反应速率下降，在B点加入少量同样的酶反应速率会提高。最后总结：本课讲了酶的三个特性、影响酶活性的温度和pH条件，以及怎样设计实验探究高效性、专一性和作用条件，课后作业是完成课后作业18。", "vtech": [["最适温度、最适pH：两个定义一个套路", "在一定条件下酶活性最大时对应的温度叫最适温度，对应的pH叫最适pH；低于最适值时酶促反应速率随温度或pH升高而加快，超过后随之下降，两条曲线都是先升后降；过酸、过碱或温度过高都会破坏酶的空间结构，导致酶永久失活。"], ["三组最适值数字：动物、植物与胃蛋白酶", "动物体内酶最适温度一般35–40℃（接近正常体温），植物体内酶40–50℃，细菌、真菌体内酶有的可达70℃；动物体内酶最适pH一般6.5–8.0，植物体内酶4.5–6.5，胃蛋白酶最适pH约1.5是特例——它存在于胃酸中。"], ["温度实验：三组温度与“分别保温再混合”", "三组分别放在冰水0℃、60℃温水和沸水100℃中，淀粉酶溶液与可溶性淀粉溶液各取2毫升，先分别在设定温度下水浴保温5分钟再混合摇匀；先混合再保温是错的——酶促反应快，还没放进冰水反应可能已经完了；结果60℃组滴碘液无蓝色（淀粉被完全分解），冰水组和沸水组呈蓝色。"], ["酶浓度、底物浓度：速率变，生成物量未必变", "底物充足时酶促反应速率与酶浓度成正比，适量增加酶浓度速率加快但生成物量不变；适量增加底物浓度速率加快且生成物量也增加；底物浓度较低时速率与底物浓度成正比，超过一定范围后限制因素是酶的数量；酶只能缩短达到化学平衡的时间，不能改变化学平衡点和生成物量。"]], "vgaokao": []}}, "u_bio_15": {"id": "u_bio_15", "name": "细胞的能量“货币”ATP", "secs": "第二节", "pageFrom": 86, "pageTo": 89, "members": ["bio_b018"], "video": {"bvid": "BV1p54y177e6", "p": 37, "t": "细胞的能量“货币”ATP", "dur": "48:56", "from": "锦城大同教育·杨波生物", "vtop": ["ATP 是细胞的直接能源物质，不是主要的能源物质——主要的能源物质是糖类，ATP 只是直接供能。", "结构简式 A—P～P～P 用口诀“123”记：1 个腺苷、2 个高能磷酸键、3 个磷酸基团。", "ATP 与 ADP 的转化不是可逆反应：物质上可逆、能量上不可逆，合成用 ATP 合酶、水解用 ATP 水解酶。"], "vsum": "本课讲第五章第二节，讲细胞的能量“货币”**ATP**。开场先看教材例子：杜牧《秋夕》里“天阶夜色凉如水，卧看牵牛织女星”，夜空中与星光媲美的点点流萤，萤火虫发光不是为了好看，和孔雀开屏一样是**求偶行为**，发光需要细胞提供能量，给细胞提供能量的物质就是 ATP。第一个知识点是 ATP 的功能：**ATP 是驱动细胞生命活动的直接能源物质**，能直接给细胞提供能量。注意 **ATP 不等于能量**：能量是一种形式，ATP 是储存能量的一种物质。ATP 的结构：元素组成是 **C、H、O、N、P** 五种，和核酸的组成元素相同，原因在结构里——ATP 由一分子**腺嘌呤**、一分子**核糖**和三分子的**磷酸基团**构成，和核苷酸（磷酸+五碳糖+含氮碱基）很像；一分子腺嘌呤和一分子核糖共同构成的结构叫**腺苷**，用大写字母 A 表示，所以 ATP 的中文名称是**腺苷三磷酸**。三个磷酸基团从靠近核糖的往外编号为 **α、β、γ**。和核苷酸的区别有三点：核苷酸只有一分子磷酸基团，ATP 有三个；核苷酸的五碳糖可以是核糖或脱氧核糖，ATP 的五碳糖只能是**核糖**；核苷酸的含氮碱基有腺嘌呤、鸟嘌呤、胞嘧啶、胸腺嘧啶、尿嘧啶五种，ATP 的碱基只能是**腺嘌呤**。ATP 脱掉远离腺苷的 γ 磷酸基团就变成 **ADP（腺苷二磷酸）**，再脱一个变成 **AMP（腺苷一磷酸）**，三者可以相互转化。ATP 的结构简式写作 **A—P～P～P**：A 代表腺苷，P 是磷酸基团，中间的短横线“—”是普通化学键，两个波浪线“～”是**高能磷酸键**，断裂时会释放出较多的能量，所以 ATP 分子含有**两个**高能磷酸键。口诀“**123**”帮你记：1 个腺苷、2 个高能磷酸键、3 个磷酸基团。ATP 有两个特点：①**不稳定**，因为相邻的磷酸基团都带负电荷、同种电荷相互排斥，一分子 ATP 含 4 个负电荷，末端的 γ 磷酸基团有较高的转移势能、容易脱掉；②**水解是放能过程**，远离腺苷的那个高能磷酸键断裂，末端磷酸基团脱下、携带着能量与其他分子结合，1 mol ATP 水解释放的能量高达 **30.54 kJ**，所以 ATP 是高能磷酸化合物。易错提醒三则：①ATP 由一个腺嘌呤和三个磷酸基团构成——错，应为一个腺苷（或一个腺嘌呤+一个核糖）加三个磷酸基团；②ATP 含三个特殊化学键——错，是两个；③ATP 是细胞内主要的能源物质——错，ATP 是**直接能源物质**，主要的能源物质是**糖类**。顺带复习细胞内的能源物质：能源物质包括糖类、脂肪、蛋白质和 ATP；**主要能源物质是糖类**（细胞呼吸的底物主要是糖类）；储能物质有脂肪、淀粉、糖原，淀粉只存在于植物细胞、糖原只存在于动物细胞，**主要储能物质是脂肪**（1 g 脂肪氧化分解放 39000 J，1 g 糖原只有 17000 J）；**直接能源物质是 ATP**；能量的**最终来源是太阳能**（人吃食物，食物最终来自植物的光合作用）。第二个重点是 **ATP 与 ADP 的相互转化**：ADP 加上游离的磷酸 Pi 再加上能量，在 **ATP 合酶**催化下合成 ATP；ATP 合酶广泛分布于**线粒体内膜、叶绿体类囊体膜和细菌质膜**上，质子（H⁺）顺电化学梯度流动时催化 ADP 和磷酸合成 ATP。合成 ATP 所需要的能量，对动物、人、真菌和大多数细菌来说来自**呼吸作用**，对绿色植物来说来自**呼吸作用和光合作用**。ATP 水解脱掉 γ 磷酸基团变成 ADP 并释放能量，用的酶是 **ATP 水解酶**，和合成用的 ATP 合酶不是同一种酶。**ATP 与 ADP 的相互转化不是可逆反应**：物质上可逆（游离的磷酸可以反复利用），能量上不可逆（合成的能量来自呼吸作用和光合作用，水解释放的能量用于细胞的各项吸能反应），酶也不一样、反应场所也有区别。相互转化的特点有两点：①**时刻不停地发生、处于动态平衡**，细胞内 ATP 的含量很少、不能大量储存，挣多少用多少，靠快速转化供能；②能量供应机制在所有生物的细胞内都一样，体现了**生物界的统一性**。ATP 的利用：细胞中**绝大多数**需要能量的生命活动都是由 ATP 直接提供能量的（并非全部，还有 GTP、CTP、UTP 等，高中不用掌握）。实例有主动运输、生物发电（电鳐）、生物发光（萤火虫）、肌肉收缩、细胞内各种吸能反应（合成反应）、大脑思考。ATP 中的能量可以直接转化成六种形式：**渗透能**（主动运输）、**机械能**（肌肉收缩、精子尾部摆动）、**电能**（生物发电、大脑思考）、**化学能**（吸能反应）、**光能**（萤火虫发光）、**热能**（维持体温）。ATP 为主动运输供能的原理以**钙泵**为例：参与 Ca²⁺ 主动运输的载体蛋白是一种能催化 ATP 水解的酶，叫 **Ca²⁺-ATP 酶**，又叫**钙泵**。过程是：膜内侧的 Ca²⁺ 与载体蛋白相应位点结合→酶活性被激活→ATP 末端磷酸基团脱离、与载体蛋白结合（**载体蛋白磷酸化**，能量转移）→载体蛋白空间结构改变，结合位点转向膜外侧→Ca²⁺ 释放到膜外；每消耗 1 分子 ATP 可将 2 个 Ca²⁺ 从膜内转移到膜外。类似的还有**钠钾泵**（Na⁺-K⁺-ATP 酶），每消耗 1 分子 ATP，泵出 3 个 Na⁺、泵入 2 个 K⁺。最后理解“**ATP 是细胞内流通的能量‘货币’**”：**吸能反应**（细胞需要吸收能量）一般与 ATP 水解相联系，由 ATP 水解提供能量；**放能反应**与 ATP 合成相联系，放出的能量储存在 ATP 里；能量通过 ATP 分子在吸能反应和放能反应之间流通。注意吸能反应和放能反应是针对细胞说的，不是针对 ATP 说的。易错提醒三则：①细胞内储存有大量的 ATP——错，ATP 含量很少，靠快速转化供能；②吸能反应伴随着 ATP 的合成、放能反应伴随着 ATP 的水解——说反了，吸能反应伴随 ATP 水解，放能反应伴随 ATP 合成；③人在饥饿时细胞中 ATP 与 ADP 的含量难以达到动态平衡——错，健康人都能保持动态平衡。萤火虫发光的原理：尾部发光细胞里有**荧光素和荧光素酶**，荧光素接受 ATP 提供的能量后被激活，在荧光素酶催化下与氧发生化学反应，形成氧化荧光素并发出荧光。教材练习要点：①能准确表示 ATP 结构的简式是 B 选项——腺苷与第一个磷酸基团之间是普通化学键，后面两个是特殊化学键；②能直接给细胞生命活动提供能量的是 ATP；③关于 ATP 的叙述错误的是 B——ATP 合成所需能量由磷酸提供是错的，应来自呼吸作用和光合作用；④离子泵：选 C——动物一氧化碳中毒会降低离子泵跨膜运输离子的速率（CO 中毒→血红蛋白结合氧的能力下降→供氧不足→有氧呼吸减弱→ATP 减少）；⑤关于水稻细胞内 ATP 的叙述错误的是 B——只能由细胞呼吸产生是错的，水稻细胞还能进行光合作用。", "vtech": [["直接、主要、储能、最终：四种地位别搞混", "看到能源物质题 → 先问地位：直接能源物质是 ATP，主要能源物质是糖类，主要储能物质是脂肪，最终能量来源是太阳能；“ATP 是主要的能源物质”是典型错句。"], ["ATP 与 ADP 转化不是可逆反应", "物质上可逆（Pi 可反复利用），能量上不可逆：合成的能量来自呼吸作用（植物还有光合作用），水解释放的能量用于吸能反应；两种酶也不一样（ATP 合酶 vs ATP 水解酶）。"], ["钙泵和钠钾泵的数字", "钙泵：每消耗 1 分子 ATP 转移 2 个 Ca²⁺（膜内→膜外）；钠钾泵：每消耗 1 分子 ATP 泵出 3 个 Na⁺、泵入 2 个 K⁺；离子泵跨膜运输是主动运输，离不开 ATP 水解。"], ["结构简式与口诀“123”", "A—P～P～P：A 是腺苷（腺嘌呤+核糖），“—”是普通化学键，“～”是高能磷酸键；口诀 123：1 个腺苷、2 个高能磷酸键、3 个磷酸基团；ATP 含 4 个负电荷、1 mol 水解释放 30.54 kJ。"]], "vgaokao": []}}, "u_bio_16": {"id": "u_bio_16", "name": "细胞呼吸的原理和应用", "secs": "第三节", "pageFrom": 90, "pageTo": 96, "members": ["bio_b019", "bio_b020"], "video": {"bvid": "BV1p54y177e6", "p": 39, "t": "细胞呼吸的原理和应用", "dur": "126:45", "from": "锦城大同教育·杨波生物", "vtop": ["有氧呼吸分三个阶段记场所和产物：第一阶段在细胞质基质把葡萄糖分解成 2 分子丙酮酸和 4 分子 [H]，第二阶段在线粒体基质产生二氧化碳，第三阶段在线粒体内膜生成水并释放大量能量，1 mol 葡萄糖共生成 32 mol ATP、转化效率约 34%。", "无氧呼吸全程只在细胞质基质进行，第一阶段与有氧呼吸第一阶段完全相同，第二阶段不产能，产物按酶的种类分产乳酸式和产酒精加二氧化碳式，人体细胞只能产乳酸。", "氧气浓度为 5% 时二氧化碳释放总量最少，所以储存粮食、水果和蔬菜要用低氧而不是无氧环境，粮食还要干燥、水果蔬菜还要一定湿度。"], "vsum": "本课讲第五章第三节**细胞呼吸的原理和应用**，分两讲：第一讲是探究酵母菌细胞呼吸的方式加有氧呼吸，第二讲是无氧呼吸加影响因素与应用。开场先看教材例子：酵母菌细胞富含蛋白质，可以用作饲料添加剂，培养时要通气或者震荡，让它大量繁殖；利用酵母菌生产葡萄酒时却需要密封发酵。三个问题：为什么都是培养酵母菌，有的需要通气、有的却需要密封？为什么通气有利于酵母菌大量繁殖，而密封环境不利于大量繁殖？密封发酵时酵母菌把有机物转化为酒精，对它自身又有什么意义？先分清两个概念：**呼吸**是人体的肺与外界环境进行气体交换，也就是平时呼气和吸气的过程，又叫呼吸运动；**呼吸作用**是细胞内有机物氧化分解并且释放能量的过程，也叫**细胞呼吸**。酵母菌是真菌、真核生物，代谢类型是**异养兼性厌氧型**：异养是只能利用现成的有机物，兼性厌氧是**有氧和无氧条件下都能正常生活**，所以它既能进行**有氧呼吸**，也能进行**无氧呼吸**。检测产物有两套办法：**二氧化碳**用**澄清石灰水**检测，变浑浊说明有二氧化碳，浑浊的程度能判断二氧化碳含量的多少；还可以用**溴麝香草酚蓝溶液**，它本身是蓝色，遇到二氧化碳由**蓝变绿再变黄**，变色时间越短说明二氧化碳越多。**酒精**用**酸性重铬酸钾溶液**检测，本身是橙色，遇到酒精由**橙变灰绿**，一定要在酸性条件下用，酸性条件靠加**浓硫酸**提供，因为重铬酸钾在碱性或中性条件下作用很微弱，而且硫酸根能参与生成灰绿色的硫酸铬。实验装置是两组实验组相互对照：A 瓶和 B 瓶都装等量酵母菌培养液，加等量质量分数 5% 的葡萄糖溶液，变量就是**有无氧气**，其他无关变量保持相同且适宜；葡萄糖溶液要先煮沸消毒杀死杂菌，冷却后再加入酵母菌，不然高温会把酵母菌烫死。A 瓶前面多一个装 10% 氢氧化钠溶液的锥形瓶，用来除去通入空气里的二氧化碳，再接橡皮球或气泵通气，提供有氧环境；不能用澄清石灰水代替氢氧化钠来除二氧化碳，因为澄清石灰水吸收二氧化碳有一定限度、吸不完。B 瓶直接密封，提供无氧环境。检测二氧化碳时把导管通入澄清石灰水或溴麝香草酚蓝溶液；检测酒精时从 A、B 瓶各取等量培养液，加酸性重铬酸钾溶液观察变色，而且要**适当延长培养时间**，等葡萄糖耗尽再测，因为葡萄糖是还原糖，也会被重铬酸钾氧化、颜色反应和酒精相同，会干扰结果。实验结论：酵母菌在有氧和无氧条件下都能进行细胞呼吸，**有氧条件下产生大量的二氧化碳和水，无氧条件下产生酒精和少量的二氧化碳**；有氧条件利于大量繁殖，无氧条件进行酒精发酵，所以酿酒要密封。这个实验属于**对比实验**：只设置两个或两个以上的实验组，通过对结果的比较分析来探究某种因素的影响，也叫相互对照实验，是对照实验的一种。易错提醒：葡萄糖溶液煮沸后要冷却再加酵母菌；气体使澄清石灰水变浑浊只能说明有二氧化碳，不能直接断定就是有氧呼吸，因为无氧呼吸也产生二氧化碳；重铬酸钾要在酸性条件下用；两组都是实验组，没有对照组。接着讲**有氧呼吸**：对大多数生物来说，有氧呼吸是细胞呼吸的主要形式。**有氧呼吸的主要场所是线粒体**，真核细胞里有氧呼吸的场所是线粒体和细胞质基质；线粒体内膜折叠形成**嵴**，增大膜面积，给有氧呼吸有关的酶提供更多附着位点。原核细胞没有线粒体，但部分原核细胞（如硝化细菌、蓝细菌、根瘤菌）含有有氧呼吸的酶，也能进行有氧呼吸，场所在细胞质基质和细胞膜上。有氧呼吸的总反应式以葡萄糖为例：葡萄糖加氧气加水，在酶的作用下生成二氧化碳和水并释放能量，生成大量 ATP。注意底物**主要是葡萄糖**，但不只有葡萄糖，其他有机物也可以参加有氧呼吸；反应物里的水不能省掉，它参加第二阶段，生成物里的水是第三阶段产生的；反应式里写的是能量，不能写成 ATP，因为大部分能量以热能形式散失了；箭头上面的酶不能漏，各阶段的酶种类也不一样。有氧呼吸分**三个阶段**：**第一阶段在细胞质基质**，1 分子葡萄糖在酶的作用下分解成 2 分子**丙酮酸**和 4 分子**[H]**，释放少量能量，一部分以热能散失、一部分生成少量 ATP，也叫**糖酵解**；**第二阶段在线粒体基质**，2 分子丙酮酸和 6 分子水生成 20 分子 [H] 和 6 分子二氧化碳，释放少量能量，也叫**三羧酸循环**，二氧化碳就是在这个阶段产生的；**第三阶段在线粒体内膜**，前面两阶段产生的 24 分子 [H] 和 6 分子氧气生成 12 分子水，释放大量能量，也叫**氧化磷酸化**。葡萄糖不能进入线粒体分解，因为线粒体里没有分解葡萄糖的酶，分解葡萄糖的酶只分布在细胞质基质里；有机物彻底分解发生在第二、三阶段，所以有氧呼吸的主要场所是线粒体。能量上，1 mol 葡萄糖有氧呼吸共释放 **2870 kJ**，其中 **977.28 kJ** 储存在 ATP 里，剩下 1892.72 kJ 以热能散失；每合成 1 mol ATP 需要 30.54 kJ，所以 1 mol 葡萄糖共生成 **32 mol ATP**，能量转化效率约 **34%**。氧的去向：氧气里的氧全部进入生成的水，葡萄糖和反应物水里的氧全部进入二氧化碳。易错提醒：葡萄糖不是有氧呼吸唯一利用的物质；不是所有真核细胞都能进行有氧呼吸，哺乳动物成熟的红细胞和蛔虫细胞没有线粒体，不能进行有氧呼吸；有氧呼吸的实质不是葡萄糖在线粒体中彻底氧化分解，而是在氧的参与下通过多种酶的作用，把葡萄糖等有机物彻底氧化分解，产生二氧化碳和水，释放能量、生成大量 ATP。教材练习题：把酵母菌培养液离心，得到只含细胞质基质的上清液和只含细胞器的沉淀物，分别加等量等浓度葡萄糖溶液，在有氧条件下只有未离心处理的完整酵母菌（丙试管）能产生二氧化碳和水，因为甲只有细胞质基质、只能完成第一阶段，乙只有细胞器、葡萄糖进不了线粒体。第二讲讲**无氧呼吸**：整个过程都发生在**细胞质基质**，分两个阶段。**第一阶段与有氧呼吸的第一阶段完全相同**，1 分子葡萄糖分解成 2 分子丙酮酸和 4 分子 [H]，释放少量能量。**第二阶段**也在细胞质基质，2 分子丙酮酸和 4 分子 [H] 在酶的作用下生成 2 分子乳酸，或者生成 2 分子酒精和 2 分子二氧化碳，**第二阶段不产能**，写反应式时别把 [H] 漏掉。按酶的种类不同分两种：产物是乳酸的用**乳酸脱氢酶**，叫**产乳酸式**；产物是酒精和二氧化碳的用**乙醇脱氢酶**，老师简称为产酒气式，写的时候别漏了二氧化碳。反应式后面一定要加“**少量能量**”，以区别于有氧呼吸释放的大量能量；写乳酸和酒精的分子式后面要加括号注明是哪种物质，因为 C₃H₆O₃ 和 C₂H₆O 都是同分异构体、可能代表别的物质。产物归属要记牢：动物细胞和人体细胞无氧呼吸的产物只有乳酸；大多数植物细胞产酒精和二氧化碳，玉米胚乳、甜菜块根、马铃薯块茎这三个特例产乳酸；微生物里乳酸菌只能产乳酸，酵母菌产酒精和二氧化碳。能量上，1 mol 葡萄糖无氧呼吸分解成乳酸只释放 **196.65 kJ**，其中 61.08 kJ 储存在 ATP 里，正好生成 **2 mol ATP**，剩下 135.57 kJ 以热能散失；大部分能量没有释放出来，还储存在乳酸或酒精这些没有彻底分解的有机产物里。**无氧呼吸**的概念是：在没有氧气参与的情况下，葡萄糖等有机物经过不完全分解、释放少量能量的过程；酵母菌、乳酸菌等微生物的无氧呼吸也叫**发酵**，但工业上的发酵不一定是无氧呼吸，比如醋酸发酵用的醋酸菌是需氧菌、只能进行有氧呼吸。**细胞呼吸**除了提供能量，还是生物体**代谢的枢纽**，蛋白质、糖类和脂质的代谢都能通过细胞呼吸联系起来。易错提醒：无氧呼吸没有氧气参与，但 [H] 不会积累，第二阶段还要用它当反应物；马铃薯块茎无氧呼吸的产物是乳酸，不是酒精和二氧化碳；人体产生二氧化碳的细胞呼吸方式一定是有氧呼吸，因为人体细胞不能进行产酒精式的无氧呼吸；无氧呼吸只有第一阶段释放少量能量，第二阶段不产能；必须是释放出来的那部分能量才说大部分以热能散失、少部分储存在 ATP 里，无氧条件下葡萄糖里的大部分能量根本没释放出来。应用要会联系生活：包扎伤口用**透气的消毒纱布或创可贴**，是为了避免厌氧病原菌繁殖，不是为了保证伤口处细胞的有氧呼吸，因为伤口处细胞不能直接利用外界氧气，要靠血红蛋白输送；酿酒前期先适宜通气让酵母菌有氧呼吸大量繁殖，后期再密封发酵产酒精；花盆土壤板结要松土透气，既利于根细胞有氧呼吸，也利于土壤里需氧微生物分解有机物、供植物吸收无机盐；储藏水果粮食要降低温度、降低氧气含量来减弱呼吸作用、减少有机物消耗，注意是**低氧而非无氧**；破伤风芽孢杆菌是厌氧菌，伤口深或被锈钉扎伤后深处无氧、容易大量繁殖，要打破伤风针；提倡慢跑这种有氧运动，是为了避免肌细胞供氧不足进行无氧呼吸、乳酸大量积累使肌肉酸胀乏力。影响细胞呼吸的因素分内部和外部：内部因素有遗传特性、生长发育时期、器官类型，一般幼苗期呼吸速率高、成熟期低；外部因素是重点。**温度**通过影响酶的活性来影响呼吸速率，最适温度一般在 **25 到 35 摄氏度**，低温储存食品、大棚夜间和阴天适当降温都是利用低温降低酶活性，温水和面发得快是因为温度高、酶活性高、呼吸快、产生大量二氧化碳。**氧气**是有氧呼吸的反应物，氧气含量影响有氧呼吸速率，同时氧气对无氧呼吸有**抑制作用**；看坐标图：横坐标是氧气含量，纵坐标是二氧化碳释放量，无氧呼吸释放的二氧化碳随氧气增多而下降，有氧呼吸释放的二氧化碳随氧气增多而上升，两者相加是总量曲线；氧气浓度为 0 时只进行无氧呼吸，0 到 10% 两种呼吸同时进行，**10% 时无氧呼吸消失**，10% 以上只进行有氧呼吸；二氧化碳释放总量在氧气浓度 **5%** 时最少，说明这时有机物消耗最少，所以储存粮食水果蔬菜要用低氧环境，粮食还要干燥，水果蔬菜还要一定湿度。**水分**既是有氧呼吸的反应物，又是生化反应的介质，在一定范围内呼吸速率随含水量增加而加快，粮食入仓前要晾晒减少自由水、降低呼吸速率，干种子萌发前浸泡是提高含水量、加快呼吸。**二氧化碳**是细胞呼吸的最终产物，积累过多会抑制细胞呼吸，所以适当增加二氧化碳浓度也有利于水果蔬菜保鲜。最后比较有氧呼吸和无氧呼吸：不同点是反应条件（要不要氧气）、反应场所、分解产物（有氧是二氧化碳和水、无氧是乳酸或酒精加二氧化碳）、能量转化和特点（有氧彻底氧化分解、能量完全释放，无氧不彻底分解、能量没有完全释放）；相同点是实质都是分解有机物、释放能量、生成 ATP，意义都是为生物提供能量、作为代谢枢纽；联系是第一阶段从葡萄糖到丙酮酸完全相同，之后在不同条件、场所和酶的作用下沿不同途径形成不同产物。判断呼吸方式有**三看法**：一看反应物和产物，消耗氧气或产物中有水的一定存在有氧呼吸，有酒精或乳酸生成的一定存在无氧呼吸；二看物质的量关系，不消耗氧气却释放二氧化碳的只能是产酒精式无氧呼吸，不消耗氧气也不释放二氧化碳的可能是产乳酸式无氧呼吸或细胞已死亡，二氧化碳释放量等于氧气吸收量时只进行有氧呼吸，或同时进行有氧呼吸和产乳酸式无氧呼吸；三看场所，只在细胞质基质中进行的是无氧呼吸，有线粒体参与的一定存在有氧呼吸，但这只针对真核细胞，原核细胞不论哪种呼吸场所都在细胞质基质里。数量关系要会算：消耗等量葡萄糖时，有氧呼吸与产酒精式无氧呼吸的二氧化碳产生量之比是 **3:1**；产生等量二氧化碳时，两者消耗葡萄糖量之比是 **1:3**；两者同时进行时，氧气吸收量与二氧化碳释放总量之比等于 **3:4** 说明速率相等，小于 3:4 说明有氧呼吸速率小于无氧呼吸速率，大于 3:4 则相反。课后作业是完成课后作业 21。", "vtech": [["三阶段场所与产物先对表", "第一阶段在细胞质基质：1 分子葡萄糖→2 丙酮酸＋4[H]＋少量能量；第二阶段在线粒体基质：2 丙酮酸＋6 水→20[H]＋6 二氧化碳＋少量能量；第三阶段在线粒体内膜：24[H]＋6 氧气→12 水＋大量能量；三阶段别名糖酵解、三羧酸循环、氧化磷酸化。"], ["无氧呼吸两类产物看酶", "产乳酸式用乳酸脱氢酶，产物是 2 乳酸；产酒精式用乙醇脱氢酶，产物是 2 酒精＋2 二氧化碳，写的时候别漏了二氧化碳；反应式后面一定要写“少量能量”，第二阶段不产能；人体细胞只能产乳酸，酵母菌产酒精加二氧化碳，玉米胚乳、甜菜块根、马铃薯块茎这三个植物特例产乳酸。"], ["检测题先看试剂与颜色", "二氧化碳：澄清石灰水变浑浊，浑浊程度看多少；溴麝香草酚蓝由蓝变绿再变黄，变色时间越短二氧化碳越多；酒精：酸性重铬酸钾由橙变灰绿，酸性条件靠浓硫酸提供；测酒精要适当延长培养时间，等葡萄糖耗尽再测，否则葡萄糖的还原性会干扰。"], ["氧气曲线抓 5% 与 10% 两个点", "氧气浓度为 0 时只进行无氧呼吸，0 到 10% 两种呼吸同时进行，10% 时无氧呼吸消失；二氧化碳释放总量在氧气浓度 5% 时最少，所以低氧储存最省有机物；温度通过影响酶活性起作用，最适温度一般在 25 到 35 摄氏度。"]], "vgaokao": []}}, "u_bio_17": {"id": "u_bio_17", "name": "光合作用与能量转化（上）：捕获光能的色素和结构", "secs": "第四节", "pageFrom": 97, "pageTo": 99, "members": ["bio_b021"], "video": {"bvid": "BV1p54y177e6", "p": 43, "t": "光合作用与能量转化（一）", "dur": "58:25", "from": "锦城大同教育·杨波生物", "vtop": ["四条色素带从上往下是胡萝卜素、叶黄素、叶绿素a、叶绿素b，口诀“胡黄AB”——扩散快慢看溶解度、带宽看含量。", "叶绿素a和叶绿素b主要吸收蓝紫光和红光，类胡萝卜素主要吸收蓝紫光；绿光吸收最少、被反射出来，所以叶片是绿色的。", "叶绿体是光合作用的场所，但不是唯一场所——蓝细菌没有叶绿体也能进行光合作用；叶绿体是植物细胞特有的细胞器，但不是所有植物细胞都有，如根尖细胞。"], "vsum": "本课讲第五章第四节光合作用与能量转化（一），讲捕获光能的色素和叶绿体的结构。开场先看玉米白化苗：白化苗叶片里不含绿色色素，种子中储存的养分耗尽就会死去，可见叶片中的色素可能与光能的捕获有关——只有含绿色色素的细胞才能进行光合作用、合成积累有机物，这里的绿色色素就是**光合色素**。第一个重点是绿叶中色素的**提取与分离**实验，分为提取和分离两大部分。先讲提取的原理：绿叶中的色素是有机物，根据**相似相溶**原理能溶解在有机溶剂中，教材用的溶剂是**无水乙醇**；没有无水乙醇时，可以用体积分数为95%的乙醇加上适量的**无水碳酸钠**来代替，因为无水碳酸钠能吸收水分。实验用品：无水乙醇是提取用的溶剂；**二氧化硅**是坚硬的固体，研磨时加入有助于研磨得更充分；**碳酸钙**是防止研磨时色素分子被破坏；过滤用**单层尼龙布**，不能用滤纸代替，因为滤纸吸附性强，会把色素分子吸附在上面，导致滤液里色素含量低、后续现象不明显甚至不出现。提取的具体步骤：第一步取材，称取**5克**绿叶（比如菠菜叶），尽量选新鲜又嫩的绿叶——放久的叶子发黄是叶绿素被破坏了，嫩叶的叶绿素含量更高，现象更明显；去掉叶脉、剪碎，加入少许二氧化硅和碳酸钙，研磨破坏细胞结构、释放出色素分子；再加入**5到10毫升**无水乙醇，迅速研磨，过滤得到滤液，用棉塞将试管口塞紧，防止空气中的氧气破坏色素。对着光看滤液呈绿色、背着光看呈红色，这种现象叫**叶绿素荧光现象**，了解即可。接下来是分离：用**纸层析法**，原理是不同色素在**层析液**中的溶解度不同，溶解度高的随层析液在滤纸上扩散得快，溶解度低的扩散得慢，扩散时间相同、速度不同，最终在滤纸上分层、实现分离。老师用钢笔字滴水扩散打比方帮助理解。滤纸条的准备：用干燥的**定性滤纸**（湿滤纸会影响层析液扩散），剪成宽度略小于试管直径、长度略小于试管长度的滤纸条，在一端剪去两脚——这样色素扩散的起点相同，能得到平整的色素带；距去角一端1厘米处用铅笔画一条细线；再用毛细吸管吸取少量滤液，沿铅笔线均匀画出一条滤液细线，要求**细、直、齐**，等干了之后再重复画一两次（没干就画会扩散变粗、色素带重叠），也可以用盖玻片蘸取少量滤液轻压在铅笔线处画线。分离操作：将适量层析液倒入试管（层析液是**石油醚、丙酮和苯**的混合物，都是有机溶剂），把滤纸条有滤液细线的一端朝下轻轻插入层析液中，注意**不能让滤液细线触及层析液**（否则色素直接溶解在层析液里，几乎没有色素再往滤纸上扩散），用棉塞塞紧试管口。实验结果：滤纸条上出现**四条色素带**，从上往下依次是**胡萝卜素、叶黄素、叶绿素a、叶绿素b**，口诀“**胡黄AB**”。扩散起点相同、时间相同，扩散路程不同说明扩散速度不同：最上面扩散最远的胡萝卜素在层析液中溶解度最高，最下面扩散最慢的叶绿素b溶解度最低；色素带的宽度反映色素的相对含量，最宽的第三条叶绿素a含量最多，最窄的第一条胡萝卜素含量最少。四种色素的颜色也要记住：胡萝卜素**橙黄色**、叶黄素**黄色**、叶绿素a**蓝绿色**、叶绿素b**黄绿色**；叶绿素a和叶绿素b都属于绿色这一大范围，叶绿素b比叶绿素a更稳定一些。秋天叶片变黄的原因：低温下叶绿素被分解，绿色的色素没了，剩下的橙黄色、黄色的类胡萝卜素的颜色就显现出来了。四种色素的共同功能是**吸收、传递和转化光能**。再看叶绿素分子的结构：分为头部和尾部，头部是**卟啉环**，尾部是植醇；卟啉环中间有一个**镁离子**，不稳定——在酸性环境下，镁离子会被氢离子取代，变成不再是绿色的褐色的**去镁叶绿素**，叶绿素分子就相当于被破坏了。这就解释了为什么研磨时要加碳酸钙：植物细胞的液泡里含有有机酸，研磨破坏细胞结构后有机酸释放出来，叶绿素就处在酸性环境中，镁离子会被氢离子取代；加入碳酸钙可以中和这些酸性物质，保住镁离子，从而保护叶绿素分子在研磨时不被破坏。影响叶绿素合成的因素有三个：**光照**是必需的、缺一不可（黄豆芽在黑暗环境下发芽长出来是黄色的，就是因为没有光照、不能合成叶绿素）；**温度**通过影响酶的活性来影响叶绿素的合成，低温还会导致叶绿素分解；**矿质元素**（叶绿素合成需要镁、氮等元素）。异常现象分析：色素带颜色过浅有六个可能原因——未加二氧化硅或研磨不充分；用了放置数天的绿叶或绿叶用量太少；一次加入大量无水乙醇导致提取液浓度太低；未加碳酸钙或加入过少导致色素被破坏；画滤液细线次数过少；层析液触及滤液细线但时间不长；色素带重叠是因为滤液细线画得太粗；完全看不见色素带，可能是忘了画滤液细线（只画了铅笔线），或是滤液细线触及层析液时间较长、色素全部溶解在层析液中。接着看绿叶中色素的**吸收光谱**：叶绿素a和叶绿素b**主要吸收蓝紫光和红光**，类胡萝卜素（胡萝卜素和叶黄素）**主要吸收蓝紫光**；注意是“主要吸收”，其他色光也有一些吸收。光合作用利用的光都是**可见光**，波长大于700纳米的红外光和波长小于400纳米的紫外光这些不可见光，色素不能吸收利用。叶绿素a、叶绿素b和类胡萝卜素在绿光区吸收都非常低，绿光吸收得最少、被反射出来，所以叶片呈现绿色。应用：大棚里给蔬菜补光，功率相同的情况下应选**蓝紫光或红光**，因为植物对这两种光的利用效率更高。四个易错提醒：①提取色素时加碳酸钙的目的是使研磨更充分——错，那是二氧化硅的作用，碳酸钙是防止色素被破坏；②绿叶中含量越多的色素在滤纸条上扩散得越快——错，扩散快慢和色素在层析液中的溶解度有关，和含量无关；③叶绿素a和叶绿素b只吸收红光和蓝紫光——错，是“主要吸收”，其他色光也有吸收；④植物叶片之所以呈现绿色是因为叶片中的叶绿体吸收了绿光——错，绿光是吸收最少的、被反射出来才看到绿色。第二个知识点是**叶绿体的结构**适于进行光合作用：叶绿体是进行光合作用的场所，是植物细胞特有的细胞器，但**并非所有植物细胞都含有叶绿体**，比如植物的根尖细胞就不含叶绿体。叶绿体的形态一般为扁平的椭球形或球形，少数是其他形态（水绵的叶绿体就是螺旋带状）。叶绿体是双层膜的细胞器，最外面是**外膜**、里面是**内膜**，教材图上内外膜画成不同颜色只是为了区分，实际上内外膜都是无色透明的，而且内外膜的膜面积几乎相等；叶绿体增大膜面积靠的是**类囊体**堆叠成**基粒**——许多扁平的圆盘状结构类囊体堆积形成基粒，类囊体同样是有膜的结构；**基质**里分布有与光合作用有关的酶。叶绿体和线粒体一样是**半自主细胞器**，因为内部含有少量的DNA、RNA和核糖体，能自己合成部分需要的酶。叶绿体是进行光合作用的场所，但**不是唯一场所**：蓝细菌没有叶绿体也能进行光合作用。**恩格尔曼的两个实验**：第一个实验在黑暗环境中用极细的光束照射水绵，好氧细菌只分布在叶绿体有光束照射的部位——有光才能进行光合作用、释放氧气，供好氧细菌利用；第二个实验用透过三棱镜的光照射水绵临时装片，好氧细菌主要分布在叶绿体蓝紫光与红光照射的部位，正好对应叶绿素主要吸收红光和蓝紫光。这两个实验证明叶绿体能够吸收光能用于光合作用、释放氧气，是进行光合作用的场所。叶绿体捕获光能进行光合作用的物质基础有两个：一是能吸收光能的色素分子（光合色素），二是与光合作用有关的酶——蓝细菌虽然没有叶绿体，但它的光合片层上分布有光合色素和与光合作用有关的酶，所以依然能进行光合作用。注意细胞内含色素的细胞器除了叶绿体还有**液泡**（如花青素），但只有叶绿体里的光合色素才能参与光合作用，液泡里的色素不能。三个易错提醒：①没有叶绿体的生物无法进行光合作用——错，蓝细菌可以；②植物细胞都含有叶绿体——错，根尖细胞就没有；③在植物细胞内能进行光合作用的色素分布在叶绿体以及液泡中——错，液泡里的色素不能参与光合作用。教材练习题：第一题判断叶绿体结构与功能的表述——“叶绿体中只有叶绿素吸收的光能才能用于光合作用”是错的，类胡萝卜素吸收的光能也能用于光合作用；“叶绿体的类囊体上有巨大的膜面积，有利于充分吸收光能”是对的；“植物叶片之所以呈现绿色是因为叶片中的叶绿体吸收了绿光”是错的，绿光是被反射出来的。第二题选关于高等植物细胞色素叙述错误的一项，选A——“所有植物细胞中都含有四种色素”是错的，并不是所有植物细胞都有叶绿体，而且有的植物细胞既有叶绿体、液泡里还可能有其他色素；其余选项都对：有些植物细胞的液泡中也含有色素、叶绿素和类胡萝卜素都可以吸收光、植物细胞内的光合色素主要包括叶绿素和类胡萝卜素两大类。最后总结：本课学的是捕获光能的色素（胡萝卜素、叶黄素、叶绿素a、叶绿素b）与叶绿体的结构，重点是色素提取与分离实验的原理、过程、步骤和注意事项，四种色素都分布在类囊体的薄膜上。", "vtech": [["提取还是分离：溶剂别用混", "提取色素用无水乙醇（没有就用体积分数95%的乙醇加适量无水碳酸钠代替），分离色素用层析液（石油醚、丙酮和苯的混合物）；研磨时加二氧化硅助研磨更充分、加碳酸钙防色素被破坏，两者作用别互换。"], ["四条色素带：胡黄AB", "从上往下依次是胡萝卜素（橙黄色）、叶黄素（黄色）、叶绿素a（蓝绿色）、叶绿素b（黄绿色）；扩散最快的是胡萝卜素，在层析液中溶解度最高；带最宽的是叶绿素a，含量最多；扩散快慢看溶解度、带宽看含量。"], ["碳酸钙为什么能保护叶绿素", "叶绿素头部是卟啉环，中间有个镁离子；酸性环境下镁离子会被氢离子取代，变成褐色的去镁叶绿素；研磨会释放液泡里的有机酸，加入碳酸钙中和酸性物质，就保住了镁离子、保住了叶绿素。"], ["吸收光谱与易错点", "叶绿素a、b主要吸收蓝紫光和红光，类胡萝卜素主要吸收蓝紫光；红外光（波长大于700纳米）和紫外光（波长小于400纳米）不能利用；叶片呈绿色是因为绿光吸收最少、被反射出来，不是吸收了绿光；大棚补光功率相同时选蓝紫光或红光效率更高。"]], "vgaokao": []}}, "u_bio_18": {"id": "u_bio_18", "name": "光合作用与能量转化（下）：光合作用的原理和应用", "secs": "第四节", "pageFrom": 100, "pageTo": 108, "members": ["bio_b022", "bio_b023"], "video": {"bvid": "BV1p54y177e6", "p": 45, "t": "光合作用与能量转化（二）", "dur": "122:15", "from": "锦城大同教育·杨波生物", "vtop": ["光合作用释放的氧气全部来自水，不是来自二氧化碳——1941 年鲁宾和卡门用同位素标记实验证明的。", "光反应在类囊体薄膜上进行，暗反应在叶绿体基质中进行；光反应为暗反应提供 ATP 和 NADPH，暗反应为光反应提供 ADP、Pi 和 NADP⁺，两者不能长期独立进行。", "真正光合速率等于净光合速率加呼吸速率；氧气的产生量、二氧化碳的固定量、葡萄糖的生成量表示总光合，释放量、吸收量、积累量表示净光合。"], "vsum": "本课是光合作用的第二讲，分两集：第一集讲光合作用的原理与过程，第二集讲光合作用强度和影响它的因素。先复习概念：**光合作用**是指绿色植物通过**叶绿体**，利用光能将**二氧化碳**和**水**转化成储存着能量的**有机物**，并且释放出**氧气**的过程，产物有机物主要就是**糖类**。反应式要会写两条：一般形式是二氧化碳加水生成糖类加氧气；算葡萄糖时用 6CO₂＋12H₂O→C₆H₁₂O₆＋6H₂O＋6O₂。注意光合作用既消耗水又生成水，但消耗的水比生成的水多，所以教材的反应式把产物里的水省掉了。光合作用的反应式和有氧呼吸的反应式刚好互为倒置：光合作用的反应物就是有氧呼吸的产物，产物就是有氧呼吸的反应物，记住有氧呼吸的反应式就能倒过来写出光合作用的反应式。接下来是探索光合作用原理的实验。19 世纪末科学界普遍认为二氧化碳的碳和氧被分开，氧释放成氧气，碳和水结合成甲醛再缩合成糖；到了 1928 年发现甲醛对植物有毒害、也不能通过光合作用转化成糖，这个观点被否定了。1937 年英国科学家**希尔**做实验：在离体的叶绿体悬浮液中加入铁盐或其他氧化剂，发现水的光解能产生氧气。1941 年美国科学家**鲁宾和卡门**用**同位素标记**法：第一组用 ¹⁸O 标记水、给正常二氧化碳，植物释放的氧气含 ¹⁸O；第二组用 ¹⁸O 标记二氧化碳、给正常水，释放的氧气不含 ¹⁸O，两组对比得出结论——光合作用释放的氧气**全部来自水**。1954 年美国科学家**阿尔农**发现，在光照下叶绿体可以合成 **ATP**，这一过程总与水的光解相伴随。两道思考题要会答：希尔的实验能不能说明氧气中的氧全部来自水？不能，它只说明离体叶绿体在适当条件下能发生水的光解释放氧气，没有排除悬浮液里其他含氧物质的干扰。希尔的实验能不能说明水的光解与糖的合成不是同一个反应？能，因为合成糖需要二氧化碳提供碳，而水的光解悬浮液里没有二氧化碳，所以水光解时没有发生糖的合成。光合作用的过程分两个阶段。**光反应阶段**必须有光照才能进行，场所是**类囊体薄膜**，因为光合色素和有关酶分布在类囊体薄膜上。光反应有三个主要反应：第一，**水的光解**——光合色素吸收光能后夺取水分子中氧元素的电子，水被分解成氧气和氢离子；第二，ADP 加 Pi 再加上光能合成 **ATP**，注意合成 ATP 这一步会生成水；第三，NADP⁺ 加氢离子生成 **NADPH**，中文名**还原型辅酶Ⅱ**，和细胞呼吸里的还原型辅酶Ⅰ（NADH）是两种不同的物质，但都可以简写为 [H]。光能的去路有三条：分解水，转化成 ATP 里活跃的化学能，储存在 NADPH 的化学能里。**暗反应阶段**不需要光照，有光没光都能进行，场所是**叶绿体基质**，因为与暗反应有关的酶分布在叶绿体基质里。暗反应是一个循环过程，由卡尔文发现，又叫**卡尔文循环**。第一步是**二氧化碳的固定**：**C₅**（五碳化合物）加一分子二氧化碳生成两分子 **C₃**（三碳化合物），这一步也有水分子参与，数量关系可以用元素守恒自己推——5 个碳加 1 个碳等于 6 个碳，所以要生成两个三碳化合物。第二步是**三碳化合物的还原**：C₃ 在 ATP 提供能量、NADPH 提供能量和氢的作用下被还原，一部分还原成糖类等有机物，另一部分还原成 C₅，维持循环。还原出来的糖类一部分在细胞质中转化成**蔗糖**，另一部分在叶绿体中形成**淀粉**暂时储存，需要时再分解成葡萄糖进入细胞质。能量变化是 ATP 和 NADPH 里**活跃的化学能**转化成有机物里**稳定的化学能**。光反应和暗反应相互影响、相互制约：光反应为暗反应提供 ATP 和 NADPH，暗反应为光反应提供 ADP、Pi 和 **NADP⁺**，两者都不能长期独立进行。易错提醒四则：①植物在夜晚不能进行光反应，也不能长期进行暗反应，因为暗反应需要光反应提供物质和能量；②ATP 的移动方向是从叶绿体基质到类囊体薄膜（在基质中生成 ADP，在类囊体薄膜上消耗 ADP 合成 ATP）；③光合作用产生的 ATP 只能用于暗反应，不能为细胞内其他生命活动提供能量；④用 ¹⁴C 标记二氧化碳追踪碳的转移途径是二氧化碳→三碳化合物→糖类和五碳化合物。含量变化题是常考题型，只问短时间内怎么变，分析时从生成和消耗两个方面综合判断：光照由强到弱、二氧化碳供应不变时，ATP 和 NADPH 生成减少，三碳化合物的还原减慢，所以 C₃ 增多、C₅ 减少、有机物合成减少；二氧化碳供应由充足到不足、光照不变时，二氧化碳固定减慢，C₃ 生成减少、C₃ 减少、C₅ 增多、ATP 和 NADPH 因为消耗减少而积累升高；反过来光照由弱变强、或二氧化碳由不足变充足时，结论刚好相反。教材练习题要点：光合作用生成葡萄糖的反应式里，氧气中的氧全部来自水（12 个水中的氧），二氧化碳里的氧进入葡萄糖和水；暗反应不是只能在黑暗中进行，有光无光都能进行；叶绿体不同于线粒体的特点是能分解水产生氧气和氢离子；叶绿体基质只能进行暗反应、消耗 ATP，不能合成 ATP，所以不能合成 ATP 的场所是叶绿体基质。第二集先讲**光合作用强度**，指植物在单位时间内通过光合作用制造糖类的数量，也就是**光合速率**。影响因素有外部因素和内部因素：外部因素有土壤水分、二氧化碳浓度、温度、光照时间长短、光照强度、光的成分等，内部因素有叶片成熟程度、叶龄、植物种类等。衡量光合速率的指标不唯一：可以从原料消耗量衡量，比如单位时间内二氧化碳的消耗量；也可以从产物生成量衡量，比如单位时间内有机物的生成量、氧气的生成量。但叶片质量的增加量（有机物积累量）不能直接衡量光合速率，因为有光时植物既进行光合作用又进行细胞呼吸，测到的增加量是光合作用与呼吸作用的差值，这个差值就叫**净光合速率**，也叫**表观光合速率**：净光合速率＝实际光合速率－呼吸速率，所以**真正光合速率＝净光合速率＋呼吸速率**，真正光合速率也叫实际光合速率或总光合速率。黑暗条件下植物只能进行呼吸作用，所以黑暗条件下测得的数值表示呼吸速率，比如二氧化碳释放量或氧气吸收量。总光合速率和净光合速率的表示要分清：用氧气表示时，氧气的**产生量**是总光合速率，氧气的**释放量**是净光合速率；用二氧化碳表示时，二氧化碳的**固定量**或**消耗量**是总光合速率，二氧化碳的**吸收量**是净光合速率；用葡萄糖表示时，葡萄糖的**生成量**是总光合速率，葡萄糖的**积累量**是净光合速率。教材实验探究环境因素对光合作用强度的影响：用直径 0.6 厘米的打孔器打出圆形小叶片 30 片，尽量避开叶脉；抽气排出叶片细胞间隙的空气，叶片下沉后放入黑暗处盛有清水的烧杯中待用；分组倒入等量富含二氧化碳的清水，可以往清水里吹气，也可以用质量分数 1% 到 2% 的**碳酸氢钠溶液**；给予强、中、弱三种光照，可以用三种不同功率的灯泡；记录同一时间段内各装置中圆形小叶片浮起的数量，光合速率越大、产生氧气越多越快，上浮的叶片就越多。接着讲**化能合成作用**：硝化细菌把氨氧化成亚硝酸、再把亚硝酸氧化成硝酸，释放的化学能把二氧化碳和水合成糖类；硫细菌把硫化氢氧化成硫酸盐，氢细菌把氢气氧化成水，铁细菌氧化铁，这些细菌都属于**自养生物**。自养生物分两类：利用光能把无机物转变成有机物的叫光能自养生物，利用化学能的叫化能自养生物；能进行光合作用的生物是自养生物，但自养生物不都是利用光能的。影响因素第一个是**光照强度**：光是光合作用的能量来源，直接影响光反应阶段，制约 ATP 和 NADPH 的生成。在光照强度—二氧化碳吸收量曲线上，A 点光照强度为零，植物只进行呼吸作用，OA 段表示呼吸速率；AB 段呼吸速率大于光合速率，二氧化碳仍释放到外界；B 点光合速率等于呼吸速率，细胞与外界没有气体交换，B 点对应的光照强度叫**光补偿点**；光照强度继续增大，光合速率加快到一定程度后不再加快，对应最大光合速率的最小光照强度叫**光饱和点**，注意光饱和点不是曲线最高点 C 点；光照过强时光合速率甚至会下降，因为强光会灼伤细胞。把横坐标下移，曲线就表示总光合速率。阴生植物的光补偿点和光饱和点都比阳生植物低，所以间作套种时要搭配种类，让阳生植物利用大部分光能，透过的少量光能刚好被中间的阴生植物利用；阴雨天适当补充光照、及时给大棚除霜除雾都能提高产量。第二个是**二氧化碳浓度**：二氧化碳是光合作用的原料，经叶片表面的气孔进入叶肉细胞的叶绿体。在一定范围内光合速率随二氧化碳浓度增加而加快；光合速率等于呼吸速率时对应的二氧化碳浓度叫**二氧化碳补偿点**，达到最大光合速率时对应的最小二氧化碳浓度叫**二氧化碳饱和点**。C₃ 植物的曲线不从原点开始，必须二氧化碳浓度达到一定值才能进行光合作用；C₄ 植物能利用低浓度的二氧化碳，曲线从原点开始，高中不要求掌握两者的区分。农业上合理密植、通风能增大二氧化碳浓度，增施农家肥也能间接增大二氧化碳浓度，因为土壤里的微生物分解农家肥里的有机物会释放二氧化碳。第三个是**温度**：温度主要通过影响酶的活性来影响光合速率，主要是影响暗反应阶段的酶，温度还会影响气孔的开闭。一般植物光合作用的最适温度是 25 摄氏度，这节课图里的植物最适温度在 32 到 33 摄氏度。冬季温室栽培白天适当提高温度、晚上适当降低温度，可以减少呼吸作用消耗的有机物；新疆的瓜果特别甜，就是因为昼夜温差大，白天温度高、光合作用强、生成大量有机物，晚上温度低、呼吸作用弱、消耗的有机物少，有机物积累得多。第四个是**水分**：水既是光合作用的原料，又是体内各种化学反应的介质，还能影响气孔开闭。气孔由两个保卫细胞构成，保卫细胞失水皱缩时气孔关闭，吸水膨胀时气孔开放，因为保卫细胞外侧壁薄、吸水后向外侧膨胀，把内侧壁拉开，气孔就打开了。植物一天的光合速率曲线：凌晨到早上四五点只有呼吸作用、释放二氧化碳，日出后光合速率逐渐加快，中午两点左右出现一个下降，这就是**光合午休现象**——中午温度过高、蒸腾作用过强，植物为减少水分散失关闭气孔，吸收的二氧化碳减少，光合速率暂时降低。最后是**光质**：在可见光范围内，不同波长的光下光合作用效率不同，红光和蓝紫光下光合作用强度较大，绿光下最弱；叶绿素主要吸收红光和蓝光，类胡萝卜素主要吸收蓝紫光。大棚的塑料薄膜要选无色的，因为太阳光是复合光、功率相同，红色薄膜只透过红光、其他色光都被吸收掉了，利用到的光反而更少；人工补光时功率相同，补红光和蓝光最好。", "vtech": [["氧气来源看标记实验", "希尔 1937 年离体叶绿体加铁盐实验只能说明水光解产生氧气，不能证明氧全来自水；鲁宾和卡门 1941 年用 ¹⁸O 分别标记水和二氧化碳，证明释放的氧气全部来自水；1954 年阿尔农发现光照下叶绿体合成 ATP 总与水的光解相伴随。"], ["光暗反应分工与互供", "光反应在类囊体薄膜：水光解产生 O₂ 和 H⁺，ADP＋Pi 合成 ATP，NADP⁺ 生成 NADPH（还原型辅酶Ⅱ）；暗反应在叶绿体基质：C₅＋CO₂ 生成 2C₃，C₃ 还原成糖类和 C₅；光反应产生的 ATP 只能用于暗反应，不能用于其他生命活动。"], ["含量变化题只看短时间、两头分析", "光照或 CO₂ 改变时，C₃、C₅、ATP、NADPH 的含量变化只分析短时间，从生成和消耗两个方面综合判断：光照由强变弱、CO₂ 不变时 C₃ 增多、C₅ 减少；CO₂ 由充足变不足、光照不变时 C₃ 减少、C₅ 增多、ATP 和 NADPH 积累升高。"], ["补偿点与饱和点别认错点", "光补偿点是光合速率等于呼吸速率时对应的光照强度（B 点），光饱和点是达到最大光合速率时对应的最小光照强度（不是曲线最高点 C 点）；阴生植物的光补偿点和光饱和点都比阳生植物低；二氧化碳补偿点和饱和点同理，C₃ 植物曲线不从原点开始，C₄ 植物能利用低浓度二氧化碳。"]], "vgaokao": []}}, "u_bio_19": {"id": "u_bio_19", "name": "细胞的增殖", "secs": "第一节", "pageFrom": 110, "pageTo": 117, "members": ["bio_b024", "bio_b025"], "video": {"bvid": "BV1p54y177e6", "p": 51, "t": "细胞的增殖", "dur": "124:51", "from": "锦城大同教育·杨波生物", "vtop": ["细胞周期只属于连续分裂的细胞：从一次分裂完成到下一次分裂完成为止，间期长、分裂期短，间期里完成 DNA 复制和有关蛋白质合成。", "有丝分裂认时期抓标志：中期着丝点排在赤道板上、形态固定数目清晰；后期着丝点分裂、染色单体消失、染色体数暂时加倍。", "数曲线只看核 DNA：核 DNA 2N→4N→2N，染色体数后期才加倍，染色单体只在前中期有，1:2:2 只在有染色单体时成立。"], "vsum": "本课讲第六章第一节，讲**细胞的增殖**，分两讲。第一讲开场先算一道题：象和鼠个体大小相差悬殊，细胞大小差多少？动物细胞直径一般 20–30 微米，取小鼠 20 微米、大象 30 微米，直径比 2:3，用球体体积公式算体积比是 8:27——个体大小的差异主要来自**细胞数量**的多少，不是细胞大小。一个受精卵变成多细胞个体，细胞数量增多靠**细胞增殖**，种类增多靠**细胞分化**（第六章第二节再讲）。第一个重点是**细胞增殖**与**细胞周期**：细胞增殖是细胞通过分裂增加细胞数量的过程，常和细胞分裂同义；细胞周期是从一次分裂完成开始，到下一次分裂完成为止，只有**连续分裂的细胞**才有，比如受精卵、根尖分生区细胞、茎的形成层细胞、皮肤生发层细胞和各种干细胞。一次细胞周期分**分裂间期**和**分裂期**：间期做物质准备，处在两次分裂之间，所以叫间期；间期占大头——蚕豆根尖分生区细胞周期 17.3 小时、间期 15.3 小时，小鼠十二指肠上皮细胞周期 15.3 小时、间期 13.5 小时；不同细胞周期长短不同，即使同一个体也一般不同，人肝细胞和宫颈癌细胞周期都是 22 小时，间期时长却不一样。第二个重点是**有丝分裂**，分前、中、后、末四个时期，是人为划分的。分裂间期主要进行 **DNA 的复制和有关蛋白质的合成**。前期：细丝状的**染色质**螺旋缠绕变成短棒状的**染色体**，细胞两极发出**纺锤丝**（蛋白质）形成纺锤体，核膜、核仁消失；染色质和染色体是同一种物质，只是形态不同，数染色体只数数量、不看形状。中期：染色体进一步螺旋、缩短变粗，形态比较固定、数目比较清晰，**着丝点**整齐排列在**赤道板**上，是观察染色体形态和数目的最佳时期。后期：**着丝点分裂**，姐妹染色单体分开变成两条染色体，分别移向细胞两极，染色单体消失，染色体数目暂时加倍。末期：染色体变回染色质，纺锤体消失，核膜、核仁重现；植物细胞在赤道板位置出现**细胞板**，向四周扩展成新的细胞壁；染色体、纺锤体出现与核膜、核仁消失，前期和末期刚好相反。间期还能细分为 **G1 期**（DNA 合成前期，合成蛋白质）、**S 期**（DNA 合成期）、**G2 期**（DNA 合成后期），有丝分裂期又叫 **M 期**。第三个重点是**动物细胞**的有丝分裂，和植物大体相同，不同有三处：间期**中心体**由一组倍增为两组；前期中心体移向两极、发出**星射线**形成纺锤体，不是两极发纺锤丝；末期没有细胞板，靠细胞膜从中部向内凹陷、形成收缩环把细胞**缢裂**成两个——答题写“缢裂”不写“分裂”。问与动物细胞有丝分裂有关的细胞器，要加上中心体、去掉高尔基体（高尔基体与细胞壁形成有关，动物细胞没有细胞壁）。**有丝分裂的意义**有两点：第一，把亲代细胞的染色体经过复制（关键是染色体内 DNA 的复制）后**精确地平均分配**到两个子细胞中——平均分配的只是细胞核内的 DNA，细胞质 DNA 是随机分配的，细胞器也随机分配，只有中心体例外、是平均分配的；第二，染色体上有遗传物质 DNA，这样就在亲代和子代之间保持了**遗传的稳定性**。**癌细胞**是遗传物质发生改变、不受机体控制、能连续分裂的恶性增殖细胞。最后一个知识点是**无丝分裂**：过程是核延长→核缢裂→细胞质缢裂，同样先进行 DNA 复制，子细胞的遗传物质和亲代一样；特点是分裂过程没有出现纺锤丝和染色体的变化，速度比较快；蛙的红细胞能进行无丝分裂，低等植物中普遍存在，高等植物的胚乳细胞、薄壁细胞、表皮细胞、根冠细胞和动物的某些腺体细胞也能进行。易错提醒：蛙生长发育过程中体细胞增殖仅靠有丝分裂——错，还要靠无丝分裂。第二讲先问细胞为什么不能无限长大。原因一是细胞大小影响**物质运输效率**：用边长 2、4、8 毫米的正方体模拟细胞，表面积分别是 24、96、384，体积分别是 8、64、512，相对表面积从 3 降到 1.5 再到 0.75；把三个模型放进葡萄糖溶液相同时间、假设扩散深度都是 0.5 毫米，葡萄糖扩散的体积占总体积分别是 7/8、37/64、169/512，细胞越大、表面积与体积之比越小，运输效率越低。原因二是**细胞核是细胞的控制中心**，细胞太大、细胞核的控制作用就有限，就像一个班主任管 50 个学生还行、管 200 个就管不过来。接着做教材实验**观察根尖分生区组织细胞的有丝分裂**：原理是根尖分生区细胞能连续分裂、有细胞周期；高倍显微镜下根据染色体的存在状态判断所处时期；染色体容易被碱性染料着色。步骤是解离→漂洗→染色→制片：解离液是质量分数 15% 的盐酸和体积分数 95% 的酒精按 1:1 混合，3–5 分钟，目的是使组织中的细胞相互分离开来，细胞在解离时已经死亡，解离到根尖酥软、镊子一碾就散即可，解离过度会妨碍染色；漂洗用清水、10 分钟以上，洗去多余解离液；染色用质量浓度 0.01 或 0.02 g/mL 的龙胆紫溶液（龙胆紫溶于质量分数 2% 的醋酸配成）或醋酸洋红液，3–5 分钟；制片是取根尖放载玻片上、加一滴清水、用镊子弄碎、盖上盖玻片、拇指轻压使细胞分散开。观察时先低倍镜找到分生区细胞，再换高倍镜辨认各时期，视野里处于分裂间期的细胞数量最多。最后看三条数量曲线：细胞核内 DNA 数在间期从 2N 复制到 4N，复制发生在 S 期，画图时前面要留一段平的 G1 期、后面留 G2 期，末期一分为二又回到 2N；**染色单体**数只有 0 和 4N 两个值，S 期出现、后期着丝点分裂时归 0；**染色体**数只有 2N 和 4N，后期加倍、末期减半；每条染色体上的 DNA 含量在 S 期从 1 条变 2 条，后期开始又从 2 条变回 1 条。有染色单体时（前期、中期）染色体数:染色单体数:核 DNA 数 = 1:2:2，没有染色单体时（后期、末期）染色体数:核 DNA 数 = 1:1。教材习题：洋葱根尖细胞有 16 条染色体，“分裂期细胞数量较多”是错的，间期细胞才多；“间期染色体复制后为 32 条”也是错的，间期染色体数不加倍，加倍只在后期。", "vtech": [["细胞周期先问“连续分裂”", "看到细胞周期题 → 先问是不是连续分裂的细胞：受精卵、根尖分生区、茎形成层、皮肤生发层、干细胞才有；不同细胞周期长短不同，同一体也不一样——人肝细胞和宫颈癌细胞都是 22 小时，间期时长却不同。"], ["前中后末抓标志性变化", "前期染色质螺旋成染色体、纺锤体出现、核膜核仁消失；中期着丝点排赤道板、形态固定数目清晰，是看染色体最好的时期；后期着丝点分裂、染色单体消失、染色体数加倍；末期核膜核仁重现，植物出现细胞板，动物细胞膜向内凹陷缢裂。"], ["动物细胞三处不同记时期", "间期中心体由一组倍增为两组；前期中心体移向两极发出星射线形成纺锤体，不是两极发纺锤丝；末期没有细胞板，靠细胞膜向内凹陷、收缩环缢裂成两个细胞；问有关细胞器要加上中心体、去掉高尔基体。"], ["曲线题先定 2N、4N、0 三个数", "核 DNA：间期 2N→S 期复制→4N，末期一分为二回 2N；染色单体只有 0 和 4N 两个值，S 期出现、后期着丝点分裂时归 0；染色体数只有 2N 和 4N，后期加倍、末期减半；有染色单体时染色体:染色单体:核 DNA = 1:2:2，无染色单体时是 1:1。"]], "vgaokao": []}}, "u_bio_20": {"id": "u_bio_20", "name": "细胞的分化", "secs": "第二节", "pageFrom": 118, "pageTo": 122, "members": ["bio_b026"], "video": {"bvid": "BV1p54y177e6", "p": 55, "t": "细胞的分化", "dur": "49:17", "from": "锦城大同教育·杨波生物", "vtop": ["细胞分化的实质是基因的选择性表达：分化后的细胞仍含本物种全套基因，变的只是哪些基因在表达——同一个体不同细胞的基因组成相同、表达情况不同。", "全能性不等于表现出全能性：一般活细胞理论上都有全能性（哺乳动物成熟红细胞没有细胞核，要除外），但要表现出来，必须发育成完整个体或分化出各种细胞。", "植物细胞全能性易于表达（组织培养：脱分化成愈伤组织、再分化成完整植株），动物体细胞全能性受细胞质限制，只能说细胞核具有全能性——受精卵和早期胚胎细胞除外。"], "vsum": "本课讲第六章第二节，讲**细胞的分化**。开场先看教材例子：在人体内，**红细胞**的寿命为 120 天左右，**白细胞**的寿命只有 5 到 7 天，这些血细胞都是失去分裂能力的细胞。教材提了两个问题：为什么健康人的血细胞数量不会随着血细胞的死亡而减少？因为机体会不断产生新的血细胞补充到血液中去；骨髓与血细胞的形成有什么关系？因为红细胞、白细胞和血小板都有共同的起源——**造血干细胞**，它主要存在于骨髓里，能通过增殖分化形成这三种血细胞，所以向白血病患者移植正常的骨髓，让正常的干细胞产生正常的血细胞，就能达到治疗白血病的目的。造血干细胞变成红细胞、白细胞、血小板时，细胞的种类增加了，细胞种类的增加依靠的就是细胞的分化。第一个重点是**细胞分化及其意义**。细胞分化的概念是：在**个体发育**中，由一个或一种细胞增殖产生的后代，在**形态、结构和生理功能**上发生**稳定性差异**的过程。一个细胞比如受精卵，一种细胞比如造血干细胞，都能分化；以红细胞和白细胞为例，哺乳动物成熟的红细胞是两面凹的圆盘状，白细胞一般是球形，形态结构不同，功能也不同——红细胞主要运输氧气，白细胞是免疫细胞、帮助机体抵御病原体。所谓稳定性，是指分化后的细胞一般维持分化后的状态直到死亡。接着看分化的过程和实质：受精卵含有本物种全套的遗传物质，比如 ABCD 四个基因，分裂产生的两个子细胞也都含有全套基因；分化时，上面那个子细胞只表达 A 和 C 基因，下面那个只表达 B 和 C 基因，表达不同，形态结构和功能就不同了，但分化后的细胞仍然含有全套基因，没表达的基因还在细胞里。所以细胞分化一般不会改变遗传物质，实质就是**基因的选择性表达**——在个体发育过程中，不同种类的细胞中遗传信息的表达情况不同。基因表达主要是合成蛋白质，有的蛋白质是结构蛋白、构成细胞结构，有的蛋白质是酶、参与细胞内的生理功能，表达的蛋白质不同，细胞的结构和生理过程就不同。分化有四个特点：①**普遍性**，在生物界中普遍存在，是生物个体发育的基础——没有分化，受精卵不可能变成一个完整的婴儿；但并非一切生物都能分化，病毒连细胞都不是，某些单细胞生物也不能分化；②**持久性**，发生在生物体的整个生命进程中，小孩、成年人、老年人身体里造血干细胞都在分化产生血细胞补充死亡的细胞，在胚胎时期达到最大限度；③**稳定性**或**不可逆性**，一般来说分化后的细胞将一直保持分化后的状态直到死亡，但少数特殊情况下，在离体或人工培养的条件下，某些高度分化的细胞可以恢复分裂和分化能力；④**遗传物质的不变性**，一般情况下分化后的细胞内遗传物质不发生改变。分化的结果是形成不同形态、结构和功能的细胞，不同类型的细胞构成不同的组织和器官，比如上皮细胞构成上皮组织，骨骼肌细胞构成肌肉组织，软骨细胞、神经细胞也是分化产生的。分化的意义有两点：一是生物个体发育的基础，没有分化人体不能完成正常发育；二是使多细胞生物体的细胞**趋向专门化**，有利于提高各种生理功能的效率——叶肉细胞含大量叶绿体、能充分表达合成叶绿体的基因，更好地完成光合作用；表皮细胞不含叶绿体，细胞壁外面形成角质层、起保护作用；储藏细胞也不含叶绿体，储藏大量有机物供植物体使用。接着看分化的变与不变：变的是细胞的形态、结构和生理功能，细胞器的种类和数目、细胞质基质的成分和功能，蛋白质的种类、数量和功能，以及基因的选择性表达；不变的是细胞的数量和细胞内的遗传物质——分化不改变细胞数目，细胞数目靠增殖改变，分化后的细胞都含本物种全套遗传信息。易错提醒三则：①同一个体的小肠上皮细胞和平滑肌细胞所含的基因是不同的——错，同一个体都来自一个受精卵，遗传物质相同；②蛙的红细胞和人的红细胞形态不同的原因是基因选择性表达的结果——错，这是两个不同物种，基因本身就不同，选择性表达是同一个体或同一物种内部的事；③同一细胞内往往含有不同的蛋白质，这是基因选择性表达的结果——错，同一细胞内基因不同、表达了就会产生不同蛋白质，与选择性表达无关，而且分化说的是后代之间的差异，不是一个细胞内部。第二个重点是**细胞的全能性**。概念是：细胞经过分裂和分化后，仍然具有产生**完整有机体**或分化成**其他各种细胞**的潜能和特性。未分化的细胞如受精卵、动物和人体的早期胚胎细胞、植物体的分生组织细胞都具有全能性；细胞是否具有全能性，与是否经过分裂和分化没有必然联系；一般来说活细胞理论上都具有全能性，但有的细胞除外，比如**哺乳动物成熟的红细胞**等。植物细胞全能性的表达就是**植物组织培养**：科学家利用胡萝卜的韧皮部细胞，取一部分放到含有营养物质和植物激素的特定培养液中，先经过**脱分化**形成细胞团块——**愈伤组织**，也就是恢复了分裂和分化能力的薄壁细胞，再经过**再分化**产生根、茎、叶，最终形成一株完整的植株。所以植物组织培养就是利用植物的细胞、组织或器官进行离体培养，经过脱分化和再分化培育成完整植株，属于植物无性繁殖的一种；结论是高度分化的植物细胞仍然具有发育成完整植株的能力，植物细胞具有全能性。动物方面说的是**动物细胞核的全能性**：非洲爪蟾的核移植实验，先用紫外线处理蛙卵使细胞核失活、得到去核的卵细胞，再把蝌蚪肠上皮细胞的细胞核移植进去，得到的细胞经过增殖和分化发育成完整的蝌蚪，而且克隆蝌蚪的性状和提供细胞核的那只蝌蚪一样；还有克隆羊多利，以及我国科学家首次完成的克隆猴中中和华华。这说明已分化的动物细胞的细胞核具有全能性，但到目前为止科学家还没有把一个动物体细胞直接培育成完整个体，因为动物体细胞全能性的表达受**细胞质**的限制；例外的是动物的受精卵和早期胚胎细胞，这两种细胞可以直接说细胞具有全能性。接着讲**干细胞**：特点是具有分裂和分化能力，在动物和人体内数量比较少，比如骨髓中的造血干细胞能不断产生红细胞、白细胞和血小板。按分化潜能不同，干细胞分为三类：**全能干细胞**（受精卵、早期卵裂的细胞，能分化成组成该机体的各种细胞）、**多能干细胞**（胚胎干细胞、造血干细胞、骨髓间充质干细胞，只能分化成多种细胞）、**单能干细胞**，又叫**专能干细胞**（神经干细胞、小肠上皮干细胞，通常只能分化成一种或关系密切的两种细胞）。还要注意两点：一是并非所有干细胞都要分化，部分干细胞保留分裂能力、进行自我更新，源源不断地产生新的干细胞；二是只有全能干细胞是未分化的细胞，多能和单能干细胞都是已经分化的细胞，只不过分化程度没有高度分化。细胞具有全能性的原因是：已分化的细胞一般都有一套和受精卵完全相同的遗传物质，所以仍有发育成完整新个体的潜能；哺乳动物成熟的红细胞除外，因为它没有细胞核，细胞核内的遗传物质在发育过程中逐渐退化掉了。植物细胞全能性实现的条件是：离体状态、水、无机盐、有机营养及激素（如生长素、细胞分裂素）、适宜的温度等外界条件。动植物细胞全能性的区别是：植物细胞的全能性易于表达，动物细胞的全能性受到极大限制，但动物细胞核的全能性仍然可以表达。分化程度与全能性的关系：一般情况下，细胞分化程度不断提高，全能性逐渐变小，但分化程度高的细胞全能性不一定低，比如**生殖细胞**（精子和卵子）是高度分化的细胞，全能性却较高；除了生殖细胞之外的体细胞，全能性小于生殖细胞，生殖细胞的全能性又小于受精卵。分裂与分化的关系：一般来说细胞分化程度越高，分裂能力越低，大部分分化细胞失去了分裂能力，但小部分高度分化的细胞仍然具有分裂能力，比如小肠上皮细胞和平滑肌细胞。易错提醒四则：①成熟个体体内的所有细胞都已经高度分化——错，成年人、老年人身体里都有干细胞在增殖分化、补充新细胞；②种子发育成完整个体体现了细胞的全能性——错，种子里面含有一个植物的幼体，长大只是自然生长的过程，就像婴儿长大成人不能体现细胞的全能性；③壁虎断尾后重新长出尾巴体现了细胞的全能性——错，全能性的体现要么发育成完整植株（个体），要么分化出各种细胞，壁虎只长出了尾巴部分的细胞；④造血干细胞分化出各种血细胞体现了细胞的全能性——错，虽然有各种两个字，但只是各种血细胞，除非说能分化出组成这个个体所需的各种细胞才可以。问题探究：细胞具有全能性，不等于细胞表现出全能性——只要有细胞核的活细胞一般都具有全能性，但要表现出全能性，必须发育成一个完整的个体，或者分化出各种细胞。教材习题要点：①受精卵没有分化，所以没有全能性——错，是否分化与是否具有全能性没有必然联系，受精卵没有分化但仍具有全能性；②细胞的分化程度越高，表现出来的全能性就越弱——对，注意这里说的是表现出来的全能性，改成具有的全能性就错了，生殖细胞就是特例；③把自体骨髓干细胞植入胰腺后分化为胰岛样细胞、替代损伤的胰岛 B 细胞治疗糖尿病——选 D，骨髓干细胞与胰岛 B 细胞基因组成相同、基因表达情况不同；④多细胞生物体内存在各种形态结构和功能上有差异的细胞——选 D，不同细胞中基因的选择性表达；⑤蛙的细胞中最容易表达出全能性的是受精卵——选 C，神经细胞、肌肉细胞、口腔上皮细胞都是高度分化的体细胞，只有受精卵是未分化的细胞。最后小结：本课学了细胞分化的概念、特点（普遍性、持久性、不可逆性、遗传物质的不变性）、意义和实质，以及细胞全能性的概念、植物细胞全能性的条件、动植物全能性的差异和应用——植物是组织培养、能快速繁殖，动物是克隆；课后作业是完成课后作业 28，下节课评讲。", "vtech": [["分化后遗传物质变没变：没变", "分化是基因的选择性表达：分化后的细胞仍含本物种全套基因，只是表达的基因不同；同一个体的小肠上皮细胞和平滑肌细胞基因组成相同，错说成不同是典型易错点。"], ["分化的四个特点要会区分", "普遍性（生物界普遍存在、个体发育的基础，但病毒和某些单细胞生物不能分化）、持久性（贯穿整个生命进程，胚胎时期达到最大限度）、稳定性或不可逆性（一般保持分化状态直到死亡，离体或人工培养条件下某些高度分化细胞可恢复）、遗传物质的不变性。"], ["全能性表达的两个条件：发育成完整个体或分化出各种细胞", "种子长成植株、壁虎断尾长尾巴、造血干细胞分化出各种血细胞都不能体现全能性——种子含幼体只是自然生长，后两者只分化出部分细胞，不是各种细胞；具有全能性不等于表现出全能性。"], ["干细胞三类与全能性大小排序", "按分化潜能分全能干细胞（受精卵、早期卵裂细胞）、多能干细胞（胚胎干细胞、造血干细胞、骨髓间充质干细胞）、单能或专能干细胞（神经干细胞、小肠上皮干细胞）；体细胞全能性小于生殖细胞，生殖细胞小于受精卵；分化程度越高分裂能力一般越低，但小肠上皮细胞和平滑肌细胞这类高度分化细胞仍能分裂。"]], "vgaokao": []}}, "u_bio_21": {"id": "u_bio_21", "name": "细胞的衰老和死亡", "secs": "第三节", "pageFrom": 123, "pageTo": 128, "members": ["bio_b027"], "video": {"bvid": "BV1p54y177e6", "p": 57, "t": "细胞的衰老和死亡", "dur": "35:13", "from": "锦城大同教育·杨波生物", "vtop": ["细胞衰老的五个特征用口诀“一大一小一多三低”记：核大、细胞小、色素多，膜运输、酶活性、代谢速率三低。", "细胞衰老不等于个体衰老：单细胞生物细胞衰老就是个体衰老；多细胞生物任何年龄体内都有衰老细胞，个体衰老是组成细胞的普遍衰老。", "细胞凋亡是基因决定的程序性死亡、对机体有利；细胞坏死是被动死亡、对机体有害——判断看主动/被动和有利/有害。"], "vsum": "本课是必修一第六章第三节、也是必修一的最后一节，讲**细胞的衰老和死亡**。开场从教材例子引入：人到一定年龄会长白头发，而且越来越多，原因是毛囊细胞合成黑色素的功能下降了；老师留下三个问题：老年人白头发的形成与毛囊细胞衰老有什么关系、老年人体内有没有幼嫩的细胞、年轻人体内有没有衰老的细胞、细胞衰老与个体衰老有什么关系。第一个重点是**细胞的衰老**：细胞衰老是细胞的生理状态和化学反应发生复杂变化的过程，最终表现为细胞的形态、结构和功能发生变化。**细胞衰老的五个特征**要重点掌握：①**细胞膜通透性改变，物质运输功能下降**——老年人肠胃消化吸收不好就是这个原因；②**细胞核体积增大、核膜内折、染色质收缩、染色加深**——染色质收缩会影响 DNA 的复制，因为 DNA 就位于染色质上；③**细胞内水分减少，细胞萎缩、体积变小**——老年人皮肤失去弹性就是水分减少；注意这里体积变小指的是细胞的体积，和②的细胞核体积增大不要记混；④**细胞内多种酶的活性降低，呼吸速率减慢、新陈代谢速率减慢**——不是所有酶都降低，与衰老相关的酶活性反而升高；老年人冬天更怕冷，就是呼吸作用有关酶的活性下降、产热不足；⑤**细胞内色素逐渐积累，妨碍细胞内物质的交流和传递**——积累的主要是**脂褐素**，不是黑色素，老年斑就是褐色的。白头发的成因：毛囊里的黑色素细胞衰老，里面的**酪氨酸酶**活性下降，酪氨酸转变成黑色素减少，头发就逐渐变白。五个特征用口诀“**一大一小一多三低**”记：一大是细胞核体积变大、染色质收缩染色加深；一小是细胞内水分减少、细胞萎缩变小；一多是细胞内色素（脂褐素）增多；三低是细胞膜物质运输功能降低、酶的活性降低、代谢速率降低。易错提醒：衰老细胞染色质收缩影响 DNA 复制；“所有酶活性都降低”是错的，只是多种酶；“细胞核体积减小”是错的，增大的是核、减小的是细胞；“物质运输功能增强”是错的，是减弱。第二个内容是细胞衰老的原因，目前被大家接受的有两个学说：**自由基学说**——**自由基**是异常活泼的带电分子或基团，经辐射、有害物质入侵、细胞内氧化反应等产生，会攻击破坏生物分子：攻击磷脂分子会产生更多自由基，像雪崩一样越破坏越严重；攻击 DNA 会引起基因突变；攻击蛋白质会使蛋白质活性下降，最终细胞衰老。**端粒学说**——**端粒**是每条染色体两端的特殊序列 DNA 与蛋白质的复合体；每次细胞分裂后，端粒的 DNA 序列就缩短一截，分裂次数越多端粒越短，短到损伤端粒内侧正常基因的 DNA 序列，细胞活动就异常、发生衰老；人体细胞通常只能分裂 **50 到 60 次**，可能就是这个原因。第三个内容是**细胞衰老与个体衰老的关系**，要分两类：**单细胞生物**一个细胞就是一个个体，单个细胞的衰老或死亡就是个体的衰老或死亡；**多细胞生物**细胞的衰老和死亡不等于个体的衰老和死亡——无论小孩、成人还是老年人，体内总有一部分细胞处于衰老和死亡状态，比如红细胞寿命只有 **120 天**、白细胞只有 **5 到 7 天**、小肠上皮细胞只有 **1 到 2 天**；反过来，**个体衰老的过程是组成个体的细胞普遍衰老的过程**，但不是所有细胞都衰老，老年人体内也有幼嫩的细胞和还在增殖分化的干细胞。还有一个核移植实验：年轻人的体细胞去核后与老年人的细胞核融合，细胞不分裂；老年人的体细胞去核后与年轻人的细胞核融合，细胞还能分裂而且比较旺盛，说明细胞分裂受细胞核控制，**细胞核是细胞生命活动的控制中心**，衰老细胞的分裂会逐渐减少甚至停止。易错提醒：端粒不是存在于所有细胞中，只有有染色体的细胞才有端粒；同一种体细胞端粒长度与有丝分裂能力成正相关；自由基不只攻击蛋白质，攻击磷脂和 DNA 同样导致衰老；衰老的生物体中并非所有细胞都衰老；多细胞生物幼嫩的个体中也有衰老的细胞。第二个重点是**细胞的死亡**，主要有**细胞凋亡**和**细胞坏死**两种方式，其中凋亡是细胞死亡的主要形式。**细胞凋亡**是由**基因所决定的细胞自动结束生命的过程**，受严格的遗传机制程序性调控，所以又叫**细胞的程序性死亡**。凋亡有三种类型：①个体发育中细胞的程序性死亡，比如胎儿手指形成过程中指间细胞的死亡；②成熟生物体中细胞的自然更新，比如红细胞、白细胞衰老死亡后由新细胞补充；③被病原体感染的细胞的清除。凋亡的意义有三点：对多细胞生物体完成正常发育有重要作用（没有凋亡手指不能正常形成）；维持内部环境的稳定（衰老死亡的细胞不清除就会在体内堆积成废物）；抵御外界各种因素的干扰（清除被病原体感染的细胞）。总之**细胞凋亡对机体是有利的**。**细胞坏死**则是在极端的物理、化学因素或严重的病理性刺激等种种不利因素影响下，细胞正常代谢活动受损或中断引起的细胞损伤或死亡，比如烫伤后皮肤黏膜脱落、骨折时部分骨细胞死亡、吸烟者肺部细胞因尼古丁作用死亡；坏死是**被动死亡**，对机体**有害**。判断凋亡还是坏死有两个方法：看主动还是被动，主动的是凋亡、被动的是坏死；看对机体有利还是有害，有利的是凋亡、有害的是坏死。易错提醒：被病原体感染的细胞被清除是凋亡不是坏死，因为清除它们能维持机体正常生命活动、对机体有利。教材补充内容**细胞自噬**：在一定条件下，细胞将受损或功能退化的细胞结构等通过**溶酶体**降解后再利用；动物细胞通过溶酶体，植物细胞通过具有类似功能的**液泡**完成；自噬的实质是细胞内的一种膜内吞，形成具有双层膜、裹挟着底物的自噬泡，再与溶酶体或液泡融合，里面的水解酶把底物分解成小分子供细胞再次利用。自噬有三个作用：营养缺乏时获得维持生存所需的物质和能量；细胞受到损伤或衰老时清除受损或衰老的细胞器；微生物入侵时清除感染的微生物和毒素；有些激烈的细胞自噬可能诱导细胞凋亡。易错提醒：细胞凋亡过程中并非所有酶活性都下降，与凋亡有关的酶活性反而升高；凋亡从根本上看是由基因决定的程序性死亡；细胞的衰老和凋亡是正常的生命活动，坏死才是异常的。最后讲了教材上的四道练习题：衰老的生物体中并非所有细胞都衰老；端粒受损可能导致细胞衰老；细胞凋亡是自主有序的死亡、对生物体有利；细胞死亡与细胞凋亡不是同一概念，而是包含关系；“细胞不能继续分化”不是细胞衰老的特征；哺乳动物成熟红细胞没有细胞核和众多细胞器、只能进行无氧呼吸、不产生二氧化碳，衰老后控制其凋亡的基因无法表达，因为它没有细胞核、没有染色体、没有基因；衰老细胞新陈代谢速率是减慢不是加快。最后总结：本课学了细胞衰老的五个特征（口诀“一大一小一多三低”）、自由基学说和端粒学说、细胞衰老与个体衰老的关系，以及细胞死亡（凋亡与坏死的区别）和细胞自噬；作业是复习后完成课后作业，下节课评讲。", "vtech": [["口诀“一大一小一多三低”", "一大：细胞核体积变大、染色质收缩、染色加深；一小：细胞内水分减少、细胞萎缩、体积变小；一多：细胞内色素（脂褐素）增多；三低：细胞膜物质运输功能降低、多种酶活性降低、代谢速率降低。注意核大与细胞小别记反，酶降低是“多种”不是“所有”。"], ["色素积累≠黑色素", "衰老细胞内积累的是脂褐素（老年斑就是褐色的）；黑色素合成在减少——毛囊黑色素细胞衰老、酪氨酸酶活性下降，酪氨酸转变成黑色素减少，才长白头发。"], ["端粒学说与分裂上限", "端粒是每条染色体两端的特殊DNA序列与蛋白质的复合体；每次分裂端粒缩短一截，短到损伤内侧正常基因序列就衰老；人体细胞通常只能分裂50到60次。端粒只存在于有染色体的细胞中，同种体细胞端粒越长、有丝分裂能力越强。"], ["凋亡vs坏死：两看判断", "一看主动还是被动：凋亡是基因决定的主动结束生命（程序性死亡），坏死是外界不利因素下被动死亡；二看对机体有利还是有害：凋亡有利、坏死有害。易错：被病原体感染的细胞被清除是凋亡，不是坏死。"]], "vgaokao": []}}}, "nodeUnit": {"bio_b001": "u_bio_1", "bio_b002": "u_bio_1", "bio_b003": "u_bio_2", "bio_b004": "u_bio_2", "bio_b005": "u_bio_3", "bio_b006": "u_bio_3", "bio_b007": "u_bio_4", "bio_b008": "u_bio_5", "bio_b009": "u_bio_6", "bio_b010": "u_bio_7", "bio_b011": "u_bio_8", "bio_b012": "u_bio_9", "bio_b013": "u_bio_10", "bio_b014": "u_bio_11", "bio_b015": "u_bio_12", "bio_b016": "u_bio_13", "bio_b017": "u_bio_14", "bio_b018": "u_bio_15", "bio_b019": "u_bio_16", "bio_b020": "u_bio_16", "bio_b021": "u_bio_17", "bio_b022": "u_bio_18", "bio_b023": "u_bio_18", "bio_b024": "u_bio_19", "bio_b025": "u_bio_19", "bio_b026": "u_bio_20", "bio_b027": "u_bio_21"}};
